INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35801, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要がなくなった物やゴミを、捨てて処分すること。", "primary_collocate": null, "pronunciation": "はいき", "ipa": "haiki", "syllable_count": 3, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "廃棄", "complexity_tier": "T6", "furigana": "単[たん]なる廃棄物[はいきぶつ]としての隔離[かくり]にとどまらず、炭素[たんそ]を資源[しげん]へと転換[てんかん]し、あるいは地中[ちちゅう]へ封[ふう]じ込[こ]めるこの技術[ぎじゅつ]は、経済活動[けいざいかつどう]と脱炭素化[だつたんそか]の両立[りょうりつ]という難題[なんだい]に対[たい]する、現時点[げんじてん]での最適解[さいてきかい]たり得[う]る。", "sentence_source": "mined"}, {"text": "古い書類を廃棄する。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "古[ふる]い書類[しょるい]を廃棄[はいき]する。", "sentence_source": "generated"}, {"text": "食品の廃棄を減らしたい。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "食品[しょくひん]の廃棄[はいき]を減[へ]らしたい。", "sentence_source": "generated"}, {"text": "期限切れの薬は廃棄してください。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "期限切[きげんぎ]れの薬[くすり]は廃棄[はいき]してください。", "sentence_source": "generated"}, {"text": "廃棄された机が山積みだった。", "target_word": "廃棄", "complexity_tier": "T4", "furigana": "廃棄[はいき]された机[つくえ]が山積[やまづ]みだった。", "sentence_source": "generated"}, {"text": "廃棄の手続きを会社に頼んだ。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "廃棄[はいき]の手続[てつづ]きを会社[かいしゃ]に頼[たの]んだ。", "sentence_source": "generated"}, {"text": "データを廃棄すると、元に戻せない。", "target_word": "廃棄", "complexity_tier": "T4", "furigana": "データを廃棄[はいき]すると、元[もと]に戻[もど]せない。", "sentence_source": "generated"}, {"text": "不要な機器の廃棄に費用がかかる。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "不要[ふよう]な機器[きき]の廃棄[はいき]に費用[ひよう]がかかる。", "sentence_source": "generated"}, {"text": "工場は古い部品を廃棄している。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "工場[こうじょう]は古[ふる]い部品[ぶひん]を廃棄[はいき]している。", "sentence_source": "generated"}, {"text": "廃棄を急ぐ必要はない。", "target_word": "廃棄", "complexity_tier": "T3", "furigana": "廃棄[はいき]を急[いそ]ぐ必要[ひつよう]はない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "廃棄する", "label": "活用"}, {"form": "廃棄される", "label": "活用"}, {"form": "廃棄物", "label": "派生"}, {"form": "廃棄処分", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 不要な物を捨てて処分すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
