INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35802, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かといっしょに起こる。", "primary_collocate": null, "pronunciation": "ともなう", "ipa": "tomonaɯ", "syllable_count": 4, "sentences": [{"text": "仕事には責任が伴う。", "target_word": "伴う", "complexity_tier": "T1", "furigana": "仕事[しごと]には責任[せきにん]が伴[ともな]う。", "sentence_source": "generated"}, {"text": "痛みを伴う治療もあります。", "target_word": "伴う", "complexity_tier": "T2", "furigana": "痛[いた]みを伴[ともな]う治療[ちりょう]もあります。", "sentence_source": "generated"}, {"text": "この山に登るのは、危険を伴います。", "target_word": "伴います", "complexity_tier": "T3", "furigana": "この山[やま]に登[のぼ]るのは、危険[きけん]を伴[ともな]います。", "sentence_source": "generated"}, {"text": "強い風を伴った雨が降っている。", "target_word": "伴った", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]を伴[ともな]った雨[あめ]が降[ふ]っている。", "sentence_source": "generated"}, {"text": "雷を伴う大雨になるそうです。", "target_word": "伴う", "complexity_tier": "T3", "furigana": "雷[かみなり]を伴[ともな]う大雨[おおあめ]になるそうです。", "sentence_source": "generated"}, {"text": "この治療には痛みが伴って、とてもつらかった。", "target_word": "伴って", "complexity_tier": "T3", "furigana": "この治療[ちりょう]には痛[いた]みが伴[ともな]って、とてもつらかった。", "sentence_source": "generated"}, {"text": "成功には、それなりの苦労が伴うものだ。", "target_word": "伴う", "complexity_tier": "T4", "furigana": "成功[せいこう]には、それなりの苦労[くろう]が伴[ともな]うものだ。", "sentence_source": "generated"}, {"text": "副作用を伴わない薬を探している。", "target_word": "伴わない", "complexity_tier": "T4", "furigana": "副作用[ふくさよう]を伴[ともな]わない薬[くすり]を探[さが]している。", "sentence_source": "generated"}, {"text": "決断には必ずリスクが伴うが、挑戦しなければ何も変わらない。", "target_word": "伴う", "complexity_tier": "T4", "furigana": "決断[けつだん]には必[かなら]ずリスクが伴[ともな]うが、挑戦[ちょうせん]しなければ何[なに]も変[か]わらない。", "sentence_source": "generated"}, {"text": "台風は、強い風と大雨を伴いながら、ゆっくり北へ進んでいます。", "target_word": "伴いながら", "complexity_tier": "T5", "furigana": "台風[たいふう]は、強[つよ]い風[かぜ]と大雨[おおあめ]を伴[ともな]いながら、ゆっくり北[きた]へ進[すす]んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伴った", "label": "活用"}, {"form": "伴って", "label": "活用"}, {"form": "伴わない", "label": "活用"}, {"form": "伴います", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 何かといっしょに起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35802, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伴う", "is_correct": true, "explanation": "「責任が伴う」で、仕事に付随して責任が生じる意味になる。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、責任が眠るでは意味が合わない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "形は合うが、責任が泳ぐでは意味が合わない。"}, {"text": "焼ける", "is_correct": false, "explanation": "形は合うが、責任が焼けるでは意味が合わない。"}], "explanations": {"伴う": "「責任が伴う」で、仕事に付随して責任が生じる意味になる。", "眠る": "形は合うが、責任が眠るでは意味が合わない。", "泳ぐ": "形は合うが、責任が泳ぐでは意味が合わない。", "焼ける": "形は合うが、責任が焼けるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "伴う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に辞書を伴ってある。", "explanation": "「伴う」は何かと一緒に起こる意味で、物が置いてある意味では使えない。"}, {"text": "私は毎日、バスを伴って歩いている。", "explanation": "バスは歩くことと一緒に起こる事柄ではなく、「伴う」が合わない。"}, {"text": "弟は大きな声で、夕飯を伴った。", "explanation": "「伴う」に食べる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伴う", "is_correct": true, "explanation": "「苦労が伴う」で、成功に付随して苦労が生じる意味になる。"}, {"text": "咲く", "is_correct": false, "explanation": "形は合うが、苦労が咲くものだでは意味が合わない。"}, {"text": "転ぶ", "is_correct": false, "explanation": "形は合うが、苦労が転ぶものだでは意味が合わない。"}, {"text": "溶ける", "is_correct": false, "explanation": "形は合うが、苦労が溶けるものだでは意味が合わない。"}], "explanations": {"伴う": "「苦労が伴う」で、成功に付随して苦労が生じる意味になる。", "咲く": "形は合うが、苦労が咲くものだでは意味が合わない。", "転ぶ": "形は合うが、苦労が転ぶものだでは意味が合わない。", "溶ける": "形は合うが、苦労が溶けるものだでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "伴う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は鉛筆を伴いながら、手紙を書いた。", "explanation": "鉛筆は道具で、一緒に起こる事柄ではないため「伴う」が合わない。"}, {"text": "彼は山の頂上を伴いながら歩いた。", "explanation": "頂上は付随して起こる事柄ではなく、「伴う」の使い方が合わない。"}, {"text": "姉は新しい傘を伴いながら、駅まで歩いた。", "explanation": "傘は物で、一緒に起こる事柄ではないため「伴う」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
