INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「増加に伴い」は決まった形で、付随する元の事柄を示す。"}, {"text": "で", "is_correct": false, "explanation": "「増加で伴い」という形は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「増加と伴い」という形は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「増加から伴い」という形は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「増加に伴い」は決まった形で、付随する元の事柄を示す。", "で": "「増加で伴い」という形は成り立たない。", "と": "「増加と伴い」という形は成り立たない。", "から": "「増加から伴い」という形は成り立たない。"}, "error_tags": {"で": "means", "と": "comitative", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「進むのに伴って」は決まった形で、付随する元の事柄を示す。"}, {"text": "と", "is_correct": false, "explanation": "「進むのと伴って」という形は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「進むのへ伴って」という形は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「進むのから伴って」という形は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「進むのに伴って」は決まった形で、付随する元の事柄を示す。", "と": "「進むのと伴って」という形は成り立たない。", "へ": "「進むのへ伴って」という形は成り立たない。", "から": "「進むのから伴って」という形は成り立たない。"}, "error_tags": {"と": "comitative", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "ある事柄に付随して、別の事柄が生じる。", "primary_collocate": null, "pronunciation": "ともなう", "ipa": "tomonaɯ", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "伴う", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "人口の増加に伴い、ごみも増えた。", "target_word": "伴い", "complexity_tier": "T3", "furigana": "人口[じんこう]の増加[ぞうか]に伴[ともな]い、ごみも増[ふ]えた。", "sentence_source": "generated"}, {"text": "年をとるに伴って、体力が落ちてくる。", "target_word": "伴って", "complexity_tier": "T3", "furigana": "年[とし]をとるに伴[ともな]って、体力[たいりょく]が落[お]ちてくる。", "sentence_source": "generated"}, {"text": "引っ越しに伴う手続きは、とても多い。", "target_word": "伴う", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しに伴[ともな]う手続[てつづ]きは、とても多[おお]い。", "sentence_source": "generated"}, {"text": "工事に伴い、この道は通れなくなる。", "target_word": "伴い", "complexity_tier": "T3", "furigana": "工事[こうじ]に伴[ともな]い、この道[みち]は通[とお]れなくなる。", "sentence_source": "generated"}, {"text": "大きな変化を伴った改革は、反対も多かった。", "target_word": "伴った", "complexity_tier": "T4", "furigana": "大[おお]きな変化[へんか]を伴[ともな]った改革[かいかく]は、反対[はんたい]も多[おお]かった。", "sentence_source": "generated"}, {"text": "技術の進歩に伴う変化は、とても速い。", "target_word": "伴う", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]に伴[ともな]う変化[へんか]は、とても速[はや]い。", "sentence_source": "generated"}, {"text": "計画が進むのに伴って、費用も増えてくる。", "target_word": "伴って", "complexity_tier": "T4", "furigana": "計画[けいかく]が進[すす]むのに伴[ともな]って、費用[ひよう]も増[ふ]えてくる。", "sentence_source": "generated"}, {"text": "円安に伴って、海外旅行の費用が高くなった。", "target_word": "伴って", "complexity_tier": "T4", "furigana": "円安[えんやす]に伴[ともな]って、海外[かいがい]旅行[りょこう]の費用[ひよう]が高[たか]くなった。", "sentence_source": "generated"}, {"text": "新しい制度の導入は、混乱を伴いながらも、少しずつ社会に定着していった。", "target_word": "伴いながら", "complexity_tier": "T5", "furigana": "新[あたら]しい制度[せいど]の導入[どうにゅう]は、混乱[こんらん]を伴[ともな]いながらも、少[すこ]しずつ社会[しゃかい]に定着[ていちゃく]していった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伴い", "label": "活用"}, {"form": "伴って", "label": "活用"}, {"form": "伴った", "label": "活用"}, {"form": "伴わない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 事柄に付随して別の事柄が生じる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伴う", "is_correct": true, "explanation": "「拡大に伴う」で、拡大に付随して起こる意味になる。"}, {"text": "守る", "is_correct": false, "explanation": "形は合うが、拡大に守る緑では意味が合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、拡大に眠る緑では意味が合わない。"}, {"text": "抱える", "is_correct": false, "explanation": "形は合うが、拡大に抱える緑では意味が合わない。"}], "explanations": {"伴う": "「拡大に伴う」で、拡大に付随して起こる意味になる。", "守る": "形は合うが、拡大に守る緑では意味が合わない。", "眠る": "形は合うが、拡大に眠る緑では意味が合わない。", "抱える": "形は合うが、拡大に抱える緑では意味が合わない。"}, "sentence_index": 0, "correct_answer": "伴う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に辞書が伴っている。", "explanation": "「伴う」は事柄に付随して別の事柄が生じる意味で、物がある意味では使えない。"}, {"text": "昨日の試合は、私のチームに伴って勝った。", "explanation": "「に伴って」は変化に付随して起こる意味で、チームに従う意味はない。"}, {"text": "私は朝ごはんに伴う電車に乗った。", "explanation": "朝ごはんと電車には付随して生じる関係がなく、「伴う」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伴う", "is_correct": true, "explanation": "「進歩に伴う変化」で、進歩に付随して起こる変化という意味になる。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、進歩に眠る変化では意味が合わない。"}, {"text": "光る", "is_correct": false, "explanation": "形は合うが、進歩に光る変化では意味が合わない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "形は合うが、進歩に泳ぐ変化では意味が合わない。"}], "explanations": {"伴う": "「進歩に伴う変化」で、進歩に付随して起こる変化という意味になる。", "眠る": "形は合うが、進歩に眠る変化では意味が合わない。", "光る": "形は合うが、進歩に光る変化では意味が合わない。", "泳ぐ": "形は合うが、進歩に泳ぐ変化では意味が合わない。"}, "sentence_index": 6, "correct_answer": "伴う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は味噌汁を伴いながら茶碗を洗った。", "explanation": "味噌汁は付随して生じる事柄ではなく、「伴う」が合わない。"}, {"text": "窓の外で空が伴いながら、雨が降った。", "explanation": "「空が伴う」は付随して生じる関係を表さず、意味が通らない。"}, {"text": "兄は財布に伴って、駅まで走った。", "explanation": "「に伴って」は変化に付随する意味で、物と一緒に走る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "収入の増加で伴い、支出も増えた。", "corrected_sentence": "収入の増加に伴い、支出も増えた。", "error_description": "「伴い」は「に伴い」の形で使う。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35803, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "改革は痛みへ伴った。", "corrected_sentence": "改革は痛みを伴った。", "error_description": "「伴う」の目的語は「を」で示す。「へ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "上げる対象（負荷）を示す。「負荷を上げる」で自然になる。"}, {"text": "に", "is_correct": false, "explanation": "到達点を示す。「負荷に上げる」とは言わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「負荷が上げる」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞。「運動の負荷の少しずつ」となり文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "上げる対象（負荷）を示す。「負荷を上げる」で自然になる。", "に": "到達点を示す。「負荷に上げる」とは言わない。", "が": "主語を示す。「負荷が上げる」は誤り。", "の": "名詞をつなぐ助詞。「運動の負荷の少しずつ」となり文が成り立たない。"}, "error_tags": {"に": "方向・到達", "が": "主格", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「負荷が腰にかかった」で、負荷が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「負荷を腰にかかった」は他動詞の形にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「負荷で腰にかかった」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す。「負荷と腰にかかった」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「負荷が腰にかかった」で、負荷が主語になる。", "を": "「負荷を腰にかかった」は他動詞の形にならず不自然。", "で": "手段や場所を示す。「負荷で腰にかかった」は成り立たない。", "と": "相手や並列を示す。「負荷と腰にかかった」は文が成り立たない。"}, "error_tags": {"を": "目的格", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、体や心にかかる重さや力のこと。", "primary_collocate": null, "pronunciation": "ふか", "ipa": "ɸɯka", "syllable_count": 2, "sentences": [{"text": "毎日の残業で、体にかかる負荷が大きくなってきた。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "毎日[まいにち]の残業[ざんぎょう]で、体[からだ]にかかる負荷[ふか]が大[おお]きくなってきた。", "sentence_source": "generated"}, {"text": "運動の負荷を少しずつ上げると、筋肉がつきやすい。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "運動[うんどう]の負荷[ふか]を少[すこ]しずつ上[あ]げると、筋肉[きんにく]がつきやすい。", "sentence_source": "generated"}, {"text": "仕事の負荷が重すぎて、心が疲れてしまった。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "仕事[しごと]の負荷[ふか]が重[おも]すぎて、心[こころ]が疲[つか]れてしまった。", "sentence_source": "generated"}, {"text": "膝に負荷をかけないように、ゆっくり階段を下りた。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "膝[ひざ]に負荷[ふか]をかけないように、ゆっくり階段[かいだん]を下[お]りた。", "sentence_source": "generated"}, {"text": "彼女は負荷の高い練習を毎日続けている。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は負荷[ふか]の高[たか]い練習[れんしゅう]を毎日[まいにち]続[つづ]けている。", "sentence_source": "generated"}, {"text": "医者に、心への負荷を減らすよう言われた。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、心[こころ]への負荷[ふか]を減[へ]らすよう言[い]われた。", "sentence_source": "generated"}, {"text": "初心者なので、軽い負荷から始めることにした。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]なので、軽[かる]い負荷[ふか]から始[はじ]めることにした。", "sentence_source": "generated"}, {"text": "重い荷物を持ち続けたため、腰に負荷がかかった。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]ち続[つづ]けたため、腰[こし]に負荷[ふか]がかかった。", "sentence_source": "generated"}, {"text": "試験前は勉強の負荷が増えて、よく眠れない。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "試験[しけん]前[まえ]は勉強[べんきょう]の負荷[ふか]が増[ふ]えて、よく眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "負荷の大きい作業のあとは、しっかり休むことが大切だ。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "負荷[ふか]の大[おお]きい作業[さぎょう]のあとは、しっかり休[やす]むことが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負荷", "label": "基本形"}, {"form": "負荷が", "label": "主格"}, {"form": "負荷を", "label": "目的格"}, {"form": "負荷に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "運動や仕事などで体や心にかかる負担の重さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負荷", "is_correct": true, "explanation": "体や心にかかる重さを表す。定義どおりに体にかかるものとして合う。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額のこと。体にかかるものではない。"}, {"text": "売上", "is_correct": false, "explanation": "商品が売れた金額のこと。体にかかるものではない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態のこと。体にかかるものではない。"}], "explanations": {"負荷": "体や心にかかる重さを表す。定義どおりに体にかかるものとして合う。", "料金": "支払う金額のこと。体にかかるものではない。", "売上": "商品が売れた金額のこと。体にかかるものではない。", "天気": "空の状態のこと。体にかかるものではない。"}, "sentence_index": 0, "correct_answer": "負荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎月、給料の半分を負荷の返済にあてている。", "explanation": "ここは〈借金〉の意味（負債）。負荷は体や心にかかる重さなので、お金の借りの意味では使わない。"}, {"text": "料理に香りを負荷した。", "explanation": "ここは〈付け加える〉の意味（付加、同じ読み）。香りを加える話で、重さの意味の負荷では言えない。"}, {"text": "試合中に膝を負荷して、そのまま退場した。", "explanation": "ここは〈けがをする〉の意味（負傷）。膝の故障の話なので、体にかかる重さの負荷では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負荷", "is_correct": true, "explanation": "体にかかる重さや作業の負担を表す。軽い負荷から始める文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点をつける作業。「軽い採点から始める」とは言わない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を送る仕組み。「軽い郵便から始める」とは言わない。"}, {"text": "会計", "is_correct": false, "explanation": "支払いの計算。「軽い会計から始める」とは言わない。"}], "explanations": {"負荷": "体にかかる重さや作業の負担を表す。軽い負荷から始める文脈に合う。", "採点": "答案などに点をつける作業。「軽い採点から始める」とは言わない。", "郵便": "手紙や荷物を送る仕組み。「軽い郵便から始める」とは言わない。", "会計": "支払いの計算。「軽い会計から始める」とは言わない。"}, "sentence_index": 6, "correct_answer": "負荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この館内は飲食負荷だ。", "explanation": "ここは〈禁止されている〉の意味（不可、同じ読み）。飲食が禁止だと言う文脈で、重さの負荷は合わない。"}, {"text": "ブレーキを離すと、車がさらに負荷した。", "explanation": "ここは〈速度が増す〉の意味（加速）。負荷は体や機械にかかる重さで、車の速さには使わない。"}, {"text": "トラックに負荷を積んで出発した。", "explanation": "ここは〈運ぶ品物〉の意味（荷物）。負荷は体や心にかかる重さなので、積んで運ぶ品物の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の長い通勤で、心身に負荷をかかっている。", "corrected_sentence": "毎日の長い通勤で、心身に負荷がかかっている。", "error_description": "「かかる」は主語（負荷）を「が」で取る動詞。「を」は誤りで、正しくは「負荷がかかる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35804, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業が続くと、体に負荷がかかれるおそれがある。", "corrected_sentence": "作業が続くと、体に負荷がかかるおそれがある。", "error_description": "「体に負荷がかかる」は負荷を主語にとる自動詞の定型。「かかれる」は意味が通らず誤りで、正しくは「かかる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "耐える対象を示す。「負荷に耐える」で自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「高い負荷が長時間耐えられる」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞。「高い負荷の長時間耐えられる」となり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「負荷へ耐える」とは言わず不自然。"}], "correct_answer": "に", "explanations": {"に": "耐える対象を示す。「負荷に耐える」で自然になる。", "が": "主語を示す。「高い負荷が長時間耐えられる」では文が成り立たない。", "の": "名詞をつなぐ助詞。「高い負荷の長時間耐えられる」となり文が成り立たない。", "へ": "方向を示す。「負荷へ耐える」とは言わず不自然。"}, "error_tags": {"が": "主格", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "感じる対象（負荷）を示す。「負荷を強く感じている」で自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「心身への負荷へ強く感じている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す。「負荷と強く感じている」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点や理由を示す。「負荷から強く感じている」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "感じる対象（負荷）を示す。「負荷を強く感じている」で自然になる。", "へ": "方向を示す。「心身への負荷へ強く感じている」は成り立たない。", "と": "相手や並列を示す。「負荷と強く感じている」は不自然。", "から": "起点や理由を示す。「負荷から強く感じている」は目的語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "から": "起点・理由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行う際に、人や機械などにかかる重さや、心身に感じる重圧。", "primary_collocate": null, "pronunciation": "ふか", "ipa": "ɸɯka", "syllable_count": 2, "sentences": [{"text": "アクセスが集中して、サーバーに大きな負荷がかかった。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "アクセスが集中[しゅうちゅう]して、サーバーに大[おお]きな負荷[ふか]がかかった。", "sentence_source": "generated"}, {"text": "このエンジンは高い負荷に長時間耐えられる。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "このエンジンは高[たか]い負荷[ふか]に長時間[ちょうじかん]耐[た]えられる。", "sentence_source": "generated"}, {"text": "モーターに負荷をかけすぎると、故障の原因になる。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "モーターに負荷[ふか]をかけすぎると、故障[こしょう]の原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "新しい制度で、現場の職員の負荷が増えた。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]で、現場[げんば]の職員[しょくいん]の負荷[ふか]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "橋に負荷がかかる重い車の通行は制限されている。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "橋[はし]に負荷[ふか]がかかる重[おも]い車[くるま]の通行[つうこう]は制限[せいげん]されている。", "sentence_source": "generated"}, {"text": "パソコンの負荷が高いときは、使わないソフトを閉じる。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "パソコンの負荷[ふか]が高[たか]いときは、使[つか]わないソフトを閉[と]じる。", "sentence_source": "generated"}, {"text": "機械の負荷を調べてから、運転の速度を決めた。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "機械[きかい]の負荷[ふか]を調[しら]べてから、運転[うんてん]の速度[そくど]を決[き]めた。", "sentence_source": "generated"}, {"text": "責任が重くなり、心身への負荷を強く感じている。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "責任[せきにん]が重[おも]くなり、心身[しんしん]への負荷[ふか]を強[つよ]く感[かん]じている。", "sentence_source": "generated"}, {"text": "全員で分担して、一人あたりの負荷を軽くした。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "全員[ぜんいん]で分担[ぶんたん]して、一人[ひとり]あたりの負荷[ふか]を軽[かる]くした。", "sentence_source": "generated"}, {"text": "負荷が限界に近づくと、装置は自動的に止まる。", "target_word": "負荷", "complexity_tier": "T3", "furigana": "負荷[ふか]が限界[げんかい]に近[ちか]づくと、装置[そうち]は自動的[じどうてき]に止[と]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "負荷", "label": "基本形"}, {"form": "負荷が", "label": "主格"}, {"form": "負荷を", "label": "目的格"}, {"form": "負荷に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "人や機械・設備にかかる作業量や力の大きさ。サーバーやモーターなどの負担、心身の重圧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "負荷", "is_correct": true, "explanation": "人や機械にかかる作業量や重さを表す。サーバーに大きくかかる文脈に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚。サーバーに大きくかかるものではない。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名のこと。かかるものではない。"}, {"text": "年齢", "is_correct": false, "explanation": "生きてきた年数のこと。かかるものではない。"}], "explanations": {"負荷": "人や機械にかかる作業量や重さを表す。サーバーに大きくかかる文脈に合う。", "眠気": "眠くなる感覚。サーバーに大きくかかるものではない。", "名前": "呼び名のこと。かかるものではない。", "年齢": "生きてきた年数のこと。かかるものではない。"}, "sentence_index": 0, "correct_answer": "負荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい機能を負荷して、製品の価格が上がった。", "explanation": "ここは〈付け加える〉の意味（付加、同じ読み）。機能を加える話で、作業量や重さの負荷は合わない。"}, {"text": "アクセルを踏むと、エンジンが負荷する。", "explanation": "ここは〈速度が増す〉の意味（加速）。負荷は作業量や重さで、速さには使わない。"}, {"text": "試合中に選手が肩を負荷した。", "explanation": "ここは〈けがをする〉の意味（負傷）。けがの話なので、作業量や重さの負荷では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "負荷", "is_correct": true, "explanation": "機械にかかる作業量を表す。運転前に調べる対象として合う。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ているときに出す言葉のこと。機械の調査対象ではない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌の言葉のこと。機械の調査対象ではない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の味のこと。機械の運転前に調べるものではない。"}], "explanations": {"負荷": "機械にかかる作業量を表す。運転前に調べる対象として合う。", "寝言": "寝ているときに出す言葉のこと。機械の調査対象ではない。", "歌詞": "歌の言葉のこと。機械の調査対象ではない。", "味": "食べ物の味のこと。機械の運転前に調べるものではない。"}, "sentence_index": 6, "correct_answer": "負荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察が建物を負荷した。", "explanation": "ここは〈取り囲む〉の意味（包囲）。負荷は作業量や重さで、建物を囲む意味には使わない。"}, {"text": "寒いのでマスクを負荷した。", "explanation": "ここは〈身につける〉の意味（装着）。負荷は作業量や重さで、身につける行為には合わない。"}, {"text": "インフルエンザに負荷した。", "explanation": "ここは〈病気がうつる〉の意味（感染）。負荷は作業量や重さなので、病気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大量の処理が重なり、CPUに負荷をかかった。", "corrected_sentence": "大量の処理が重なり、CPUに負荷がかかった。", "error_description": "「かかる」は主語（負荷）を「が」で取る動詞。「を」は誤りで、正しくは「負荷がかかる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35805, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "負荷が高くと、部品が傷みやすい。", "corrected_sentence": "負荷が高いと、部品が傷みやすい。", "error_description": "「高い」に条件の「と」が続くときは「高いと」。「高くと」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「課題」が主語となり、「山積み」の状態を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「山積み」は状態を表すので合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示し、ここでは状態の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、状態の主語には合わない。"}], "correct_answer": "が", "explanations": {"が": "「課題」が主語となり、「山積み」の状態を示す。", "を": "目的語を示すが、「山積み」は状態を表すので合わない。", "に": "場所や相手を示し、ここでは状態の主語にならない。", "へ": "方向を示す助詞で、状態の主語には合わない。"}, "error_tags": {"を": "目的語", "に": "場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "やらなければならないことや、解決しなければならない問題のことです。", "primary_collocate": null, "pronunciation": "かだい", "ipa": "kadai", "syllable_count": 3, "sentences": [{"text": "先生に出された課題を、今週中に提出しなければならない。", "target_word": "課題", "complexity_tier": "T3", "furigana": "先生[せんせい]に出[だ]された課題[かだい]を、今週中[こんしゅうちゅう]に提出[ていしゅつ]しなければならない。", "sentence_source": "generated"}, {"text": "環境問題は、世界が解決すべき大きな課題だ。", "target_word": "課題", "complexity_tier": "T3", "furigana": "環境[かんきょう]問題[もんだい]は、世界[せかい]が解決[かいけつ]すべき大[おお]きな課題[かだい]だ。", "sentence_source": "generated"}, {"text": "今回の試合で、守りに課題が残った。", "target_word": "課題", "complexity_tier": "T3", "furigana": "今回[こんかい]の試合[しあい]で、守[まも]りに課題[かだい]が残[のこ]った。", "sentence_source": "generated"}, {"text": "夏休みの課題が多くて、遊びに行く時間がない。", "target_word": "課題", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの課題[かだい]が多[おお]くて、遊[あそ]びに行[い]く時間[じかん]がない。", "sentence_source": "generated"}, {"text": "会社には、人手不足という課題がある。", "target_word": "課題", "complexity_tier": "T3", "furigana": "会社[かいしゃ]には、人手不足[ひとでぶそく]という課題[かだい]がある。", "sentence_source": "generated"}, {"text": "この課題を終えたら、次の段階に進める。", "target_word": "課題", "complexity_tier": "T3", "furigana": "この課題[かだい]を終[お]えたら、次[つぎ]の段階[だんかい]に進[すす]める。", "sentence_source": "generated"}, {"text": "自分の課題を見つけて、毎日練習している。", "target_word": "課題", "complexity_tier": "T3", "furigana": "自分[じぶん]の課題[かだい]を見[み]つけて、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "課題が山積みで、どこから手をつけるか迷っている。", "target_word": "課題", "complexity_tier": "T3", "furigana": "課題[かだい]が山積[やまづ]みで、どこから手[て]をつけるか迷[まよ]っている。", "sentence_source": "generated"}, {"text": "町の高齢化は、これから取り組むべき課題だ。", "target_word": "課題", "complexity_tier": "T3", "furigana": "町[まち]の高齢化[こうれいか]は、これから取[と]り組[く]むべき課題[かだい]だ。", "sentence_source": "generated"}, {"text": "課題の提出が遅れたので、先生に理由を説明した。", "target_word": "課題", "complexity_tier": "T3", "furigana": "課題[かだい]の提出[ていしゅつ]が遅[おく]れたので、先生[せんせい]に理由[りゆう]を説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "課題", "label": "基本形"}, {"form": "課題が", "label": "主格"}, {"form": "課題を", "label": "目的格"}, {"form": "課題に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "与えられた宿題や、取り組んで解決すべき問題・やるべきこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "課題", "is_correct": true, "explanation": "先生に出された学習上の課題を指し、今週中に提出する対象として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "提出できるものではなく、「提出しなければならない」と合わない。"}, {"text": "財布", "is_correct": false, "explanation": "提出する対象になりにくく、「先生に出された」にも合わない。"}, {"text": "季節", "is_correct": false, "explanation": "提出するものではなく、文の主語と目的語の関係が成り立たない。"}], "explanations": {"課題": "先生に出された学習上の課題を指し、今週中に提出する対象として文に合う。", "天気": "提出できるものではなく、「提出しなければならない」と合わない。", "財布": "提出する対象になりにくく、「先生に出された」にも合わない。", "季節": "提出するものではなく、文の主語と目的語の関係が成り立たない。"}, "sentence_index": 0, "correct_answer": "課題"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関の課題が重すぎて、一人では運べない。", "explanation": "ここは〈荷物〉の意味。課題は取り組むものであり、運べる物には使わない。"}, {"text": "練習で身につけた課題を、試合で発揮した。", "explanation": "ここは〈能力〉の意味。課題は発揮するものではないので合わない。"}, {"text": "今日は朝から課題が晴れて、気持ちがいい。", "explanation": "ここは〈空〉の意味。空は晴れるが、課題は晴れたり曇ったりしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "課題", "is_correct": true, "explanation": "自分が取り組む学習上の課題を指し、「見つけて練習する」に合う。"}, {"text": "天井", "is_correct": false, "explanation": "見つけて練習する対象にならず、文が成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "練習の対象にはならず、「自分の」と結びつかない。"}, {"text": "湖", "is_correct": false, "explanation": "練習する対象にならず、「毎日練習している」と合わない。"}], "explanations": {"課題": "自分が取り組む学習上の課題を指し、「見つけて練習する」に合う。", "天井": "見つけて練習する対象にならず、文が成り立たない。", "座布団": "練習の対象にはならず、「自分の」と結びつかない。", "湖": "練習する対象にならず、「毎日練習している」と合わない。"}, "sentence_index": 6, "correct_answer": "課題"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この課題は甘くて、子どもがよく食べる。", "explanation": "ここは〈料理〉の意味。課題は食べ物ではないので、甘い・食べるとは言わない。"}, {"text": "この布は課題が強くて、雨に濡れても平気だ。", "explanation": "ここは〈素材〉の意味。課題は布の強さには使わない。"}, {"text": "午後から課題が崩れると、ニュースが言っていた。", "explanation": "ここは〈天気〉の意味。天気は崩れるが、課題は崩れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今週の課題を終わらなくて、困っている。", "corrected_sentence": "今週の課題が終わらなくて、困っている。", "error_description": "「課題」に続く助詞が誤り。「終わる」は自動詞なので、主語を示す「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35806, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生徒は、先生に出された課題を歌った。", "corrected_sentence": "生徒は、先生に出された課題を片付けた。", "error_description": "「課題」に続く動詞が誤り。課題は「片付ける」「終える」ものであり、「歌う」は曲や歌詞に使うので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "「軽視」は「重視」の対義語で、大切に思わず軽く扱う意味。"}, {"text": "尊重", "is_correct": false, "explanation": "「尊重」は相手の意見や権利を大切にする意味で、「重視」の類義語であって対義語ではない。"}, {"text": "検討", "is_correct": false, "explanation": "「検討」は良し悪しを調べて考える意味で、「重視」の対義語ではない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除」は汚れを取る意味で、「重視」とは意味の関係がない。"}], "correct_answer": "軽視", "explanations": {"軽視": "「軽視」は「重視」の対義語で、大切に思わず軽く扱う意味。", "尊重": "「尊重」は相手の意見や権利を大切にする意味で、「重視」の類義語であって対義語ではない。", "検討": "「検討」は良し悪しを調べて考える意味で、「重視」の対義語ではない。", "掃除": "「掃除」は汚れを取る意味で、「重視」とは意味の関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重視する」の目的語を示す格助詞で、「誠実さを重視する」と続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「誠実さが重視する」では目的語が欠けて文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐため、「誠実さの重視する人」では動詞の目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すため、動詞「重視する」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「重視する」の目的語を示す格助詞で、「誠実さを重視する」と続く。", "が": "「が」は主語を示すため、「誠実さが重視する」では目的語が欠けて文が成り立たない。", "の": "「の」は名詞どうしをつなぐため、「誠実さの重視する人」では動詞の目的語を示せない。", "から": "「から」は起点や理由を示すため、動詞「重視する」の目的語にはならない。"}, "error_tags": {"が": "主語", "の": "所有・修飾", "から": "起点・理由"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "「軽視」は「重視」の対義語で、大切に思わず軽く扱う意味。"}, {"text": "作曲", "is_correct": false, "explanation": "音楽を作ることを表し、「重視」の対義語ではない。"}, {"text": "監督", "is_correct": false, "explanation": "「監督」は見守って指示する意味で、「重視」とは意味の関係がない。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」は壊れた物を直す意味で、「重視」とは意味の関係がない。"}], "correct_answer": "軽視", "explanations": {"軽視": "「軽視」は「重視」の対義語で、大切に思わず軽く扱う意味。", "作曲": "音楽を作ることを表し、「重視」の対義語ではない。", "監督": "「監督」は見守って指示する意味で、「重視」とは意味の関係がない。", "修理": "「修理」は壊れた物を直す意味で、「重視」とは意味の関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをとても大切に思うこと。", "primary_collocate": null, "pronunciation": "じゅうし", "ipa": "dʑɯːɕi", "syllable_count": 3, "sentences": [{"text": "祖母は家族の絆をとても重視していて、毎週みんなを集めます。", "target_word": "重視", "complexity_tier": "T3", "furigana": "祖母[そぼ]は家族[かぞく]の絆[きずな]をとても重視[じゅうし]していて、毎週[まいしゅう]みんなを集[あつ]めます。", "sentence_source": "generated"}, {"text": "私は約束を守ることを重視していますので、遅刻は絶対にしません。", "target_word": "重視", "complexity_tier": "T3", "furigana": "私[わたし]は約束[やくそく]を守[まも]ることを重視[じゅうし]していますので、遅刻[ちこく]は絶対[ぜったい]にしません。", "sentence_source": "generated"}, {"text": "日本の会社は昔から、年功を重視する傾向がありました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "日本[にほん]の会社[かいしゃ]は昔[むかし]から、年功[ねんこう]を重視[じゅうし]する傾向[けいこう]がありました。", "sentence_source": "generated"}, {"text": "彼女は友人の意見を重視して、自分の考えを少し変えました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は友人[ゆうじん]の意見[いけん]を重視[じゅうし]して、自分[じぶん]の考[かんが]えを少[すこ]し変[か]えました。", "sentence_source": "generated"}, {"text": "医者は患者との信頼関係を重視しています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]との信頼[しんらい]関係[かんけい]を重視[じゅうし]しています。", "sentence_source": "generated"}, {"text": "親が成績ばかり重視すると、子どもは楽しく学べなくなります。", "target_word": "重視", "complexity_tier": "T3", "furigana": "親[おや]が成績[せいせき]ばかり重視[じゅうし]すると、子[こ]どもは楽[たの]しく学[まな]べなくなります。", "sentence_source": "generated"}, {"text": "この国では、自然との共生が昔から重視されてきました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "この国[くに]では、自然[しぜん]との共生[きょうせい]が昔[むかし]から重視[じゅうし]されてきました。", "sentence_source": "generated"}, {"text": "結婚相手に誠実さを重視する人は少なくありません。", "target_word": "重視", "complexity_tier": "T3", "furigana": "結婚[けっこん]相手[あいて]に誠実[せいじつ]さを重視[じゅうし]する人[ひと]は少[すく]なくありません。", "sentence_source": "generated"}, {"text": "私たちのチームは、勝つことよりも仲間を重視しています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "私[わたし]たちのチームは、勝[か]つことよりも仲間[なかま]を重視[じゅうし]しています。", "sentence_source": "generated"}, {"text": "上司が時間を重視する人なので、会議は必ず定刻に始まります。", "target_word": "重視", "complexity_tier": "T3", "furigana": "上司[じょうし]が時間[じかん]を重視[じゅうし]する人[ひと]なので、会議[かいぎ]は必[かなら]ず定刻[ていこく]に始[はじ]まります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重視する", "label": "終止形"}, {"form": "重視した", "label": "過去形"}, {"form": "重視して", "label": "て形"}, {"form": "重視される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "人や価値観、約束などを心の中でとても大切なものと考えること。する動詞として使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 年功 (Zipf 1.89)']::text[], '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重視", "is_correct": true, "explanation": "「重視」は「大切に思う」の意味で、家族の絆を大切にする文に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除」は汚れを取る動作で、「絆を掃除する」とは言わないので空所に入らない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物やサービスを頼む意味で、「絆を注文する」は不自然なので空所に入らない。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は目的地へ向かうことで、「絆をとても出発していて」とは続かないので空所に入らない。"}], "explanations": {"重視": "「重視」は「大切に思う」の意味で、家族の絆を大切にする文に合う。", "掃除": "「掃除」は汚れを取る動作で、「絆を掃除する」とは言わないので空所に入らない。", "注文": "「注文」は品物やサービスを頼む意味で、「絆を注文する」は不自然なので空所に入らない。", "出発": "「出発」は目的地へ向かうことで、「絆をとても出発していて」とは続かないので空所に入らない。"}, "sentence_index": 0, "correct_answer": "重視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その発表は会場の重視を集めた。", "explanation": "ここは〈注目〉（人の関心が向くこと）の意味。重視は価値を高く置くことで、人の関心を集める意味では使わない。"}, {"text": "箱の重視を量ったら、二十キロあった。", "explanation": "ここは〈重量〉（重さ）の意味。重視は大切に思うことで、物の重さを表す言葉ではない。"}, {"text": "父の病状は重視だと言われ、すぐに入院が必要になった。", "explanation": "ここは〈重症〉（病気やけががひどいこと）の意味。重視は価値を重く見ることで、病状の重さを表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重視", "is_correct": true, "explanation": "「重視されてきました」で、自然との共生を大切にしてきたという意味になる。"}, {"text": "解決", "is_correct": false, "explanation": "「解決」は問題を片づける意味で、「共生が解決されてきた」とは言えないので空所に入らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「翻訳」は言葉を別の言語に置き換える意味で、「共生が翻訳されてきた」は不自然なので空所に入らない。"}, {"text": "運搬", "is_correct": false, "explanation": "「運搬」は物を運ぶ意味で、「共生が運搬されてきた」は不自然なので空所に入らない。"}], "explanations": {"重視": "「重視されてきました」で、自然との共生を大切にしてきたという意味になる。", "解決": "「解決」は問題を片づける意味で、「共生が解決されてきた」とは言えないので空所に入らない。", "翻訳": "「翻訳」は言葉を別の言語に置き換える意味で、「共生が翻訳されてきた」は不自然なので空所に入らない。", "運搬": "「運搬」は物を運ぶ意味で、「共生が運搬されてきた」は不自然なので空所に入らない。"}, "sentence_index": 6, "correct_answer": "重視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で重視を負った人が病院へ運ばれた。", "explanation": "ここは〈重傷〉（けががひどいこと）の意味。「重傷を負う」と組むのは重傷で、重視は大切に思うことなので合わない。"}, {"text": "ボールは重視に引かれて、地面へ落ちた。", "explanation": "ここは〈重力〉の意味。重視は価値を高く置くことで、物を引く力を表す言葉ではない。"}, {"text": "彼は家族の重視を背負って働いている。", "explanation": "ここは〈重荷〉（大きな負担）の意味。重視は価値を高く置くことで、背負うような負担は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は約束を守ることに重視しています。", "corrected_sentence": "私は約束を守ることを重視しています。", "error_description": "誤：「に」、正：「を」。「重視する」は目的語を「を」で取るので、「守ることを」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35810, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は安全を重視いて、毎朝車を点検しています。", "corrected_sentence": "彼は安全を重視して、毎朝車を点検しています。", "error_description": "誤：「重視いて」、正：「重視して」。「重視する」はサ変動詞なので、て形は「して」になる。「いて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人柄を重視する」の目的語を示す。重視は「〜を重視する」と使う。"}, {"text": "が", "is_correct": false, "explanation": "「人柄が重視する」では主語になり、重視の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す「に」では、重視の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では、重視の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「人柄を重視する」の目的語を示す。重視は「〜を重視する」と使う。", "が": "「人柄が重視する」では主語になり、重視の目的語にならない。", "に": "位置や相手を表す「に」では、重視の対象を示せない。", "から": "起点を表す「から」では、重視の対象を示せない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "ある点を大切だと考えず、重く見ないことを表す対義語。「点数だけでなく努力も重視」の反対。"}, {"text": "機能", "is_correct": false, "explanation": "物の働きを表す名詞で、重視の対義語ではない。"}, {"text": "配慮", "is_correct": false, "explanation": "相手に心を配ることを表し、重視の対義語ではない。"}, {"text": "作業", "is_correct": false, "explanation": "手を動かす仕事を表し、重視の対義語ではない。"}], "correct_answer": "軽視", "explanations": {"軽視": "ある点を大切だと考えず、重く見ないことを表す対義語。「点数だけでなく努力も重視」の反対。", "機能": "物の働きを表す名詞で、重視の対義語ではない。", "配慮": "相手に心を配ることを表し、重視の対義語ではない。", "作業": "手を動かす仕事を表し、重視の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「力を重視しています」の目的語を示す。重視は「〜を重視する」と使う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、重視の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では、重視の対象を示す文の形にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、重視の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「力を重視しています」の目的語を示す。重視は「〜を重視する」と使う。", "へ": "方向を表す「へ」では、重視の対象を示せない。", "と": "並列の「と」では、重視の対象を示す文の形にならない。", "より": "比較の「より」では、重視の対象を示せない。"}, "error_tags": {"へ": "方向", "と": "並列", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "ある点を大切だと考えず、軽く見ることを表す対義語。「景色を重視して選んだ」の反対。"}, {"text": "建設", "is_correct": false, "explanation": "建物を造ることを表し、重視の対義語ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書の一種で、重視の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す名詞で、重視の対義語ではない。"}], "correct_answer": "軽視", "explanations": {"軽視": "ある点を大切だと考えず、軽く見ることを表す対義語。「景色を重視して選んだ」の反対。", "建設": "建物を造ることを表し、重視の対義語ではない。", "手紙": "文書の一種で、重視の対義語ではない。", "季節": "時期を表す名詞で、重視の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事を特に大切なものとして、注意や関心を向けること。", "primary_collocate": null, "pronunciation": "じゅうし", "ipa": "dʑɯːɕi", "syllable_count": 3, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "戦後[せんご]の都市[とし]計画[けいかく]において、ブルータリズムは機能性[きのうせい]を重視[じゅうし]した新[あら]たな住宅[じゅうたく]様式[ようしき]として普及[ふきゅう]しました。", "sentence_source": "mined"}, {"text": "面接では、経験より人柄を重視する会社が増えています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、経験[けいけん]より人柄[ひとがら]を重視[じゅうし]する会社[かいしゃ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "今年の新製品は、軽さと使いやすさを重視して設計されました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "今年[ことし]の新製品[しんせいひん]は、軽[かる]さと使[つか]いやすさを重視[じゅうし]して設計[せっけい]されました。", "sentence_source": "generated"}, {"text": "先生は点数だけでなく、毎日の努力も重視しています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "先生[せんせい]は点数[てんすう]だけでなく、毎日[まいにち]の努力[どりょく]も重視[じゅうし]しています。", "sentence_source": "generated"}, {"text": "健康を重視する父は、毎朝一時間歩いています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "健康[けんこう]を重視[じゅうし]する父[ちち]は、毎朝[まいあさ]一時間[いちじかん]歩[ある]いています。", "sentence_source": "generated"}, {"text": "彼は見た目を重視するあまり、中身を確認しませんでした。", "target_word": "重視", "complexity_tier": "T3", "furigana": "彼[かれ]は見[み]た目[め]を重視[じゅうし]するあまり、中身[なかみ]を確認[かくにん]しませんでした。", "sentence_source": "generated"}, {"text": "安全を重視した結果、工事の完成は予定より遅れました。", "target_word": "重視", "complexity_tier": "T3", "furigana": "安全[あんぜん]を重視[じゅうし]した結果[けっか]、工事[こうじ]の完成[かんせい]は予定[よてい]より遅[おく]れました。", "sentence_source": "generated"}, {"text": "この学校は、生徒が自分で考える力を重視しています。", "target_word": "重視", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、生徒[せいと]が自分[じぶん]で考[かんが]える力[ちから]を重視[じゅうし]しています。", "sentence_source": "generated"}, {"text": "値段を重視するなら、この店で買うほうが得です。", "target_word": "重視", "complexity_tier": "T3", "furigana": "値段[ねだん]を重視[じゅうし]するなら、この店[みせ]で買[か]うほうが得[とく]です。", "sentence_source": "generated"}, {"text": "景色を重視して選んだ部屋なので、駅から少し遠いです。", "target_word": "重視", "complexity_tier": "T3", "furigana": "景色[けしき]を重視[じゅうし]して選[えら]んだ部屋[へや]なので、駅[えき]から少[すこ]し遠[とお]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重視する", "label": "終止形"}, {"form": "重視した", "label": "過去形"}, {"form": "重視して", "label": "て形"}, {"form": "重視しない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "ある点を特に大切だと考え、判断や設計の際にそこへ注意を向けること。する動詞として使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重視", "is_correct": true, "explanation": "「機能性を重視した」の動詞。機能性を大切だと考えて注目したという意味になる。"}, {"text": "機能", "is_correct": false, "explanation": "「機能性を機能した」と動詞として成立せず、文が意味をなさない。"}, {"text": "重要", "is_correct": false, "explanation": "形容動詞で、「機能性を重要した」とは言えない。"}, {"text": "安定", "is_correct": false, "explanation": "「機能性を安定した」は成立せず、目的語に合わない。"}], "explanations": {"重視": "「機能性を重視した」の動詞。機能性を大切だと考えて注目したという意味になる。", "機能": "「機能性を機能した」と動詞として成立せず、文が意味をなさない。", "重要": "形容動詞で、「機能性を重要した」とは言えない。", "安定": "「機能性を安定した」は成立せず、目的語に合わない。"}, "sentence_index": 0, "correct_answer": "重視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の重視を量ったら、二十キロあった。", "explanation": "ここは〈重量〉（重さ）の意味。重視は注意や関心を向けることで、物の重さは表さないので合わない。"}, {"text": "父の病状は重視だと言われ、すぐに入院が必要になった。", "explanation": "ここは〈重症〉（病気がひどいこと）の意味。重視は注意を向けることで、病状の重さは表さないので合わない。"}, {"text": "ボールは重視に引かれて、地面へ落ちた。", "explanation": "ここは〈重力〉の意味。重視は注意を向けることで、物を引く力は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重視", "is_correct": true, "explanation": "「安全を重視した結果」の動詞。安全を大切にしたという意味になる。"}, {"text": "完成", "is_correct": false, "explanation": "「安全を完成した」は成立せず、目的語に合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "「安全を卒業した」は成立せず、文が意味をなさない。"}, {"text": "出発", "is_correct": false, "explanation": "「安全を出発した」は成立せず、文が意味をなさない。"}], "explanations": {"重視": "「安全を重視した結果」の動詞。安全を大切にしたという意味になる。", "完成": "「安全を完成した」は成立せず、目的語に合わない。", "卒業": "「安全を卒業した」は成立せず、文が意味をなさない。", "出発": "「安全を出発した」は成立せず、文が意味をなさない。"}, "sentence_index": 6, "correct_answer": "重視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話を重視して、部屋を出た。", "explanation": "ここは〈切る〉の意味。通話を終えることは切るで、重視は大切なものとして関心を向けることなので合わない。"}, {"text": "棚に本を載せすぎて、重視で板が割れた。", "explanation": "ここは〈重さ〉の意味。重視は注意や関心を向けることで、物の重さは表さないので合わない。"}, {"text": "玄関のドアを重視して、外へ出た。", "explanation": "ここは〈閉める〉の意味。ドアを閉めることは閉めるで、重視は大切なものとして関心を向けることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は味を重視しで、新鮮な材料を使っています。", "corrected_sentence": "この店は味を重視して、新鮮な材料を使っています。", "error_description": "「重視して」の濁音化「重視しで」は誤り。て形は「して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35811, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は価格を重視せ、品質を選んだ。", "corrected_sentence": "私は価格を重視せず、品質を選んだ。", "error_description": "否定の「ず」が必要。「重視せ」は誤った活用で、正しくは「重視せず」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「体の動きが遅くなる」の「が」。遅くなるものを示す主語の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に使う。「遅くなる」は自動詞なので「動きを」は文法に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」を入れると「動きに遅くなる」となり、「遅くなる」の結果を表す語として合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」を入れると「動きの遅くなる」となり、文の述語が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「体の動きが遅くなる」の「が」。遅くなるものを示す主語の助詞。", "を": "「を」は他動詞の目的語に使う。「遅くなる」は自動詞なので「動きを」は文法に合わない。", "に": "「に」を入れると「動きに遅くなる」となり、「遅くなる」の結果を表す語として合わない。", "の": "「の」を入れると「動きの遅くなる」となり、文の述語が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「表情の動きから、うそをついているとわかった」の「から」。手がかりや根拠を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「動きへ、うそをついている」では根拠の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」を入れると「動きと、うそをついている」となり、根拠を示す文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準。「動きより、うそをついている」は根拠を示せない。"}], "correct_answer": "から", "explanations": {"から": "「表情の動きから、うそをついているとわかった」の「から」。手がかりや根拠を示す。", "へ": "「へ」は方向を示す。「動きへ、うそをついている」では根拠の意味にならない。", "と": "「と」を入れると「動きと、うそをついている」となり、根拠を示す文の意味が通らない。", "より": "「より」は比較の基準。「動きより、うそをついている」は根拠を示せない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをするときの、体や心のようすのこと。", "primary_collocate": null, "pronunciation": "うごき", "ipa": "ɯɡoki", "syllable_count": 3, "sentences": [{"text": "ダンサーの動きがとてもなめらかで、みんな目をうばわれた。", "target_word": "動き", "complexity_tier": "T3", "furigana": "ダンサーの動[うご]きがとてもなめらかで、みんな目[め]をうばわれた。", "sentence_source": "generated"}, {"text": "年をとると、体の動きが少しずつ遅くなる。", "target_word": "動き", "complexity_tier": "T3", "furigana": "年[とし]をとると、体[からだ]の動[うご]きが少[すこ]しずつ遅[おそ]くなる。", "sentence_source": "generated"}, {"text": "犬は人の動きを見て、散歩に行くとわかった。", "target_word": "動き", "complexity_tier": "T3", "furigana": "犬[いぬ]は人[ひと]の動[うご]きを見[み]て、散歩[さんぽ]に行[い]くとわかった。", "sentence_source": "generated"}, {"text": "彼女の動きには無駄がなく、見ていて気持ちがいい。", "target_word": "動き", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の動[うご]きには無駄[むだ]がなく、見[み]ていて気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "面接では、相手の心の動きを読むことも大切だ。", "target_word": "動き", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、相手[あいて]の心[こころ]の動[うご]きを読[よ]むことも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "緊張して、足の動きがかたくなってしまった。", "target_word": "動き", "complexity_tier": "T3", "furigana": "緊張[きんちょう]して、足[あし]の動[うご]きがかたくなってしまった。", "sentence_source": "generated"}, {"text": "先生は、子どもたちの動きを見ながら、体操を教えた。", "target_word": "動き", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもたちの動[うご]きを見[み]ながら、体操[たいそう]を教[おし]えた。", "sentence_source": "generated"}, {"text": "彼の表情の動きから、うそをついているとわかった。", "target_word": "動き", "complexity_tier": "T3", "furigana": "彼[かれ]の表情[ひょうじょう]の動[うご]きから、うそをついているとわかった。", "sentence_source": "generated"}, {"text": "選手は相手の動きを読んで、すばやくボールを取った。", "target_word": "動き", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は相手[あいて]の動[うご]きを読[よ]んで、すばやくボールを取[と]った。", "sentence_source": "generated"}, {"text": "毎朝ストレッチをすると、体の動きが軽くなる。", "target_word": "動き", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]ストレッチをすると、体[からだ]の動[うご]きが軽[かる]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動き", "label": "基本形"}], "register": "ふつうの話し言葉・書き言葉（常体）", "sense_fingerprint": "人の体の動作や心の変化のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: うばわ (Zipf 2.03)']::text[], '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動き", "is_correct": true, "explanation": "「ダンサーの動き」は踊りの体の動きのこと。なめらかさを述べるのに合う。"}, {"text": "ため息", "is_correct": false, "explanation": "ため息は息を吐くこと。「なめらか」に動くものとしては文に合わない。"}, {"text": "影", "is_correct": false, "explanation": "影は光によってできる暗い部分。「なめらか」と組み合わせて人の動作は表せない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は表情のこと。「なめらか」に動くものとしては文の意味に合わない。"}], "explanations": {"動き": "「ダンサーの動き」は踊りの体の動きのこと。なめらかさを述べるのに合う。", "ため息": "ため息は息を吐くこと。「なめらか」に動くものとしては文に合わない。", "影": "影は光によってできる暗い部分。「なめらか」と組み合わせて人の動作は表せない。", "笑顔": "笑顔は表情のこと。「なめらか」に動くものとしては文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "動き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外国語の動きが得意で、すぐ話せるようになった。", "explanation": "ここは〈語学力〉の意味。動きは体や心のようすで、言葉を使う力は指さないので合わない。"}, {"text": "彼はピアノの動きに恵まれ、少ない練習で上達した。", "explanation": "ここは「才能」の意味。動きは体や心の動作のようすで、生まれつきの能力は指さないので合わない。"}, {"text": "この鍋の動きはとても重く、一人では持ち上げられない。", "explanation": "ここは〈重さ〉の意味。動きは体や心のようすで、物の重さは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動き", "is_correct": true, "explanation": "「子どもたちの動きを見ながら」は子どもの体の動きを見る意味。文に合う。"}, {"text": "声", "is_correct": false, "explanation": "声は聞くもの。「見ながら」と組み合わせると文の意味が通らない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は聴くもの。「子どもたちの歌を見ながら」は不自然で、体操の文脈にも合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は聞こえるもの。「見ながら」とは組み合わず、文の意味が通らない。"}], "explanations": {"動き": "「子どもたちの動きを見ながら」は子どもの体の動きを見る意味。文に合う。", "声": "声は聞くもの。「見ながら」と組み合わせると文の意味が通らない。", "歌": "歌は聴くもの。「子どもたちの歌を見ながら」は不自然で、体操の文脈にも合わない。", "足音": "足音は聞こえるもの。「見ながら」とは組み合わず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "動き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープの動きは、少し塩辛くて飲みにくい。", "explanation": "ここは〈味〉の意味。動きは体や心のようすで、料理の味は指さないので合わない。"}, {"text": "このタンスの動きは思ったより重く、一人では運べない。", "explanation": "ここは〈重さ〉の意味。動きは体や心のようすで、家具の重さは指さないので合わない。"}, {"text": "彼女は、母の店の動きを手紙に書いた。", "explanation": "ここは〈商売の様子〉の意味。動きは体や心のようすで、店の経営状況は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の動きを合わせて、みんなが手をたたいた。", "corrected_sentence": "彼女の動きに合わせて、みんなが手をたたいた。", "error_description": "誤った形は「動きを合わせて」。「合わせる」は「〜に合わせる」なので、動きに付く助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35812, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝ストレッチを続けると、体の動きを軽くなる。", "corrected_sentence": "毎朝ストレッチを続けると、体の動きが軽くなる。", "error_description": "誤った形は「動きを軽くなる」。「軽くなる」は自動詞なので、主語の「体の動き」には「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「世の中の動きが速くて」の「が」。速いものを示す主語の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「動きを速くて」は文として成り立たず、「を」は目的語には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「動きに速くて」は述語と結びつかず、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「動きで速くて」は手段や原因として不自然で、述語の関係が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「世の中の動きが速くて」の「が」。速いものを示す主語の助詞。", "を": "「動きを速くて」は文として成り立たず、「を」は目的語には合わない。", "に": "「動きに速くて」は述語と結びつかず、文の意味が通らない。", "で": "「動きで速くて」は手段や原因として不自然で、述語の関係が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人口の動きを調べると」の「を」。調べる対象を示す目的語の助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「動きへ調べる」は対象の関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「動きと調べる」は並列の意味になり、調べる対象としては合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準。「動きより調べる」は文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「人口の動きを調べると」の「を」。調べる対象を示す目的語の助詞。", "へ": "「へ」は方向を示す。「動きへ調べる」は対象の関係が成り立たない。", "と": "「動きと調べる」は並列の意味になり、調べる対象としては合わない。", "より": "「より」は比較の基準。「動きより調べる」は文の意味が通らない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が変化したり、何かが行われたりするようす。また、そのような変化や行動の傾向。", "primary_collocate": null, "pronunciation": "うごき", "ipa": "ɯɡoki", "syllable_count": 3, "sentences": [{"text": "来月から、株価の動きに注意したほうがいい。", "target_word": "動き", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、株価[かぶか]の動[うご]きに注意[ちゅうい]したほうがいい。", "sentence_source": "generated"}, {"text": "世の中の動きが速くて、ニュースを見るのが大変だ。", "target_word": "動き", "complexity_tier": "T3", "furigana": "世[よ]の中[なか]の動[うご]きが速[はや]くて、ニュースを見[み]るのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "政府は、景気の動きを見て新しい政策を決めた。", "target_word": "動き", "complexity_tier": "T3", "furigana": "政府[せいふ]は、景気[けいき]の動[うご]きを見[み]て新[あたら]しい政策[せいさく]を決[き]めた。", "sentence_source": "generated"}, {"text": "会社の中で、社長を変えようという動きが出てきた。", "target_word": "動き", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の中[なか]で、社長[しゃちょう]を変[か]えようという動[うご]きが出[で]てきた。", "sentence_source": "generated"}, {"text": "町では、駅の近くに店を作ろうという動きが広がっている。", "target_word": "動き", "complexity_tier": "T3", "furigana": "町[まち]では、駅[えき]の近[ちか]くに店[みせ]を作[つく]ろうという動[うご]きが広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "為替の動きが大きいので、旅行の前にお金を替えておいた。", "target_word": "動き", "complexity_tier": "T3", "furigana": "為替[かわせ]の動[うご]きが大[おお]きいので、旅行[りょこう]の前[まえ]にお金[かね]を替[か]えておいた。", "sentence_source": "generated"}, {"text": "環境を守ろうとする動きは、世界中で強まっている。", "target_word": "動き", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]ろうとする動[うご]きは、世界中[せかいじゅう]で強[つよ]まっている。", "sentence_source": "generated"}, {"text": "人口の動きを調べると、若い人が都会に集まっていることがわかる。", "target_word": "動き", "complexity_tier": "T3", "furigana": "人口[じんこう]の動[うご]きを調[しら]べると、若[わか]い人[ひと]が都会[とかい]に集[あつ]まっていることがわかる。", "sentence_source": "generated"}, {"text": "各国の動きを見てから、わたしたちの会社も決めよう。", "target_word": "動き", "complexity_tier": "T3", "furigana": "各国[かっこく]の動[うご]きを見[み]てから、わたしたちの会社[かいしゃ]も決[き]めよう。", "sentence_source": "generated"}, {"text": "物価の動きを毎月ニュースで確認している。", "target_word": "動き", "complexity_tier": "T3", "furigana": "物価[ぶっか]の動[うご]きを毎月[まいつき]ニュースで確認[かくにん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動き", "label": "基本形"}], "register": "ふつうの話し言葉・書き言葉（常体）", "sense_fingerprint": "社会・経済・組織などの変化や動向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動き", "is_correct": true, "explanation": "「株価の動きに注意する」は株価の変化や動向を見るという意味。文に合う。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている時の発言。株価の変化に注意するという文には合わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は表情のこと。株価の変化に注意するという文には合わない。"}, {"text": "響き", "is_correct": false, "explanation": "響きは音の余韻。株価に対して注意する対象ではない。"}], "explanations": {"動き": "「株価の動きに注意する」は株価の変化や動向を見るという意味。文に合う。", "寝言": "寝言は眠っている時の発言。株価の変化に注意するという文には合わない。", "笑顔": "笑顔は表情のこと。株価の変化に注意するという文には合わない。", "響き": "響きは音の余韻。株価に対して注意する対象ではない。"}, "sentence_index": 0, "correct_answer": "動き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は、町の地図の動きを見て新しい道路を決めた。", "explanation": "ここは〈地図上の線や形〉の意味。地図は動かないものなので、物事の変化や動向を表す今回の意味では合わない。"}, {"text": "この帽子の動きはぴったりで、頭によく合う。", "explanation": "ここは〈サイズ〉の意味。動きは変化や動向で、物の大きさや合い具合は指さないので合わない。"}, {"text": "この箱の動きは、本棚にちょうど入るほど小さい。", "explanation": "ここは〈大きさ〉の意味。動きは変化や動向で、物の寸法は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動き", "is_correct": true, "explanation": "「環境を守ろうとする動きが強まる」は社会の動向が広がるという意味。文に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠たい感じのこと。環境を守る動きが強まるという文には合わない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いのこと。社会の動きが強まるという文には合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は舌で感じるもの。「強まっている」と組み合わせて社会の動向は表せない。"}], "explanations": {"動き": "「環境を守ろうとする動きが強まる」は社会の動向が広がるという意味。文に合う。", "眠気": "眠気は眠たい感じのこと。環境を守る動きが強まるという文には合わない。", "香り": "香りは匂いのこと。社会の動きが強まるという文には合わない。", "味": "味は舌で感じるもの。「強まっている」と組み合わせて社会の動向は表せない。"}, "sentence_index": 6, "correct_answer": "動き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このパンの動きは、ふわふわしていて食べやすい。", "explanation": "ここは〈食感〉の意味。動きは変化や動向で、食べ物のやわらかさは指さないので合わない。"}, {"text": "毎月の動きを、ケーキの材料として買いに行く。", "explanation": "ここは〈材料〉の意味。動きは変化や動向で、食べ物の材料は指さないので合わない。"}, {"text": "妹は、お気に入りの服の動きを何度も手で確かめている。", "explanation": "ここは〈生地の伸び〉の意味。動きは変化や動向で、布の伸び具合は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は、物価の動きに見て新しい政策を決めた。", "corrected_sentence": "政府は、物価の動きを見て新しい政策を決めた。", "error_description": "誤った形は「動きに見て」。「見る」は「〜を見る」なので、動きに付く助詞は「に」ではなく「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35813, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "為替の動きを大きいので、旅行の前に両替をした。", "corrected_sentence": "為替の動きが大きいので、旅行の前に両替をした。", "error_description": "誤った形は「動きを大きい」。形容詞「大きい」の主語となる「為替の動き」には「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拡大", "is_correct": true, "explanation": "大きさや規模を広げる意味で、縮小の対義語。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残す意味で、大きさの対義語ではない。"}, {"text": "変更", "is_correct": false, "explanation": "内容を変える意味で、大きさの対義語ではない。"}, {"text": "発展", "is_correct": false, "explanation": "進んで盛んになる意味で、縮小と対になる関係ではない。"}], "correct_answer": "拡大", "explanations": {"拡大": "大きさや規模を広げる意味で、縮小の対義語。", "保存": "そのまま残す意味で、大きさの対義語ではない。", "変更": "内容を変える意味で、大きさの対義語ではない。", "発展": "進んで盛んになる意味で、縮小と対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「伴う」の対象を示し、「縮小に伴い」となる。"}, {"text": "が", "is_correct": false, "explanation": "「縮小が伴い」は動詞「伴う」の形に合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、「伴う」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、「伴う」の相手にはならない。"}], "correct_answer": "に", "explanations": {"に": "「伴う」の対象を示し、「縮小に伴い」となる。", "が": "「縮小が伴い」は動詞「伴う」の形に合わない。", "で": "手段や場所を示し、「伴う」の対象にはならない。", "へ": "方向を示し、「伴う」の相手にはならない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拡大", "is_correct": true, "explanation": "大きさや規模を広げる意味で、縮小の対義語。"}, {"text": "変化", "is_correct": false, "explanation": "状態が変わる意味で、大きさの対義語ではない。"}, {"text": "発達", "is_correct": false, "explanation": "成長して進む意味で、縮小と対になる関係ではない。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残す意味で、大きさの対義語ではない。"}], "correct_answer": "拡大", "explanations": {"拡大": "大きさや規模を広げる意味で、縮小の対義語。", "変化": "状態が変わる意味で、大きさの対義語ではない。", "発達": "成長して進む意味で、縮小と対になる関係ではない。", "保存": "そのまま残す意味で、大きさの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "大きかったものが、小さくなること。", "primary_collocate": null, "pronunciation": "しゅくしょう", "ipa": "ɕɯkɯɕoː", "syllable_count": 4, "sentences": [{"text": "売り上げが落ちたため、店の規模を縮小することになった。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが落[お]ちたため、店[みせ]の規模[きぼ]を縮小[しゅくしょう]することになった。", "sentence_source": "generated"}, {"text": "地図を縮小して、手帳にはさめる大きさにした。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "地図[ちず]を縮小[しゅくしょう]して、手帳[てちょう]にはさめる大[おお]きさにした。", "sentence_source": "generated"}, {"text": "不況で、会社は事業の縮小を発表した。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "不況[ふきょう]で、会社[かいしゃ]は事業[じぎょう]の縮小[しゅくしょう]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "写真を縮小すると、細かい文字が読めなくなる。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "写真[しゃしん]を縮小[しゅくしょう]すると、細[こま]かい文字[もじ]が読[よ]めなくなる。", "sentence_source": "generated"}, {"text": "人口が減り、町の商店街は縮小している。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "人口[じんこう]が減[へ]り、町[まち]の商店街[しょうてんがい]は縮小[しゅくしょう]している。", "sentence_source": "generated"}, {"text": "予算の縮小により、行事の数が減った。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "予算[よさん]の縮小[しゅくしょう]により、行事[ぎょうじ]の数[かず]が減[へ]った。", "sentence_source": "generated"}, {"text": "画面を縮小して、表の全体を見た。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "画面[がめん]を縮小[しゅくしょう]して、表[ひょう]の全体[ぜんたい]を見[み]た。", "sentence_source": "generated"}, {"text": "工場の縮小に伴い、働く人の数も減った。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "工場[こうじょう]の縮小[しゅくしょう]に伴[ともな]い、働[はたら]く人[ひと]の数[かず]も減[へ]った。", "sentence_source": "generated"}, {"text": "軍備を縮小するよう、各国に求める声がある。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "軍備[ぐんび]を縮小[しゅくしょう]するよう、各国[かっこく]に求[もと]める声[こえ]がある。", "sentence_source": "generated"}, {"text": "資料が大きすぎるので、A4に縮小して印刷した。", "target_word": "縮小", "complexity_tier": "T3", "furigana": "資料[しりょう]が大[おお]きすぎるので、A4に縮小[しゅくしょう]して印刷[いんさつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縮小", "label": "基本形"}, {"form": "縮小する", "label": "サ変動詞・終止形"}, {"form": "縮小した", "label": "サ変動詞・過去形"}, {"form": "縮小して", "label": "サ変動詞・て形"}, {"form": "縮小しない", "label": "サ変動詞・否定形"}], "register": "neutral", "sense_fingerprint": "規模・大きさ・数量などが小さくなる、または小さくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: はさめる (Zipf 1.24)']::text[], 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "縮小", "is_correct": true, "explanation": "規模を小さくする意味で、「店の規模を縮小することになった」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "規模を変える対象にならず、文が成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "規模に対して使う語ではなく、文に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "規模を小さくする対象にはならず、文が成り立たない。"}], "explanations": {"縮小": "規模を小さくする意味で、「店の規模を縮小することになった」に合う。", "天気": "規模を変える対象にならず、文が成り立たない。", "切手": "規模に対して使う語ではなく、文に合わない。", "天井": "規模を小さくする対象にはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "縮小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は本当の気持ちを縮小して、笑って見せた。", "explanation": "ここは〈隠す〉の意味。気持ちは隠すと言い、縮小は規模などに使う。"}, {"text": "友達との関係を縮小して、連絡もしなくなった。", "explanation": "ここは〈疎遠になる〉の意味。関係は薄れると言い、縮小は規模などに使う。"}, {"text": "彼女は怒られて、態度を縮小した。", "explanation": "ここは〈しおらしくなる〉の意味。態度は改まると言い、縮小は規模などに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縮小", "is_correct": true, "explanation": "画面を小さくする操作を表し、「表の全体を見た」に合う。"}, {"text": "座布団", "is_correct": false, "explanation": "画面に対して使う語ではなく、文が成り立たない。"}, {"text": "湖", "is_correct": false, "explanation": "画面を操作する対象にならず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "画面を操作する対象にならず、文が成り立たない。"}], "explanations": {"縮小": "画面を小さくする操作を表し、「表の全体を見た」に合う。", "座布団": "画面に対して使う語ではなく、文が成り立たない。", "湖": "画面を操作する対象にならず、文に合わない。", "季節": "画面を操作する対象にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "縮小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は怒りを縮小して、冷静に話した。", "explanation": "ここは〈抑える〉の意味。怒りは抑えると言い、縮小は規模などに使う。"}, {"text": "果汁を縮小して、濃いジャムを作った。", "explanation": "ここは〈凝縮〉の意味。中身を濃くする場合は凝縮を使う。"}, {"text": "彼は意見を縮小して、相手に合わせた。", "explanation": "ここは〈譲る〉の意味。意見は譲ると言い、縮小は規模などに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は、規模の縮小が発表した。", "corrected_sentence": "店は、規模の縮小を発表した。", "error_description": "「縮小」の後は発表の目的語を示す「を」が必要。「発表する」は他動詞なので「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35814, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は人員を縮小したて、新しい方法を試した。", "corrected_sentence": "会社は人員を縮小して、新しい方法を試した。", "error_description": "サ変動詞「縮小する」のて形は「縮小して」。「縮小したて」は「したて」の誤用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
