INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35816, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "年をとっていること。", "primary_collocate": null, "pronunciation": "こうれい", "ipa": "koːɾeː", "syllable_count": 4, "sentences": [{"text": "祖母は高齢なので、長い距離を歩くのは大変だ。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "祖母[そぼ]は高齢[こうれい]なので、長[なが]い距離[きょり]を歩[ある]くのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "高齢になっても、毎朝散歩を続けたいと思う。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]になっても、毎朝[まいあさ]散歩[さんぽ]を続[つづ]けたいと思[おも]う。", "sentence_source": "generated"}, {"text": "高齢の犬は、あまり走らずに一日中寝ている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の犬[いぬ]は、あまり走[はし]らずに一日中[いちにちじゅう]寝[ね]ている。", "sentence_source": "generated"}, {"text": "彼は高齢にもかかわらず、今も現役で働いている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "彼[かれ]は高齢[こうれい]にもかかわらず、今[いま]も現役[げんえき]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "高齢の母に代わって、私が手続きに行った。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の母[はは]に代[か]わって、私[わたし]が手続[てつづ]きに行[い]った。", "sentence_source": "generated"}, {"text": "父は高齢になってから、新しい趣味を始めた。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "父[ちち]は高齢[こうれい]になってから、新[あたら]しい趣味[しゅみ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "高齢の人は、階段の上り下りに気をつけたほうがいい。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の人[ひと]は、階段[かいだん]の上[のぼ]り下[くだ]りに気[き]をつけたほうがいい。", "sentence_source": "generated"}, {"text": "彼女は高齢で足が弱くなり、杖を使っている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は高齢[こうれい]で足[あし]が弱[よわ]くなり、杖[つえ]を使[つか]っている。", "sentence_source": "generated"}, {"text": "高齢の猫には、やわらかい食べ物をあげている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の猫[ねこ]には、やわらかい食[た]べ物[もの]をあげている。", "sentence_source": "generated"}, {"text": "社長は高齢だが、会議ではいつも元気に話す。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は高齢[こうれい]だが、会議[かいぎ]ではいつも元気[げんき]に話[はな]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高齢の", "label": "連体形"}, {"form": "高齢で", "label": "で形"}, {"form": "高齢だ", "label": "断定形"}, {"form": "高齢になる", "label": "変化形"}, {"form": "高齢だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "人や動物が年をとっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高齢", "is_correct": true, "explanation": "年をとっている状態を表し、「祖母は高齢なので」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "人の状態を表す語ではなく、「祖母は天気なので」は成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "人の状態を表す語ではなく、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "人の状態を表す語ではなく、「祖母は季節なので」は成り立たない。"}], "explanations": {"高齢": "年をとっている状態を表し、「祖母は高齢なので」に合う。", "天気": "人の状態を表す語ではなく、「祖母は天気なので」は成り立たない。", "財布": "人の状態を表す語ではなく、文に合わない。", "季節": "人の状態を表す語ではなく、「祖母は季節なので」は成り立たない。"}, "sentence_index": 0, "correct_answer": "高齢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家は高齢で、柱が傾いている。", "explanation": "ここは〈古い〉の意味。建物には高齢を使わず、古いと言う。"}, {"text": "この技術は高齢で、専門家しか扱えない。", "explanation": "ここは〈高度〉の意味。技術の水準は高度と言い、高齢とは言わない。"}, {"text": "夏は高齢で涼しく過ごした。", "explanation": "ここは〈高冷地〉の意味。場所は「高冷地」と言い、高齢とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高齢", "is_correct": true, "explanation": "年をとっている人を表し、「高齢の人は」に合う。"}, {"text": "座布団", "is_correct": false, "explanation": "人を表す語ではなく、「座布団の人」は成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "人を表す語ではなく、文に合わない。"}, {"text": "湖", "is_correct": false, "explanation": "人を表す語ではなく、「湖の人」は成り立たない。"}], "explanations": {"高齢": "年をとっている人を表し、「高齢の人は」に合う。", "座布団": "人を表す語ではなく、「座布団の人」は成り立たない。", "天井": "人を表す語ではなく、文に合わない。", "湖": "人を表す語ではなく、「湖の人」は成り立たない。"}, "sentence_index": 6, "correct_answer": "高齢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体の高齢を防ぐため、毎日運動している。", "explanation": "ここは〈老化〉の意味。高齢は状態を表し、進んでいく過程には使わない。"}, {"text": "この野菜は高齢で取引されている。", "explanation": "ここは〈高値〉の意味。値段が高いことは高値と言い、高齢とは言わない。"}, {"text": "高齢の部活で、毎日練習している。", "explanation": "ここは〈高校〉の意味。部活は高校などの学校に属するもので、高齢とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は高齢をなってから、少し耳が遠くなった。", "corrected_sentence": "母は高齢になってから、少し耳が遠くなった。", "error_description": "「なる」の前は変化の結果を示す「に」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は高齢くなり、よく眠るようになった。", "corrected_sentence": "祖父は高齢になり、よく眠るようになった。", "error_description": "「高齢」は形容動詞型なので、「なる」と続けるには「に」が必要。「くなり」はイ形容詞の活用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
