INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35817, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "年齢が高いこと。特に、老年期にあること。", "primary_collocate": null, "pronunciation": "こうれい", "ipa": "koːɾeː", "syllable_count": 4, "sentences": [{"text": "高齢の患者さんには、ゆっくり説明してください。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の患者[かんじゃ]さんには、ゆっくり説明[せつめい]してください。", "sentence_source": "generated"}, {"text": "高齢の方のために、駅にエレベーターができた。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の方[かた]のために、駅[えき]にエレベーターができた。", "sentence_source": "generated"}, {"text": "日本では、高齢の人が年々増えている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "日本[にほん]では、高齢[こうれい]の人[ひと]が年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "高齢で一人暮らしをするのは、心配なことも多い。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]で一人暮[ひとりぐ]らしをするのは、心配[しんぱい]なことも多[おお]い。", "sentence_source": "generated"}, {"text": "高齢の両親と同じ家に住んで、毎日食事を作っている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の両親[りょうしん]と同[おな]じ家[いえ]に住[す]んで、毎日[まいにち]食事[しょくじ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "高齢になると、病気にかかりやすくなる。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]になると、病気[びょうき]にかかりやすくなる。", "sentence_source": "generated"}, {"text": "高齢の夫婦が、手をつないで公園を歩いていた。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の夫婦[ふうふ]が、手[て]をつないで公園[こうえん]を歩[ある]いていた。", "sentence_source": "generated"}, {"text": "高齢でも働ける仕事を探す人が増えている。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]でも働[はたら]ける仕事[しごと]を探[さが]す人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "高齢の運転者の事故が、ニュースで取り上げられた。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の運転者[うんてんしゃ]の事故[じこ]が、ニュースで取[と]り上[あ]げられた。", "sentence_source": "generated"}, {"text": "高齢の客のために、店は大きな字のメニューを作った。", "target_word": "高齢", "complexity_tier": "T3", "furigana": "高齢[こうれい]の客[きゃく]のために、店[みせ]は大[おお]きな字[じ]のメニューを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高齢の", "label": "連体形"}, {"form": "高齢で", "label": "で形"}, {"form": "高齢だ", "label": "断定形"}, {"form": "高齢になる", "label": "変化形"}, {"form": "高齢だった", "label": "過去形"}], "register": "formal", "sense_fingerprint": "年齢が高く、老年期にあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35817, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高級", "is_correct": false, "explanation": "「高級」は品質の高さを表す語で、「高級の患者さん」とは言わない。"}, {"text": "高齢", "is_correct": true, "explanation": "「高齢の患者さん」は年配の患者を指し、ゆっくり説明する配慮が必要な相手として文に合う。"}, {"text": "新鮮", "is_correct": false, "explanation": "「新鮮」は鮮度を表す語で、人である患者には使えない。"}, {"text": "公共", "is_correct": false, "explanation": "「公共」は社会全体に関わる施設や事業を表し、患者を修飾できない。"}], "explanations": {"高級": "「高級」は品質の高さを表す語で、「高級の患者さん」とは言わない。", "高齢": "「高齢の患者さん」は年配の患者を指し、ゆっくり説明する配慮が必要な相手として文に合う。", "新鮮": "「新鮮」は鮮度を表す語で、人である患者には使えない。", "公共": "「公共」は社会全体に関わる施設や事業を表し、患者を修飾できない。"}, "sentence_index": 0, "correct_answer": "高齢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンは高齢で、もう食べられない。", "explanation": "ここは〈古くなった〉の意味。食べ物の傷みや古さには「古くなる」を使い、〈高齢〉は人の年齢に限るので食べ物には合わない。"}, {"text": "高齢の子が、小さい弟の手を引いて歩いた。", "explanation": "ここは〈年長〉の意味。年上であることを言うなら〈年長〉を使い、〈高齢〉は老年期の意味なので子どもには合わない。"}, {"text": "彼女の高齢は三十歳で、会社でも若い方だ。", "explanation": "ここは〈年齢〉の意味。年齢の数字は「年齢は三十歳」と言い、〈高齢〉は年を重ねた時期を指すので数字とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35817, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木製", "is_correct": false, "explanation": "「木製」は材質を表す語で、夫婦という人の組み合わせには使えない。"}, {"text": "機械", "is_correct": false, "explanation": "「機械」は人ではない物を指すので、夫婦を修飾できない。"}, {"text": "高齢", "is_correct": true, "explanation": "「高齢の夫婦」は年配の二人組を指し、手をつないで公園を歩く場面に合う。"}, {"text": "新品", "is_correct": false, "explanation": "「新品」は商品の状態を表す語で、人の夫婦には使えない。"}], "explanations": {"木製": "「木製」は材質を表す語で、夫婦という人の組み合わせには使えない。", "機械": "「機械」は人ではない物を指すので、夫婦を修飾できない。", "高齢": "「高齢の夫婦」は年配の二人組を指し、手をつないで公園を歩く場面に合う。", "新品": "「新品」は商品の状態を表す語で、人の夫婦には使えない。"}, "sentence_index": 6, "correct_answer": "高齢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高齢の橋を架け替える工事が始まった。", "explanation": "ここは〈老朽〉の意味。橋や建物の傷みには〈老朽〉を使い、〈高齢〉は人の老年期を指すので橋には合わない。"}, {"text": "彼は会社で高齢の役職に就いた。", "explanation": "ここは〈高位〉の意味。役職の高さには〈高位〉を使い、〈高齢〉は年齢の高さなので地位には合わない。"}, {"text": "この遺跡は高齢で、千年前の人々の暮らしを伝えている。", "explanation": "ここは〈古い（年代が昔の）〉の意味。遺跡の古さには「古代の」「昔の」を使い、〈高齢〉は人の年齢の高さを表すので遺跡には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高齢に父は、毎朝公園を散歩している。", "corrected_sentence": "高齢の父は、毎朝公園を散歩している。", "error_description": "「高齢」は名詞なので、後ろの名詞を修飾するには「の」が要る。ここで「に」を付けたのが誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高齢すると、体力が落ちやすくなる。", "corrected_sentence": "高齢になると、体力が落ちやすくなる。", "error_description": "「高齢」は「する」を付けて動詞にできない名詞なので、「高齢すると」は誤り。年を重ねるという意味では「なる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "「若年で意見も聞いて」では手段や場所を表せず、文が成り立たない。"}, {"text": "の", "is_correct": true, "explanation": "「若年の意見」で、名詞「若年」を後ろの「意見」に結び付ける連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「若年を意見も聞いて」は目的語にできず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「若年へ意見も聞いて」は方向を表すが、向かう先として文脈に合わない。"}], "correct_answer": "の", "explanations": {"で": "「若年で意見も聞いて」では手段や場所を表せず、文が成り立たない。", "の": "「若年の意見」で、名詞「若年」を後ろの「意見」に結び付ける連体修飾の「の」。", "を": "「若年を意見も聞いて」は目的語にできず、意味が通らない。", "へ": "「若年へ意見も聞いて」は方向を表すが、向かう先として文脈に合わない。"}, "error_tags": {"で": "場所・手段の用法", "を": "目的格の用法", "へ": "方向の用法"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "「若年で人は」では場所や手段を表せず、「若年」の使い方として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「若年に人は」は与格の「に」になり、文の関係が成り立たない。"}, {"text": "の", "is_correct": true, "explanation": "「若年の人」で、名詞「若年」を「人」に結び付けて修飾する「の」。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる相手が要り、文の主語「人は」と噛み合わない。"}], "correct_answer": "の", "explanations": {"で": "「若年で人は」では場所や手段を表せず、「若年」の使い方として不自然。", "に": "「若年に人は」は与格の「に」になり、文の関係が成り立たない。", "の": "「若年の人」で、名詞「若年」を「人」に結び付けて修飾する「の」。", "より": "比較の「より」は比べる相手が要り、文の主語「人は」と噛み合わない。"}, "error_tags": {"で": "場所・手段の用法", "に": "与格の用法", "より": "比較の用法"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "わかい人のこと。", "primary_collocate": null, "pronunciation": "じゃくねん", "ipa": "dʑakɯneɴ", "syllable_count": 4, "sentences": [{"text": "この映画は、若年の人にも人気がある。", "target_word": "若年", "complexity_tier": "T3", "furigana": "この映画[えいが]は、若年[じゃくねん]の人[ひと]にも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "若年の意見も聞いて、新しい計画を決めた。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]の意見[いけん]も聞[き]いて、新[あたら]しい計画[けいかく]を決[き]めた。", "sentence_source": "generated"}, {"text": "町に若年が増えて、祭りがにぎやかになった。", "target_word": "若年", "complexity_tier": "T3", "furigana": "町[まち]に若年[じゃくねん]が増[ふ]えて、祭[まつ]りがにぎやかになった。", "sentence_source": "generated"}, {"text": "このクラブは、若年を中心に会員を集めている。", "target_word": "若年", "complexity_tier": "T3", "furigana": "このクラブは、若年[じゃくねん]を中心[ちゅうしん]に会員[かいいん]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "若年には、まだ経験が足りないと言われることもある。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]には、まだ経験[けいけん]が足[た]りないと言[い]われることもある。", "sentence_source": "generated"}, {"text": "若年の参加者が多く、会場は元気な声で満ちていた。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]の参加者[さんかしゃ]が多[おお]く、会場[かいじょう]は元気[げんき]な声[こえ]で満[み]ちていた。", "sentence_source": "generated"}, {"text": "店は若年向けに、安くて明るい服を並べた。", "target_word": "若年", "complexity_tier": "T3", "furigana": "店[みせ]は若年[じゃくねん]向[む]けに、安[やす]くて明[あか]るい服[ふく]を並[なら]べた。", "sentence_source": "generated"}, {"text": "若年の人は新しい機械にすぐ慣れる。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]の人[ひと]は新[あたら]しい機械[きかい]にすぐ慣[な]れる。", "sentence_source": "generated"}, {"text": "若年に仕事を任せるのは、会社の将来のためだ。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]に仕事[しごと]を任[まか]せるのは、会社[かいしゃ]の将来[しょうらい]のためだ。", "sentence_source": "generated"}, {"text": "町の将来のために、若年が集まる場所を作った。", "target_word": "若年", "complexity_tier": "T3", "furigana": "町[まち]の将来[しょうらい]のために、若年[じゃくねん]が集[あつ]まる場所[ばしょ]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "若年の", "label": "連体形"}, {"form": "若年が", "label": "主格"}, {"form": "若年を", "label": "目的格"}, {"form": "若年に", "label": "与格"}, {"form": "若年向け", "label": "派生形"}], "register": "formal", "sense_fingerprint": "年の若い人、若者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新品", "is_correct": false, "explanation": "「新品」は物の状態を表す語で、人の年代を示せない。"}, {"text": "木製", "is_correct": false, "explanation": "「木製」は材質を表す語で、人には使えない。"}, {"text": "若年", "is_correct": true, "explanation": "「若年の人」は若い年代の人を指し、映画の客層として自然に合う。"}, {"text": "機械", "is_correct": false, "explanation": "「機械」は人ではない物を指すので、「機械の人」とは言わない。"}], "explanations": {"新品": "「新品」は物の状態を表す語で、人の年代を示せない。", "木製": "「木製」は材質を表す語で、人には使えない。", "若年": "「若年の人」は若い年代の人を指し、映画の客層として自然に合う。", "機械": "「機械」は人ではない物を指すので、「機械の人」とは言わない。"}, "sentence_index": 0, "correct_answer": "若年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は若年で、まだ十分に使える。", "explanation": "ここは〈新しい〉の意味。機械の新しさには「新しい」を使い、〈若年〉は人の年齢の若さを表す語なので機械には合わない。"}, {"text": "この公園には、若年が風に揺れている。", "explanation": "ここは〈若木〉の意味。植物の若い木には〈若木〉を使い、〈若年〉は人の年齢に使うので木には合わない。"}, {"text": "その法律は若年で、来年から施行される。", "explanation": "ここは〈新しく作られた〉の意味。新しい法律には「新しい」「制定された」を使い、〈若年〉は人の年齢の若さを表すので法律には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷凍", "is_correct": false, "explanation": "「冷凍」は食品の保存方法で、客層を表す「〜向け」には合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "「新鮮」は鮮度を表す語で、「新鮮向け」とは言わない。"}, {"text": "若年", "is_correct": true, "explanation": "「若年向け」は若い人向けの意味で、安くて明るい服を並べる店の客層に合う。"}, {"text": "石造り", "is_correct": false, "explanation": "「石造り」は材質を表す語で、客向けの服には使わない。"}], "explanations": {"冷凍": "「冷凍」は食品の保存方法で、客層を表す「〜向け」には合わない。", "新鮮": "「新鮮」は鮮度を表す語で、「新鮮向け」とは言わない。", "若年": "「若年向け」は若い人向けの意味で、安くて明るい服を並べる店の客層に合う。", "石造り": "「石造り」は材質を表す語で、客向けの服には使わない。"}, "sentence_index": 6, "correct_answer": "若年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は若年にあふれ、いつも張り切っている。", "explanation": "ここは〈若さ〉の意味。活力や勢いが「あふれる」には〈若さ〉を使い、〈若年〉は若い人を指す語なので「あふれる」とは組まない。"}, {"text": "彼の若年は二十五歳で、まだ学生だ。", "explanation": "ここは〈年齢〉の意味。年齢の数字は「年齢」で表し、〈若年〉は若い時期を指すので数字とは組まない。"}, {"text": "この子犬は若年で、まだ甘えん坊だ。", "explanation": "ここは〈幼い〉の意味。犬の幼さには「子犬」「幼い」を使い、〈若年〉は人の年齢の若さを表すので犬には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
