INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35818, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若年な参加者は、新しい機械の使い方をすぐに覚えた。", "corrected_sentence": "若年の参加者は、新しい機械の使い方をすぐに覚えた。", "error_description": "「若年」は名詞なので、後ろの名詞を修飾するには「の」が要る。「な」は形容動詞に付くもので、ここでは誤りで正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
