INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35819, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "年齢が若いこと。また、その人。", "primary_collocate": null, "pronunciation": "じゃくねん", "ipa": "dʑakɯneɴ", "syllable_count": 4, "sentences": [{"text": "若年のうちに、いろいろな国を見ておきたい。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]のうちに、いろいろな国[くに]を見[み]ておきたい。", "sentence_source": "generated"}, {"text": "彼は若年ながら、会社の大切な仕事を任された。", "target_word": "若年", "complexity_tier": "T3", "furigana": "彼[かれ]は若年[じゃくねん]ながら、会社[かいしゃ]の大切[たいせつ]な仕事[しごと]を任[まか]された。", "sentence_source": "generated"}, {"text": "若年で病気になると、仕事を続けるのが難しい。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]で病気[びょうき]になると、仕事[しごと]を続[つづ]けるのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "若年での失敗は、後で大きな経験になる。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]での失敗[しっぱい]は、後[あと]で大[おお]きな経験[けいけん]になる。", "sentence_source": "generated"}, {"text": "彼女は若年にもかかわらず、落ち着いて話した。", "target_word": "若年", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は若年[じゃくねん]にもかかわらず、落[お]ち着[つ]いて話[はな]した。", "sentence_source": "generated"}, {"text": "若年のときに習った歌を、今もよく覚えている。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]のときに習[なら]った歌[うた]を、今[いま]もよく覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "若年で社長になった彼は、よく注目された。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]で社長[しゃちょう]になった彼[かれ]は、よく注目[ちゅうもく]された。", "sentence_source": "generated"}, {"text": "若年から続けた努力が、ようやく実った。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]から続[つづ]けた努力[どりょく]が、ようやく実[みの]った。", "sentence_source": "generated"}, {"text": "若年の選手が大きな大会で優勝した。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]の選手[せんしゅ]が大[おお]きな大会[たいかい]で優勝[ゆうしょう]した。", "sentence_source": "generated"}, {"text": "若年だからといって、考えが浅いわけではない。", "target_word": "若年", "complexity_tier": "T3", "furigana": "若年[じゃくねん]だからといって、考[かんが]えが浅[あさ]いわけではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "若年の", "label": "連体形"}, {"form": "若年で", "label": "で形"}, {"form": "若年だ", "label": "断定形"}, {"form": "若年だった", "label": "過去形"}, {"form": "若年ながら", "label": "逆接形"}], "register": "formal", "sense_fingerprint": "年齢が若い状態、またその年頃の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35819, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "機械", "is_correct": false, "explanation": "「機械のうちに」は人の時期を表せず、不自然になる。"}, {"text": "若年", "is_correct": true, "explanation": "「若年のうちに」は若い年齢のうちにという意味で、「〜のうちに」の前に自然に入る。"}, {"text": "木製", "is_correct": false, "explanation": "「木製」は材質を表す語で、時期を表す「うちに」の前には入らない。"}, {"text": "公共", "is_correct": false, "explanation": "「公共のうちに」は時間の区切りにならず、文が成り立たない。"}], "explanations": {"機械": "「機械のうちに」は人の時期を表せず、不自然になる。", "若年": "「若年のうちに」は若い年齢のうちにという意味で、「〜のうちに」の前に自然に入る。", "木製": "「木製」は材質を表す語で、時期を表す「うちに」の前には入らない。", "公共": "「公共のうちに」は時間の区切りにならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "若年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "若年を生かして、新しい分野に挑戦した。", "explanation": "ここは〈若さ〉の意味。「若さを生かす」と言うべきで、〈若年〉は年齢の時期を指すので「生かす」対象にならない。"}, {"text": "この製品は若年で、まだ改良の余地がある。", "explanation": "ここは〈開発初期〉の意味。製品の新しさには「開発初期」「新しい」を使い、〈若年〉は人の年齢の若さを表すので製品には合わない。"}, {"text": "彼女の若年は二十八歳で、もう結婚している。", "explanation": "ここは〈年齢〉の意味。年齢の数字は「年齢」で表し、〈若年〉は若い時期を指すので数字とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35819, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新品", "is_correct": false, "explanation": "「新品」は物の状態を表す語で、人が社長になった時期には使えない。"}, {"text": "冷凍", "is_correct": false, "explanation": "「冷凍」は食品の保存方法で、人の年齢や時期を表せない。"}, {"text": "石造り", "is_correct": false, "explanation": "「石造り」は材質を表す語で、社長になった時期を示せない。"}, {"text": "若年", "is_correct": true, "explanation": "「若年で社長になった」は若い年齢で社長になったという意味で、文脈に合う。"}], "explanations": {"新品": "「新品」は物の状態を表す語で、人が社長になった時期には使えない。", "冷凍": "「冷凍」は食品の保存方法で、人の年齢や時期を表せない。", "石造り": "「石造り」は材質を表す語で、社長になった時期を示せない。", "若年": "「若年で社長になった」は若い年齢で社長になったという意味で、文脈に合う。"}, "sentence_index": 6, "correct_answer": "若年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若年になってから、ようやく夢をかなえた人もいる。", "explanation": "「若年になる」とは言わない。年を重ねた時期は〈高齢〉で表し、〈若年〉は「若年で〜になる」のように使う。"}, {"text": "この果物は若年で、もう食べ頃を過ぎている。", "explanation": "ここは〈熟し具合〉の意味。果物の熟し具合には「熟す」「食べ頃」を使い、〈若年〉は人の年齢に使うので果物には合わない。"}, {"text": "新事業は若年の段階で、まだ利益が出ていない。", "explanation": "ここは〈初期〉の意味。事業の初期段階には「初期」「立ち上げ」を使い、〈若年〉は人の年齢の若さを表すので事業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35819, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若年を亡くなった作家の本が、今も読まれている。", "corrected_sentence": "若年で亡くなった作家の本が、今も読まれている。", "error_description": "「若年で亡くなる」は若い年齢で死ぬという意味で、「で」が正しい。「を」は目的語を取る形で、自動詞の「亡くなる」とは組まないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35819, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若年な挑戦者が、勢いのある走りで試合を制した。", "corrected_sentence": "若年の挑戦者が、勢いのある走りで試合を制した。", "error_description": "「若年」は名詞なので、後ろの名詞を修飾するには「の」が要る。「な」は形容動詞に付くもので、ここでは誤りで正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「都会からの離れを決めた」の「を」。決める対象を示す目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「離れが決めた」では主語と述語が合わず、決める対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「離れへ決めた」は決める先を示す「へ」が不自然で、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「離れで決めた」は手段のように読め、決める対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「都会からの離れを決めた」の「を」。決める対象を示す目的語の助詞。", "が": "「離れが決めた」では主語と述語が合わず、決める対象にならない。", "へ": "「離れへ決めた」は決める先を示す「へ」が不自然で、文が成り立たない。", "で": "「離れで決めた」は手段のように読め、決める対象にはならない。"}, "error_tags": {"が": "主語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「農業からの離れが続き」の「が」。続く出来事の主語を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「離れを続き」は自動詞「続く」と合わず、目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「離れで続き」は手段のように読め、続くものの主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「離れの続き」は名詞化されて述語が成り立たず、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「農業からの離れが続き」の「が」。続く出来事の主語を示す助詞。", "を": "「離れを続き」は自動詞「続く」と合わず、目的語にはならない。", "で": "「離れで続き」は手段のように読め、続くものの主語にはならない。", "の": "「離れの続き」は名詞化されて述語が成り立たず、文の意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が仕事や住んでいた場所から、はなれること。", "primary_collocate": null, "pronunciation": "はなれ", "ipa": "hanaɾe", "syllable_count": 3, "sentences": [{"text": "若い人の村からの離れが進み、村の人口が減っている。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]の村[むら]からの離[はな]れが進[すす]み、村[むら]の人口[じんこう]が減[へ]っている。", "sentence_source": "generated"}, {"text": "都会からの離れを決めた夫婦が、山の村に引っ越した。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "都会[とかい]からの離[はな]れを決[き]めた夫婦[ふうふ]が、山[やま]の村[むら]に引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "仕事のきつさから、新人の現場からの離れが続いている。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "仕事[しごと]のきつさから、新人[しんじん]の現場[げんば]からの離[はな]れが続[つづ]いている。", "sentence_source": "generated"}, {"text": "町の工場が閉まってから、住民の町からの離れが目立つようになった。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "町[まち]の工場[こうじょう]が閉[し]まってから、住民[じゅうみん]の町[まち]からの離[はな]れが目立[めだ]つようになった。", "sentence_source": "generated"}, {"text": "先生たちの学校からの離れを止めるために、給料を上げることになった。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "先生[せんせい]たちの学校[がっこう]からの離[はな]れを止[と]めるために、給料[きゅうりょう]を上[あ]げることになった。", "sentence_source": "generated"}, {"text": "若い人の地方からの離れは、田舎の大きな問題だ。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]の地方[ちほう]からの離[はな]れは、田舎[いなか]の大[おお]きな問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "看護師の職場からの離れを防ぐには、休みを増やすことが大切だ。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "看護師[かんごし]の職場[しょくば]からの離[はな]れを防[ふせ]ぐには、休[やす]みを増[ふ]やすことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "農家の農業からの離れが続き、使われない畑が増えた。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "農家[のうか]の農業[のうぎょう]からの離[はな]れが続[つづ]き、使[つか]われない畑[はたけ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "急に人気がなくなって、住民の地元からの離れが一気に進んだ。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "急[きゅう]に人気[にんき]がなくなって、住民[じゅうみん]の地元[じもと]からの離[はな]れが一気[いっき]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "社員の会社からの離れが多いので、社長は働き方を見直した。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "社員[しゃいん]の会社[かいしゃ]からの離[はな]れが多[おお]いので、社長[しゃちょう]は働[はたら]き方[かた]を見直[みなお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "離れ", "label": "基本形"}], "register": "ふつうの話し言葉・書き言葉（常体）", "sense_fingerprint": "人々が職場や土地から去っていくこと（〜離れ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "離れ", "is_correct": true, "explanation": "「村からの離れが進む」は人が住んでいた場所から去っていくこと。文に合う。"}, {"text": "眠り", "is_correct": false, "explanation": "眠りは寝ている状態。「村からの眠りが進む」は意味が通らない。"}, {"text": "矢", "is_correct": false, "explanation": "矢は射るもの。人の流出を表す文には合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は物の名前。村の人口が減る文脈とは組み合わない。"}], "explanations": {"離れ": "「村からの離れが進む」は人が住んでいた場所から去っていくこと。文に合う。", "眠り": "眠りは寝ている状態。「村からの眠りが進む」は意味が通らない。", "矢": "矢は射るもの。人の流出を表す文には合わない。", "石": "石は物の名前。村の人口が減る文脈とは組み合わない。"}, "sentence_index": 0, "correct_answer": "離れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の家の離れは、母屋の奥にある小さな部屋だ。", "explanation": "ここは〈別棟〉の意味。母屋から離れて建つ部屋を指し、仕事や場所から距離を置く意味ではないので合わない。"}, {"text": "長く続いた友人との離れが、寂しくてたまらない。", "explanation": "ここは「別れ」の意味。離れは場所や仕事から距離を置くことで、人間関係の別れは指さないので合わない。"}, {"text": "妹は来年、結婚の離れをする予定だ。", "explanation": "ここは〈結婚〉の意味。離れは仕事や場所から距離を置くことで、結婚という出来事は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "離れ", "is_correct": true, "explanation": "「職場からの離れを防ぐ」は人が職場から去るのを止めるという意味。文に合う。"}, {"text": "雪", "is_correct": false, "explanation": "雪は降るもの。「職場からの雪を防ぐ」は文の意味が通らない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は粒状の物質。人が職場から去るのを防ぐ文には合わない。"}, {"text": "鈴", "is_correct": false, "explanation": "鈴は音の出る物。職場から人が去る文脈とは組み合わない。"}], "explanations": {"離れ": "「職場からの離れを防ぐ」は人が職場から去るのを止めるという意味。文に合う。", "雪": "雪は降るもの。「職場からの雪を防ぐ」は文の意味が通らない。", "砂": "砂は粒状の物質。人が職場から去るのを防ぐ文には合わない。", "鈴": "鈴は音の出る物。職場から人が去る文脈とは組み合わない。"}, "sentence_index": 6, "correct_answer": "離れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の祭りで、祖父は家の離れを一日だけ貸した。", "explanation": "ここは〈別棟〉の意味。母屋から離れて建つ部屋を指し、休みの意味ではないので合わない。"}, {"text": "彼は子どもの頃から、ピアノの離れを続けてきた。", "explanation": "ここは「練習」の意味。離れは場所や仕事から距離を置くことで、技能を磨く練習は指さないので合わない。"}, {"text": "町の離れに、古い店が一軒だけ残っている。", "explanation": "ここは〈町はずれ〉の意味。場所の名前として使い、仕事や場所から距離を置く意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若い人の都会からの離れに進み、町の活気が落ちている。", "corrected_sentence": "若い人の都会からの離れが進み、町の活気が落ちている。", "error_description": "誤った形は「離れに進み」。「進む」は主語に「が」を取るので、「離れが進む」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35820, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員の会社からの離れを相次いで、社長は働き方を見直した。", "corrected_sentence": "社員の会社からの離れが相次いで、社長は働き方を見直した。", "error_description": "誤った形は「離れを相次いで」。「相次ぐ」は主語に「が」を取るので、「離れが相次ぐ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「仕事からの離れ」の「の」。「仕事から」を「離れ」につなぎ、名詞を修飾する連体修飾の働き。"}, {"text": "を", "is_correct": false, "explanation": "「仕事からを離れ」は「から」の後に「を」が続かず、「離れ」を修飾できないので文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「仕事からが離れ」は「が」が「離れ」を修飾できず、名詞の並びとして意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「仕事からで離れ」は「で」が手段や場所を示すため、「離れ」の修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "「仕事からの離れ」の「の」。「仕事から」を「離れ」につなぎ、名詞を修飾する連体修飾の働き。", "を": "「仕事からを離れ」は「から」の後に「を」が続かず、「離れ」を修飾できないので文が成り立たない。", "が": "「仕事からが離れ」は「が」が「離れ」を修飾できず、名詞の並びとして意味が通らない。", "で": "「仕事からで離れ」は「で」が手段や場所を示すため、「離れ」の修飾にはならない。"}, "error_tags": {"を": "目的語（「から」の後には続かない）", "が": "主語（連体修飾にならない）", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「前の会社からの離れを決めて」の「を」。決める対象を示す目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「離れが決めて」は主語と述語が合わず、決める対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「離れの決めて」は述語が成り立たず、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「離れへ決めて」は決める先を示す「へ」が不自然で、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「前の会社からの離れを決めて」の「を」。決める対象を示す目的語の助詞。", "が": "「離れが決めて」は主語と述語が合わず、決める対象にならない。", "の": "「離れの決めて」は述語が成り立たず、文の意味が通らない。", "へ": "「離れへ決めて」は決める先を示す「へ」が不自然で、文が成り立たない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が、それまで関わっていた仕事や場所から、距離を置くこと。", "primary_collocate": null, "pronunciation": "はなれ", "ipa": "hanaɾe", "syllable_count": 3, "sentences": [{"text": "夫が定年になって、会社からの離れに少し時間がかかった。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "夫[おっと]が定年[ていねん]になって、会社[かいしゃ]からの離[はな]れに少[すこ]し時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "長く働いた店を辞め、仕事からの離れを楽しんでいる。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "長[なが]く働[はたら]いた店[みせ]を辞[や]め、仕事[しごと]からの離[はな]れを楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "課長になってから、現場からの離れが進んで現場の声が聞こえにくい。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "課長[かちょう]になってから、現場[げんば]からの離[はな]れが進[すす]んで現場[げんば]の声[こえ]が聞[き]こえにくい。", "sentence_source": "generated"}, {"text": "彼は有名になっても、地元からの離れをせず、同じ町で暮らしている。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "彼[かれ]は有名[ゆうめい]になっても、地元[じもと]からの離[はな]れをせず、同[おな]じ町[まち]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "母は退職後、職場からの離れがうまくできず、毎朝早く目が覚める。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "母[はは]は退職後[たいしょくご]、職場[しょくば]からの離[はな]れがうまくできず、毎朝[まいあさ]早[はや]く目[め]が覚[さ]める。", "sentence_source": "generated"}, {"text": "社長の現場からの離れが進んだせいで、工場の問題に気づくのが遅れた。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の現場[げんば]からの離[はな]れが進[すす]んだせいで、工場[こうじょう]の問題[もんだい]に気[き]づくのが遅[おく]れた。", "sentence_source": "generated"}, {"text": "大学を出た兄は、実家からの離れを決めて一人で暮らし始めた。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]た兄[あに]は、実家[じっか]からの離[はな]れを決[き]めて一人[ひとり]で暮[く]らし始[はじ]めた。", "sentence_source": "generated"}, {"text": "新しい社長は、前の会社からの離れを決めて、自分の店を開いた。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]は、前[まえ]の会社[かいしゃ]からの離[はな]れを決[き]めて、自分[じぶん]の店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "本業からの離れが進んだ会社は、売り上げが急に落ちた。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "本業[ほんぎょう]からの離[はな]れが進[すす]んだ会社[かいしゃ]は、売[う]り上[あ]げが急[きゅう]に落[お]ちた。", "sentence_source": "generated"}, {"text": "地元からの離れをして十年たつが、祭りの季節になると思い出す。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "地元[じもと]からの離[はな]れをして十年[じゅうねん]たつが、祭[まつ]りの季節[きせつ]になると思[おも]い出[だ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "離れ", "label": "基本形"}], "register": "ふつうの話し言葉・書き言葉（常体）", "sense_fingerprint": "自分が関わってきた仕事や場所と距離を置くこと（〜離れ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "離れ", "is_correct": true, "explanation": "「会社からの離れに時間がかかる」は会社と距離を置くことに時間がかかるという意味。文に合う。"}, {"text": "波", "is_correct": false, "explanation": "波は水の動き。「会社からの波に時間がかかる」は文の意味が通らない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は空気中の水滴。会社との関係を表す文には合わない。"}, {"text": "瓶", "is_correct": false, "explanation": "瓶は容器。会社からの距離の話には合わない。"}], "explanations": {"離れ": "「会社からの離れに時間がかかる」は会社と距離を置くことに時間がかかるという意味。文に合う。", "波": "波は水の動き。「会社からの波に時間がかかる」は文の意味が通らない。", "霧": "霧は空気中の水滴。会社との関係を表す文には合わない。", "瓶": "瓶は容器。会社からの距離の話には合わない。"}, "sentence_index": 0, "correct_answer": "離れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父の家の離れで、夏の間は孫たちが寝泊まりする。", "explanation": "ここは〈別棟〉の意味。母屋から離れて建つ建物を指し、仕事から距離を置く意味ではないので合わない。"}, {"text": "彼は運動会の前、練習の離れを重ねた。", "explanation": "ここは「練習」の意味。離れは距離を置くことで、技能を磨く練習は指さないので合わない。"}, {"text": "町の離れに住む人は、毎朝バスで中心部へ出る。", "explanation": "ここは〈町はずれ〉の意味。場所の名前として使い、仕事から距離を置く意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "離れ", "is_correct": true, "explanation": "「実家からの離れを決める」は実家と距離を置く決心をするという意味。文に合う。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空に浮かぶもの。「実家からの雲を決める」は意味が通らない。"}, {"text": "鉢", "is_correct": false, "explanation": "鉢は植木を入れる容器。実家との関係を決める文には合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部。「実家からの窓を決める」は文の意味が通らない。"}], "explanations": {"離れ": "「実家からの離れを決める」は実家と距離を置く決心をするという意味。文に合う。", "雲": "雲は空に浮かぶもの。「実家からの雲を決める」は意味が通らない。", "鉢": "鉢は植木を入れる容器。実家との関係を決める文には合わない。", "窓": "窓は建物の開口部。「実家からの窓を決める」は文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "離れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎晩、子どもは宿題の離れをしている。", "explanation": "ここは「勉強」の意味。離れは仕事や場所から距離を置くことで、宿題をする行為は指さないので合わない。"}, {"text": "友人と長く離れをして、夜が更けた。", "explanation": "ここは「会話」の意味。離れは距離を置くことで、話し込む行為は表せないので合わない。"}, {"text": "昨年から、離れの趣味として絵を描き始めた。", "explanation": "ここは〈趣味〉の意味。離れは仕事や場所から距離を置くことで、好きで続ける活動は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "退職してから、会社からの離れを少し時間がかかった。", "corrected_sentence": "退職してから、会社からの離れに少し時間がかかった。", "error_description": "誤った形は「離れを時間がかかった」。「時間がかかる」の対象となる「離れ」には「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35821, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地元からの離れが決めてから十年がたった。", "corrected_sentence": "地元からの離れを決めてから十年がたった。", "error_description": "誤った形は「離れが決めて」。「決める」の対象となる「離れ」には「が」ではなく「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物流の仕事」と名詞どうしをつなぐ「の」。ここでは「物流」が「仕事」を修飾している。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「物流が仕事」では名詞の修飾にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「物流へ仕事で」は方向を示す「へ」では名詞をつなげず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「物流に仕事」では「に」が相手や場所を示すことになり、名詞をつなぐ用法にはならない。"}], "correct_answer": "の", "explanations": {"の": "「物流の仕事」と名詞どうしをつなぐ「の」。ここでは「物流」が「仕事」を修飾している。", "が": "「が」は主語を示すため、「物流が仕事」では名詞の修飾にならず文が成り立たない。", "へ": "「物流へ仕事で」は方向を示す「へ」では名詞をつなげず、文が成り立たない。", "に": "「物流に仕事」では「に」が相手や場所を示すことになり、名詞をつなぐ用法にはならない。"}, "error_tags": {"を": "object", "に": "target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物流の会社」と名詞をつなぐ「の」。「物流」が「会社」を修飾している。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「物流へ会社」では名詞をつなぐ形にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「物流から会社」では修飾関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「物流より会社」では名詞の修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「物流の会社」と名詞をつなぐ「の」。「物流」が「会社」を修飾している。", "へ": "「へ」は方向を示すため、「物流へ会社」では名詞をつなぐ形にならない。", "から": "「から」は起点を示すため、「物流から会社」では修飾関係が成り立たない。", "より": "「より」は比較を示すため、「物流より会社」では名詞の修飾にならない。"}, "error_tags": {"へ": "direction", "から": "source", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "荷物や品物を運ぶこと。", "primary_collocate": null, "pronunciation": "ぶつりゅう", "ipa": "bɯtsɯɾʲɯː", "syllable_count": 4, "sentences": [{"text": "大雪で物流が止まり、店に荷物が届かなかった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で物流[ぶつりゅう]が止[と]まり、店[みせ]に荷物[にもつ]が届[とど]かなかった。", "sentence_source": "generated"}, {"text": "この会社は物流の仕事で、毎日たくさんの荷物を運ぶ。", "target_word": "物流", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は物流[ぶつりゅう]の仕事[しごと]で、毎日[まいにち]たくさんの荷物[にもつ]を運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "ネットで買い物をする人が増えて、物流が忙しくなった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "ネットで買[か]い物[もの]をする人[ひと]が増[ふ]えて、物流[ぶつりゅう]が忙[いそが]しくなった。", "sentence_source": "generated"}, {"text": "物流がよくなったので、遠くの町でも新しい魚が食べられる。", "target_word": "物流", "complexity_tier": "T3", "furigana": "物流[ぶつりゅう]がよくなったので、遠[とお]くの町[まち]でも新[あたら]しい魚[さかな]が食[た]べられる。", "sentence_source": "generated"}, {"text": "台風が来る前に、物流の車は早く荷物を届けた。", "target_word": "物流", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に、物流[ぶつりゅう]の車[くるま]は早[はや]く荷物[にもつ]を届[とど]けた。", "sentence_source": "generated"}, {"text": "道路が直ると、物流がスムーズになり、配達も早くなる。", "target_word": "物流", "complexity_tier": "T3", "furigana": "道路[どうろ]が直[なお]ると、物流[ぶつりゅう]がスムーズになり、配達[はいたつ]も早[はや]くなる。", "sentence_source": "generated"}, {"text": "年末は物流が混み合うので、早めに荷物を出したほうがいい。", "target_word": "物流", "complexity_tier": "T3", "furigana": "年末[ねんまつ]は物流[ぶつりゅう]が混[こ]み合[あ]うので、早[はや]めに荷物[にもつ]を出[だ]したほうがいい。", "sentence_source": "generated"}, {"text": "兄は物流の会社で、トラックに荷物を積む仕事をしている。", "target_word": "物流", "complexity_tier": "T3", "furigana": "兄[あに]は物流[ぶつりゅう]の会社[かいしゃ]で、トラックに荷物[にもつ]を積[つ]む仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "運転手が足りなくて、物流がうまく回らない。", "target_word": "物流", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]が足[た]りなくて、物流[ぶつりゅう]がうまく回[まわ]らない。", "sentence_source": "generated"}, {"text": "物流の仕事をする人たちのおかげで、毎日家に荷物が届く。", "target_word": "物流", "complexity_tier": "T3", "furigana": "物流[ぶつりゅう]の仕事[しごと]をする人[ひと]たちのおかげで、毎日[まいにち]家[いえ]に荷物[にもつ]が届[とど]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物流", "label": "基本形"}], "register": "ふつうの話し言葉・書き言葉（常体）", "sense_fingerprint": "荷物や品物を運んで届けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "ここは〈物流〉の意味。大雪で荷物が運べなくなり、店に届かなかったという流れに合う。"}, {"text": "物価", "is_correct": false, "explanation": "物価は品物の値段の水準のことで、大雪で止まる対象にはならない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は打ち上げるもので、雪で止まって荷物が届かない話とはつながらない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚のことで、止まって店への配達に影響するものではない。"}], "explanations": {"物流": "ここは〈物流〉の意味。大雪で荷物が運べなくなり、店に届かなかったという流れに合う。", "物価": "物価は品物の値段の水準のことで、大雪で止まる対象にはならない。", "花火": "花火は打ち上げるもので、雪で止まって荷物が届かない話とはつながらない。", "眠気": "眠気は感覚のことで、止まって店への配達に影響するものではない。"}, "sentence_index": 0, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は物流が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。物流は荷物を運ぶしくみのことなので、知っている量を表す「豊富」とは合わない。"}, {"text": "その小説は物流がとても悲しくて、最後に泣いてしまった。", "explanation": "ここは〈物語〉の意味。物流は荷物の運搬のことなので、話の内容には使えない。"}, {"text": "病院では患者の物流に専用のベッドを使う。", "explanation": "ここは〈搬送〉の意味。物流は商品や物資の流れを指し、患者を運ぶ「搬送」の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "ここは〈物流〉の意味。年末に荷物が集中して混み合う流れに合う。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は学習の課題のことで、混み合うものとしては使えない。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は庭などに生える植物で、年末に混み合うという文にはならない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は身につける道具で、混み合う対象にはならない。"}], "explanations": {"物流": "ここは〈物流〉の意味。年末に荷物が集中して混み合う流れに合う。", "宿題": "宿題は学習の課題のことで、混み合うものとしては使えない。", "雑草": "雑草は庭などに生える植物で、年末に混み合うという文にはならない。", "眼鏡": "眼鏡は身につける道具で、混み合う対象にはならない。"}, "sentence_index": 6, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物流が上がって、毎日の買い物が苦しくなった。", "explanation": "ここは〈物価〉の意味。物流は商品を運ぶしくみで、値段が上がるとは言わない。"}, {"text": "大雪の日は物流が人を乗せ、通勤する人が無事に着いた。", "explanation": "ここは〈交通〉の意味。物流は荷物を運ぶしくみで、人を乗せて送ることには使わない。"}, {"text": "役所の物流に時間がかかり、申請が遅れた。", "explanation": "ここは〈手続き〉の意味。物流は商品の流れのことで、役所の手続きの進み方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は物流を会社で事務を担当している。", "corrected_sentence": "姉は物流の会社で事務を担当している。", "error_description": "誤りは「物流を会社で」の「を」。「物流の会社」は「会社」を修飾するので「の」が正しい。「を」は目的語を示すため、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35822, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の物流に支える仕事は、朝早く始まる。", "corrected_sentence": "地域の物流を支える仕事は、朝早く始まる。", "error_description": "「支える」は目的語に「を」をとる動詞。誤りは「物流に」の「に」で、正しくは「物流を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「物流がみだれ」の「が」。「物流」が主語で、「みだれ」（乱れる）の動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「物流をみだれ」は「乱れる」が目的語を取らない自動詞のため、「を」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「物流へみだれ」では「乱れる」の主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「物流よりみだれ」では主語を示せず文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「物流がみだれ」の「が」。「物流」が主語で、「みだれ」（乱れる）の動作の主体を示す。", "を": "「物流をみだれ」は「乱れる」が目的語を取らない自動詞のため、「を」は成り立たない。", "へ": "「へ」は方向を示すため、「物流へみだれ」では「乱れる」の主語を示せない。", "より": "「より」は比較を示すため、「物流よりみだれ」では主語を示せず文の意味が通らない。"}, "error_tags": {"を": "目的語（自動詞「乱れる」には不可）", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「物流を管理する」の「を」。「管理する」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「物流に管理する」は「に」で目的語を示せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「物流より管理する」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「物流へ管理する」は方向を示す「へ」では目的語にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「物流を管理する」の「を」。「管理する」の目的語を示す。", "に": "「物流に管理する」は「に」で目的語を示せず、文が成り立たない。", "より": "「より」は比較を示すため、「物流より管理する」では文が成り立たない。", "へ": "「物流へ管理する」は方向を示す「へ」では目的語にならず、文が成り立たない。"}, "error_tags": {"に": "target", "より": "comparison", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品や物資を、国や地域の間で運ぶしくみや活動のこと。", "primary_collocate": null, "pronunciation": "ぶつりゅう", "ipa": "bɯtsɯɾʲɯː", "syllable_count": 4, "sentences": [{"text": "港が新しくなって、国と国の間の物流が大きく変わった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "港[みなと]が新[あたら]しくなって、国[くに]と国[くに]の間[あいだ]の物流[ぶつりゅう]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "戦争の影響で、世界の物流がみだれ、物の値段が上がった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "戦争[せんそう]の影響[えいきょう]で、世界[せかい]の物流[ぶつりゅう]がみだれ、物[もの]の値段[ねだん]が上[あ]がった。", "sentence_source": "generated"}, {"text": "この国は物流のしくみが整っていて、輸出がさかんだ。", "target_word": "物流", "complexity_tier": "T3", "furigana": "この国[くに]は物流[ぶつりゅう]のしくみが整[ととの]っていて、輸出[ゆしゅつ]がさかんだ。", "sentence_source": "generated"}, {"text": "物流のネットワークを広げて、アジア全体に商品を届ける。", "target_word": "物流", "complexity_tier": "T3", "furigana": "物流[ぶつりゅう]のネットワークを広[ひろ]げて、アジア全体[ぜんたい]に商品[しょうひん]を届[とど]ける。", "sentence_source": "generated"}, {"text": "海外との物流にかかる費用が高く、会社は利益が減った。", "target_word": "物流", "complexity_tier": "T3", "furigana": "海外[かいがい]との物流[ぶつりゅう]にかかる費用[ひよう]が高[たか]く、会社[かいしゃ]は利益[りえき]が減[へ]った。", "sentence_source": "generated"}, {"text": "新しい鉄道ができ、地域間の物流が速くなった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "新[あたら]しい鉄道[てつどう]ができ、地域間[ちいきかん]の物流[ぶつりゅう]が速[はや]くなった。", "sentence_source": "generated"}, {"text": "物流の改革により、農産物を外国へ早く送れるようになった。", "target_word": "物流", "complexity_tier": "T3", "furigana": "物流[ぶつりゅう]の改革[かいかく]により、農産物[のうさんぶつ]を外国[がいこく]へ早[はや]く送[おく]れるようになった。", "sentence_source": "generated"}, {"text": "港の物流を管理する仕事には、語学の力も必要だ。", "target_word": "物流", "complexity_tier": "T3", "furigana": "港[みなと]の物流[ぶつりゅう]を管理[かんり]する仕事[しごと]には、語学[ごがく]の力[ちから]も必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "世界の物流が止まると、工場の部品が足りなくなる。", "target_word": "物流", "complexity_tier": "T3", "furigana": "世界[せかい]の物流[ぶつりゅう]が止[と]まると、工場[こうじょう]の部品[ぶひん]が足[た]りなくなる。", "sentence_source": "generated"}, {"text": "政府は物流を強くするために、空港や港に予算を使うことにした。", "target_word": "物流", "complexity_tier": "T3", "furigana": "政府[せいふ]は物流[ぶつりゅう]を強[つよ]くするために、空港[くうこう]や港[みなと]に予算[よさん]を使[つか]うことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物流", "label": "基本形"}], "register": "ふつうの書き言葉（常体）", "sense_fingerprint": "国や地域をまたぐ商品・物資の輸送のしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44cca240-755f-469b-852b-7faa7d866358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "ここは〈物流〉の意味。国と国の間で商品を運ぶしくみが変わったという文脈に合う。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は植物のことで、国と国の間の関係を表す語としては合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は身につける道具で、国どうしの間の変化を表す語にはならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている時の発言で、国と国の間の変化とは結びつかない。"}], "explanations": {"物流": "ここは〈物流〉の意味。国と国の間で商品を運ぶしくみが変わったという文脈に合う。", "雑草": "雑草は植物のことで、国と国の間の関係を表す語としては合わない。", "眼鏡": "眼鏡は身につける道具で、国どうしの間の変化を表す語にはならない。", "寝言": "寝言は眠っている時の発言で、国と国の間の変化とは結びつかない。"}, "sentence_index": 0, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は物流がとても悲しくて、最後に泣いてしまった。", "explanation": "ここは〈物語〉の意味。物流は商品の運搬のしくみで、小説の筋や内容には使わない。"}, {"text": "大学は留学生の物流を増やし、学生同士が交流する機会を作った。", "explanation": "ここは〈交流〉の意味。物流は商品や物資の流れで、人どうしの交流の意味では使わない。"}, {"text": "彼女の文章は物流が豊かで、読む人の心を動かす。", "explanation": "ここは〈表現〉の意味。物流は商品の流れのことで、文章の豊かさや表現の巧みさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "ここは〈物流〉の意味。農産物を外国へ早く送るしくみを変えた改革として合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚のことで、改革の対象になる語ではない。"}, {"text": "氷山", "is_correct": false, "explanation": "氷山は海に浮かぶ氷の塊で、農産物の輸送の改革とは結びつかない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は打ち上げるもので、農産物を送る改革の対象にはならない。"}], "explanations": {"物流": "ここは〈物流〉の意味。農産物を外国へ早く送るしくみを変えた改革として合う。", "眠気": "眠気は感覚のことで、改革の対象になる語ではない。", "氷山": "氷山は海に浮かぶ氷の塊で、農産物の輸送の改革とは結びつかない。", "花火": "花火は打ち上げるもので、農産物を送る改革の対象にはならない。"}, "sentence_index": 6, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は物流が弱く、少し歩いただけで息が切れる。", "explanation": "ここは〈体力〉の意味。物流は商品の運搬のしくみで、人の体力が弱いとは言わない。"}, {"text": "彼は物流を深めるために、毎日本を読んでいる。", "explanation": "ここは〈知識〉の意味。物流は商品の運搬のことで、読書で深める対象にはならない。"}, {"text": "店の物流を明るくするために、花を置いた。", "explanation": "ここは〈雰囲気〉の意味。物流は商品の流れのことで、店の明るさや雰囲気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国は海外との物流で強化する計画を立てた。", "corrected_sentence": "この国は海外との物流を強化する計画を立てた。", "error_description": "「強化する」は目的語に「を」をとる動詞。誤りは「物流で」の「で」で、正しくは「物流を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35823, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉄道の物流で担当する課では、新しい計算表を使う。", "corrected_sentence": "鉄道の物流を担当する課では、新しい計算表を使う。", "error_description": "「担当する」は目的語に「を」をとる動詞。誤りは「物流で」の「で」で、正しくは「物流を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a4989a7-06d7-41dd-ba78-6cb1bfb73104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
