INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35826, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「リスクがある」で、あるものの主語を示す。自然な形。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「リスクをある」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ある」は向かう先を取らないので、「リスクへある」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「リスクからある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「リスクがある」で、あるものの主語を示す。自然な形。", "を": "「ある」は目的語を取らないので、「リスクをある」は成り立たない。", "へ": "「ある」は向かう先を取らないので、「リスクへある」は不自然。", "から": "起点を表すが、「リスクからある」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35826, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "こわいことがおこるかもしれないこと", "primary_collocate": null, "pronunciation": "りすく", "ipa": "ɾisɯkɯ", "syllable_count": 3, "sentences": [{"text": "夜に一人で山を歩くのは、事故にあうリスクが高い。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "夜(よる)に一人(ひとり)で山(やま)を歩(ある)くのは、事故(じこ)にあうリスクが高(たか)い。", "sentence_source": "generated"}, {"text": "新しい店を始めるには、お金をなくすリスクもある。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "新(あたら)しい店(みせ)を始(はじ)めるには、お金(かね)をなくすリスクもある。", "sentence_source": "generated"}, {"text": "彼は失敗のリスクを知っていたが、挑戦することにした。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "彼(かれ)は失敗(しっぱい)のリスクを知(し)っていたが、挑戦(ちょうせん)することにした。", "sentence_source": "generated"}, {"text": "薬には効果があるが、体に合わないリスクも少しある。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "薬(くすり)には効果(こうか)があるが、体(からだ)に合(あ)わないリスクも少(すこ)しある。", "sentence_source": "generated"}, {"text": "雨の日に自転車でスピードを出すと、転ぶリスクが大きくなる。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)に自転車(じてんしゃ)でスピードを出(だ)すと、転(ころ)ぶリスクが大(おお)きくなる。", "sentence_source": "generated"}, {"text": "保険に入るのは、病気になったときのリスクに備えるためだ。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "保険(ほけん)に入(はい)るのは、病気(びょうき)になったときのリスクに備(そな)えるためだ。", "sentence_source": "generated"}, {"text": "古い橋を渡るリスクを考えて、私たちは遠回りした。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "古(ふる)い橋(はし)を渡(わた)るリスクを考(かんが)えて、私(わたし)たちは遠回(とおまわ)りした。", "sentence_source": "generated"}, {"text": "投資にはリスクがあるので、貯金の全部を使ってはいけない。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "投資(とうし)にはリスクがあるので、貯金(ちょきん)の全部(ぜんぶ)を使(つか)ってはいけない。", "sentence_source": "generated"}, {"text": "電車が止まるリスクがあるから、早めに家を出よう。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "電車(でんしゃ)が止(と)まるリスクがあるから、早(はや)めに家(いえ)を出(で)よう。", "sentence_source": "generated"}, {"text": "医者は手術のリスクを、家族にくわしく説明した。", "target_word": "リスク", "complexity_tier": "T3", "furigana": "医者(いしゃ)は手術(しゅじゅつ)のリスクを、家族(かぞく)にくわしく説明(せつめい)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リスク", "label": "基本形"}, {"form": "リスクが", "label": "主格形（が）"}], "register": "中立", "sense_fingerprint": "リスク：悪いことが起こるかもしれない可能性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35826, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リスク", "is_correct": true, "explanation": "「事故にあう可能性」の意味で、「リスクが高い」は自然な組み合わせ。"}, {"text": "宿題", "is_correct": false, "explanation": "課された勉強の課題で、「事故にあう宿題」は意味が通らず「高い」とも合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、事故にあう文脈には入らず「体重が高い」とは言わない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、「事故にあう季節」は意味をなさない。"}], "explanations": {"リスク": "「事故にあう可能性」の意味で、「リスクが高い」は自然な組み合わせ。", "宿題": "課された勉強の課題で、「事故にあう宿題」は意味が通らず「高い」とも合わない。", "体重": "体の重さを表す語で、事故にあう文脈には入らず「体重が高い」とは言わない。", "季節": "一年の時期を表す語で、「事故にあう季節」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "リスク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の試験がリスクで、夜はよく眠れない。", "explanation": "リスクは起こるかもしれない悪い可能性を指す語で、試験前の不安な気持ちそのものは表せないので合わない。"}, {"text": "買うものを忘れないよう、リスクを紙に書いた。", "explanation": "ここは〈リスト（一覧）〉の意味。リスクは悪いことの可能性なので、買い物の一覧には合わない。"}, {"text": "宝くじで当たるリスクが高い。", "explanation": "リスクは悪いことの可能性を表す語で、当たるという良いことには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35826, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リスク", "is_correct": true, "explanation": "「古い橋を渡る危険」を考えるという文脈に合い、遠回りの理由として自然。"}, {"text": "色", "is_correct": false, "explanation": "「古い橋を渡る色」は意味が通らず、考える対象にもならない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の性質を表す語で、橋を渡ることとは結びつかない。"}, {"text": "形", "is_correct": false, "explanation": "「橋を渡る形」では橋の形を言うことになり、遠回りの理由にならない。"}], "explanations": {"リスク": "「古い橋を渡る危険」を考えるという文脈に合い、遠回りの理由として自然。", "色": "「古い橋を渡る色」は意味が通らず、考える対象にもならない。", "味": "食べ物の性質を表す語で、橋を渡ることとは結びつかない。", "形": "「橋を渡る形」では橋の形を言うことになり、遠回りの理由にならない。"}, "sentence_index": 6, "correct_answer": "リスク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は手術のリスクがとても上手だ。", "explanation": "リスクは起こりうる悪い可能性を表す語で、腕前や上手さを表す言葉ではないので合わない。"}, {"text": "朝、パンでリスクを焼いて、紅茶と一緒に食べた。", "explanation": "ここは〈ラスク（菓子）〉の意味。リスクは食べ物を指さず、危険の可能性を表すので、焼いて食べるものには使えない。"}, {"text": "このハサミは、紙を切るためのリスクだ。", "explanation": "リスクは物を指さず、悪いことが起こる可能性を表すので、道具の名前としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
