label": "派生"}, {"form": "基本要素", "label": "派生"}, {"form": "不安要素", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 作るときに欠かせない大事な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
