INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35829, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を成り立たせるための、基本的な構成部分。", "primary_collocate": null, "pronunciation": "ようそ", "ipa": "joːso", "syllable_count": 3, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "要素", "complexity_tier": "T6", "furigana": "ミニマリストの思想[しそう]に基[もと]づき、必要[ひつよう]な要素[ようそ]だけを残[のこ]すことで、居住者[きょじゅうしゃ]はより穏[おだ]やかな日常[にちじょう]を送[おく]ることができます。", "sentence_source": "mined"}, {"text": "色は部屋の印象を決める大事な要素だ。", "target_word": "要素", "complexity_tier": "T3", "furigana": "色[いろ]は部屋[へや]の印象[いんしょう]を決[き]める大事[だいじ]な要素[ようそ]だ。", "sentence_source": "generated"}, {"text": "要素を一つずつ確認します。", "target_word": "要素", "complexity_tier": "T2", "furigana": "要素[ようそ]を一[ひと]つずつ確認[かくにん]します。", "sentence_source": "generated"}, {"text": "この料理には甘い要素がありません。", "target_word": "要素", "complexity_tier": "T2", "furigana": "この料理[りょうり]には甘[あま]い要素[ようそ]がありません。", "sentence_source": "generated"}, {"text": "計画に必要な要素を書き出した。", "target_word": "要素", "complexity_tier": "T3", "furigana": "計画[けいかく]に必要[ひつよう]な要素[ようそ]を書[か]き出[だ]した。", "sentence_source": "generated"}, {"text": "要素は全部で五つあります。", "target_word": "要素", "complexity_tier": "T2", "furigana": "要素[ようそ]は全部[ぜんぶ]で五[いつ]つあります。", "sentence_source": "generated"}, {"text": "成功には運の要素も大きい。", "target_word": "要素", "complexity_tier": "T3", "furigana": "成功[せいこう]には運[うん]の要素[ようそ]も大[おお]きい。", "sentence_source": "generated"}, {"text": "要素に分けて考えれば、問題は簡単になる。", "target_word": "要素", "complexity_tier": "T4", "furigana": "要素[ようそ]に分[わ]けて考[かんが]えれば、問題[もんだい]は簡単[かんたん]になる。", "sentence_source": "generated"}, {"text": "不安な要素が多いため、計画は中止された。", "target_word": "要素", "complexity_tier": "T4", "furigana": "不安[ふあん]な要素[ようそ]が多[おお]いため、計画[けいかく]は中止[ちゅうし]された。", "sentence_source": "generated"}, {"text": "天気は旅行を左右する要素の一つです。", "target_word": "要素", "complexity_tier": "T3", "furigana": "天気[てんき]は旅行[りょこう]を左右[さゆう]する要素[ようそ]の一[ひと]つです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "構成要素", "label": "派生"}, {"form": "基本要素", "label": "派生"}, {"form": "不安要素", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を成り立たせる基本的な構成部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
