INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35829, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要素", "is_correct": true, "explanation": "「ようそ」で、聞こえた語と一致する。"}, {"text": "用紙", "is_correct": false, "explanation": "「ようし」で、最後の音が「そ」と「し」で違う。"}, {"text": "八日", "is_correct": false, "explanation": "「ようか」で、最後の音が「そ」と「か」で違う。"}, {"text": "用事", "is_correct": false, "explanation": "「ようじ」で、最後の音が「そ」と「じ」で違う。"}, {"text": "幼稚", "is_correct": false, "explanation": "「ようち」で、最後の音が「そ」と「ち」で違う。"}], "explanations": {"要素": "「ようそ」で、聞こえた語と一致する。", "用紙": "「ようし」で、最後の音が「そ」と「し」で違う。", "八日": "「ようか」で、最後の音が「そ」と「か」で違う。", "用事": "「ようじ」で、最後の音が「そ」と「じ」で違う。", "幼稚": "「ようち」で、最後の音が「そ」と「ち」で違う。"}, "sentence_index": null, "correct_answer": "要素"}, "level_3": {"options": [{"text": "要素", "is_correct": true, "explanation": "「運の要素」は成功を左右する構成部分として自然に合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「運の季節」では意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、「運の値段」では意味が合わない。"}, {"text": "場所", "is_correct": false, "explanation": "形は合うが、「運の場所」では意味が合わない。"}], "explanations": {"要素": "「運の要素」は成功を左右する構成部分として自然に合う。", "季節": "形は合うが、「運の季節」では意味が合わない。", "値段": "形は合うが、「運の値段」では意味が合わない。", "場所": "形は合うが、「運の場所」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "要素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は要素に乗って、海を渡った。", "explanation": "「要素」は乗り物ではないので、「乗る」の対象として使うのは誤り。"}, {"text": "母は要素を洗って、きれいに干した。", "explanation": "「要素」は洗って干す物ではなく、抽象的な構成部分を表す語なので誤り。"}, {"text": "要素を三匹飼っている。", "explanation": "「要素」は動物ではないので、飼う対象として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35829, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議で大切な要素が話し合いました。", "corrected_sentence": "会議で大切な要素を話し合いました。", "error_description": "「話し合う」の対象を表す助詞は「が」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35829, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気も大切な要素を一つです。", "corrected_sentence": "天気も大切な要素の一つです。", "error_description": "「要素の一つ」と言うべきところを、助詞「を」にしている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "頑丈", "is_correct": true, "explanation": "「こわれやすい」の対義語。力や衝撃に耐える強さを表し、ガラス細工の文脈と反対の関係にある。"}, {"text": "穏やか", "is_correct": false, "explanation": "性質や様子が荒くないことを表す。こわれやすさの対義語ではない。"}, {"text": "簡素", "is_correct": false, "explanation": "飾りが少ないことを表す。強度や壊れやすさとは関係がない。"}, {"text": "大胆", "is_correct": false, "explanation": "思い切った様子を表す。こわれにくさの対義語ではない。"}], "correct_answer": "頑丈", "explanations": {"頑丈": "「こわれやすい」の対義語。力や衝撃に耐える強さを表し、ガラス細工の文脈と反対の関係にある。", "穏やか": "性質や様子が荒くないことを表す。こわれやすさの対義語ではない。", "簡素": "飾りが少ないことを表す。強度や壊れやすさとは関係がない。", "大胆": "思い切った様子を表す。こわれにくさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強靭", "is_correct": true, "explanation": "「脆弱」の対義語。しなやかで強く、こわれにくいことを表す。"}, {"text": "華やか", "is_correct": false, "explanation": "目立って美しい様子を表す。こわれやすさの対義語ではない。"}, {"text": "軽快", "is_correct": false, "explanation": "動きが軽くすばやいことを表す。こわれにくさの対義語ではない。"}, {"text": "謙虚", "is_correct": false, "explanation": "へりくだる態度を表す。物の強さとは関係がない。"}], "correct_answer": "強靭", "explanations": {"強靭": "「脆弱」の対義語。しなやかで強く、こわれにくいことを表す。", "華やか": "目立って美しい様子を表す。こわれやすさの対義語ではない。", "軽快": "動きが軽くすばやいことを表す。こわれにくさの対義語ではない。", "謙虚": "へりくだる態度を表す。物の強さとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "こわれやすいこと。", "primary_collocate": null, "pronunciation": "ぜいじゃく", "ipa": "dzeːdʑakɯ", "syllable_count": 4, "sentences": [{"text": "この古い橋は構造が脆弱で、大型のトラックは通れない。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "この古[ふる]い橋[はし]は構造[こうぞう]が脆弱[ぜいじゃく]で、大型[おおがた]のトラックは通[とお]れない。", "sentence_source": "generated"}, {"text": "脆弱な氷の上を歩くのは危険だから、川には近づかないでください。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "脆弱[ぜいじゃく]な氷[こおり]の上[うえ]を歩[ある]くのは危険[きけん]だから、川[かわ]には近[ちか]づかないでください。", "sentence_source": "generated"}, {"text": "地盤が脆弱な場所に建てた家は、地震で傾きやすい。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "地盤[じばん]が脆弱[ぜいじゃく]な場所[ばしょ]に建[た]てた家[いえ]は、地震[じしん]で傾[かたむ]きやすい。", "sentence_source": "generated"}, {"text": "このガラス細工は脆弱なので、箱に入れて運んでください。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "このガラス細工[ざいく]は脆弱[ぜいじゃく]なので、箱[はこ]に入[い]れて運[はこ]んでください。", "sentence_source": "generated"}, {"text": "薄い板だけで作った棚は脆弱で、重い本を置くと壊れる。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "薄[うす]い板[いた]だけで作[つく]った棚[たな]は脆弱[ぜいじゃく]で、重[おも]い本[ほん]を置[お]くと壊[こわ]れる。", "sentence_source": "generated"}, {"text": "脆弱な土壁は、雨が続くとすぐに崩れてしまった。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "脆弱[ぜいじゃく]な土壁[つちかべ]は、雨[あめ]が続[つづ]くとすぐに崩[くず]れてしまった。", "sentence_source": "generated"}, {"text": "見た目は立派だが、この椅子の脚は脆弱で、座ると揺れる。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "見[み]た目[め]は立派[りっぱ]だが、この椅子[いす]の脚[あし]は脆弱[ぜいじゃく]で、座[すわ]ると揺[ゆ]れる。", "sentence_source": "generated"}, {"text": "海辺の岩は脆弱で、波に削られて少しずつ小さくなっている。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "海辺[うみべ]の岩[いわ]は脆弱[ぜいじゃく]で、波[なみ]に削[けず]られて少[すこ]しずつ小[ちい]さくなっている。", "sentence_source": "generated"}, {"text": "脆弱な骨組みのテントは、強い風で簡単につぶれた。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "脆弱[ぜいじゃく]な骨組[ほねぐ]みのテントは、強[つよ]い風[かぜ]で簡単[かんたん]につぶれた。", "sentence_source": "generated"}, {"text": "紙のように脆弱な素材では、この機械の部品は作れない。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "紙[かみ]のように脆弱[ぜいじゃく]な素材[そざい]では、この機械[きかい]の部品[ぶひん]は作[つく]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆弱だ", "label": "終止形"}, {"form": "脆弱な", "label": "連体形"}, {"form": "脆弱で", "label": "連用形（で）"}, {"form": "脆弱に", "label": "連用形（に）"}, {"form": "脆弱だった", "label": "過去形"}, {"form": "脆弱では", "label": "否定の形に続く形"}], "register": "硬い書き言葉", "sense_fingerprint": "物の作りや材質が弱く、力が加わるとすぐこわれてしまうさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "「構造が脆弱で」は、作りが弱くこわれやすいことを表す。重い車が通れない橋の文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "人の性格や雰囲気を表す語で、橋の構造の状態には使えない。"}, {"text": "穏和", "is_correct": false, "explanation": "人や気候が穏やかなことを表す語で、構造の弱さを説明する文には合わない。"}, {"text": "派手", "is_correct": false, "explanation": "外見が目立つことを表す語で、構造の強さや弱さとは結びつかない。"}], "explanations": {"脆弱": "「構造が脆弱で」は、作りが弱くこわれやすいことを表す。重い車が通れない橋の文脈に合う。", "陽気": "人の性格や雰囲気を表す語で、橋の構造の状態には使えない。", "穏和": "人や気候が穏やかなことを表す語で、構造の弱さを説明する文には合わない。", "派手": "外見が目立つことを表す語で、構造の強さや弱さとは結びつかない。"}, "sentence_index": 0, "correct_answer": "脆弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この織物は脆弱な模様が見事だ。", "explanation": "ここは〈繊細〉の意味。繊細は細かく美しい作りを褒める語で、脆弱は壊れやすさを表すので模様の見事さには使えない。"}, {"text": "この店は品揃えが脆弱で、欲しい物が見つからない。", "explanation": "ここは〈貧弱〉の意味。貧弱は数や質が乏しいことを表す語で、脆弱（壊れやすさ）とは意味が違うので品揃えには合わない。"}, {"text": "この毛布は脆弱で、顔をうずめると気持ちいい。", "explanation": "ここは〈柔らか〉の意味。脆弱は壊れやすさを表し、肌触りのやわらかさを言うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "「脚は脆弱で、座ると揺れる」と続く文脈に合う。作りが弱く、体重で揺れることを表す。"}, {"text": "無邪気", "is_correct": false, "explanation": "子どものように裏表がないことを表す語で、椅子の脚の状態には使えない。"}, {"text": "饒舌", "is_correct": false, "explanation": "よくしゃべることを表す語で、物の構造を説明する文には合わない。"}, {"text": "殊勝", "is_correct": false, "explanation": "行いが感心なほど立派なことを表す語で、椅子の脚の状態には使えない。"}], "explanations": {"脆弱": "「脚は脆弱で、座ると揺れる」と続く文脈に合う。作りが弱く、体重で揺れることを表す。", "無邪気": "子どものように裏表がないことを表す語で、椅子の脚の状態には使えない。", "饒舌": "よくしゃべることを表す語で、物の構造を説明する文には合わない。", "殊勝": "行いが感心なほど立派なことを表す語で、椅子の脚の状態には使えない。"}, "sentence_index": 6, "correct_answer": "脆弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵は色が脆弱で、遠くからでも目立つ。", "explanation": "ここは〈鮮やか〉の意味。鮮やかは色が鮮明なことを表す語で、脆弱（壊れやすさ）では色の鮮明さは表せない。"}, {"text": "彼は脆弱な発想で、新商品を一気に作り上げた。", "explanation": "ここは〈大胆〉の意味。大胆は思い切りよく行動することを表し、脆弱（弱くこわれやすい）とは意味が違う。"}, {"text": "彼女の振る舞いは脆弱で、どこか品がある。", "explanation": "ここは〈上品〉の意味。上品は洗練された品のよさを表す語で、脆弱は壊れやすさを表すので振る舞いの評価には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この壁は脆弱を、雨が降ると崩れやすい。", "corrected_sentence": "この壁は脆弱で、雨が降ると崩れやすい。", "error_description": "形状詞「脆弱」は「で」で続けて状態を述べる。「を」は他動詞の目的語に付く助詞なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脆弱な", "is_correct": true, "explanation": "名詞「氷」を修飾する連体形。文中の「脆弱な氷」に合う。"}, {"text": "脆弱だ", "is_correct": false, "explanation": "終止形。名詞を直接修飾できないので、「氷」の前には置けない。"}, {"text": "脆弱で", "is_correct": false, "explanation": "連用形（で）。「で」で続く形は名詞を修飾できない。"}, {"text": "脆弱に", "is_correct": false, "explanation": "連用形（に）。副詞的に使う形なので、名詞「氷」を修飾できない。"}], "correct_form": "脆弱な", "base_form": "脆弱だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"脆弱な": "名詞「氷」を修飾する連体形。文中の「脆弱な氷」に合う。", "脆弱だ": "終止形。名詞を直接修飾できないので、「氷」の前には置けない。", "脆弱で": "連用形（で）。「で」で続く形は名詞を修飾できない。", "脆弱に": "連用形（に）。副詞的に使う形なので、名詞「氷」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35830, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この板は重みで脆弱すると割れる。", "corrected_sentence": "この板は重みで脆弱になると割れる。", "error_description": "形状詞「脆弱」は動詞「する」に直接続かず、「脆弱にする」「脆弱になる」のように「に」を介する。「脆弱する」は「に」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "文中は「脆弱で」で、語幹「脆弱」に「で」が続いた形。空所には語幹の形が入る。"}, {"text": "脆弱だった", "is_correct": false, "explanation": "過去形。文は現在の状態を述べているので合わない。"}, {"text": "脆弱では", "is_correct": false, "explanation": "否定の形に続く形。「では」は文中の「で」と合わない。"}, {"text": "脆弱な", "is_correct": false, "explanation": "連体形。後ろに名詞が来る形で、「で」が続く文には合わない。"}], "correct_form": "脆弱", "base_form": "脆弱だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"脆弱": "文中は「脆弱で」で、語幹「脆弱」に「で」が続いた形。空所には語幹の形が入る。", "脆弱だった": "過去形。文は現在の状態を述べているので合わない。", "脆弱では": "否定の形に続く形。「では」は文中の「で」と合わない。", "脆弱な": "連体形。後ろに名詞が来る形で、「で」が続く文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強固", "is_correct": true, "explanation": "「脆弱」の対義語。しっかりして崩れにくいことを表し、精神の弱さと反対の関係にある。"}, {"text": "機敏", "is_correct": false, "explanation": "動作がすばやいことを表す。精神の強さの対義語ではない。"}, {"text": "誠実", "is_correct": false, "explanation": "まじめで偽りがないことを表す。もろさの対義語ではない。"}, {"text": "温厚", "is_correct": false, "explanation": "穏やかで人当たりがよいことを表す。もろさの対義語ではない。"}], "correct_answer": "強固", "explanations": {"強固": "「脆弱」の対義語。しっかりして崩れにくいことを表し、精神の弱さと反対の関係にある。", "機敏": "動作がすばやいことを表す。精神の強さの対義語ではない。", "誠実": "まじめで偽りがないことを表す。もろさの対義語ではない。", "温厚": "穏やかで人当たりがよいことを表す。もろさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "堅固", "is_correct": true, "explanation": "「脆弱」の対義語。しっかりして崩れにくいことを表し、組織のもろさと反対の関係にある。"}, {"text": "大らか", "is_correct": false, "explanation": "細かいことにこだわらないことを表す。もろさの対義語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "速いことを表す。崩れにくさの対義語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行うことを表す。組織の強さの対義語ではない。"}], "correct_answer": "堅固", "explanations": {"堅固": "「脆弱」の対義語。しっかりして崩れにくいことを表し、組織のもろさと反対の関係にある。", "大らか": "細かいことにこだわらないことを表す。もろさの対義語ではない。", "迅速": "速いことを表す。崩れにくさの対義語ではない。", "慎重": "注意深く行うことを表す。組織の強さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "もろさがあること。弱いためにこわれたり、やられたりしやすいこと。", "primary_collocate": null, "pronunciation": "ぜいじゃく", "ipa": "dzeːdʑakɯ", "syllable_count": 4, "sentences": [{"text": "古いソフトは防御が脆弱で、外部から簡単に攻撃を受けてしまう。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "古[ふる]いソフトは防御[ぼうぎょ]が脆弱[ぜいじゃく]で、外部[がいぶ]から簡単[かんたん]に攻撃[こうげき]を受[う]けてしまう。", "sentence_source": "generated"}, {"text": "資金の少ない会社は、経営基盤が脆弱で不況に耐えられない。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "資金[しきん]の少[すく]ない会社[かいしゃ]は、経営[けいえい]基盤[きばん]が脆弱[ぜいじゃく]で不況[ふきょう]に耐[た]えられない。", "sentence_source": "generated"}, {"text": "脆弱な体制のままでは、災害が起きたときに町を守れない。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "脆弱[ぜいじゃく]な体制[たいせい]のままでは、災害[さいがい]が起[お]きたときに町[まち]を守[まも]れない。", "sentence_source": "generated"}, {"text": "彼は精神が脆弱で、ちょっとした批判でも落ち込んでしまう。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "彼[かれ]は精神[せいしん]が脆弱[ぜいじゃく]で、ちょっとした批判[ひはん]でも落[お]ち込[こ]んでしまう。", "sentence_source": "generated"}, {"text": "一つの商品だけに頼る経営は脆弱で、売れなくなればすぐ行き詰まる。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "一[ひと]つの商品[しょうひん]だけに頼[たよ]る経営[けいえい]は脆弱[ぜいじゃく]で、売[う]れなくなればすぐ行[い]き詰[づ]まる。", "sentence_source": "generated"}, {"text": "パスワードが単純すぎるシステムは脆弱で、不正にログインされやすい。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "パスワードが単純[たんじゅん]すぎるシステムは脆弱[ぜいじゃく]で、不正[ふせい]にログインされやすい。", "sentence_source": "generated"}, {"text": "外国の資源に頼る脆弱な経済は、価格の変動に振り回される。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "外国[がいこく]の資源[しげん]に頼[たよ]る脆弱[ぜいじゃく]な経済[けいざい]は、価格[かかく]の変動[へんどう]に振[ふ]り回[まわ]される。", "sentence_source": "generated"}, {"text": "小さな島の脆弱な生態系は、外来種が入るとすぐ崩れる。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "小[ちい]さな島[しま]の脆弱[ぜいじゃく]な生態系[せいたいけい]は、外来種[がいらいしゅ]が入[はい]るとすぐ崩[くず]れる。", "sentence_source": "generated"}, {"text": "見張りが少なく警備が脆弱だったため、泥棒に入られた。", "target_word": "脆弱", "complexity_tier": "T3", "furigana": "見張[みは]りが少[すく]なく警備[けいび]が脆弱[ぜいじゃく]だったため、泥棒[どろぼう]に入[はい]られた。", "sentence_source": "generated"}, {"text": "人間関係が脆弱な組織では、問題が起きると一気にばらばらになる。", "target_word": "脆弱な", "complexity_tier": "T3", "furigana": "人間[にんげん]関係[かんけい]が脆弱[ぜいじゃく]な組織[そしき]では、問題[もんだい]が起[お]きると一気[いっき]にばらばらになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆弱だ", "label": "終止形"}, {"form": "脆弱な", "label": "連体形"}, {"form": "脆弱で", "label": "連用形（で）"}, {"form": "脆弱に", "label": "連用形（に）"}, {"form": "脆弱だった", "label": "過去形"}, {"form": "脆弱では", "label": "否定の形に続く形"}], "register": "硬い書き言葉", "sense_fingerprint": "仕組み・組織・心などが弱く、攻撃や打撃を受けると崩れやすいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "「防御が脆弱で」は、攻撃に対して弱いことを表す。外部から攻撃を受ける文脈に合う。"}, {"text": "気さく", "is_correct": false, "explanation": "人当たりがよいことを表す語で、防御の状態には使えない。"}, {"text": "純朴", "is_correct": false, "explanation": "素直で飾り気がないことを表す語で、防御の強さや弱さには合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "大きく勢いがあることを表す語で、防御の状態を説明する文には合わない。"}], "explanations": {"脆弱": "「防御が脆弱で」は、攻撃に対して弱いことを表す。外部から攻撃を受ける文脈に合う。", "気さく": "人当たりがよいことを表す語で、防御の状態には使えない。", "純朴": "素直で飾り気がないことを表す語で、防御の強さや弱さには合わない。", "豪快": "大きく勢いがあることを表す語で、防御の状態を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "脆弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この花は脆弱な茎で、強い風にも折れなかった。", "explanation": "ここは〈頑丈〉の意味。頑丈は丈夫で壊れにくいことを表す語で、脆弱（もろい）では茎の強さは表せない。"}, {"text": "犯人は脆弱な手口で、警備の目をかいくぐった。", "explanation": "ここは〈巧妙〉の意味。巧妙は手際よく工夫されていることを表し、脆弱（弱さ・もろさ）とは意味が違う。"}, {"text": "会社は脆弱な対応で、混乱を最小限に抑えた。", "explanation": "ここは〈柔軟〉の意味。柔軟は状況に合わせて融通がきくことを表し、脆弱は弱くこわれやすい状態を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆弱な", "is_correct": true, "explanation": "「脆弱な経済」は、弱くて外からの変動に揺れやすい経済を表す。価格の変動に振り回される文脈に合う。"}, {"text": "陽気な", "is_correct": false, "explanation": "明るく快活なことを表す語で、経済の状態には使えない。"}, {"text": "謙虚な", "is_correct": false, "explanation": "へりくだる態度を表す語で、経済の状態を説明する文には合わない。"}, {"text": "華麗な", "is_correct": false, "explanation": "はなやかで美しいことを表す語で、経済の弱さを言う文には合わない。"}], "explanations": {"脆弱な": "「脆弱な経済」は、弱くて外からの変動に揺れやすい経済を表す。価格の変動に振り回される文脈に合う。", "陽気な": "明るく快活なことを表す語で、経済の状態には使えない。", "謙虚な": "へりくだる態度を表す語で、経済の状態を説明する文には合わない。", "華麗な": "はなやかで美しいことを表す語で、経済の弱さを言う文には合わない。"}, "sentence_index": 6, "correct_answer": "脆弱な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場は脆弱な柱で支えられ、来場者は安心して過ごせた。", "explanation": "ここは〈堅固〉の意味。堅固はしっかりして崩れにくいことを表す語で、脆弱（もろい）では安心できる支えとは逆になる。"}, {"text": "彼女は脆弱な判断で、危機を乗り切った。", "explanation": "ここは〈冷静〉の意味。冷静は落ち着いて物事を判断することを表し、脆弱は弱くこわれやすいことを表すので判断の評価には使わない。"}, {"text": "脆弱な映像で、現場の様子がよく分かった。", "explanation": "ここは〈鮮明〉の意味。鮮明は細部まではっきり見えることを表し、脆弱（もろい）では映像の明瞭さは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は経営基盤が脆弱だので、不況に耐えられない。", "corrected_sentence": "この会社は経営基盤が脆弱なので、不況に耐えられない。", "error_description": "形状詞「脆弱」は連体形「脆弱な」になって「ので」に続く。「脆弱だ」のままでは「ので」に続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脆弱", "is_correct": true, "explanation": "文中は「脆弱で」で、語幹「脆弱」に「で」が続いた形。空所には語幹の形が入る。"}, {"text": "脆弱だ", "is_correct": false, "explanation": "終止形。「で」で続けて中止する文には合わない。"}, {"text": "脆弱な", "is_correct": false, "explanation": "連体形。後ろに名詞が来る形で、「経営基盤が」の後の述語には合わない。"}, {"text": "脆弱に", "is_correct": false, "explanation": "連用形（に）。「に」で続く形で、文中の「で」と合わない。"}], "correct_form": "脆弱", "base_form": "脆弱だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"脆弱": "文中は「脆弱で」で、語幹「脆弱」に「で」が続いた形。空所には語幹の形が入る。", "脆弱だ": "終止形。「で」で続けて中止する文には合わない。", "脆弱な": "連体形。後ろに名詞が来る形で、「経営基盤が」の後の述語には合わない。", "脆弱に": "連用形（に）。「に」で続く形で、文中の「で」と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は防災体制が脆弱の、災害で大きな被害を受けた。", "corrected_sentence": "この町は防災体制が脆弱で、災害で大きな被害を受けた。", "error_description": "形状詞「脆弱」の後には「の」ではなく「で」が続く。「の」は名詞を修飾する助詞なので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脆弱な", "is_correct": true, "explanation": "名詞「生態系」を修飾する連体形。文中の「脆弱な生態系」に合う。"}, {"text": "脆弱で", "is_correct": false, "explanation": "連用形（で）。名詞を修飾できないので、「生態系」の前には置けない。"}, {"text": "脆弱だった", "is_correct": false, "explanation": "過去形。文は現在の状態を述べているので合わない。"}, {"text": "脆弱では", "is_correct": false, "explanation": "否定の形に続く形。名詞を修飾できないので、「生態系」の前には置けない。"}], "correct_form": "脆弱な", "base_form": "脆弱だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"脆弱な": "名詞「生態系」を修飾する連体形。文中の「脆弱な生態系」に合う。", "脆弱で": "連用形（で）。名詞を修飾できないので、「生態系」の前には置けない。", "脆弱だった": "過去形。文は現在の状態を述べているので合わない。", "脆弱では": "否定の形に続く形。名詞を修飾できないので、「生態系」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一気に露呈」の「に」。副詞的に露呈の様子を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「一気が露呈」では主語にならず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「一気を露呈」では目的語にならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞。「一気から露呈」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「一気に露呈」の「に」。副詞的に露呈の様子を修飾する。", "が": "主語を示す助詞。「一気が露呈」では主語にならず、文が成り立たない。", "を": "目的語を示す助詞。「一気を露呈」では目的語にならないので合わない。", "から": "起点を示す助詞。「一気から露呈」では意味が通らない。"}, "error_tags": {"が": "主語用法", "を": "目的語用法", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "「露呈」の対義語。隠して表に出さないことを表し、問題が表に出る意味と反対の関係にある。"}, {"text": "改善", "is_correct": false, "explanation": "悪い点をよくすることを表す。隠すことの反対語ではない。"}, {"text": "謝罪", "is_correct": false, "explanation": "詫びることを表す。隠すことの反対語ではない。"}, {"text": "指導", "is_correct": false, "explanation": "教えて導くことを表す。隠すことの反対語ではない。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "「露呈」の対義語。隠して表に出さないことを表し、問題が表に出る意味と反対の関係にある。", "改善": "悪い点をよくすることを表す。隠すことの反対語ではない。", "謝罪": "詫びることを表す。隠すことの反対語ではない。", "指導": "教えて導くことを表す。隠すことの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "「露呈」の対義語。隠して表に出さないことを表し、問題が表に出る意味と反対の関係にある。"}, {"text": "撤回", "is_correct": false, "explanation": "発言や申し出を取り消すことを表す。隠すことの反対語ではない。"}, {"text": "調整", "is_correct": false, "explanation": "物事を整えることを表す。隠すことの反対語ではない。"}, {"text": "配布", "is_correct": false, "explanation": "広く配ることを表す。隠すことの反対語ではない。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "「露呈」の対義語。隠して表に出さないことを表し、問題が表に出る意味と反対の関係にある。", "撤回": "発言や申し出を取り消すことを表す。隠すことの反対語ではない。", "調整": "物事を整えることを表す。隠すことの反対語ではない。", "配布": "広く配ることを表す。隠すことの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "隠れていた問題や悪いところが、外から見えるようになること。", "primary_collocate": null, "pronunciation": "ろてい", "ipa": "ɾoteː", "syllable_count": 3, "sentences": [{"text": "試合が進むにつれて、このチームの守備の弱さが露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "試合[しあい]が進[すす]むにつれて、このチームの守備[しゅび]の弱[よわ]さが露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "新しい制度が始まると、準備不足が一気に露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]が始[はじ]まると、準備[じゅんび]不足[ぶそく]が一気[いっき]に露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "台風の被害で、町の防災対策の甘さが露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "台風[たいふう]の被害[ひがい]で、町[まち]の防災[ぼうさい]対策[たいさく]の甘[あま]さが露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "検査の結果、工場の管理のずさんさが露呈し、会社は謝罪した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]、工場[こうじょう]の管理[かんり]のずさんさが露呈[ろてい]し、会社[かいしゃ]は謝罪[しゃざい]した。", "sentence_source": "generated"}, {"text": "厳しい質問を受けて、彼の知識不足が露呈してしまった。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "厳[きび]しい質問[しつもん]を受[う]けて、彼[かれ]の知識[ちしき]不足[ぶそく]が露呈[ろてい]してしまった。", "sentence_source": "generated"}, {"text": "不況になって、この業界が抱える古い体質が露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "不況[ふきょう]になって、この業界[ぎょうかい]が抱[かか]える古[ふる]い体質[たいしつ]が露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "停電が起きたとき、ビルの非常用設備に欠陥があることが露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "停電[ていでん]が起[お]きたとき、ビルの非常用[ひじょうよう]設備[せつび]に欠陥[けっかん]があることが露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "練習ではうまくいったが、本番で彼女の経験の浅さが露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "練習[れんしゅう]ではうまくいったが、本番[ほんばん]で彼女[かのじょ]の経験[けいけん]の浅[あさ]さが露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "計画の甘さが露呈する前に、担当者は急いで手を打った。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "計画[けいかく]の甘[あま]さが露呈[ろてい]する前[まえ]に、担当者[たんとうしゃ]は急[いそ]いで手[て]を打[う]った。", "sentence_source": "generated"}, {"text": "大きな事故をきっかけに、安全管理の問題が露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "大[おお]きな事故[じこ]をきっかけに、安全[あんぜん]管理[かんり]の問題[もんだい]が露呈[ろてい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "露呈する", "label": "終止形"}, {"form": "露呈した", "label": "過去形"}, {"form": "露呈して", "label": "て形"}, {"form": "露呈しない", "label": "否定形"}, {"form": "露呈する", "label": "連体形"}, {"form": "露呈し", "label": "連用形"}], "register": "硬い書き言葉", "sense_fingerprint": "それまで隠れていた欠点・弱点・問題が、意図せず表に出てしまうこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "露呈", "is_correct": true, "explanation": "隠れていた守備の弱さが表に出ることを表す。試合が進んで弱点が現れた文脈に合う。"}, {"text": "配慮", "is_correct": false, "explanation": "相手の状況を思いやることを表す語で、「弱さが〜した」とは続かない。"}, {"text": "演習", "is_correct": false, "explanation": "練習や訓練を行うことを表す語で、守備の弱さを主語にすると意味が通らない。"}, {"text": "納得", "is_correct": false, "explanation": "了解して受け入れることを表す語で、守備の弱さを主語にすると成り立たない。"}], "explanations": {"露呈": "隠れていた守備の弱さが表に出ることを表す。試合が進んで弱点が現れた文脈に合う。", "配慮": "相手の状況を思いやることを表す語で、「弱さが〜した」とは続かない。", "演習": "練習や訓練を行うことを表す語で、守備の弱さを主語にすると意味が通らない。", "納得": "了解して受け入れることを表す語で、守備の弱さを主語にすると成り立たない。"}, "sentence_index": 0, "correct_answer": "露呈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画会社は新作の映画を露呈した。", "explanation": "ここは〈公開〉の意味。公開は作品を広く見せることで、露呈は隠れていた欠点が表に出ることなので、計画的な公開には使わない。"}, {"text": "研究チームは新しい成果を露呈した。", "explanation": "ここは〈発表〉の意味。発表は成果を公にすることで、露呈は隠れていた欠点や問題が表に出る意味なので、成果の発表には使わない。"}, {"text": "開会式の準備が予定より早く露呈した。", "explanation": "ここは〈完成〉の意味。完成は準備や物事が仕上がることで、露呈は隠れていた問題が見えてくることなので、ここでは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "露呈", "is_correct": true, "explanation": "隠れていた欠陥が表に出たことを表す。非常用設備の欠陥が停電で明らかになった文脈に合う。"}, {"text": "同意", "is_correct": false, "explanation": "意見が一致することを表す語で、欠陥を主語にすると成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつけることを表す語で、欠陥を主語にすると意味が通らない。"}, {"text": "出勤", "is_correct": false, "explanation": "職場に出ることを表す語で、欠陥を主語にすると成り立たない。"}], "explanations": {"露呈": "隠れていた欠陥が表に出たことを表す。非常用設備の欠陥が停電で明らかになった文脈に合う。", "同意": "意見が一致することを表す語で、欠陥を主語にすると成り立たない。", "採点": "点数をつけることを表す語で、欠陥を主語にすると意味が通らない。", "出勤": "職場に出ることを表す語で、欠陥を主語にすると成り立たない。"}, "sentence_index": 6, "correct_answer": "露呈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多くの人が彼女の努力を露呈した。", "explanation": "ここは〈賞賛〉の意味。賞賛は立派な行いをほめることで、露呈は隠れていた問題が表に出ることなので、ほめる意味には使わない。"}, {"text": "彼は新しい店を友人に露呈した。", "explanation": "ここは〈紹介〉の意味。紹介は人に知らせて引き合わせることで、露呈は隠れていた問題が見えてくることなので、ここでは使えない。"}, {"text": "係員は重要な書類を厳重に露呈した。", "explanation": "ここは〈保管〉の意味。保管は大切に預かって保つことで、露呈は表に出ることなので、保管の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
