INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35832, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本番で彼女の経験の浅さが露呈したで、試合に負けた。", "corrected_sentence": "本番で彼女の経験の浅さが露呈して、試合に負けた。", "error_description": "「露呈した」に「で」は続けられない。前の文と続けるには「露呈して」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "「露呈」の対義語。隠して表に出さないことを表し、本音が表に出る意味と反対の関係にある。"}, {"text": "交換", "is_correct": false, "explanation": "互いに物を取り替えることを表す。隠すことの反対語ではない。"}, {"text": "整理", "is_correct": false, "explanation": "乱れを正して片付けることを表す。隠すことの反対語ではない。"}, {"text": "通知", "is_correct": false, "explanation": "知らせることを表す。隠すことの反対語ではない。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "「露呈」の対義語。隠して表に出さないことを表し、本音が表に出る意味と反対の関係にある。", "交換": "互いに物を取り替えることを表す。隠すことの反対語ではない。", "整理": "乱れを正して片付けることを表す。隠すことの反対語ではない。", "通知": "知らせることを表す。隠すことの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
