INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今まで隠れていた事実や問題などが、明らかになること。また、自分から進んで明らかにすること。", "primary_collocate": null, "pronunciation": "ろてい", "ipa": "ɾoteː", "syllable_count": 3, "sentences": [{"text": "長年隠していた不正が、内部の告発によって露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "長年[ながねん]隠[かく]していた不正[ふせい]が、内部[ないぶ]の告発[こくはつ]によって露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "嘘を重ねた結果、矛盾が増えて、ついに彼の素性が露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "嘘[うそ]を重[かさ]ねた結果[けっか]、矛盾[むじゅん]が増[ふ]えて、ついに彼[かれ]の素性[すじょう]が露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "調査が進み、事件の裏にある事実が次々と露呈していった。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "調査[ちょうさ]が進[すす]み、事件[じけん]の裏[うら]にある事実[じじつ]が次々[つぎつぎ]と露呈[ろてい]していった。", "sentence_source": "generated"}, {"text": "彼は酔って、日ごろ隠している本音を露呈してしまった。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "彼[かれ]は酔[よ]って、日[ひ]ごろ隠[かく]している本音[ほんね]を露呈[ろてい]してしまった。", "sentence_source": "generated"}, {"text": "作者は小説の中で、自らの弱さを正直に露呈している。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は小説[しょうせつ]の中[なか]で、自[みずか]らの弱[よわ]さを正直[しょうじき]に露呈[ろてい]している。", "sentence_source": "generated"}, {"text": "取引先の情報が漏れ、会社の秘密が露呈する恐れがある。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]の情報[じょうほう]が漏[も]れ、会社[かいしゃ]の秘密[ひみつ]が露呈[ろてい]する恐[おそ]れがある。", "sentence_source": "generated"}, {"text": "記者の取材で、政治家の隠し資金が露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "記者[きしゃ]の取材[しゅざい]で、政治家[せいじか]の隠[かく]し資金[しきん]が露呈[ろてい]した。", "sentence_source": "generated"}, {"text": "誰にも言えなかった過去が露呈して、彼女は仕事を辞めた。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "誰[だれ]にも言[い]えなかった過去[かこ]が露呈[ろてい]して、彼女[かのじょ]は仕事[しごと]を辞[や]めた。", "sentence_source": "generated"}, {"text": "彼はあえて自分の失敗を露呈し、部下に学んでほしいと考えた。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "彼[かれ]はあえて自分[じぶん]の失敗[しっぱい]を露呈[ろてい]し、部下[ぶか]に学[まな]んでほしいと考[かんが]えた。", "sentence_source": "generated"}, {"text": "昔の写真が見つかり、二人が知り合いだったことが露呈した。", "target_word": "露呈", "complexity_tier": "T3", "furigana": "昔[むかし]の写真[しゃしん]が見[み]つかり、二人[ふたり]が知[し]り合[あ]いだったことが露呈[ろてい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "露呈する", "label": "終止形"}, {"form": "露呈した", "label": "過去形"}, {"form": "露呈して", "label": "て形"}, {"form": "露呈しない", "label": "否定形"}, {"form": "露呈していった", "label": "変化の進行を表す形"}, {"form": "露呈し", "label": "連用形"}], "register": "硬い書き言葉", "sense_fingerprint": "隠されていた事実・秘密・本音が明るみに出ること、または自ら見せること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "露呈", "is_correct": true, "explanation": "隠していた不正が表に出たことを表す。告発によって明らかになった文脈に合う。"}, {"text": "承諾", "is_correct": false, "explanation": "相手の求めに応じることを表す語で、不正を主語にすると成り立たない。"}, {"text": "逆転", "is_correct": false, "explanation": "立場や形勢が反対になることを表す語で、「不正が逆転した」とは意味が通らない。"}, {"text": "欠席", "is_correct": false, "explanation": "その場にいないことを表す語で、不正を主語にすると成り立たない。"}], "explanations": {"露呈": "隠していた不正が表に出たことを表す。告発によって明らかになった文脈に合う。", "承諾": "相手の求めに応じることを表す語で、不正を主語にすると成り立たない。", "逆転": "立場や形勢が反対になることを表す語で、「不正が逆転した」とは意味が通らない。", "欠席": "その場にいないことを表す語で、不正を主語にすると成り立たない。"}, "sentence_index": 0, "correct_answer": "露呈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場は毎日千個の部品を露呈した。", "explanation": "ここは〈生産〉の意味。生産は物をつくることで、露呈は隠れていた事実が明らかになることなので、物づくりには使わない。"}, {"text": "多くの人が彼の勇気を露呈した。", "explanation": "ここは〈賞賛〉の意味。賞賛は立派な行いをほめることで、露呈は隠れていた事実が明らかになることなので、ほめる意味には使わない。"}, {"text": "彼は三つの賞を露呈した。", "explanation": "ここは〈受賞〉の意味。受賞は賞を得ることで、露呈は隠れていた事実が明らかになることなので、賞を得る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "露呈", "is_correct": true, "explanation": "隠し資金が取材によって表に出たことを表す。政治家の資金が明らかになった文脈に合う。"}, {"text": "延長", "is_correct": false, "explanation": "長さや期間を延ばすことを表す語で、資金を主語にすると意味が通らない。"}, {"text": "着任", "is_correct": false, "explanation": "任地や役職に就くことを表す語で、資金を主語にすると成り立たない。"}, {"text": "落成", "is_correct": false, "explanation": "建物が完成することを表す語で、資金を主語にすると意味が通らない。"}], "explanations": {"露呈": "隠し資金が取材によって表に出たことを表す。政治家の資金が明らかになった文脈に合う。", "延長": "長さや期間を延ばすことを表す語で、資金を主語にすると意味が通らない。", "着任": "任地や役職に就くことを表す語で、資金を主語にすると成り立たない。", "落成": "建物が完成することを表す語で、資金を主語にすると意味が通らない。"}, "sentence_index": 6, "correct_answer": "露呈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は新しい化粧品を三か月かけて露呈した。", "explanation": "ここは〈開発〉の意味。開発は新しい物をつくり出すことで、露呈は隠れていた事実が明らかになることなので、ここでは使えない。"}, {"text": "市役所は古い地図を図書館に露呈した。", "explanation": "ここは〈寄贈〉の意味。寄贈は物を無償で贈ることで、露呈は隠れていた事実が明らかになることなので、贈る意味では使わない。"}, {"text": "店は備品を大量に露呈した。", "explanation": "ここは〈発注〉の意味。発注は商品や材料を注文することで、露呈は隠れていた事実が表に出ることなので、注文の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "嘘の矛盾に露呈して、彼は追い詰められた。", "corrected_sentence": "嘘の矛盾が露呈して、彼は追い詰められた。", "error_description": "露呈の主語には「が」を付ける。「に」は場所や対象を示す助詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35833, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の写真が見つかり、二人が知り合いだったことが露呈ていた。", "corrected_sentence": "昔の写真が見つかり、二人が知り合いだったことが露呈していた。", "error_description": "「露呈する」は「露呈している」と活用する。「露呈ていた」は「し」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『革新を恐れずに』と、恐れる対象を示す『を』が正しい。"}, {"text": "が", "is_correct": false, "explanation": "『革新が恐れずに』では、革新が恐れる主体になり、会社の姿勢を述べる文と合わない。"}, {"text": "に", "is_correct": false, "explanation": "『革新に恐れずに』では、恐れる対象の示し方として不自然。"}, {"text": "で", "is_correct": false, "explanation": "『革新で恐れずに』では手段・場所の意味になり、恐れる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "『革新を恐れずに』と、恐れる対象を示す『を』が正しい。", "が": "『革新が恐れずに』では、革新が恐れる主体になり、会社の姿勢を述べる文と合わない。", "に": "『革新に恐れずに』では、恐れる対象の示し方として不自然。", "で": "『革新で恐れずに』では手段・場所の意味になり、恐れる対象を表せない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "〈革新〉の対義語。古い方法や仕組みを守る立場を表し、この印刷技術の文脈とも対になる。"}, {"text": "運搬", "is_correct": false, "explanation": "同じ名詞だが、物を運ぶ行為を表すので、革新の対義語ではない。"}, {"text": "模倣", "is_correct": false, "explanation": "他のものをまねする行為で、革新と対になる語ではない。"}, {"text": "配布", "is_correct": false, "explanation": "物を配ることを表し、革新の対義語にはならない。"}], "correct_answer": "保守", "explanations": {"保守": "〈革新〉の対義語。古い方法や仕組みを守る立場を表し、この印刷技術の文脈とも対になる。", "運搬": "同じ名詞だが、物を運ぶ行為を表すので、革新の対義語ではない。", "模倣": "他のものをまねする行為で、革新と対になる語ではない。", "配布": "物を配ることを表し、革新の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『通信の革新と呼ばれた』と、名付けの対象を示す『と』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『革新を呼ばれた』では、呼ぶ対象を示せず、受け身の文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『革新が呼ばれた』では主語になり、名付けの意味が出ない。"}, {"text": "の", "is_correct": false, "explanation": "『革新の呼ばれた』と続けると、名詞修飾が崩れ、述語が立たない。"}], "correct_answer": "と", "explanations": {"と": "『通信の革新と呼ばれた』と、名付けの対象を示す『と』が正しい。", "を": "『革新を呼ばれた』では、呼ぶ対象を示せず、受け身の文として成り立たない。", "が": "『革新が呼ばれた』では主語になり、名付けの意味が出ない。", "の": "『革新の呼ばれた』と続けると、名詞修飾が崩れ、述語が立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "〈革新〉の対義語。古い仕組みを守る立場で、新しい客を呼ぶという変化の文脈と対になる。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語にする行為で、革新の対義語ではない。"}, {"text": "収集", "is_correct": false, "explanation": "物を集める行為を表し、革新と対になる語ではない。"}, {"text": "監督", "is_correct": false, "explanation": "人や物を見守る行為を表し、革新の対義語にはならない。"}], "correct_answer": "保守", "explanations": {"保守": "〈革新〉の対義語。古い仕組みを守る立場で、新しい客を呼ぶという変化の文脈と対になる。", "翻訳": "言葉を別の言語にする行為で、革新の対義語ではない。", "収集": "物を集める行為を表し、革新と対になる語ではない。", "監督": "人や物を見守る行為を表し、革新の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "新しく、より良いものを作ること。", "primary_collocate": null, "pronunciation": "かくしん", "ipa": "kakɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "新しい技術の革新が、私たちの生活を大きく変えた。", "target_word": "革新", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]の革新[かくしん]が、私[わたし]たちの生活[せいかつ]を大[おお]きく変[か]えた。", "sentence_source": "generated"}, {"text": "この会社は、革新を恐れずに新しい商品を作り続けている。", "target_word": "革新", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、革新[かくしん]を恐[おそ]れずに新[あたら]しい商品[しょうひん]を作[つく]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "農業にも革新が必要だと、若い農家たちは考えている。", "target_word": "革新", "complexity_tier": "T3", "furigana": "農業[のうぎょう]にも革新[かくしん]が必要[ひつよう]だと、若[わか]い農家[のうか]たちは考[かんが]えている。", "sentence_source": "generated"}, {"text": "印刷技術の革新によって、本が安く買えるようになった。", "target_word": "革新", "complexity_tier": "T3", "furigana": "印刷技術[いんさつぎじゅつ]の革新[かくしん]によって、本[ほん]が安[やす]く買[か]えるようになった。", "sentence_source": "generated"}, {"text": "企業は、革新をやめれば、すぐに競争に負けてしまう。", "target_word": "革新", "complexity_tier": "T3", "furigana": "企業[きぎょう]は、革新[かくしん]をやめれば、すぐに競争[きょうそう]に負[ま]けてしまう。", "sentence_source": "generated"}, {"text": "彼の研究は医療に革新をもたらしたと評価されている。", "target_word": "革新", "complexity_tier": "T3", "furigana": "彼[かれ]の研究[けんきゅう]は医療[いりょう]に革新[かくしん]をもたらしたと評価[ひょうか]されている。", "sentence_source": "generated"}, {"text": "古い方法に頼らず、革新に挑戦する姿勢が大切だ。", "target_word": "革新", "complexity_tier": "T3", "furigana": "古[ふる]い方法[ほうほう]に頼[たよ]らず、革新[かくしん]に挑戦[ちょうせん]する姿勢[しせい]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "スマートフォンの登場は、通信の革新と呼ばれた。", "target_word": "革新", "complexity_tier": "T3", "furigana": "スマートフォンの登場[とうじょう]は、通信[つうしん]の革新[かくしん]と呼[よ]ばれた。", "sentence_source": "generated"}, {"text": "工場では、生産の革新を進めるため、新しい機械を入れた。", "target_word": "革新", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、生産[せいさん]の革新[かくしん]を進[すす]めるため、新[あたら]しい機械[きかい]を入[い]れた。", "sentence_source": "generated"}, {"text": "小さな町の店でも、革新を続ければ、新しい客を呼べる。", "target_word": "革新", "complexity_tier": "T3", "furigana": "小[ちい]さな町[まち]の店[みせ]でも、革新[かくしん]を続[つづ]ければ、新[あたら]しい客[きゃく]を呼[よ]べる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "革新", "label": "基本形"}, {"form": "革新する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "古い方法や仕組みを改め、新しくより良いものにすること。技術・経営などの革新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "革新", "is_correct": true, "explanation": "『新しい技術の革新が生活を大きく変えた』と、技術の変化を表す主語として自然。"}, {"text": "天井", "is_correct": false, "explanation": "天井は技術の変化の主語にならず、『新しい技術の天井が生活を変えた』は意味が通らない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は技術そのものの変化を指す語ではなく、この文の主語として不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は生活を大きく変える主語にならず、『新しい技術の眠気』は文脈に合わない。"}], "explanations": {"革新": "『新しい技術の革新が生活を大きく変えた』と、技術の変化を表す主語として自然。", "天井": "天井は技術の変化の主語にならず、『新しい技術の天井が生活を変えた』は意味が通らない。", "地図": "地図は技術そのものの変化を指す語ではなく、この文の主語として不自然。", "眠気": "眠気は生活を大きく変える主語にならず、『新しい技術の眠気』は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "運転免許の革新の手続きを、昨日ようやく済ませた。", "explanation": "ここは〈更新〉（期限が来て新しくし直す）の意味。『運転免許の更新』の『更新』に当たる語で、『革新』は新しく良いものを作る意味なので、免許の手続きには使わない。"}, {"text": "雨が続いたため、出発を革新することにした。", "explanation": "ここは〈延期〉（予定を先に延ばす）の意味。『出発を延期する』の『延期』に当たる語で、『革新』は新しく良いものを作る意味なので、予定を遅らせる場面には使わない。"}, {"text": "試合が同点になったため、時間を革新することになった。", "explanation": "ここは〈延長〉（時間を長くすること）の意味。『試合を延長する』の『延長』に当たる語で、『革新』は新しく良いものを作る意味なので、時間を長くする場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "革新", "is_correct": true, "explanation": "『古い方法に頼らず、革新に挑戦する』と、新しいものへの挑戦を表す語として自然。"}, {"text": "雷", "is_correct": false, "explanation": "雷は挑戦の対象として成り立たず、『雷に挑戦する姿勢』は意味が通らない。"}, {"text": "氷河", "is_correct": false, "explanation": "氷河は挑戦する姿勢の対象として不自然で、文脈に合わない。"}, {"text": "砂時計", "is_correct": false, "explanation": "砂時計は挑戦の対象にならず、『砂時計に挑戦する』は成り立たない。"}], "explanations": {"革新": "『古い方法に頼らず、革新に挑戦する』と、新しいものへの挑戦を表す語として自然。", "雷": "雷は挑戦の対象として成り立たず、『雷に挑戦する姿勢』は意味が通らない。", "氷河": "氷河は挑戦する姿勢の対象として不自然で、文脈に合わない。", "砂時計": "砂時計は挑戦の対象にならず、『砂時計に挑戦する』は成り立たない。"}, "sentence_index": 6, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の影響で、来週の予定を革新することになった。", "explanation": "ここは〈変更〉（内容を別のものに改める）の意味。『予定を変更する』の『変更』に当たる語で、『革新』は新しく良いものを作る意味なので、予定の組み替えには使わない。"}, {"text": "先生は答案を革新して、点数をつけた。", "explanation": "ここは〈採点〉（答案の出来を評価する）の意味。『答案を採点する』の『採点』に当たる語で、『革新』は新しく良いものを作る意味なので、評価の行為には使わない。"}, {"text": "申込書の欄に革新を書いた。", "explanation": "ここは〈記入〉（書類に書き込むこと）の意味。『欄に記入する』の『記入』に当たる語で、『革新』は新しく良いものを作る意味なので、書類に書き込む場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企業は、革新に進めなければ生き残れない。", "corrected_sentence": "企業は、革新を進めなければ生き残れない。", "error_description": "『進める』の目的語は『を』で示す。『に』にすると『革新に進める』となり、対象が合わず不自然。正しくは『革新を』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35836, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い仕組みを改め、革新が起こす会社が伸びる。", "corrected_sentence": "古い仕組みを改め、革新を起こす会社が伸びる。", "error_description": "『起こす』の目的語は『を』で示す。『が』にすると『革新が起こす』となり、主語と動詞の関係が崩れる。正しくは『革新を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "「透明」の対義語。隠し事があり、見えない状態を指すので、この運営の文脈で対になる。"}, {"text": "寛容", "is_correct": false, "explanation": "広く受け入れる態度を表す語で、透明とは対義関係ではない。"}, {"text": "簡素", "is_correct": false, "explanation": "飾りがなく単純なことを表す語で、透明とは対義関係ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいことを表す語で、透明とは対義関係ではない。"}], "correct_answer": "不透明", "explanations": {"不透明": "「透明」の対義語。隠し事があり、見えない状態を指すので、この運営の文脈で対になる。", "寛容": "広く受け入れる態度を表す語で、透明とは対義関係ではない。", "簡素": "飾りがなく単純なことを表す語で、透明とは対義関係ではない。", "頑丈": "丈夫で壊れにくいことを表す語で、透明とは対義関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "「透明」の対義語。資金の使い道が見えない状態を指すので、この文の文脈で対になる。"}, {"text": "柔軟", "is_correct": false, "explanation": "状況に応じて変えられることを表す語で、対義語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "速やかなことを表す語で、対義語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "細やかで礼儀正しいことを表す語で、対義語ではない。"}], "correct_answer": "不透明", "explanations": {"不透明": "「透明」の対義語。資金の使い道が見えない状態を指すので、この文の文脈で対になる。", "柔軟": "状況に応じて変えられることを表す語で、対義語ではない。", "迅速": "速やかなことを表す語で、対義語ではない。", "丁寧": "細やかで礼儀正しいことを表す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事が隠されていなくて、誰でも見たり知ったりできること。", "primary_collocate": null, "pronunciation": "とうめい", "ipa": "toːmeː", "syllable_count": 4, "sentences": [{"text": "市は予算の使い道を公開し、透明な行政を目指している。", "target_word": "透明な", "complexity_tier": "T3", "furigana": "市[し]は予算[よさん]の使[つか]い道[みち]を公開[こうかい]し、透明[とうめい]な行政[ぎょうせい]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "選考の過程が透明でないと、不公平だという不満が出る。", "target_word": "透明", "complexity_tier": "T3", "furigana": "選考[せんこう]の過程[かてい]が透明[とうめい]でないと、不公平[ふこうへい]だという不満[ふまん]が出[で]る。", "sentence_source": "generated"}, {"text": "お金の流れを透明にするため、毎月の報告書を発表している。", "target_word": "透明に", "complexity_tier": "T3", "furigana": "お金[かね]の流[なが]れを透明[とうめい]にするため、毎月[まいつき]の報告書[ほうこくしょ]を発表[はっぴょう]している。", "sentence_source": "generated"}, {"text": "透明な運営を続けた結果、会員の信頼が高まった。", "target_word": "透明な", "complexity_tier": "T3", "furigana": "透明[とうめい]な運営[うんえい]を続[つづ]けた結果[けっか]、会員[かいいん]の信頼[しんらい]が高[たか]まった。", "sentence_source": "generated"}, {"text": "会議の内容が透明になり、社員は会社の方針をよく理解できた。", "target_word": "透明に", "complexity_tier": "T3", "furigana": "会議[かいぎ]の内容[ないよう]が透明[とうめい]になり、社員[しゃいん]は会社[かいしゃ]の方針[ほうしん]をよく理解[りかい]できた。", "sentence_source": "generated"}, {"text": "取引のルールが透明だから、初めての人でも安心して参加できる。", "target_word": "透明", "complexity_tier": "T3", "furigana": "取引[とりひき]のルールが透明[とうめい]だから、初[はじ]めての人[ひと]でも安心[あんしん]して参加[さんか]できる。", "sentence_source": "generated"}, {"text": "透明な組織であるために、記録はすべて保存される。", "target_word": "透明な", "complexity_tier": "T3", "furigana": "透明[とうめい]な組織[そしき]であるために、記録[きろく]はすべて保存[ほぞん]される。", "sentence_source": "generated"}, {"text": "この団体は寄付金の使い方が透明で、誰でもホームページで確認できる。", "target_word": "透明", "complexity_tier": "T3", "furigana": "この団体[だんたい]は寄付金[きふきん]の使[つか]い方[かた]が透明[とうめい]で、誰[だれ]でもホームページで確認[かくにん]できる。", "sentence_source": "generated"}, {"text": "評価の基準が透明になれば、社員は何を頑張ればよいかが分かる。", "target_word": "透明に", "complexity_tier": "T3", "furigana": "評価[ひょうか]の基準[きじゅん]が透明[とうめい]になれば、社員[しゃいん]は何[なに]を頑張[がんば]ればよいかが分[わ]かる。", "sentence_source": "generated"}, {"text": "政治家は、資金の使い道を透明な形で国民に知らせる責任がある。", "target_word": "透明", "complexity_tier": "T3", "furigana": "政治家[せいじか]は、資金[しきん]の使い道[つかいみち]を透明[とうめい]な形[かたち]で国民[こくみん]に知[し]らせる責任[せきにん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "透明だ", "label": "終止形"}, {"form": "透明な", "label": "連体形"}, {"form": "透明で", "label": "連用形（で）"}, {"form": "透明に", "label": "連用形（に）"}, {"form": "透明だった", "label": "過去形"}, {"form": "透明でない", "label": "否定形"}], "register": "硬い書き言葉", "sense_fingerprint": "運営・お金・手続きなどが公開されていて、誰でも内容を確認できるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明な", "is_correct": true, "explanation": "「透明な行政」の連体形。名詞「行政」を直接修飾する。"}, {"text": "透明に", "is_correct": false, "explanation": "副詞形で名詞を修飾できないので、「透明に行政」は入らない。"}, {"text": "透明で", "is_correct": false, "explanation": "連用中止形で、名詞の前に置けず不適。"}, {"text": "透明だった", "is_correct": false, "explanation": "過去形の述語で、名詞を修飾できない。"}], "explanations": {"透明な": "「透明な行政」の連体形。名詞「行政」を直接修飾する。", "透明に": "副詞形で名詞を修飾できないので、「透明に行政」は入らない。", "透明で": "連用中止形で、名詞の前に置けず不適。", "透明だった": "過去形の述語で、名詞を修飾できない。"}, "sentence_index": 0, "correct_answer": "透明な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪で喉が透明で、ひどく痛い。", "explanation": "ここは〈痛い〉の意味。喉の痛みには痛いを使い、透明は喉の状態には使わないので合わない。"}, {"text": "この部屋は透明で、ホコリ一つない。", "explanation": "ここは〈清潔〉の意味。部屋の汚れのなさは透明とは言わず、清潔を使う。"}, {"text": "この果物は透明で、とても甘い。", "explanation": "ここは〈甘い〉の意味。果物の味には甘いを使い、透明は味を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明な", "is_correct": true, "explanation": "名詞「組織」を修飾する形。「透明な組織」として文が通る。"}, {"text": "透明だ", "is_correct": false, "explanation": "終止形で名詞を直接修飾できない。「透明だ組織」は成り立たない。"}, {"text": "透明化", "is_correct": false, "explanation": "変化や処理を表す名詞で、「透明化組織」とは続かない。"}, {"text": "透明さ", "is_correct": false, "explanation": "性質を表す名詞で、「透明さ組織」とは続かない。"}], "explanations": {"透明な": "名詞「組織」を修飾する形。「透明な組織」として文が通る。", "透明だ": "終止形で名詞を直接修飾できない。「透明だ組織」は成り立たない。", "透明化": "変化や処理を表す名詞で、「透明化組織」とは続かない。", "透明さ": "性質を表す名詞で、「透明さ組織」とは続かない。"}, "sentence_index": 6, "correct_answer": "透明な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このトマトは透明で、とても赤い。", "explanation": "ここは〈赤い〉の意味。色の赤さには赤いを使い、透明は色を表さないので合わない。"}, {"text": "透明な広告で、人目を引くことに成功した。", "explanation": "ここは〈派手〉の意味。人目を引く目立ちやすさを表す語で、透明は隠し事がないことなので合わない。"}, {"text": "この山道は透明で、とても険しい。", "explanation": "ここは〈険しい〉の意味。道の険しさには険しいを使い、透明は道の状態を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は予算を透明なするため、会議の記録を公開した。", "corrected_sentence": "市は予算を透明にするため、会議の記録を公開した。", "error_description": "「透明にする」は連用形「に」が必要。「透明な」は名詞の前だけで使うので、「する」の前では誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "透明", "is_correct": true, "explanation": "語幹の形。文中では「透明でない」として使われる。"}, {"text": "透明な", "is_correct": false, "explanation": "連体形。「透明な、でない」の形は成り立たない。"}, {"text": "透明に", "is_correct": false, "explanation": "副詞形。「透明にでない」とは続かない。"}, {"text": "透明だった", "is_correct": false, "explanation": "過去形。「透明だったでないと」は不自然。"}], "correct_form": "透明", "base_form": "透明だ", "form_label": "否定形", "sentence_index": 1, "explanations": {"透明": "語幹の形。文中では「透明でない」として使われる。", "透明な": "連体形。「透明な、でない」の形は成り立たない。", "透明に": "副詞形。「透明にでない」とは続かない。", "透明だった": "過去形。「透明だったでないと」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35838, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は取引の条件を透明なして、社員に説明した。", "corrected_sentence": "会社は取引の条件を透明にして、社員に説明した。", "error_description": "「透明にして」は連用形「に」が必要。「透明な」は名詞の前だけで使うので、「して」の前には入らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "透明", "is_correct": true, "explanation": "語幹の形。文中では「透明で」として「誰でも確認できる」に続く。"}, {"text": "透明だ", "is_correct": false, "explanation": "終止形。「透明だ、誰でも」とは続かない。"}, {"text": "透明でない", "is_correct": false, "explanation": "否定形。「使い方が透明でない」と言うと文の意味が逆になる。"}, {"text": "透明なら", "is_correct": false, "explanation": "仮定形。文の意味が「もし透明なら」に変わり、事実の説明にならない。"}], "correct_form": "透明", "base_form": "透明だ", "form_label": "連用形（で）", "sentence_index": 7, "explanations": {"透明": "語幹の形。文中では「透明で」として「誰でも確認できる」に続く。", "透明だ": "終止形。「透明だ、誰でも」とは続かない。", "透明でない": "否定形。「使い方が透明でない」と言うと文の意味が逆になる。", "透明なら": "仮定形。文の意味が「もし透明なら」に変わり、事実の説明にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "「透明」の対義語。光が通らず向こうが見えない状態を指す。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがないことを表す語で、対義語の関係ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいことを表し、透明とは対義関係ではない。"}, {"text": "穏やか", "is_correct": false, "explanation": "荒れていないことを表す語で、対義語の関係ではない。"}], "correct_answer": "不透明", "explanations": {"不透明": "「透明」の対義語。光が通らず向こうが見えない状態を指す。", "清潔": "汚れがないことを表す語で、対義語の関係ではない。", "頑丈": "丈夫で壊れにくいことを表し、透明とは対義関係ではない。", "穏やか": "荒れていないことを表す語で、対義語の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
