INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "光を通して、向こうがはっきり見えるほど澄んでいること。", "primary_collocate": null, "pronunciation": "とうめい", "ipa": "toːmeː", "syllable_count": 4, "sentences": [{"text": "このコップは透明で、中の水がよく見えます。", "target_word": "透明", "complexity_tier": "T3", "furigana": "このコップは透明[とうめい]で、中[なか]の水[みず]がよく見[み]えます。", "sentence_source": "generated"}, {"text": "透明なガラスの窓から、外の庭が見えた。", "target_word": "透明", "complexity_tier": "T3", "furigana": "透明[とうめい]なガラスの窓[まど]から、外[そと]の庭[にわ]が見[み]えた。", "sentence_source": "generated"}, {"text": "汚れを落として、ガラスを透明にした。", "target_word": "透明", "complexity_tier": "T3", "furigana": "汚[よご]れを落[お]として、ガラスを透明[とうめい]にした。", "sentence_source": "generated"}, {"text": "川の水がとても透明で、底の石まで見えた。", "target_word": "透明", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がとても透明[とうめい]で、底[そこ]の石[いし]まで見[み]えた。", "sentence_source": "generated"}, {"text": "湧き水は、底まで見えるほど透明だ。", "target_word": "透明", "complexity_tier": "T3", "furigana": "湧[わ]き水[みず]は、底[そこ]まで見[み]えるほど透明[とうめい]だ。", "sentence_source": "generated"}, {"text": "透明なテープを使ったので、紙の文字が隠れなかった。", "target_word": "透明", "complexity_tier": "T3", "furigana": "透明[とうめい]なテープを使[つか]ったので、紙[かみ]の文字[もじ]が隠[かく]れなかった。", "sentence_source": "generated"}, {"text": "透明な袋に入れておけば、中身がすぐ分かります。", "target_word": "透明", "complexity_tier": "T3", "furigana": "透明[とうめい]な袋[ふくろ]に入[い]れておけば、中身[なかみ]がすぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "氷は、きれいな水で作ると透明になる。", "target_word": "透明", "complexity_tier": "T3", "furigana": "氷[こおり]は、きれいな水[みず]で作[つく]ると透明[とうめい]になる。", "sentence_source": "generated"}, {"text": "透明な水槽の中を、小さな魚が泳いでいる。", "target_word": "透明", "complexity_tier": "T3", "furigana": "透明[とうめい]な水槽[すいそう]の中[なか]を、小[ちい]さな魚[さかな]が泳[およ]いでいる。", "sentence_source": "generated"}, {"text": "濁った池の水は透明でなく、底が見えなかった。", "target_word": "透明", "complexity_tier": "T3", "furigana": "濁[にご]った池[いけ]の水[みず]は透明[とうめい]でなく、底[そこ]が見[み]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "透明だ", "label": "終止形"}, {"form": "透明な", "label": "連体形"}, {"form": "透明に", "label": "連用形"}, {"form": "透明で", "label": "連用形（で）"}, {"form": "透明だった", "label": "過去形"}], "register": "中立", "sense_fingerprint": "光を通し、向こうが見えるほど澄んでいる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "「このコップは透明で」と述語として続く形の語幹。"}, {"text": "透明な", "is_correct": false, "explanation": "連体形。「このコップは透明な、」と文を切ることはできない。"}, {"text": "透明に", "is_correct": false, "explanation": "副詞形。「このコップは透明に」では述語として成り立たない。"}, {"text": "透明だった", "is_correct": false, "explanation": "過去形。「透明だった、中の水がよく見えます」は文が成り立たない。"}], "explanations": {"透明": "「このコップは透明で」と述語として続く形の語幹。", "透明な": "連体形。「このコップは透明な、」と文を切ることはできない。", "透明に": "副詞形。「このコップは透明に」では述語として成り立たない。", "透明だった": "過去形。「透明だった、中の水がよく見えます」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雷が透明で、窓がびりびり震えた。", "explanation": "ここは〈激しい〉の意味。雷の強さには激しいを使い、透明は音や光の強さを表さないので合わない。"}, {"text": "このパンは透明で、とてもふわふわしている。", "explanation": "ここは〈ふわふわ〉の意味。パンの食感にはふわふわを使い、透明は食べ物の状態を表さないので合わない。"}, {"text": "昨日の宿題は透明で、ひどく難しかった。", "explanation": "ここは〈難しい〉の意味。宿題の難しさには難しいを使い、透明は物の見え方を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "語幹の形。「透明な袋」として名詞を修飾する形の基になる。"}, {"text": "透明で", "is_correct": false, "explanation": "連用形。名詞の前には「な」が必要で、「透明で袋」は成り立たない。"}, {"text": "透明だ", "is_correct": false, "explanation": "終止形で、名詞に直接続かない。"}, {"text": "透明さ", "is_correct": false, "explanation": "性質を表す名詞で、「透明さ袋」とは続かない。"}], "explanations": {"透明": "語幹の形。「透明な袋」として名詞を修飾する形の基になる。", "透明で": "連用形。名詞の前には「な」が必要で、「透明で袋」は成り立たない。", "透明だ": "終止形で、名詞に直接続かない。", "透明さ": "性質を表す名詞で、「透明さ袋」とは続かない。"}, "sentence_index": 6, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この皿は透明で、ひどくにおいがする。", "explanation": "ここは〈臭い〉の意味。においの強さには臭いを使い、透明は匂いを表さないので合わない。"}, {"text": "透明な写真で、細部まで見える。", "explanation": "ここは〈鮮明〉の意味。写真のはっきりさには鮮明を使い、透明は写真の状態を表さないので合わない。"}, {"text": "この映画は透明で、途中で眠くなった。", "explanation": "ここは〈退屈〉の意味。眠くなるほどつまらない話には退屈を使い、透明は隠し事がないことを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓ガラスは透明だので、外の景色がよく見える。", "corrected_sentence": "窓ガラスは透明なので、外の景色がよく見える。", "error_description": "「透明な」は名詞修飾の形で、「ので」の前には「な」を使う。「透明だので」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "透明", "is_correct": true, "explanation": "語幹の形。文中では「透明な」として名詞「ガラス」を修飾する形の基になる。"}, {"text": "透明で", "is_correct": false, "explanation": "連用形。「透明でガラス」とは名詞に続かない。"}, {"text": "透明に", "is_correct": false, "explanation": "副詞形。「透明にガラス」は成り立たない。"}, {"text": "透明だった", "is_correct": false, "explanation": "過去形で、名詞を修飾できない。"}], "correct_form": "透明", "base_form": "透明だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"透明": "語幹の形。文中では「透明な」として名詞「ガラス」を修飾する形の基になる。", "透明で": "連用形。「透明でガラス」とは名詞に続かない。", "透明に": "副詞形。「透明にガラス」は成り立たない。", "透明だった": "過去形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35839, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬ビンは透明な作られているため、中の錠剤が見える。", "corrected_sentence": "この薬ビンは透明に作られているため、中の錠剤が見える。", "error_description": "「透明に作られている」は連用形「に」が必要。「透明な」は名詞の前だけで使うので、「作られている」の前では誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "透明", "is_correct": true, "explanation": "語幹の形。文中では「透明に」の形で「なる」に続く。"}, {"text": "透明だ", "is_correct": false, "explanation": "終止形。「透明だになる」とは続かない。"}, {"text": "透明な", "is_correct": false, "explanation": "連体形。「透明なになる」は成り立たない。"}, {"text": "透明でない", "is_correct": false, "explanation": "否定形。「透明でなくなる」となり、文の意味が逆になる。"}], "correct_form": "透明", "base_form": "透明だ", "form_label": "連用形（に）", "sentence_index": 7, "explanations": {"透明": "語幹の形。文中では「透明に」の形で「なる」に続く。", "透明だ": "終止形。「透明だになる」とは続かない。", "透明な": "連体形。「透明なになる」は成り立たない。", "透明でない": "否定形。「透明でなくなる」となり、文の意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
