INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35841, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要なものや状態を、失わないようにしっかりと守ること。", "primary_collocate": null, "pronunciation": "かくほ", "ipa": "kakɯho", "syllable_count": 3, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "確保", "complexity_tier": "T6", "furigana": "従来[じゅうらい]の肉体労働[にくたいろうどう]は減少[げんしょう]しますが、機械[きかい]を操作[そうさ]する専門知識[せんもんちしき]を持[も]つ人材[じんざい]の確保[かくほ]が、新[あら]たな課題[かだい]として浮上[ふじょう]しているのです。", "sentence_source": "mined"}, {"text": "席を確保しておきました。", "target_word": "確保", "complexity_tier": "T2", "furigana": "席[せき]を確保[かくほ]しておきました。", "sentence_source": "generated"}, {"text": "安全の確保が、いちばん大切です。", "target_word": "確保", "complexity_tier": "T2", "furigana": "安全[あんぜん]の確保[かくほ]が、いちばん大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "水と食料を確保する必要がある。", "target_word": "確保", "complexity_tier": "T3", "furigana": "水[みず]と食料[しょくりょう]を確保[かくほ]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "出口を確保してから、作業を始めた。", "target_word": "確保", "complexity_tier": "T3", "furigana": "出口[でぐち]を確保[かくほ]してから、作業[さぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "会議室の確保は、私が担当します。", "target_word": "確保", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]の確保[かくほ]は、私[わたし]が担当[たんとう]します。", "sentence_source": "generated"}, {"text": "十分な睡眠時間を確保するのは難しい。", "target_word": "確保", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]な睡眠時間[すいみんじかん]を確保[かくほ]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "災害時に、避難場所が確保された。", "target_word": "確保", "complexity_tier": "T3", "furigana": "災害時[さいがいじ]に、避難場所[ひなんばしょ]が確保[かくほ]された。", "sentence_source": "generated"}, {"text": "電源を確保できず、実験は延期になった。", "target_word": "確保", "complexity_tier": "T4", "furigana": "電源[でんげん]を確保[かくほ]できず、実験[じっけん]は延期[えんき]になった。", "sentence_source": "generated"}, {"text": "人手の確保に苦労している会社が多い。", "target_word": "確保", "complexity_tier": "T3", "furigana": "人手[ひとで]の確保[かくほ]に苦労[くろう]している会社[かいしゃ]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確保する", "label": "活用"}, {"form": "確保される", "label": "活用"}, {"form": "確保できる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 必要なものや状態をしっかり守ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35841, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "確保", "is_correct": true, "explanation": "かくほ。見出し語そのもの。"}, {"text": "覚悟", "is_correct": false, "explanation": "かくご。最後の一拍だけが違う。"}, {"text": "角度", "is_correct": false, "explanation": "かくど。最後の一拍だけが違う。"}, {"text": "各自", "is_correct": false, "explanation": "かくじ。最後の一拍だけが違う。"}], "explanations": {"確保": "かくほ。見出し語そのもの。", "覚悟": "かくご。最後の一拍だけが違う。", "角度": "かくど。最後の一拍だけが違う。", "各自": "かくじ。最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "確保"}, "level_3": {"options": [{"text": "確保", "is_correct": true, "explanation": "人材を失わず手に入れることを表し、文意に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、「人材の散歩」では意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、人材の課題にならず意味が合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "形は合うが、「人材の入浴」では意味が合わない。"}], "explanations": {"確保": "人材を失わず手に入れることを表し、文意に合う。", "散歩": "形は合うが、「人材の散歩」では意味が合わない。", "洗濯": "形は合うが、人材の課題にならず意味が合わない。", "入浴": "形は合うが、「人材の入浴」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "確保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、犬と公園を確保している。", "explanation": "「確保」は散歩の意味ではなく、必要なものを手に入れ守る意味なので誤り。"}, {"text": "このカレーは確保がとても辛い。", "explanation": "「確保」は味を表さないので誤り。"}, {"text": "電車が遅れて、約束の時間に確保した。", "explanation": "「確保」は間に合うという意味ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35841, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "確保", "is_correct": true, "explanation": "かくほ。見出し語そのもの。"}, {"text": "隔離", "is_correct": false, "explanation": "かくり。最後の一拍だけが違う。"}, {"text": "格差", "is_correct": false, "explanation": "かくさ。最後の一拍だけが違う。"}, {"text": "各地", "is_correct": false, "explanation": "かくち。最後の一拍だけが違う。"}], "explanations": {"確保": "かくほ。見出し語そのもの。", "隔離": "かくり。最後の一拍だけが違う。", "格差": "かくさ。最後の一拍だけが違う。", "各地": "かくち。最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "確保"}, "level_3": {"options": [{"text": "確保", "is_correct": true, "explanation": "睡眠時間を失わず持つことを表し、文意に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、「睡眠時間を洗濯する」では意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、「睡眠時間を運転する」では意味が合わない。"}, {"text": "入浴", "is_correct": false, "explanation": "「入浴する」は「を」で目的語をとらず、「睡眠時間を入浴する」は形も意味も合わない。"}], "explanations": {"確保": "睡眠時間を失わず持つことを表し、文意に合う。", "洗濯": "形は合うが、「睡眠時間を洗濯する」では意味が合わない。", "運転": "形は合うが、「睡眠時間を運転する」では意味が合わない。", "入浴": "「入浴する」は「を」で目的語をとらず、「睡眠時間を入浴する」は形も意味も合わない。"}, "sentence_index": 6, "correct_answer": "確保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大事な書類を確保して、ごみ箱に捨てた。", "explanation": "「確保」は失わないよう守ることなので、捨てる行為と矛盾して誤り。"}, {"text": "夏休みは毎日、海で確保して遊んだ。", "explanation": "「確保」は遊ぶ意味ではないので誤り。"}, {"text": "この部屋は確保が広くて、気持ちがいい。", "explanation": "「確保」は広さを表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
