INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十分な睡眠時間が確保するのは難しい。", "corrected_sentence": "十分な睡眠時間を確保するのは難しい。", "error_description": "「確保する」は他動詞なので、確保する物は「が」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「多国の」で後の「代表」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「多国を代表」は目的語にできず、「集まり」と続かない。"}, {"text": "と", "is_correct": false, "explanation": "「多国と代表」は並列になるが、同じ立場で集まる意味にならず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「多国が代表が」と主語が二つ重なり、文が不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「多国の」で後の「代表」を修飾する。", "を": "「多国を代表」は目的語にできず、「集まり」と続かない。", "と": "「多国と代表」は並列になるが、同じ立場で集まる意味にならず不自然。", "が": "「多国が代表が」と主語が二つ重なり、文が不自然になる。"}, "error_tags": {"を": "目的語", "と": "並列", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多国が関係する」の主語を示す。「計画」に関係する国が複数あることを表す。"}, {"text": "へ", "is_correct": false, "explanation": "「多国へ関係する」は方向の意味になり、関係の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「多国より関係する」は比較の意味になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「多国を関係する」は「関係する」に「を」が続かず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「多国が関係する」の主語を示す。「計画」に関係する国が複数あることを表す。", "へ": "「多国へ関係する」は方向の意味になり、関係の対象にならない。", "より": "「多国より関係する」は比較の意味になり、文が成り立たない。", "を": "「多国を関係する」は「関係する」に「を」が続かず、不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの国が関係すること。", "primary_collocate": null, "pronunciation": "たこく", "ipa": "takokɯ", "syllable_count": 3, "sentences": [{"text": "この問題は多国が関係しているので、話し合いに時間がかかる。", "target_word": "多国", "complexity_tier": "T3", "furigana": "この問題[もんだい]は多国[たこく]が関係[かんけい]しているので、話[はな]し合[あ]いに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "多国の代表が集まり、環境について話し合った。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]の代表[だいひょう]が集[あつ]まり、環境[かんきょう]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "多国が参加する大会なので、通訳が何人も必要だ。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が参加[さんか]する大会[たいかい]なので、通訳[つうやく]が何人[なんにん]も必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "多国の協力がなければ、この調査は成功しなかっただろう。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]の協力[きょうりょく]がなければ、この調査[ちょうさ]は成功[せいこう]しなかっただろう。", "sentence_source": "generated"}, {"text": "多国が関わる事件は、法律の問題も複雑になりやすい。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が関[かか]わる事件[じけん]は、法律[ほうりつ]の問題[もんだい]も複雑[ふくざつ]になりやすい。", "sentence_source": "generated"}, {"text": "多国の意見をまとめるのは簡単ではない。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]の意見[いけん]をまとめるのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "一つの国だけでなく、多国が同じ川を使っている。", "target_word": "多国", "complexity_tier": "T3", "furigana": "一[ひと]つの国[くに]だけでなく、多国[たこく]が同[おな]じ川[かわ]を使[つか]っている。", "sentence_source": "generated"}, {"text": "多国が関係する計画では、全員の同意が必要だ。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が関係[かんけい]する計画[けいかく]では、全員[ぜんいん]の同意[どうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "事故の原因を調べるため、多国の専門家が現地に入った。", "target_word": "多国", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を調[しら]べるため、多国[たこく]の専門家[せんもんか]が現地[げんち]に入[はい]った。", "sentence_source": "generated"}, {"text": "多国の支援が届いて、被災地の人々は安心した。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]の支援[しえん]が届[とど]いて、被災地[ひさいち]の人々[ひとびと]は安心[あんしん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多国", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "一国ではなく、多くの国が関係・参加していること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "関係する国が多いことを表す名詞。「が関係している」の主語になる。"}, {"text": "多い", "is_correct": false, "explanation": "形容詞で、「この問題は多いが関係している」は文が成り立たない。"}, {"text": "多国の", "is_correct": false, "explanation": "「の」で終わる形は主語になれず、「が関係している」と続かない。"}, {"text": "多くの", "is_correct": false, "explanation": "名詞を修飾する形で、「が関係」とは続かない。"}], "explanations": {"多国": "関係する国が多いことを表す名詞。「が関係している」の主語になる。", "多い": "形容詞で、「この問題は多いが関係している」は文が成り立たない。", "多国の": "「の」で終わる形は主語になれず、「が関係している」と続かない。", "多くの": "名詞を修飾する形で、「が関係」とは続かない。"}, "sentence_index": 0, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多国の大通りは、朝からとても静かだった。", "explanation": "ここは〈閑散〉の意味。道の人通りの少なさには閑散を使い、多国は国の数を表すので道には合わない。"}, {"text": "多国の首相が、重要な決定を発表した。", "explanation": "ここは〈大国〉の意味。ひとつの大きな国を指す語で、複数国の関係を表す多国は合わない。"}, {"text": "多国の雨が降って、町の川が増水した。", "explanation": "ここは〈大雨〉の意味。雨の強さには大雨を使い、多国は国の数を表すので雨には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "関係する国が多いことを表す名詞。「多国が同じ川を使っている」の主語になる。"}, {"text": "少ない", "is_correct": false, "explanation": "形容詞で、主語にならず文が成り立たない。"}, {"text": "少なく", "is_correct": false, "explanation": "副詞形で、「少なく同じ川を使っている」と主語を示せない。"}, {"text": "単独の", "is_correct": false, "explanation": "後に名詞が必要な形で、「使っている」の主語にはならない。"}], "explanations": {"多国": "関係する国が多いことを表す名詞。「多国が同じ川を使っている」の主語になる。", "少ない": "形容詞で、主語にならず文が成り立たない。", "少なく": "副詞形で、「少なく同じ川を使っている」と主語を示せない。", "単独の": "後に名詞が必要な形で、「使っている」の主語にはならない。"}, "sentence_index": 6, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多国の大統領が、国民の前で演説した。", "explanation": "ここは〈一国〉の意味。一つの国の代表を表す語で、複数国の関係を表す多国は人の立場には使わない。"}, {"text": "多国の空が広がり、山の上まで晴れていた。", "explanation": "ここは〈晴天〉の意味。空の晴れ具合には晴天を使い、多国は国の数を表すので空には合わない。"}, {"text": "彼は多国の山頂で、一人で朝日を見た。", "explanation": "ここは〈山頂〉の意味。山の高いところには山頂を使い、多国は国の数を表すので場所には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多国を専門家が集まり、新しい治療法を検討している。", "corrected_sentence": "多国の専門家が集まり、新しい治療法を検討している。", "error_description": "「多国」は名詞で「専門家」を修飾するので「の」が必要。「を」は動詞の目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35842, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多国が協力で、支援物資が無事に届いた。", "corrected_sentence": "多国の協力で、支援物資が無事に届いた。", "error_description": "複数国の協力を表すには「の」が必要。「多国が」では「協力」とつながらず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「多国にわたる」は複数の国に広がるという意味で、「に」が範囲・到達を示して自然。"}, {"text": "が", "is_correct": false, "explanation": "「多国がわたっている」は主語として不自然で、わたる範囲を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「多国でわたっている」は場所を示すが、範囲にわたるという意味には「に」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「多国をわたっている」は目的語として不自然で、わたる動詞の形に合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「多国にわたる」は複数の国に広がるという意味で、「に」が範囲・到達を示して自然。", "が": "「多国がわたっている」は主語として不自然で、わたる範囲を示せない。", "で": "「多国でわたっている」は場所を示すが、範囲にわたるという意味には「に」が必要。", "を": "「多国をわたっている」は目的語として不自然で、わたる動詞の形に合わない。"}, "error_tags": {"が": "主語の格助詞", "で": "場所・手段", "を": "目的語の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「多国が出資して」の主語を示し、複数の国が出資する意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「多国を出資して」は目的語として不自然で、出資の主体を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「多国で出資して」は場所・手段を示すが、出資する主体には「が」が必要。"}, {"text": "の", "is_correct": false, "explanation": "「多国の出資して」は文として成り立たず、動詞の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「多国が出資して」の主語を示し、複数の国が出資する意味になる。", "を": "「多国を出資して」は目的語として不自然で、出資の主体を示せない。", "で": "「多国で出資して」は場所・手段を示すが、出資する主体には「が」が必要。", "の": "「多国の出資して」は文として成り立たず、動詞の主語を示せない。"}, "error_tags": {"を": "目的語の格助詞", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の国が関わること。また、そのさま。", "primary_collocate": null, "pronunciation": "たこく", "ipa": "takokɯ", "syllable_count": 3, "sentences": [{"text": "多国が関わる交渉は、一国だけの交渉より時間がかかる。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が関[かか]わる交渉[こうしょう]は、一国[いっこく]だけの交渉[こうしょう]より時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "この映画は多国が共同で制作し、出演者も多国にわたっている。", "target_word": "多国", "complexity_tier": "T3", "furigana": "この映画は多国[たこく]が共同で制作し、出演者も多国[たこく]にわたっている。", "sentence_source": "generated"}, {"text": "今回の調査は多国で行われ、結果が比べられた。", "target_word": "多国", "complexity_tier": "T3", "furigana": "今回[こんかい]の調査[ちょうさ]は多国[たこく]で行[おこな]われ、結果[けっか]が比[くら]べられた。", "sentence_source": "generated"}, {"text": "多国が協力して、宇宙ステーションを運営している。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が協力[きょうりょく]して、宇宙[うちゅう]ステーションを運営[うんえい]している。", "sentence_source": "generated"}, {"text": "この学校には多国から学生が集まり、教室はとてもにぎやかだ。", "target_word": "多国", "complexity_tier": "T3", "furigana": "この学校には多国[たこく]から学生が集まり、教室はとてもにぎやかだ。", "sentence_source": "generated"}, {"text": "多国が関係する問題だから、一つの国だけでは決められない。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が関係[かんけい]する問題[もんだい]だから、一[ひと]つの国[くに]だけでは決[き]められない。", "sentence_source": "generated"}, {"text": "川が多国にまたがって流れているため、水の使い方を話し合う必要がある。", "target_word": "多国", "complexity_tier": "T3", "furigana": "川[かわ]が多国[たこく]にまたがって流[なが]れているため、水[みず]の使[つか]い方[かた]を話[はな]し合[あ]う必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "多国が出資して、新しい工場が建てられた。", "target_word": "多国", "complexity_tier": "T3", "furigana": "多国[たこく]が出資して、新しい工場が建てられた。", "sentence_source": "generated"}, {"text": "国際会議には多国が参加し、共同の声明を出した。", "target_word": "多国", "complexity_tier": "T3", "furigana": "国際[こくさい]会議[かいぎ]には多国[たこく]が参加[さんか]し、共同[きょうどう]の声明[せいめい]を出[だ]した。", "sentence_source": "generated"}, {"text": "ワクチンは、多国が協力したことで短い期間で作られた。", "target_word": "多国", "complexity_tier": "T3", "furigana": "ワクチンは、多国[たこく]が協力したことで短い期間で作られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多国", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "複数の国が共同で関わっている状態やそのありさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "正解。「多国が関わる交渉」は複数の国が関わる交渉の意味で、文脈に合う。"}, {"text": "時計", "is_correct": false, "explanation": "「時計が関わる交渉」は交渉の主体として意味が通らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼けが関わる交渉」は文脈に合わず、交渉の関係者にならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「昼寝が関わる交渉」は意味が通らず、一国だけの交渉との比較も成立しない。"}], "explanations": {"多国": "正解。「多国が関わる交渉」は複数の国が関わる交渉の意味で、文脈に合う。", "時計": "「時計が関わる交渉」は交渉の主体として意味が通らない。", "夕焼け": "「夕焼けが関わる交渉」は文脈に合わず、交渉の関係者にならない。", "昼寝": "「昼寝が関わる交渉」は意味が通らず、一国だけの交渉との比較も成立しない。"}, "sentence_index": 0, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選挙では、投票の時間が多国で、夕方まで行列が続いた。", "explanation": "ここは〈多量・長時間〉の意味。多国は国の数に関する語で、時間の長さには使わない。"}, {"text": "留学先は日本ではなく、多国のイギリスだった。", "explanation": "ここは〈他国〉の意味。多国は複数の国が関わる意味で、ひとつの外国を指すときには使わない。"}, {"text": "毎朝、パンの量が多国で、店のかまどが追いつかない。", "explanation": "ここは〈大量〉の意味。多国は国の数に関する語で、パンの量の多さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "正解。「多国にまたがる」は複数の国にわたる意味で、川が国境を越えて流れる状況に合う。"}, {"text": "教室", "is_correct": false, "explanation": "「教室にまたがって流れる」は場所として不自然で、川の流れ方を表せない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井にまたがって流れる」は意味が通らない。"}, {"text": "食卓", "is_correct": false, "explanation": "「食卓にまたがって流れる」は意味が通らず、川の文脈に合わない。"}], "explanations": {"多国": "正解。「多国にまたがる」は複数の国にわたる意味で、川が国境を越えて流れる状況に合う。", "教室": "「教室にまたがって流れる」は場所として不自然で、川の流れ方を表せない。", "天井": "「天井にまたがって流れる」は意味が通らない。", "食卓": "「食卓にまたがって流れる」は意味が通らず、川の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この城は多国の壁に囲まれ、攻めにくい。", "explanation": "ここは〈多重〉の意味。多国は国の数に関する語で、壁が重なっている様子には使わない。"}, {"text": "宝くじで多国の賞金を当てた。", "explanation": "ここは〈多額〉の意味。多国は複数の国に関わる語で、金額の大きさには使わない。"}, {"text": "この地域では雨の量が多国で、畑が水びたしになった。", "explanation": "ここは〈多量〉の意味。多国は国の数に関する語で、雨の量の多さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この番組は多国を共同で作り、出演者も多国にわたっている。", "corrected_sentence": "この番組は多国が共同で作り、出演者も多国にわたっている。", "error_description": "「共同で作る」の主語は多国なので、格助詞は「を」ではなく「が」が正しい。「を」は目的語を示すため、ここでは不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山脈が多国をまたがって連なり、冬は雪が多い。", "corrected_sentence": "山脈が多国にまたがって連なり、冬は雪が多い。", "error_description": "「またがる」は「に」を取るので「多国にまたがる」が正しい。「を」は「またがる」の対象を示す形として合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『確認する』は確認の対象を目的語に取るので、体制に『を』が付く。"}, {"text": "が", "is_correct": false, "explanation": "『体制が確認』では体制が主語になり、確認する人が合わない。"}, {"text": "に", "is_correct": false, "explanation": "確認の対象は『に』では示せず、『体制に確認』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は確認の対象にならず、『体制へ確認』は不自然。"}], "correct_answer": "を", "explanations": {"を": "『確認する』は確認の対象を目的語に取るので、体制に『を』が付く。", "が": "『体制が確認』では体制が主語になり、確認する人が合わない。", "に": "確認の対象は『に』では示せず、『体制に確認』は意味が通らない。", "へ": "方向の『へ』は確認の対象にならず、『体制へ確認』は不自然。"}, "error_tags": {"が": "主格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を進めるための、まとまった仕組みややり方。", "primary_collocate": null, "pronunciation": "たいせい", "ipa": "taiseː", "syllable_count": 4, "sentences": [{"text": "新しい店では、お客様を待たせない体制を整えました。", "target_word": "体制", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]では、お客様[きゃくさま]を待[ま]たせない体制[たいせい]を整[ととの]えました。", "sentence_source": "generated"}, {"text": "災害が起きたときにすぐ動ける体制を、もう一度確認しておきましょう。", "target_word": "体制", "complexity_tier": "T3", "furigana": "災害[さいがい]が起[お]きたときにすぐ動[うご]ける体制[たいせい]を、もう一度[いちど]確認[かくにん]しておきましょう。", "sentence_source": "generated"}, {"text": "人が足りなくて、二十四時間対応する体制は作れない。", "target_word": "体制", "complexity_tier": "T3", "furigana": "人[ひと]が足[た]りなくて、二十四時間[にじゅうよじかん]対応[たいおう]する体制[たいせい]は作[つく]れない。", "sentence_source": "generated"}, {"text": "会社は、問い合わせにすぐ答えられる体制を作った。", "target_word": "体制", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、問[と]い合[あ]わせにすぐ答[こた]えられる体制[たいせい]を作[つく]った。", "sentence_source": "generated"}, {"text": "工事の安全を守る体制が弱かったため、事故が起きてしまった。", "target_word": "体制", "complexity_tier": "T3", "furigana": "工事[こうじ]の安全[あんぜん]を守[まも]る体制[たいせい]が弱[よわ]かったため、事故[じこ]が起[お]きてしまった。", "sentence_source": "generated"}, {"text": "この病院は、夜でも患者を受け入れる体制が整っている。", "target_word": "体制", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、夜[よる]でも患者[かんじゃ]を受[う]け入[い]れる体制[たいせい]が整[ととの]っている。", "sentence_source": "generated"}, {"text": "準備の体制ができたら、すぐに作業を始めます。", "target_word": "体制", "complexity_tier": "T3", "furigana": "準備[じゅんび]の体制[たいせい]ができたら、すぐに作業[さぎょう]を始[はじ]めます。", "sentence_source": "generated"}, {"text": "学校では、先生たちが協力して子どもを見守る体制をとっています。", "target_word": "体制", "complexity_tier": "T3", "furigana": "学校[がっこう]では、先生[せんせい]たちが協力[きょうりょく]して子[こ]どもを見守[みまも]る体制[たいせい]をとっています。", "sentence_source": "generated"}, {"text": "助ける体制が足りないと、新人はすぐにやめてしまう。", "target_word": "体制", "complexity_tier": "T3", "furigana": "助[たす]ける体制[たいせい]が足[た]りないと、新人[しんじん]はすぐにやめてしまう。", "sentence_source": "generated"}, {"text": "来月から、全員で当番を回す体制に変わります。", "target_word": "体制", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、全員[ぜんいん]で当番[とうばん]を回[まわ]す体制[たいせい]に変[か]わります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体制", "label": "基本形"}], "register": "formal", "sense_fingerprint": "物事を進めるために整えた、まとまった仕組みややり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "お客様を待たせない仕組みを整える、の意味。ここに入る語。"}, {"text": "感想", "is_correct": false, "explanation": "感想は心に抱く意見のことで、整える対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのことで、店の仕組みには当たらない。"}, {"text": "返事", "is_correct": false, "explanation": "返事は応答の言葉で、整えるとは言わない。"}], "explanations": {"体制": "お客様を待たせない仕組みを整える、の意味。ここに入る語。", "感想": "感想は心に抱く意見のことで、整える対象にならない。", "寿命": "寿命は命の長さのことで、店の仕組みには当たらない。", "返事": "返事は応答の言葉で、整えるとは言わない。"}, "sentence_index": 0, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面接では、背すじを伸ばした体制で座ると印象がよくなる。", "explanation": "ここは〈姿勢〉の意味。体の構えは姿勢と言い、体制は仕組みを指すので合わない。"}, {"text": "彼は中身より、人前での体制をいつも気にしている。", "explanation": "ここは〈体裁〉の意味。外から見た格好は体裁と言い、体制は仕組みなので合わない。"}, {"text": "週末の店の前には、体制のお客さんがずらりと並んだ。", "explanation": "ここは〈大勢〉の意味。人数の多さは大勢と言い、体制は仕組みを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "準備のための仕組みを指す語で、ここに入る。"}, {"text": "予感", "is_correct": false, "explanation": "予感は前触れを感じる気持ちで、準備の後に続かない。"}, {"text": "印象", "is_correct": false, "explanation": "印象は受ける感じのことで、準備の対象にならない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は響きが残ることで、準備には結びつかない。"}], "explanations": {"体制": "準備のための仕組みを指す語で、ここに入る。", "予感": "予感は前触れを感じる気持ちで、準備の後に続かない。", "印象": "印象は受ける感じのことで、準備の対象にならない。", "余韻": "余韻は響きが残ることで、準備には結びつかない。"}, "sentence_index": 6, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの店員は、いつも誠実な体制でお客さんに接する。", "explanation": "ここは〈態度〉の意味。人への振る舞いは態度と言い、体制は仕組みなので合わない。"}, {"text": "怒りそうになったが、体制を抑えて冷静に話した。", "explanation": "ここは〈感情〉の意味。怒りを抑えるのは感情で、体制は抑える対象ではない。"}, {"text": "説明の途中から、彼の体制が強く伝わってきた。", "explanation": "ここは〈熱意〉の意味。相手に伝わるのは熱意で、仕組みを指す体制は伝わらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週から、夜間も対応できる体制が組むことになった。", "corrected_sentence": "来週から、夜間も対応できる体制を組むことになった。", "error_description": "『組む』は他動詞なので、体制の後ろは『を』が正しい。『体制が組む』は主語と動詞が合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35844, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜間の対応体制が整えた。", "corrected_sentence": "夜間の対応体制が整った。", "error_description": "『体制』が主語なので自動詞の『整う』が正しい。『整える』は他動詞で人が主語になるため、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を示す『で』。国と市が協力する仕組みを通して工事を進める、の意味になる。"}, {"text": "を", "is_correct": false, "explanation": "『体制を、川の工事を進めている』と目的語が重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は工事の進め先にならず、『体制へ進めている』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "『体制の、川の工事を進めている』は名詞句にならず、文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を示す『で』。国と市が協力する仕組みを通して工事を進める、の意味になる。", "を": "『体制を、川の工事を進めている』と目的語が重なり、文として成り立たない。", "へ": "方向の『へ』は工事の進め先にならず、『体制へ進めている』は不自然。", "の": "『体制の、川の工事を進めている』は名詞句にならず、文として成り立たない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を達成するために組織された、人や組織の関係の仕組み。", "primary_collocate": null, "pronunciation": "たいせい", "ipa": "taiseː", "syllable_count": 4, "sentences": [{"text": "新しい社長は、会社の体制を大きく変えた。", "target_word": "体制", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]は、会社[かいしゃ]の体制[たいせい]を大[おお]きく変[か]えた。", "sentence_source": "generated"}, {"text": "国と市が協力する体制で、川の工事を進めている。", "target_word": "体制", "complexity_tier": "T3", "furigana": "国[くに]と市[し]が協力[きょうりょく]する体制[たいせい]で、川[かわ]の工事[こうじ]を進[すす]めている。", "sentence_source": "generated"}, {"text": "このプロジェクトは、三つの部署が一つの体制で動いている。", "target_word": "体制", "complexity_tier": "T3", "furigana": "このプロジェクトは、三[みっ]つの部署[ぶしょ]が一[ひと]つの体制[たいせい]で動[うご]いている。", "sentence_source": "generated"}, {"text": "警察と消防が一つの体制を組み、事故に対応した。", "target_word": "体制", "complexity_tier": "T3", "furigana": "警察[けいさつ]と消防[しょうぼう]が一[ひと]つの体制[たいせい]を組[く]み、事故[じこ]に対応[たいおう]した。", "sentence_source": "generated"}, {"text": "古い体制のままでは、会社は新しい仕事に対応できない。", "target_word": "体制", "complexity_tier": "T3", "furigana": "古[ふる]い体制[たいせい]のままでは、会社[かいしゃ]は新[あたら]しい仕事[しごと]に対応[たいおう]できない。", "sentence_source": "generated"}, {"text": "大会は、学生三十人と先生五人の体制で運営されている。", "target_word": "体制", "complexity_tier": "T3", "furigana": "大会[たいかい]は、学生[がくせい]三十人[さんじゅうにん]と先生[せんせい]五人[ごにん]の体制[たいせい]で運営[うんえい]されている。", "sentence_source": "generated"}, {"text": "部長が全体を指揮する体制に、チームを組み直した。", "target_word": "体制", "complexity_tier": "T3", "furigana": "部長[ぶちょう]が全体[ぜんたい]を指揮[しき]する体制[たいせい]に、チームを組[く]み直[なお]した。", "sentence_source": "generated"}, {"text": "大学と企業が手を結ぶ体制ができ、共同研究が始まった。", "target_word": "体制", "complexity_tier": "T3", "furigana": "大学[だいがく]と企業[きぎょう]が手[て]を結[むす]ぶ体制[たいせい]ができ、共同[きょうどう]研究[けんきゅう]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "新人には担当者が一人つく体制に変わり、質問しやすくなった。", "target_word": "体制", "complexity_tier": "T3", "furigana": "新人[しんじん]には担当者[たんとうしゃ]が一人[ひとり]つく体制[たいせい]に変[か]わり、質問[しつもん]しやすくなった。", "sentence_source": "generated"}, {"text": "新事業のため、営業部と開発部が連携する体制を築いた。", "target_word": "体制", "complexity_tier": "T3", "furigana": "新事業[しんじぎょう]のため、営業部[えいぎょうぶ]と開発部[かいはつぶ]が連携[れんけい]する体制[たいせい]を築[きず]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体制", "label": "基本形"}], "register": "formal", "sense_fingerprint": "目的のために組まれた、人や組織どうしの関係の仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 組み直し (Zipf 2.34)']::text[], 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "会社の仕組みや人の関係を指す語で、変える対象になる。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸で、会社を変える対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのことで、会社の仕組みには当たらない。"}, {"text": "腹痛", "is_correct": false, "explanation": "腹痛は体の痛みで、会社の体制とは無関係。"}], "explanations": {"体制": "会社の仕組みや人の関係を指す語で、変える対象になる。", "寝息": "寝息は眠っている時の呼吸で、会社を変える対象にならない。", "寿命": "寿命は命の長さのことで、会社の仕組みには当たらない。", "腹痛": "腹痛は体の痛みで、会社の体制とは無関係。"}, "sentence_index": 0, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "背すじを伸ばした体制で座ると、腰が楽になる。", "explanation": "ここは〈姿勢〉の意味。体の構えは姿勢と言い、体制は組織の仕組みを指すので合わない。"}, {"text": "大会の会場には、体制のファンがずらりと集まった。", "explanation": "ここは〈大勢〉の意味。人数の多さは大勢と言い、体制は組織の形なので合わない。"}, {"text": "審判に対して、誠実な体制で接した。", "explanation": "ここは〈態度〉の意味。振る舞いは態度と言い、組織の仕組みである体制とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体制", "is_correct": true, "explanation": "全体を指揮する組織の仕組みを指し、組み直す対象になる語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、チームを組み直す対象にならない。"}, {"text": "景色", "is_correct": false, "explanation": "景色は眺めのことで、チームを組み直す対象にならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている時の言葉で、ここには合わない。"}], "explanations": {"体制": "全体を指揮する組織の仕組みを指し、組み直す対象になる語。", "天気": "天気は空模様のことで、チームを組み直す対象にならない。", "景色": "景色は眺めのことで、チームを組み直す対象にならない。", "寝言": "寝言は眠っている時の言葉で、ここには合わない。"}, "sentence_index": 6, "correct_answer": "体制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海辺で撮ったその写真には、彼女の体制がきれいに写っていた。", "explanation": "ここは〈姿〉の意味。写るのは姿で、体制は組織の仕組みを指すので写らない。"}, {"text": "嬉しさを表に出さないよう、体制を抑えて黙っていた。", "explanation": "ここは〈感情〉の意味。心の動きは感情と言い、体制は抑える対象ではない。"}, {"text": "応援の声から、チームの体制がよく伝わってきた。", "explanation": "ここは〈熱意〉の意味。伝わるのは熱意で、仕組みを指す体制は伝わらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい部長は、部の体制が大きく変えた。", "corrected_sentence": "新しい部長は、部の体制を大きく変えた。", "error_description": "『変える』は他動詞なので、体制の後ろは『を』が正しい。『体制が大きく変えた』は主語と動詞が合わず、変えたのは部長なのに文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35845, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新製品のため、設計部と販売部が連携する体制に築いた。", "corrected_sentence": "新製品のため、設計部と販売部が連携する体制を築いた。", "error_description": "『築く』は目的語に『を』を取る。『体制に築いた』は不自然で、『を』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
