INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「たしかめる」の対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語は「先生は」なので、対象を示す位置に「が」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「たしかめる」は対象に「に」を取らないので、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、確認する対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「たしかめる」の対象（目的語）を示す。", "が": "主語は「先生は」なので、対象を示す位置に「が」は使えない。", "に": "「たしかめる」は対象に「に」を取らないので、文が成り立たない。", "へ": "方向を表すが、確認する対象には合わない。"}, "error_tags": {"が": "主語の格", "に": "対象の格", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんのコンピューターや機械がつながった、つながり。", "primary_collocate": null, "pronunciation": "ねっとわーく", "ipa": "nettowaːkɯ", "syllable_count": 6, "sentences": [{"text": "会社のネットワークがつながらなくて、メールが送れません。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "会社[かいしゃ]のネットワークがつながらなくて、メールが送[おく]れません。", "sentence_source": "generated"}, {"text": "この学校では、全部のコンピューターがネットワークでつながっています。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、全部[ぜんぶ]のコンピューターがネットワークでつながっています。", "sentence_source": "generated"}, {"text": "ネットワークが止まったので、仕事ができませんでした。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "ネットワークが止[と]まったので、仕事[しごと]ができませんでした。", "sentence_source": "generated"}, {"text": "工場の機械はネットワークで動きを知らせ合います。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]はネットワークで動[うご]きを知[し]らせ合[あ]います。", "sentence_source": "generated"}, {"text": "家のネットワークが遅いので、新しいルーターを買いました。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "家[いえ]のネットワークが遅[おそ]いので、新[あたら]しいルーターを買[か]いました。", "sentence_source": "generated"}, {"text": "ネットワークにつなぐ前に、パスワードを入れてください。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "ネットワークにつなぐ前[まえ]に、パスワードを入[い]れてください。", "sentence_source": "generated"}, {"text": "町の図書館は、ネットワークで本の場所を調べられます。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "町[まち]の図書館[としょかん]は、ネットワークで本[ほん]の場所[ばしょ]を調[しら]べられます。", "sentence_source": "generated"}, {"text": "先生は教室のネットワークを毎朝たしかめます。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "先生[せんせい]は教室[きょうしつ]のネットワークを毎朝[まいあさ]たしかめます。", "sentence_source": "generated"}, {"text": "大きな地震のあとも、ネットワークは止まりませんでした。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "大[おお]きな地震[じしん]のあとも、ネットワークは止[と]まりませんでした。", "sentence_source": "generated"}, {"text": "病院のネットワークで、どの部屋でもカルテを見られます。", "target_word": "ネットワーク", "complexity_tier": "T3", "furigana": "病院[びょういん]のネットワークで、どの部屋[へや]でもカルテを見[み]られます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネットワーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "コンピューターや機械が互いにつながった仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: たしかめ (Zipf 1.67)']::text[], '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ネットワーク", "is_correct": true, "explanation": "会社の通信網がつながらないという文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "電気製品だが、メールが送れない理由として通信のつながりとは結びつかない。"}, {"text": "書類", "is_correct": false, "explanation": "紙の書類は通信でつながるものではないので、文が成り立たない。"}, {"text": "駐車場", "is_correct": false, "explanation": "場所を表す語で、通信がつながるものではない。"}], "explanations": {"ネットワーク": "会社の通信網がつながらないという文脈に合う。", "冷蔵庫": "電気製品だが、メールが送れない理由として通信のつながりとは結びつかない。", "書類": "紙の書類は通信でつながるものではないので、文が成り立たない。", "駐車場": "場所を表す語で、通信がつながるものではない。"}, "sentence_index": 0, "correct_answer": "ネットワーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "そのシュートは、ゴールのネットワークを大きく揺らした。", "explanation": "ここは〈ゴールネット〉（ゴールを囲む網）の意味。ネットワークは機器のつながりを指すので、ゴールの網の名前には使わない。"}, {"text": "届いたネットワークには、住所が書いてあった。", "explanation": "ここは〈通信〉（送られてきた連絡）の意味。ネットワークは通信の仕組み全体を指すので、届いた一通の連絡には使わない。"}, {"text": "漁師は朝から海にネットワークを投げ入れて、魚を取った。", "explanation": "ここは〈網〉（魚を取る道具）の意味。ネットワークは機器のつながりを指すので、漁具には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ネットワーク", "is_correct": true, "explanation": "通信網を使って場所を調べる、という手段に合う。"}, {"text": "料理", "is_correct": false, "explanation": "調べる手段にはならず、本の場所を調べる文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "本の場所を調べる手段として合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "行為であり、本の場所を調べる手段にはならない。"}], "explanations": {"ネットワーク": "通信網を使って場所を調べる、という手段に合う。", "料理": "調べる手段にはならず、本の場所を調べる文脈に合わない。", "天気": "本の場所を調べる手段として合わない。", "散歩": "行為であり、本の場所を調べる手段にはならない。"}, "sentence_index": 6, "correct_answer": "ネットワーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あのチームは、ネットワークで二年連続の優勝を果たした。", "explanation": "ここは〈リーグ〉（試合を組んだ大会）の意味。ネットワークは機器のつながりを指すので、試合の組には使わない。"}, {"text": "テニスの試合で、ボールがネットワークに引っかかり、そのポイントは相手のものになった。", "explanation": "ここは〈ネット〉（テニスの網）の意味。ネットワークは機器のつながりを指すので、競技の網には使わない。"}, {"text": "来月の大会のネットワークは十日間です。", "explanation": "ここは〈日程〉（予定の期間）の意味。ネットワークは機器のつながりを指すので、大会の日程には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社のネットワークを止まったので、会議ができませんでした。", "corrected_sentence": "会社のネットワークが止まったので、会議ができませんでした。", "error_description": "「止まる」は自動詞なので、主語は「が」で示す。「ネットワークを」は誤りで、正しくは「ネットワークが止まった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35850, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校のネットワークが遅いくて、動画が見られません。", "corrected_sentence": "学校のネットワークが遅くて、動画が見られません。", "error_description": "「遅い」は形容詞で、「て」に続く形は「遅くて」。「遅いくて」は活用の誤りで、ネットワークの状態を述べる部分が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「木の枠に入れる」は収める先を示し、枠の中に入れる意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「木の枠を入れて」は目的語が二つになり不自然で、収める先を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「木の枠が入れて」は主語として不自然で、入れる先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「木の枠の入れて」は文として成り立たず、動詞を支えられない。"}], "correct_answer": "に", "explanations": {"に": "正解。「木の枠に入れる」は収める先を示し、枠の中に入れる意味になる。", "を": "「木の枠を入れて」は目的語が二つになり不自然で、収める先を示せない。", "が": "「木の枠が入れて」は主語として不自然で、入れる先を示せない。", "の": "「木の枠の入れて」は文として成り立たず、動詞を支えられない。"}, "error_tags": {"を": "目的語の格助詞", "が": "主語の格助詞", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「黒い枠で囲まれた」は手段・道具を示し、枠で囲む意味になる。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す助詞。「黒い枠と囲まれた」では囲む手段を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「黒い枠へ囲まれた」では囲む手段にならず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞。「黒い枠から囲まれた」では囲む手段を示せず、不自然になる。"}], "correct_answer": "で", "explanations": {"で": "正解。「黒い枠で囲まれた」は手段・道具を示し、枠で囲む意味になる。", "と": "並列を示す助詞。「黒い枠と囲まれた」では囲む手段を示せず、文が成り立たない。", "へ": "方向を示す助詞。「黒い枠へ囲まれた」では囲む手段にならず、意味が通らない。", "から": "起点を示す助詞。「黒い枠から囲まれた」では囲む手段を示せず、不自然になる。"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もののまわりのへりや、かごや箱の形のことです。", "primary_collocate": null, "pronunciation": "わく", "ipa": "wakɯ", "syllable_count": 2, "sentences": [{"text": "窓の枠にほこりがたまっているので、布でふいた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "窓[まど]の枠[わく]にほこりがたまっているので、布[ぬの]でふいた。", "sentence_source": "generated"}, {"text": "写真を木の枠に入れて、壁にかけた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "写真[しゃしん]を木[き]の枠[わく]に入[い]れて、壁[かべ]にかけた。", "sentence_source": "generated"}, {"text": "古い絵の枠が、少し曲がっている。", "target_word": "枠", "complexity_tier": "T3", "furigana": "古[ふる]い絵[え]の枠[わく]が、少[すこ]し曲[ま]がっている。", "sentence_source": "generated"}, {"text": "子どもは紙に鉛筆で四角い枠をかいた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "子[こ]どもは紙[かみ]に鉛筆[えんぴつ]で四角[しかく]い枠[わく]をかいた。", "sentence_source": "generated"}, {"text": "眼鏡の枠が壊れたので、店で直してもらった。", "target_word": "枠", "complexity_tier": "T3", "furigana": "眼鏡[めがね]の枠[わく]が壊[こわ]れたので、店[みせ]で直[なお]してもらった。", "sentence_source": "generated"}, {"text": "枠だけ残して、ガラスはすべて外された。", "target_word": "枠", "complexity_tier": "T3", "furigana": "枠[わく]だけ残[のこ]して、ガラスはすべて外[はず]された。", "sentence_source": "generated"}, {"text": "ドアの枠に背の高さを書いて、成長を記録した。", "target_word": "枠", "complexity_tier": "T3", "furigana": "ドアの枠[わく]に背[せ]の高[たか]さを書[か]いて、成長[せいちょう]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "黒い枠で囲まれた文字が、ポスターの中央にある。", "target_word": "枠", "complexity_tier": "T3", "furigana": "黒[くろ]い枠[わく]で囲[かこ]まれた文字[もじ]が、ポスターの中央[ちゅうおう]にある。", "sentence_source": "generated"}, {"text": "鏡の枠には、きれいな花の模様がほられている。", "target_word": "枠", "complexity_tier": "T3", "furigana": "鏡[かがみ]の枠[わく]には、きれいな花[はな]の模様[もよう]がほられている。", "sentence_source": "generated"}, {"text": "板で枠を作り、その中にコンクリートを流した。", "target_word": "枠", "complexity_tier": "T3", "furigana": "板[いた]で枠[わく]を作[つく]り、その中[なか]にコンクリートを流[なが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "枠", "label": "基本形"}], "register": "中立", "sense_fingerprint": "窓・額・眼鏡などの周囲を囲む具体的な縁や、箱状の骨組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枠", "is_correct": true, "explanation": "正解。「窓の枠」は窓の縁を指し、ほこりがたまる場所として自然。"}, {"text": "手紙", "is_correct": false, "explanation": "「窓の手紙にほこりがたまっている」は意味が通らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「窓の夕焼け」は物として存在せず、ほこりがたまる場所にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "「窓の教科書」は意味が通らず、ほこりがたまる部分を指せない。"}], "explanations": {"枠": "正解。「窓の枠」は窓の縁を指し、ほこりがたまる場所として自然。", "手紙": "「窓の手紙にほこりがたまっている」は意味が通らない。", "夕焼け": "「窓の夕焼け」は物として存在せず、ほこりがたまる場所にならない。", "教科書": "「窓の教科書」は意味が通らず、ほこりがたまる部分を指せない。"}, "sentence_index": 0, "correct_answer": "枠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は青い枠が多く、夏にぴったりだ。", "explanation": "ここは〈柄〉の意味。枠は縁や囲みを指し、布の模様には使わない。"}, {"text": "子どもは紙に鉛筆で、かわいい犬の枠をかいた。", "explanation": "ここは〈絵〉の意味。枠は周囲の縁を指し、描かれた対象そのものにはならない。"}, {"text": "この水は枠が冷たく、夏に飲むと気持ちがいい。", "explanation": "ここは〈温度〉の意味。枠は縁や囲みで、水の冷たさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枠", "is_correct": true, "explanation": "正解。「ドアの枠」は戸の縁で、背の高さを書き込む場所として自然。"}, {"text": "花瓶", "is_correct": false, "explanation": "「ドアの花瓶に背の高さを書いて」は意味が通らない。"}, {"text": "夜空", "is_correct": false, "explanation": "「ドアの夜空」は場所として成り立たず、背の高さを書けない。"}, {"text": "掃除機", "is_correct": false, "explanation": "「ドアの掃除機」は意味が通らず、書き込む場所にならない。"}], "explanations": {"枠": "正解。「ドアの枠」は戸の縁で、背の高さを書き込む場所として自然。", "花瓶": "「ドアの花瓶に背の高さを書いて」は意味が通らない。", "夜空": "「ドアの夜空」は場所として成り立たず、背の高さを書けない。", "掃除機": "「ドアの掃除機」は意味が通らず、書き込む場所にならない。"}, "sentence_index": 6, "correct_answer": "枠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "金庫の枠を回して、鍵を開けた。", "explanation": "ここは〈ダイヤル〉の意味。枠は縁や囲みで、回して数字を合わせる部品ではない。"}, {"text": "このジュースは枠が甘く、子どもに人気だ。", "explanation": "ここは〈味〉の意味。枠は縁や範囲で、甘さは表せない。"}, {"text": "自動販売機の枠を押すと、ジュースが出る。", "explanation": "ここは〈ボタン〉の意味。枠は縁で、押して操作する部品には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の枠で鳥が止まっている。", "corrected_sentence": "窓の枠に鳥が止まっている。", "error_description": "「止まる」は着地する場所を「に」で示すので、「枠に」が正しい。「で」は動作の場所・手段を示すため不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木の枠が外して、新しい板を入れた。", "corrected_sentence": "木の枠を外して、新しい板を入れた。", "error_description": "「外す」は取り外す対象を「を」で示すので、「枠を外す」が正しい。「が」は主語を示すため、ここでは不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「常識の枠にとらわれる」は、とらわれる対象を「に」で示し、自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「常識の枠をとらわれず」は目的語として不自然で、「とらわれる」の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「常識の枠がとらわれず」は主語として不自然で、とらわれる対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「常識の枠のとらわれず」は文として成り立たず、動詞を支えられない。"}], "correct_answer": "に", "explanations": {"に": "正解。「常識の枠にとらわれる」は、とらわれる対象を「に」で示し、自然な形になる。", "を": "「常識の枠をとらわれず」は目的語として不自然で、「とらわれる」の対象を示せない。", "が": "「常識の枠がとらわれず」は主語として不自然で、とらわれる対象を示せない。", "の": "「常識の枠のとらわれず」は文として成り立たず、動詞を支えられない。"}, "error_tags": {"を": "目的語の格助詞", "が": "主語の格助詞", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「国の枠を越えて」は越える対象を「を」で示し、国境という範囲を越える意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「国の枠が越えて」は主語として不自然で、越える対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「国の枠に越えて」は「越える」の対象に「に」は付かないため不自然。"}, {"text": "で", "is_correct": false, "explanation": "「国の枠で越えて」は手段を示すが、越える対象を示す形としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「国の枠を越えて」は越える対象を「を」で示し、国境という範囲を越える意味になる。", "が": "「国の枠が越えて」は主語として不自然で、越える対象を示せない。", "に": "「国の枠に越えて」は「越える」の対象に「に」は付かないため不自然。", "で": "「国の枠で越えて」は手段を示すが、越える対象を示す形としては成り立たない。"}, "error_tags": {"が": "主語の格助詞", "に": "方向・到達", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "予算・人数・時間などを区切る境界や制限。決められた範囲。", "primary_collocate": null, "pronunciation": "わく", "ipa": "wakɯ", "syllable_count": 2, "sentences": [{"text": "予算の枠を超えないように、買い物の計画を立てた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "予算[よさん]の枠[わく]を超[こ]えないように、買[か]い物[もの]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "彼は常識の枠にとらわれず、新しい方法を考えた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "彼[かれ]は常識[じょうしき]の枠[わく]にとらわれず、新[あたら]しい方法[ほうほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "今年は新入社員の採用の枠が、去年より少ない。", "target_word": "枠", "complexity_tier": "T3", "furigana": "今年[ことし]は新入[しんにゅう]社員[しゃいん]の採用[さいよう]の枠[わく]が、去年[きょねん]より少[すく]ない。", "sentence_source": "generated"}, {"text": "決められた枠の中で、自由に絵を表現してください。", "target_word": "枠", "complexity_tier": "T3", "furigana": "決[き]められた枠[わく]の中[なか]で、自由[じゆう]に絵[え]を表現[ひょうげん]してください。", "sentence_source": "generated"}, {"text": "この仕事は、担当の枠を超えて協力する必要がある。", "target_word": "枠", "complexity_tier": "T3", "furigana": "この仕事[しごと]は、担当[たんとう]の枠[わく]を超[こ]えて協力[きょうりょく]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "学校の枠に合わない子どもにも、学べる場所が必要だ。", "target_word": "枠", "complexity_tier": "T3", "furigana": "学校[がっこう]の枠[わく]に合[あ]わない子[こ]どもにも、学[まな]べる場所[ばしょ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "発表の時間の枠は、一人五分までです。", "target_word": "枠", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の時間[じかん]の枠[わく]は、一人[ひとり]五分[ごふん]までです。", "sentence_source": "generated"}, {"text": "国の枠を越えて、多くの人が災害の支援に集まった。", "target_word": "枠", "complexity_tier": "T3", "furigana": "国[くに]の枠[わく]を越[こ]えて、多[おお]くの人[ひと]が災害[さいがい]の支援[しえん]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "先生は、考え方の枠を広げる質問を生徒に投げかけた。", "target_word": "枠", "complexity_tier": "T3", "furigana": "先生[せんせい]は、考[かんが]え方[かた]の枠[わく]を広[ひろ]げる質問[しつもん]を生徒[せいと]に投[な]げかけた。", "sentence_source": "generated"}, {"text": "出場できる枠が限られているため、予選は厳しい。", "target_word": "枠", "complexity_tier": "T3", "furigana": "出場[しゅつじょう]できる枠[わく]が限[かぎ]られているため、予選[よせん]は厳[きび]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "枠", "label": "基本形"}], "register": "中立", "sense_fingerprint": "予算・人数・考え方などを区切る境界や制限、決められた範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ecfd4c5-f186-4c3a-b6f8-62c95cbbff14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枠", "is_correct": true, "explanation": "正解。「予算の枠」は使える金額の範囲を指し、超えないよう注意する対象として自然。"}, {"text": "手紙", "is_correct": false, "explanation": "「予算の手紙を超えない」は意味が通らず、金額の範囲を表せない。"}, {"text": "笑顔", "is_correct": false, "explanation": "「予算の笑顔」は意味が通らず、超えるべき範囲にならない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "「予算の夕暮れ」は意味が通らず、金額の制限を表せない。"}], "explanations": {"枠": "正解。「予算の枠」は使える金額の範囲を指し、超えないよう注意する対象として自然。", "手紙": "「予算の手紙を超えない」は意味が通らず、金額の範囲を表せない。", "笑顔": "「予算の笑顔」は意味が通らず、超えるべき範囲にならない。", "夕暮れ": "「予算の夕暮れ」は意味が通らず、金額の制限を表せない。"}, "sentence_index": 0, "correct_answer": "枠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は枠が暖かく、冬でも過ごしやすい。", "explanation": "ここは〈温度〉の意味。枠は範囲や境界で、部屋の暖かさは表せない。"}, {"text": "この薬は枠が効いて、熱がすぐ下がった。", "explanation": "ここは〈効き目〉の意味。枠は範囲や境界で、薬の作用には使わない。"}, {"text": "母は料理の枠が上手で、いつもおいしい夕食を作る。", "explanation": "ここは〈腕〉の意味。枠は範囲の区切りで、料理の技量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枠", "is_correct": true, "explanation": "正解。「時間の枠」は割り当てられた時間の区切りで、一人五分までという制限に合う。"}, {"text": "花", "is_correct": false, "explanation": "「発表の時間の花」は意味が通らず、制限を表せない。"}, {"text": "雨", "is_correct": false, "explanation": "「発表の時間の雨」は意味が通らず、割り当てられた時間を示せない。"}, {"text": "大根", "is_correct": false, "explanation": "「発表の時間の大根」は意味が通らず、時間の制限にならない。"}], "explanations": {"枠": "正解。「時間の枠」は割り当てられた時間の区切りで、一人五分までという制限に合う。", "花": "「発表の時間の花」は意味が通らず、制限を表せない。", "雨": "「発表の時間の雨」は意味が通らず、割り当てられた時間を示せない。", "大根": "「発表の時間の大根」は意味が通らず、時間の制限にならない。"}, "sentence_index": 6, "correct_answer": "枠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このパンは枠が柔らかく、子どもにも食べやすい。", "explanation": "ここは〈食感〉の意味。枠は範囲や境界で、柔らかさは表せない。"}, {"text": "この絵は色の枠が鮮やかで、目立つ。", "explanation": "ここは〈鮮明さ〉の意味。枠は範囲や境界で、鮮やかさは表せない。"}, {"text": "この魚は枠がおいしく、家族みんなが喜んだ。", "explanation": "ここは〈味〉の意味。枠は範囲や境界で、味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "予算の枠を収まるように、旅行の計画を立てた。", "corrected_sentence": "予算の枠に収まるように、旅行の計画を立てた。", "error_description": "「収まる」は入る範囲を「に」で示すので、「枠に収まる」が正しい。「を」は目的語を示すため、この動詞には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35853, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の時間の枠が決めてから、議題に入った。", "corrected_sentence": "会議の時間の枠を決めてから、議題に入った。", "error_description": "「決める」は決める対象を「を」で示すので、「枠を決める」が正しい。「が」は主語を示すため、ここでは不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d6d3e-c14c-43a5-bc17-afe26052f555') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『倫理に反する』と反する対象を示す『に』。"}, {"text": "が", "is_correct": false, "explanation": "『倫理が反する』は倫理を主語にし、反する行為と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "『倫理で反する』は手段を示すが、反する対象は『に』で示す。"}, {"text": "を", "is_correct": false, "explanation": "『倫理を反する』は不可。反する対象は『に』で示す。"}], "correct_answer": "に", "explanations": {"に": "『倫理に反する』と反する対象を示す『に』。", "が": "『倫理が反する』は倫理を主語にし、反する行為と結びつかない。", "で": "『倫理で反する』は手段を示すが、反する対象は『に』で示す。", "を": "『倫理を反する』は不可。反する対象は『に』で示す。"}, "error_tags": {"が": "主格", "で": "手段", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『軽く見る』の対象を示す『を』。"}, {"text": "の", "is_correct": false, "explanation": "『倫理の軽く見る』は名詞に続かず、見る対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は見る対象にならず、『倫理へ軽く見る』は不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、軽く見る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『軽く見る』の対象を示す『を』。", "の": "『倫理の軽く見る』は名詞に続かず、見る対象にならない。", "へ": "方向の『へ』は見る対象にならず、『倫理へ軽く見る』は不自然。", "から": "『から』は起点を示すので、軽く見る対象にはならない。"}, "error_tags": {"の": "連体", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が正しい行いをするための考え方や決まりのことです。", "primary_collocate": null, "pronunciation": "りんり", "ipa": "ɾiɲɾi", "syllable_count": 3, "sentences": [{"text": "医者には、患者を守るための倫理が求められる。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "医者[いしゃ]には、患者[かんじゃ]を守[まも]るための倫理[りんり]が求[もと]められる。", "sentence_source": "generated"}, {"text": "倫理に反する行為は、会社の信用を失わせる。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "倫理[りんり]に反[はん]する行為[こうい]は、会社[かいしゃ]の信用[しんよう]を失[うしな]わせる。", "sentence_source": "generated"}, {"text": "この授業では、科学者の倫理について考えます。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、科学者[かがくしゃ]の倫理[りんり]について考[かんが]えます。", "sentence_source": "generated"}, {"text": "記者は取材の倫理を守って、記事を書いた。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "記者[きしゃ]は取材[しゅざい]の倫理[りんり]を守[まも]って、記事[きじ]を書[か]いた。", "sentence_source": "generated"}, {"text": "彼は倫理を大切にする人で、うそをついて得をしようとはしない。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "彼[かれ]は倫理[りんり]を大切[たいせつ]にする人[ひと]で、うそをついて得[とく]をしようとはしない。", "sentence_source": "generated"}, {"text": "動物を使う実験には、厳しい倫理の決まりがある。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "動物[どうぶつ]を使[つか]う実験[じっけん]には、厳[きび]しい倫理[りんり]の決[き]まりがある。", "sentence_source": "generated"}, {"text": "倫理を学ぶと、何が正しいかを自分で考えられるようになる。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "倫理[りんり]を学[まな]ぶと、何[なに]が正[ただ]しいかを自分[じぶん]で考[かんが]えられるようになる。", "sentence_source": "generated"}, {"text": "倫理を軽く見る会社では、不正が起きやすい。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "倫理[りんり]を軽[かる]く見[み]る会社[かいしゃ]では、不正[ふせい]が起[お]きやすい。", "sentence_source": "generated"}, {"text": "研究者の倫理を問う声が、ニュースで大きくなった。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]の倫理[りんり]を問[と]う声[こえ]が、ニュースで大[おお]きくなった。", "sentence_source": "generated"}, {"text": "新しい技術が増え、社会の倫理も見直されている。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]が増[ふ]え、社会[しゃかい]の倫理[りんり]も見直[みなお]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "倫理", "label": "基本形"}], "register": "formal", "sense_fingerprint": "人が正しく行動するための考え方や決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倫理", "is_correct": true, "explanation": "患者を守るための道徳的な決まりを指し、求められる語として入る。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのことで、求められるものではない。"}, {"text": "予感", "is_correct": false, "explanation": "予感は前触れを感じる気持ちで、求められる対象にならない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は響きが残ることで、ここには合わない。"}], "explanations": {"倫理": "患者を守るための道徳的な決まりを指し、求められる語として入る。", "寿命": "寿命は命の長さのことで、求められるものではない。", "予感": "予感は前触れを感じる気持ちで、求められる対象にならない。", "余韻": "余韻は響きが残ることで、ここには合わない。"}, "sentence_index": 0, "correct_answer": "倫理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その説明は倫理が通っていて、誰も反論できない。", "explanation": "ここは〈論理〉の意味。筋道が通るのは論理で、倫理は通るものではない。"}, {"text": "彼は倫理が大きくて、会議室の端まで届く。", "explanation": "ここは〈声〉の意味。大きさを言うのは声で、倫理に大きさの話は当てはまらない。"}, {"text": "彼女の倫理は、この一年で長く伸びた。", "explanation": "ここは〈髪〉の意味。伸びるのは髪で、倫理は伸びるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倫理", "is_correct": true, "explanation": "正しい行いを考える基準を指し、学ぶ対象になる語。"}, {"text": "感想", "is_correct": false, "explanation": "感想は受けた印象の言葉で、学ぶ対象にならない。"}, {"text": "返事", "is_correct": false, "explanation": "返事は応答の言葉で、学ぶ対象にならない。"}, {"text": "印象", "is_correct": false, "explanation": "印象は受けた感じのことで、学ぶ対象にはならない。"}], "explanations": {"倫理": "正しい行いを考える基準を指し、学ぶ対象になる語。", "感想": "感想は受けた印象の言葉で、学ぶ対象にならない。", "返事": "返事は応答の言葉で、学ぶ対象にならない。", "印象": "印象は受けた感じのことで、学ぶ対象にはならない。"}, "sentence_index": 6, "correct_answer": "倫理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は倫理が豊かで、映画を見ると必ず泣く。", "explanation": "ここは〈感情〉の意味。豊かさを言うのは感情で、倫理は豊かさの対象にならない。"}, {"text": "彼女は倫理が上手で、合唱の中心にいる。", "explanation": "ここは〈歌〉の意味。上手かどうかは歌について言うので、倫理は当てはまらない。"}, {"text": "この店のスープは倫理が濃くて、少し塩辛い。", "explanation": "ここは〈味〉の意味。濃さを言うのは味で、倫理に濃さは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "取材先の情報は、倫理が守って扱うべきだ。", "corrected_sentence": "取材先の情報は、倫理を守って扱うべきだ。", "error_description": "『守る』は他動詞なので、倫理の後ろは『を』が正しい。『が』にすると倫理が主語になり、守る人が文に現れない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は取材の倫理に従えて行動した。", "corrected_sentence": "彼は取材の倫理に従って行動した。", "error_description": "『従う』の連用形（て形）は『従って』。『従えて』は『従える』の活用で、意味が変わり文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『によって』の『に』で、違いの根拠や原因を示す。"}, {"text": "を", "is_correct": false, "explanation": "『個人の倫理を少しちがう』は不成立。違いの主体を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は違いの根拠を示せない。"}, {"text": "の", "is_correct": false, "explanation": "『個人の倫理の少しちがう』は名詞に続かず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "『によって』の『に』で、違いの根拠や原因を示す。", "を": "『個人の倫理を少しちがう』は不成立。違いの主体を示せない。", "へ": "方向の『へ』は違いの根拠を示せない。", "の": "『個人の倫理の少しちがう』は名詞に続かず、文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『教える』の目的語を示す『を』。"}, {"text": "と", "is_correct": false, "explanation": "『倫理と教える』は並列や相手を示すが、教える内容にならない。"}, {"text": "の", "is_correct": false, "explanation": "『倫理の教える』は名詞に続かず、動詞の目的語にならない。"}, {"text": "が", "is_correct": false, "explanation": "『倫理が教える』は倫理を主語にし、教える人が文に現れない。"}], "correct_answer": "を", "explanations": {"を": "『教える』の目的語を示す『を』。", "と": "『倫理と教える』は並列や相手を示すが、教える内容にならない。", "の": "『倫理の教える』は名詞に続かず、動詞の目的語にならない。", "が": "『倫理が教える』は倫理を主語にし、教える人が文に現れない。"}, "error_tags": {"と": "並列・相手", "の": "連体", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間として正しい行動をするために、何が良いか悪いかを考える基準や考え方。", "primary_collocate": null, "pronunciation": "りんり", "ipa": "ɾiɲɾi", "syllable_count": 3, "sentences": [{"text": "人工知能を使うときは、倫理の基準を決める必要がある。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "人工知能[じんこうちのう]を使[つか]うときは、倫理[りんり]の基準[きじゅん]を決[き]める必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "何が良くて何が悪いかは、個人の倫理によって少しちがう。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "何[なに]が良[よ]くて何[なに]が悪[わる]いかは、個人[こじん]の倫理[りんり]によって少[すこ]しちがう。", "sentence_source": "generated"}, {"text": "彼女は自分の倫理に従って、その仕事を断った。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の倫理[りんり]に従[したが]って、その仕事[しごと]を断[ことわ]った。", "sentence_source": "generated"}, {"text": "この映画は、命を救うための嘘は許されるのかという倫理の問題を描いている。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "この映画[えいが]は、命[いのち]を救[すく]うための嘘[うそ]は許[ゆる]されるのかという倫理[りんり]の問題[もんだい]を描[えが]いている。", "sentence_source": "generated"}, {"text": "先生は授業で、何が正しいかを倫理の観点から生徒に考えさせた。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で、何[なに]が正[ただ]しいかを倫理[りんり]の観点[かんてん]から生徒[せいと]に考[かんが]えさせた。", "sentence_source": "generated"}, {"text": "利益だけを考えて、倫理を忘れた経営は長く続かない。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "利益[りえき]だけを考[かんが]えて、倫理[りんり]を忘[わす]れた経営[けいえい]は長[なが]く続[つづ]かない。", "sentence_source": "generated"}, {"text": "遺伝子を変える技術には、倫理の面で反対する人も多い。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "遺伝子[いでんし]を変[か]える技術[ぎじゅつ]には、倫理[りんり]の面[めん]で反対[はんたい]する人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "子どもに倫理を教えるには、まず大人が正しい行動を見せることだ。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "子[こ]どもに倫理[りんり]を教[おし]えるには、まず大人[おとな]が正[ただ]しい行動[こうどう]を見[み]せることだ。", "sentence_source": "generated"}, {"text": "彼の行動は法律には合っているが、倫理としては疑問が残る。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "彼[かれ]の行動[こうどう]は法律[ほうりつ]には合[あ]っているが、倫理[りんり]としては疑問[ぎもん]が残[のこ]る。", "sentence_source": "generated"}, {"text": "医療の倫理を考える会議が、来週ひらかれる。", "target_word": "倫理", "complexity_tier": "T3", "furigana": "医療[いりょう]の倫理[りんり]を考[かんが]える会議[かいぎ]が、来週[らいしゅう]ひらかれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "倫理", "label": "基本形"}], "register": "formal", "sense_fingerprint": "何が良く何が悪いかを判断するための基準や考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倫理", "is_correct": true, "explanation": "人が正しく行動するための判断の基準を指し、ここに入る語。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのことで、基準の対象にはならない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸で、基準とは結びつかない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は響きが残ることで、基準の前に置けない。"}], "explanations": {"倫理": "人が正しく行動するための判断の基準を指し、ここに入る語。", "寿命": "寿命は命の長さのことで、基準の対象にはならない。", "寝息": "寝息は眠っている時の呼吸で、基準とは結びつかない。", "余韻": "余韻は響きが残ることで、基準の前に置けない。"}, "sentence_index": 0, "correct_answer": "倫理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は倫理をよく表に出し、喜ぶとすぐ笑う。", "explanation": "ここは〈感情〉の意味。表に出すのは感情で、倫理は表に出すものではない。"}, {"text": "その主張は倫理が矛盾していて、説得力がない。", "explanation": "ここは〈論理〉の意味。筋が通るかどうかは論理で、倫理は矛盾の有無を言う語ではない。"}, {"text": "この部屋は倫理が大きくて、昼でも明るい。", "explanation": "ここは〈窓〉の意味。大きさを言うのは窓で、倫理の大きさは当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倫理", "is_correct": true, "explanation": "何が正しいかを判断する基準を指し、反対の理由になる語。"}, {"text": "腹痛", "is_correct": false, "explanation": "腹痛は体の痛みのことで、反対する面にはならない。"}, {"text": "予感", "is_correct": false, "explanation": "予感は前触れを感じる気持ちで、反対する面にはならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は眠っている時の言葉で、ここには合わない。"}], "explanations": {"倫理": "何が正しいかを判断する基準を指し、反対の理由になる語。", "腹痛": "腹痛は体の痛みのことで、反対する面にはならない。", "予感": "予感は前触れを感じる気持ちで、反対する面にはならない。", "寝言": "寝言は眠っている時の言葉で、ここには合わない。"}, "sentence_index": 6, "correct_answer": "倫理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生には、いつも丁寧な倫理で接する。", "explanation": "ここは〈態度〉の意味。人への接し方は態度と言い、倫理で接するとは言わない。"}, {"text": "彼の倫理が丁寧で、読みやすい。", "explanation": "ここは〈字〉の意味。丁寧さや読みやすさを言うのは字で、倫理には当てはまらない。"}, {"text": "空の倫理が美しく、皆が見とれた。", "explanation": "ここは〈夕焼け〉の意味。美しさを言うのは夕焼けで、倫理は美しさの対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、倫理に観点から案を検討した。", "corrected_sentence": "会議では、倫理の観点から案を検討した。", "error_description": "『倫理の観点』は『の』で名詞をつなぐ。『に』にすると『倫理に観点』となり不自然なので、『の』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医師は患者への倫理を守るて判断する。", "corrected_sentence": "医師は患者への倫理を守って判断する。", "error_description": "『守る』のて形は『守って』。『守るて』は活用の誤りで、ここは『守って』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「現代の社会」の連体修飾を示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「現代が社会を舞台にしている」は文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「現代へ社会を舞台にしている」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「現代より社会を舞台にしている」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「現代の社会」の連体修飾を示す「の」。", "が": "「が」は主語を示すため、「現代が社会を舞台にしている」は文が成立しない。", "へ": "「へ」は方向を示すので、「現代へ社会を舞台にしている」は意味が通らない。", "より": "「より」は比較を示すため、「現代より社会を舞台にしている」は成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「現代にも通じる」の「に」で、時代に対して通じることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「現代を通じる」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「現代から通じる」は文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、「現代の通じる」の形では文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「現代にも通じる」の「に」で、時代に対して通じることを示す。", "を": "「を」は目的語を示すため、「現代を通じる」は不自然。", "から": "「から」は起点を示すので、「現代から通じる」は文が成立しない。", "の": "「の」は名詞を修飾するため、「現代の通じる」の形では文が成立しない。"}, "error_tags": {"を": "目的語", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今の時代のこと。", "primary_collocate": null, "pronunciation": "げんだい", "ipa": "ɡendai", "syllable_count": 4, "sentences": [{"text": "現代の若者は、スマートフォンで何でも調べる。", "target_word": "現代", "complexity_tier": "T3", "furigana": "現代[げんだい]の若者[わかもの]は、スマートフォンで何[なん]でも調[しら]べる。", "sentence_source": "generated"}, {"text": "この小説は、現代の社会を舞台にしている。", "target_word": "現代", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、現代[げんだい]の社会[しゃかい]を舞台[ぶたい]にしている。", "sentence_source": "generated"}, {"text": "現代では、遠くの人とすぐに話ができる。", "target_word": "現代", "complexity_tier": "T3", "furigana": "現代[げんだい]では、遠[とお]くの人[ひと]とすぐに話[はなし]ができる。", "sentence_source": "generated"}, {"text": "博物館で、昔の道具と現代の道具を比べた。", "target_word": "現代", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、昔[むかし]の道具[どうぐ]と現代[げんだい]の道具[どうぐ]を比[くら]べた。", "sentence_source": "generated"}, {"text": "現代に生きる私たちは、情報が多すぎて疲れる。", "target_word": "現代", "complexity_tier": "T3", "furigana": "現代[げんだい]に生[い]きる私[わたし]たちは、情報[じょうほう]が多[おお]すぎて疲[つか]れる。", "sentence_source": "generated"}, {"text": "彼は古い建物を、現代の技術で直す仕事をしている。", "target_word": "現代", "complexity_tier": "T3", "furigana": "彼[かれ]は古[ふる]い建物[たてもの]を、現代[げんだい]の技術[ぎじゅつ]で直[なお]す仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "現代の都市では、高い建物が次々に建っている。", "target_word": "現代", "complexity_tier": "T3", "furigana": "現代[げんだい]の都市[とし]では、高[たか]い建物[たてもの]が次々[つぎつぎ]に建[た]っている。", "sentence_source": "generated"}, {"text": "この詩は百年前のものだが、現代にも通じる。", "target_word": "現代", "complexity_tier": "T3", "furigana": "この詩[し]は百年前[ひゃくねんまえ]のものだが、現代[げんだい]にも通[つう]じる。", "sentence_source": "generated"}, {"text": "現代は変化が速いので、学び続けることが大切だ。", "target_word": "現代", "complexity_tier": "T3", "furigana": "現代[げんだい]は変化[へんか]が速[はや]いので、学[まな]び続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "祖父の時代と現代とでは、暮らしがまったく違う。", "target_word": "現代", "complexity_tier": "T3", "furigana": "祖父[そふ]の時代[じだい]と現代[げんだい]とでは、暮[く]らしがまったく違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "今、自分たちが生きている時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現代", "is_correct": true, "explanation": "正解。スマートフォンが普及した今の時代を指すので、文の内容に合う。"}, {"text": "江戸", "is_correct": false, "explanation": "江戸時代にはスマートフォンがなく、「江戸の若者はスマートフォンで調べる」は成り立たない。"}, {"text": "古代", "is_correct": false, "explanation": "古代にはスマートフォンが存在しないので、文の内容と合わない。"}, {"text": "明治", "is_correct": false, "explanation": "明治時代にはスマートフォンがなく、「明治の若者はスマートフォンで…」は成り立たない。"}], "explanations": {"現代": "正解。スマートフォンが普及した今の時代を指すので、文の内容に合う。", "江戸": "江戸時代にはスマートフォンがなく、「江戸の若者はスマートフォンで調べる」は成り立たない。", "古代": "古代にはスマートフォンが存在しないので、文の内容と合わない。", "明治": "明治時代にはスマートフォンがなく、「明治の若者はスマートフォンで…」は成り立たない。"}, "sentence_index": 0, "correct_answer": "現代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "現代の天気を確かめてから、遠足に出かけた。", "explanation": "ここは〈今日〉の意味。その日一日の天気は今日と言い、時代を表す現代とは合わない。"}, {"text": "書類には、現代の住所を書いてください。", "explanation": "ここは〈現在〉の意味。今いる所の住所は現在と言い、時代を表す現代とは合わない。"}, {"text": "祖母が若かった現代には、この町に電車が通っていなかった。", "explanation": "ここは〈当時〉の意味。過去のある時点を指すときは当時と言い、今の時代を表す現代とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現代", "is_correct": true, "explanation": "正解。高い建物が次々に建つ今の都市の様子を指すので、文に合う。"}, {"text": "農村", "is_correct": false, "explanation": "農村は都市ではなく、高い建物が次々に建つ場所として不自然。"}, {"text": "離島", "is_correct": false, "explanation": "離島で高い建物が次々に建つ状況は考えにくく、文の内容と合わない。"}, {"text": "縄文", "is_correct": false, "explanation": "縄文時代には都市も高い建物もなく、文の内容と合わない。"}], "explanations": {"現代": "正解。高い建物が次々に建つ今の都市の様子を指すので、文に合う。", "農村": "農村は都市ではなく、高い建物が次々に建つ場所として不自然。", "離島": "離島で高い建物が次々に建つ状況は考えにくく、文の内容と合わない。", "縄文": "縄文時代には都市も高い建物もなく、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "現代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十年後の現代を思い描いて、夢を語り合った。", "explanation": "ここは〈未来〉の意味。これから先の時代は未来と言い、今の時代を指す現代とは合わない。"}, {"text": "この遺跡からは、現代の人々が使った文字が見つかった。", "explanation": "ここは〈古代〉の意味。遠い昔の時代は古代と言い、今の時代を指す現代とは合わない。"}, {"text": "この小説は、明治の現代を舞台にしている。", "explanation": "ここは〈近代〉の意味。明治など過去の時代を指すときは近代と言い、今の時代を表す現代とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "現代を生まれた子どもは、画面に慣れている。", "corrected_sentence": "現代に生まれた子どもは、画面に慣れている。", "error_description": "「生まれる」は時や場所を「に」で示す。「現代を」は誤りで、正しくは「現代に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの若者が、現代を生まれるための技術を学んでいる。", "corrected_sentence": "多くの若者が、現代を生きるための技術を学んでいる。", "error_description": "「現代を生きる」と言う。「生まれる」は自分が生まれた時期に使うので、「現代を生まれる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35861, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「意味を内包する」で、内包する対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}, {"text": "と", "is_correct": false, "explanation": "「意味と内包する」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "「意味を内包する」で、内包する対象を示す。", "へ": "方向を表す助詞で、ここでは使えない。", "と": "「意味と内包する」は文として成り立たない。", "から": "起点を表す助詞で、ここでは使えない。"}, "error_tags": {"へ": "direction", "と": "accompaniment", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35861, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「意味を内包する」で、内包する対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「意味に内包する」は対象の示し方として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の助詞で、ここでは使えない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "「意味を内包する」で、内包する対象を示す。", "に": "「意味に内包する」は対象の示し方として成り立たない。", "より": "比較・起点の助詞で、ここでは使えない。", "から": "起点を表す助詞で、ここでは使えない。"}, "error_tags": {"に": "target_marker", "より": "comparison", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35861, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事の中に、別の要素や意味が含まれていること。", "primary_collocate": null, "pronunciation": "ないほう", "ipa": "naihoː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "内包している", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価上昇圧力[ぶっかじょうしょうあつりょく]と相乗効果[そうじょうこうか]を生[う]み、予期[よき]せぬスタグフレーションや財政主導[ざいせいしゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "この言葉は二つの意味を内包する。", "target_word": "内包する", "complexity_tier": "T2", "furigana": "この言葉[ことば]は二[ふた]つの意味[いみ]を内包[ないほう]する。", "sentence_source": "generated"}, {"text": "その計画は危険を内包する。", "target_word": "内包する", "complexity_tier": "T2", "furigana": "その計画[けいかく]は危険[きけん]を内包[ないほう]する。", "sentence_source": "generated"}, {"text": "大きな問題を内包した計画です。", "target_word": "内包した", "complexity_tier": "T3", "furigana": "大[おお]きな問題[もんだい]を内包[ないほう]した計画[けいかく]です。", "sentence_source": "generated"}, {"text": "この詩は深い悲しみを内包している。", "target_word": "内包している", "complexity_tier": "T3", "furigana": "この詩[し]は深[ふか]い悲[かな]しみを内包[ないほう]している。", "sentence_source": "generated"}, {"text": "内包された意味を考えてみよう。", "target_word": "内包された", "complexity_tier": "T4", "furigana": "内包[ないほう]された意味[いみ]を考[かんが]えてみよう。", "sentence_source": "generated"}, {"text": "その制度は矛盾を内包していたため、長くは続かなかった。", "target_word": "内包していた", "complexity_tier": "T4", "furigana": "その制度[せいど]は矛盾[むじゅん]を内包[ないほう]していたため、長[なが]くは続[つづ]かなかった。", "sentence_source": "generated"}, {"text": "一つの単語が複数の意味を内包することは珍しくない。", "target_word": "内包する", "complexity_tier": "T4", "furigana": "一[ひと]つの単語[たんご]が複数[ふくすう]の意味[いみ]を内包[ないほう]することは珍[めずら]しくない。", "sentence_source": "generated"}, {"text": "彼の笑顔は、怒りを内包しているように見えた。", "target_word": "内包している", "complexity_tier": "T4", "furigana": "彼[かれ]の笑顔[えがお]は、怒[いか]りを内包[ないほう]しているように見[み]えた。", "sentence_source": "generated"}, {"text": "成長する市場は、大きな機会とともに危険も内包していると言われる。", "target_word": "内包している", "complexity_tier": "T5", "furigana": "成長[せいちょう]する市場[しじょう]は、大[おお]きな機会[きかい]とともに危険[きけん]も内包[ないほう]していると言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内包する", "label": "活用"}, {"form": "内包した", "label": "活用"}, {"form": "内包される", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の中に別の要素を含み持つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35861, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内包", "is_correct": true, "explanation": "見出し語「ないほう」そのもの。"}, {"text": "内容", "is_correct": false, "explanation": "「ないよう」は「ほ」が「よ」に変わる1拍違いの別語。"}, {"text": "内臓", "is_correct": false, "explanation": "「ないぞう」は「ほ」が「ぞ」に変わる1拍違いの別語。"}, {"text": "内装", "is_correct": false, "explanation": "「ないそう」は「ほ」が「そ」に変わる1拍違いの別語。"}, {"text": "内向", "is_correct": false, "explanation": "「ないこう」は「ほ」が「こ」に変わる1拍違いの別語。"}], "explanations": {"内包": "見出し語「ないほう」そのもの。", "内容": "「ないよう」は「ほ」が「よ」に変わる1拍違いの別語。", "内臓": "「ないぞう」は「ほ」が「ぞ」に変わる1拍違いの別語。", "内装": "「ないそう」は「ほ」が「そ」に変わる1拍違いの別語。", "内向": "「ないこう」は「ほ」が「こ」に変わる1拍違いの別語。"}, "sentence_index": null, "correct_answer": "内包"}, "level_3": {"options": [{"text": "内包している", "is_correct": true, "explanation": "リスクを含み持っているという意味が文脈に合う。"}, {"text": "演奏している", "is_correct": false, "explanation": "形は合うが、リスクを演奏するという意味が合わない。"}, {"text": "禁止している", "is_correct": false, "explanation": "形は合うが、リスクを禁止するという意味が合わない。"}, {"text": "修理している", "is_correct": false, "explanation": "形は合うが、リスクを修理するという意味が合わない。"}], "explanations": {"内包している": "リスクを含み持っているという意味が文脈に合う。", "演奏している": "形は合うが、リスクを演奏するという意味が合わない。", "禁止している": "形は合うが、リスクを禁止するという意味が合わない。", "修理している": "形は合うが、リスクを修理するという意味が合わない。"}, "sentence_index": 0, "correct_answer": "内包している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昨日、友達と一緒に公園を内包した。", "explanation": "「内包」は「歩く・散歩する」の意味では使えない。"}, {"text": "彼は先生に宿題を内包して、教室を出た。", "explanation": "「内包」は「提出する」の意味では使えない。"}, {"text": "彼女は新しい服を内包するために、デパートへ行った。", "explanation": "「内包」は「買う」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35861, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "内包", "is_correct": true, "explanation": "見出し語「ないほう」そのもの。"}, {"text": "内通", "is_correct": false, "explanation": "「ないつう」は「ほ」が「つ」に変わる1拍違いの別語。"}, {"text": "内憂", "is_correct": false, "explanation": "「ないゆう」は「ほ」が「ゆ」に変わる1拍違いの別語。"}, {"text": "内証", "is_correct": false, "explanation": "「ないしょう」は「ほ」が「しょ」に変わる1拍違いの別語。"}], "explanations": {"内包": "見出し語「ないほう」そのもの。", "内通": "「ないつう」は「ほ」が「つ」に変わる1拍違いの別語。", "内憂": "「ないゆう」は「ほ」が「ゆ」に変わる1拍違いの別語。", "内証": "「ないしょう」は「ほ」が「しょ」に変わる1拍違いの別語。"}, "sentence_index": null, "correct_answer": "内包"}, "level_3": {"options": [{"text": "内包していた", "is_correct": true, "explanation": "制度が矛盾を含み持っていたという意味が合い、続かなかった理由になる。"}, {"text": "運んでいた", "is_correct": false, "explanation": "形は合うが、矛盾を運ぶという意味が合わない。"}, {"text": "洗っていた", "is_correct": false, "explanation": "形は合うが、矛盾を洗うという意味が合わない。"}, {"text": "祝っていた", "is_correct": false, "explanation": "形は合うが、矛盾を祝うという意味が合わない。"}], "explanations": {"内包していた": "制度が矛盾を含み持っていたという意味が合い、続かなかった理由になる。", "運んでいた": "形は合うが、矛盾を運ぶという意味が合わない。", "洗っていた": "形は合うが、矛盾を洗うという意味が合わない。", "祝っていた": "形は合うが、矛盾を祝うという意味が合わない。"}, "sentence_index": 6, "correct_answer": "内包していた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ったので、旅行を内包して家にいた。", "explanation": "「内包」は「中止する」の意味では使えない。"}, {"text": "私は毎日六時に起きて、犬を内包している。", "explanation": "「内包」は「散歩させる」の意味では使えない。"}, {"text": "この店は客を内包するために、新しい看板を作った。", "explanation": "「内包」は「引きつける」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
