INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35869, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "数量や程度がわずかであること。", "primary_collocate": null, "pronunciation": "すこし", "ipa": "sɯkoɕi", "syllable_count": 3, "sentences": [{"text": "この部屋は少し暗いので、電気をつけました。", "target_word": "少し", "complexity_tier": "T2", "furigana": "この部屋[へや]は少[すこ]し暗[くら]いので、電気[でんき]をつけました。", "sentence_source": "generated"}, {"text": "疲れたので、少し休んでもいいですか。", "target_word": "少し", "complexity_tier": "T2", "furigana": "疲[つか]れたので、少[すこ]し休[やす]んでもいいですか。", "sentence_source": "generated"}, {"text": "スープに塩を少し足したら、ちょうどいい味になった。", "target_word": "少し", "complexity_tier": "T3", "furigana": "スープに塩[しお]を少[すこ]し足[た]したら、ちょうどいい味[あじ]になった。", "sentence_source": "generated"}, {"text": "少し寒いから、窓を閉めてください。", "target_word": "少し", "complexity_tier": "T2", "furigana": "少[すこ]し寒[さむ]いから、窓[まど]を閉[し]めてください。", "sentence_source": "generated"}, {"text": "駅から少し歩くと、小さな公園があります。", "target_word": "少し", "complexity_tier": "T2", "furigana": "駅[えき]から少[すこ]し歩[ある]くと、小[ちい]さな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "昨日より熱が少し下がったが、まだ学校には行けない。", "target_word": "少し", "complexity_tier": "T3", "furigana": "昨日[きのう]より熱[ねつ]が少[すこ]し下[さ]がったが、まだ学校[がっこう]には行[い]けない。", "sentence_source": "generated"}, {"text": "少し待ってください。すぐに資料を持ってきます。", "target_word": "少し", "complexity_tier": "T3", "furigana": "少[すこ]し待[ま]ってください。すぐに資料[しりょう]を持[も]ってきます。", "sentence_source": "generated"}, {"text": "日本語は少し話せますが、漢字を読むのは苦手です。", "target_word": "少し", "complexity_tier": "T3", "furigana": "日本語[にほんご]は少[すこ]し話[はな]せますが、漢字[かんじ]を読[よ]むのは苦手[にがて]です。", "sentence_source": "generated"}, {"text": "財布にお金が少ししか入っていなかったので、買うのをあきらめた。", "target_word": "少し", "complexity_tier": "T4", "furigana": "財布[さいふ]にお金[かね]が少[すこ]ししか入[はい]っていなかったので、買[か]うのをあきらめた。", "sentence_source": "generated"}, {"text": "彼女は少し驚いた顔をして、私の話を聞いていた。", "target_word": "少し", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は少[すこ]し驚[おどろ]いた顔[かお]をして、私[わたし]の話[はなし]を聞[き]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "少し", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数量・程度がわずかな様子を表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35869, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少し", "is_correct": true, "explanation": "副詞。「少し暗い」で、部屋の暗さがわずかであることを表す。"}, {"text": "初めて", "is_correct": false, "explanation": "初回を表す語で、「初めて暗い」は程度を表せず文にならない。"}, {"text": "同時に", "is_correct": false, "explanation": "同時を表す語で、「同時に暗い」は程度を表せず不自然。"}, {"text": "必ず", "is_correct": false, "explanation": "断定を表す副詞で、「必ず暗い」は程度を表せず不自然。"}], "explanations": {"少し": "副詞。「少し暗い」で、部屋の暗さがわずかであることを表す。", "初めて": "初回を表す語で、「初めて暗い」は程度を表せず文にならない。", "同時に": "同時を表す語で、「同時に暗い」は程度を表せず不自然。", "必ず": "断定を表す副詞で、「必ず暗い」は程度を表せず不自然。"}, "sentence_index": 0, "correct_answer": "少し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "少し完全に、作業は終わった。", "explanation": "ここは〈少し〉を〈ほぼ〉（ほとんど）の意味で使った誤用。〈少し〉は程度がわずかなことなので、「完全に」とは合わない。"}, {"text": "少し大量の資料をコピーした。", "explanation": "ここは〈少し〉を〈少なからず〉（かなり多く）の意味で使った誤用。〈少し〉は量がわずかなことを表すので、「大量」とは合わない。"}, {"text": "少し一年間もかかった。", "explanation": "ここは〈少し〉を〈少しの間〉（短い時間）の意味で使った誤用。「一年間もかかった」と長さを強める文とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35869, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少し", "is_correct": true, "explanation": "副詞。「少し待ってください」で、待つ時間がわずかであることを表す。"}, {"text": "大いに", "is_correct": false, "explanation": "程度や量が大きいことを表す副詞で、「大いに待ってください」は意味が合わず不自然。"}, {"text": "既に", "is_correct": false, "explanation": "すでにを表す語で、「既に待ってください」は意味が合わない。"}, {"text": "確かに", "is_correct": false, "explanation": "確実さを表す副詞で、「確かに待ってください」は文脈に合わず不自然。"}], "explanations": {"少し": "副詞。「少し待ってください」で、待つ時間がわずかであることを表す。", "大いに": "程度や量が大きいことを表す副詞で、「大いに待ってください」は意味が合わず不自然。", "既に": "すでにを表す語で、「既に待ってください」は意味が合わない。", "確かに": "確実さを表す副詞で、「確かに待ってください」は文脈に合わず不自然。"}, "sentence_index": 6, "correct_answer": "少し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少し数回の練習で、すぐに上達した。", "explanation": "ここは〈少し〉を〈何回か〉（回数がわずか）の意味で使った誤用。〈少し〉は数量の少なさを表し、回数を数える「数回」と重ねると意味が合わない。"}, {"text": "少し常に笑っていて、とても楽しそうだった。", "explanation": "ここは〈少し〉を〈時々〉（ときどき）の意味で使った誤用。「常に」は絶えず続くことを表し、〈少し〉とは両立しない。"}, {"text": "少し何度も確認した。", "explanation": "ここは〈少し〉を〈何回か〉（回数がわずか）の意味で使った誤用。「何度も」は回数が多いことを表し、〈少し〉とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35869, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少しに遠いので、バスで行きましょう。", "corrected_sentence": "少し遠いので、バスで行きましょう。", "error_description": "「少し」は副詞なので、助詞「に」は付かない。「少し遠い」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35869, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は少しな驚いた顔で、私に手を振った。", "corrected_sentence": "彼は少し驚いた顔で、私に手を振った。", "error_description": "「少し」は副詞なので、形容動詞の「な」は付かない。「少し驚いた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一種類", "is_correct": true, "explanation": "種類がひとつだけで、いろいろの反対を表す。"}, {"text": "様々", "is_correct": false, "explanation": "いろいろと同じ意味で、反対ではない。"}, {"text": "多様", "is_correct": false, "explanation": "種類が多いことを表し、いろいろに近い。"}, {"text": "豊富", "is_correct": false, "explanation": "量が多いことで、種類がひとつという反対の意味ではない。"}], "correct_answer": "一種類", "explanations": {"一種類": "種類がひとつだけで、いろいろの反対を表す。", "様々": "いろいろと同じ意味で、反対ではない。", "多様": "種類が多いことを表し、いろいろに近い。", "豊富": "量が多いことで、種類がひとつという反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "均一", "is_correct": true, "explanation": "どれも同じであることで、いろいろの反対を表す。"}, {"text": "様々", "is_correct": false, "explanation": "いろいろと同じ意味で、反対ではない。"}, {"text": "豊富", "is_correct": false, "explanation": "量が多いことで、反対の意味ではない。"}, {"text": "無数", "is_correct": false, "explanation": "数が非常に多いことで、いろいろの反対ではない。"}], "correct_answer": "均一", "explanations": {"均一": "どれも同じであることで、いろいろの反対を表す。", "様々": "いろいろと同じ意味で、反対ではない。", "豊富": "量が多いことで、反対の意味ではない。", "無数": "数が非常に多いことで、いろいろの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "たくさんの ちがう しゅるいが ある こと。", "primary_collocate": null, "pronunciation": "いろいろ", "ipa": "iroiro", "syllable_count": 4, "sentences": [{"text": "いろいろな魚がいる。", "target_word": "いろいろな", "complexity_tier": "T1", "furigana": "いろいろな魚[さかな]がいる。", "sentence_source": "generated"}, {"text": "服の色はいろいろです。", "target_word": "いろいろです", "complexity_tier": "T2", "furigana": "服[ふく]の色[いろ]はいろいろです。", "sentence_source": "generated"}, {"text": "公園でいろいろな鳥を見ました。", "target_word": "いろいろな", "complexity_tier": "T2", "furigana": "公園[こうえん]でいろいろな鳥[とり]を見[み]ました。", "sentence_source": "generated"}, {"text": "町にはお店がいろいろあります。", "target_word": "いろいろ", "complexity_tier": "T2", "furigana": "町[まち]にはお店[みせ]がいろいろあります。", "sentence_source": "generated"}, {"text": "動物園には、いろいろな動物がいる。", "target_word": "いろいろな", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]には、いろいろな動物[どうぶつ]がいる。", "sentence_source": "generated"}, {"text": "いろいろ食べて、おなかがいっぱいになった。", "target_word": "いろいろ", "complexity_tier": "T3", "furigana": "いろいろ食[た]べて、おなかがいっぱいになった。", "sentence_source": "generated"}, {"text": "本屋でいろいろ見て、三冊買った。", "target_word": "いろいろ", "complexity_tier": "T3", "furigana": "本屋[ほんや]でいろいろ見[み]て、三冊[さんさつ]買[か]った。", "sentence_source": "generated"}, {"text": "みんなの好きなものは、いろいろだ。", "target_word": "いろいろだ", "complexity_tier": "T3", "furigana": "みんなの好[す]きなものは、いろいろだ。", "sentence_source": "generated"}, {"text": "世界にはいろいろな言葉があって、国によって違う。", "target_word": "いろいろな", "complexity_tier": "T4", "furigana": "世界[せかい]にはいろいろな言葉[ことば]があって、国[くに]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "先生は色々と教えてくれた。", "target_word": "色々と", "complexity_tier": "T3", "furigana": "先生[せんせい]は色々[いろいろ]と教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "いろいろな", "label": "活用"}, {"form": "いろいろに", "label": "活用"}, {"form": "いろいろだ", "label": "活用"}, {"form": "いろいろです", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | たくさんのちがう種類があること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "いろいろな", "is_correct": true, "explanation": "たくさんの違う種類の魚という意味で自然に合う。"}, {"text": "ひまな", "is_correct": false, "explanation": "形は合うが、魚がひまという意味が合わない。"}, {"text": "ふべんな", "is_correct": false, "explanation": "形は合うが、魚が不便という意味が合わない。"}, {"text": "ていねいな", "is_correct": false, "explanation": "形は合うが、魚がていねいという意味が合わない。"}], "explanations": {"いろいろな": "たくさんの違う種類の魚という意味で自然に合う。", "ひまな": "形は合うが、魚がひまという意味が合わない。", "ふべんな": "形は合うが、魚が不便という意味が合わない。", "ていねいな": "形は合うが、魚がていねいという意味が合わない。"}, "sentence_index": 0, "correct_answer": "いろいろな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町にはお店がいろいろ一つだけあります。", "explanation": "いろいろは多くの種類を表すので、「一つだけ」と矛盾する。"}, {"text": "私の家族はいろいろ一人です。", "explanation": "いろいろは種類が多いことを表すので、「一人」と使えない。"}, {"text": "今日はいろいろ寒いので、上着を着た。", "explanation": "いろいろは程度を強める言葉ではないので、「寒い」を修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "いろいろ", "is_correct": true, "explanation": "本屋でさまざまな本を見たという意味で自然に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "形は合うが、ぐっすりは眠る様子で「見る」と意味が合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "形は合うが、本屋で見る様子として意味が合わない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "形は合うが、柔らかい様子で「見る」と意味が合わない。"}], "explanations": {"いろいろ": "本屋でさまざまな本を見たという意味で自然に合う。", "ぐっすり": "形は合うが、ぐっすりは眠る様子で「見る」と意味が合わない。", "ぴったり": "形は合うが、本屋で見る様子として意味が合わない。", "ふわふわ": "形は合うが、柔らかい様子で「見る」と意味が合わない。"}, "sentence_index": 6, "correct_answer": "いろいろ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は色々と、同じことだけを教えてくれた。", "explanation": "色々とは違う種類のことを表すので、「同じことだけ」と矛盾する。"}, {"text": "先生は色々と暑くて、汗をかいていた。", "explanation": "色々とは程度を強める言葉ではないので、「暑い」を修飾できない。"}, {"text": "この教室の先生は色々と一人しかいない。", "explanation": "色々とは種類が多いことを表すので、「一人しかいない」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園にいろいろに鳥がいます。", "corrected_sentence": "公園にいろいろな鳥がいます。", "error_description": "名詞「鳥」を修飾するときは、「いろいろに」ではなく「いろいろな」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "いろいろです", "is_correct": true, "explanation": "「服の色は」を受けて、丁寧に言い切る形になる。"}, {"text": "いろいろな", "is_correct": false, "explanation": "名詞を修飾する形で、文末では使えない。"}, {"text": "いろいろに", "is_correct": false, "explanation": "動詞を修飾する形で、文末では使えない。"}, {"text": "いろいろで", "is_correct": false, "explanation": "文をつなぐ形で、ここで終わるのは不自然。"}], "correct_form": "いろいろです", "base_form": "いろいろ", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"いろいろです": "「服の色は」を受けて、丁寧に言い切る形になる。", "いろいろな": "名詞を修飾する形で、文末では使えない。", "いろいろに": "動詞を修飾する形で、文末では使えない。", "いろいろで": "文をつなぐ形で、ここで終わるのは不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は色々なと教えてくれた。", "corrected_sentence": "先生は色々と教えてくれた。", "error_description": "動詞を修飾する「色々と」に「な」は付けられないので、「色々と」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "いろいろだ", "is_correct": true, "explanation": "「好きなものは」を受けて、言い切る形になる。"}, {"text": "いろいろな", "is_correct": false, "explanation": "名詞を修飾する形で、文末では使えない。"}, {"text": "いろいろと", "is_correct": false, "explanation": "動詞を修飾する形で、文末では使えない。"}, {"text": "いろいろの", "is_correct": false, "explanation": "名詞を修飾する形で、文末では使えない。"}], "correct_form": "いろいろだ", "base_form": "いろいろ", "form_label": "終止形", "sentence_index": 7, "explanations": {"いろいろだ": "「好きなものは」を受けて、言い切る形になる。", "いろいろな": "名詞を修飾する形で、文末では使えない。", "いろいろと": "動詞を修飾する形で、文末では使えない。", "いろいろの": "名詞を修飾する形で、文末では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "単一", "is_correct": true, "explanation": "種類がひとつだけで、いろいろの反対を表す。"}, {"text": "様々", "is_correct": false, "explanation": "いろいろと同じ意味で、反対ではない。"}, {"text": "多様", "is_correct": false, "explanation": "種類が多いことを表し、いろいろに近い。"}, {"text": "たくさん", "is_correct": false, "explanation": "数が多いことで、種類がひとつという反対の意味ではない。"}], "correct_answer": "単一", "explanations": {"単一": "種類がひとつだけで、いろいろの反対を表す。", "様々": "いろいろと同じ意味で、反対ではない。", "多様": "種類が多いことを表し、いろいろに近い。", "たくさん": "数が多いことで、種類がひとつという反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同じ", "is_correct": true, "explanation": "みな同じということで、人によっていろいろの反対を表す。"}, {"text": "様々", "is_correct": false, "explanation": "いろいろと同じ意味で、反対ではない。"}, {"text": "豊富", "is_correct": false, "explanation": "量や種類が多いことで、反対の意味ではない。"}, {"text": "複雑", "is_correct": false, "explanation": "しくみが入り組んでいることで、いろいろの反対ではない。"}], "correct_answer": "同じ", "explanations": {"同じ": "みな同じということで、人によっていろいろの反対を表す。", "様々": "いろいろと同じ意味で、反対ではない。", "豊富": "量や種類が多いことで、反対の意味ではない。", "複雑": "しくみが入り組んでいることで、いろいろの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "さまざまな種類や状態があること。", "primary_collocate": null, "pronunciation": "いろいろ", "ipa": "iroiro", "syllable_count": 4, "sentences": [{"text": "あたらしいロボットは、おうちでいろいろなてつだいをします。", "target_word": "いろいろな", "complexity_tier": "T4", "furigana": "あたらしいロボットは、おうちでいろいろなてつだいをします。", "sentence_source": "mined"}, {"text": "いろいろな本がある。", "target_word": "いろいろな", "complexity_tier": "T1", "furigana": "いろいろな本[ほん]がある。", "sentence_source": "generated"}, {"text": "公園でいろいろな花を見ました。", "target_word": "いろいろな", "complexity_tier": "T2", "furigana": "公園[こうえん]でいろいろな花[はな]を見[み]ました。", "sentence_source": "generated"}, {"text": "店にはいろいろ売っています。", "target_word": "いろいろ", "complexity_tier": "T3", "furigana": "店[みせ]にはいろいろ売[う]っています。", "sentence_source": "generated"}, {"text": "友だちといろいろ話して、楽しかった。", "target_word": "いろいろ", "complexity_tier": "T3", "furigana": "友[とも]だちといろいろ話[はな]して、楽[たの]しかった。", "sentence_source": "generated"}, {"text": "週末はいろいろと忙しかった。", "target_word": "いろいろと", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]はいろいろと忙[いそが]しかった。", "sentence_source": "generated"}, {"text": "道がいろいろあって、迷ってしまった。", "target_word": "いろいろ", "complexity_tier": "T3", "furigana": "道[みち]がいろいろあって、迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "人にはいろいろな考え方があるから、よく聞くことが大切だ。", "target_word": "いろいろな", "complexity_tier": "T4", "furigana": "人[ひと]にはいろいろな考[かんが]え方[かた]があるから、よく聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "旅行の前にいろいろ調べたおかげで、予定どおりに楽しむことができた。", "target_word": "いろいろ", "complexity_tier": "T5", "furigana": "旅行[りょこう]の前[まえ]にいろいろ調[しら]べたおかげで、予定[よてい]どおりに楽[たの]しむことができた。", "sentence_source": "generated"}, {"text": "好きな食べ物は人によっていろいろだ。", "target_word": "いろいろだ", "complexity_tier": "T3", "furigana": "好[す]きな食[た]べ物[もの]は人[ひと]によっていろいろだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "いろいろな", "label": "活用"}, {"form": "いろいろに", "label": "活用"}, {"form": "いろいろだ", "label": "活用"}, {"form": "いろいろです", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | さまざまな種類や状態があること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "いろいろな", "is_correct": true, "explanation": "さまざまな種類のお手伝いという意味で自然に合う。"}, {"text": "ひまな", "is_correct": false, "explanation": "形は合うが、手伝いを修飾する意味が合わない。"}, {"text": "ゆうめいな", "is_correct": false, "explanation": "形は合うが、手伝いが有名という意味が合わない。"}, {"text": "ざんねんな", "is_correct": false, "explanation": "形は合うが、手伝いが残念という意味が合わない。"}], "explanations": {"いろいろな": "さまざまな種類のお手伝いという意味で自然に合う。", "ひまな": "形は合うが、手伝いを修飾する意味が合わない。", "ゆうめいな": "形は合うが、手伝いが有名という意味が合わない。", "ざんねんな": "形は合うが、手伝いが残念という意味が合わない。"}, "sentence_index": 0, "correct_answer": "いろいろな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は店でいろいろ、りんごを一つだけ買った。", "explanation": "いろいろは多くの種類を表すので、「一つだけ」と矛盾する。"}, {"text": "毎日、いろいろ同じものばかり食べている。", "explanation": "いろいろは違う種類があることを表すので、「同じもの」と矛盾する。"}, {"text": "今日はいろいろ暑いので、水をたくさん飲んだ。", "explanation": "いろいろは程度を強める言葉ではないので、「暑い」を修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "いろいろ", "is_correct": true, "explanation": "道がさまざまにあるという意味で、迷った理由にもなる。"}, {"text": "しっかり", "is_correct": false, "explanation": "形は合うが、道がしっかりあるでは意味が合わない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "形は合うが、道があることの様子として意味が合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "形は合うが、道がぴったりあるでは意味が合わない。"}], "explanations": {"いろいろ": "道がさまざまにあるという意味で、迷った理由にもなる。", "しっかり": "形は合うが、道がしっかりあるでは意味が合わない。", "ゆっくり": "形は合うが、道があることの様子として意味が合わない。", "ぴったり": "形は合うが、道がぴったりあるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "いろいろ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の中身はいろいろだから、一つしか入っていない。", "explanation": "いろいろは種類が多いことを表すので、「一つしか」と矛盾する。"}, {"text": "先週の天気はいろいろで、毎日まったく同じ晴れだった。", "explanation": "いろいろは違う種類があることを表すので、「同じ晴れ」と矛盾する。"}, {"text": "私はいろいろな一冊の本を読んだ。", "explanation": "いろいろは種類が多いことを表すので、「一冊の本」と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "図書館にいろいろに本があります。", "corrected_sentence": "図書館にいろいろな本があります。", "error_description": "名詞「本」を修飾するときは、「いろいろに」ではなく「いろいろな」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "いろいろな", "is_correct": true, "explanation": "名詞「本」を修飾する形で、ここに合う。"}, {"text": "いろいろに", "is_correct": false, "explanation": "「に」は動詞を修飾する形で、名詞の前では使えない。"}, {"text": "いろいろだ", "is_correct": false, "explanation": "言い切りの形で、名詞の前では使えない。"}, {"text": "いろいろです", "is_correct": false, "explanation": "丁寧な言い切りの形で、名詞の前では使えない。"}], "correct_form": "いろいろな", "base_form": "いろいろ", "form_label": "連体形", "sentence_index": 1, "explanations": {"いろいろな": "名詞「本」を修飾する形で、ここに合う。", "いろいろに": "「に」は動詞を修飾する形で、名詞の前では使えない。", "いろいろだ": "言い切りの形で、名詞の前では使えない。", "いろいろです": "丁寧な言い切りの形で、名詞の前では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35873, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行の前にいろいろな調べたおかげで、予定どおりに楽しむことができた。", "corrected_sentence": "旅行の前にいろいろ調べたおかげで、予定どおりに楽しむことができた。", "error_description": "動詞「調べる」を修飾するときは、「いろいろな」ではなく副詞の「いろいろ」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "いろいろな", "is_correct": true, "explanation": "名詞「考え方」を修飾する形で、ここに合う。"}, {"text": "いろいろで", "is_correct": false, "explanation": "「で」は文をつなぐ形で、名詞の前では使えない。"}, {"text": "いろいろと", "is_correct": false, "explanation": "「と」は動詞を修飾する形で、名詞の前では使えない。"}, {"text": "いろいろだろう", "is_correct": false, "explanation": "推量の形で、名詞の前では使えない。"}], "correct_form": "いろいろな", "base_form": "いろいろ", "form_label": "連体形", "sentence_index": 7, "explanations": {"いろいろな": "名詞「考え方」を修飾する形で、ここに合う。", "いろいろで": "「で」は文をつなぐ形で、名詞の前では使えない。", "いろいろと": "「と」は動詞を修飾する形で、名詞の前では使えない。", "いろいろだろう": "推量の形で、名詞の前では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
