INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35878, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みみに はいって わかる。", "primary_collocate": null, "pronunciation": "きこえる", "ipa": "kikoeɾɯ", "syllable_count": 4, "sentences": [{"text": "隣の部屋から、子どもの声が聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "隣(となり)の部屋(へや)から、子(こ)どもの声(こえ)が聞(き)こえる。", "sentence_source": "generated"}, {"text": "後ろの席だと、先生の声がよく聞こえない。", "target_word": "聞こえない", "complexity_tier": "T3", "furigana": "後(うし)ろの席(せき)だと、先生(せんせい)の声(こえ)がよく聞(き)こえない。", "sentence_source": "generated"}, {"text": "電話の向こうで、母の笑う声が聞こえた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "電話(でんわ)の向(む)こうで、母(はは)の笑(わら)う声(こえ)が聞(き)こえた。", "sentence_source": "generated"}, {"text": "もう少し大きな声で話して。よく聞こえないよ。", "target_word": "聞こえない", "complexity_tier": "T3", "furigana": "もう少(すこ)し大(おお)きな声(こえ)で話(はな)して。よく聞(き)こえないよ。", "sentence_source": "generated"}, {"text": "夜になると、隣の人の話し声が聞こえてくる。", "target_word": "聞こえてくる", "complexity_tier": "T3", "furigana": "夜(よる)になると、隣(となり)の人(ひと)の話(はな)し声(ごえ)が聞(き)こえてくる。", "sentence_source": "generated"}, {"text": "遠くから、友だちが呼ぶ声が聞こえた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "遠(とお)くから、友(とも)だちが呼(よ)ぶ声(こえ)が聞(き)こえた。", "sentence_source": "generated"}, {"text": "壁が薄いので、となりの人の話し声が聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "壁(かべ)が薄(うす)いので、となりの人(ひと)の話(はな)し声(ごえ)が聞(き)こえる。", "sentence_source": "generated"}, {"text": "誰かが私の名前を呼ぶのが聞こえた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "誰(だれ)かが私(わたし)の名前(なまえ)を呼(よ)ぶのが聞(き)こえた。", "sentence_source": "generated"}, {"text": "マスクをしていると、相手の声が聞こえない。", "target_word": "聞こえない", "complexity_tier": "T3", "furigana": "マスクをしていると、相手(あいて)の声(こえ)が聞(き)こえない。", "sentence_source": "generated"}, {"text": "教室の外から、歌う声が聞こえて、みんな窓を見た。", "target_word": "聞こえて", "complexity_tier": "T3", "furigana": "教室(きょうしつ)の外(そと)から、歌(うた)う声(こえ)が聞(き)こえて、みんな窓(まど)を見(み)た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞こえる", "label": "終止形"}, {"form": "聞こえない", "label": "否定形"}, {"form": "聞こえた", "label": "過去形"}, {"form": "聞こえて", "label": "て形"}], "register": "標準（普通体）", "sense_fingerprint": "聞こえる（自動詞）：人の声や話し声が自然に耳に入って分かる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞こえる", "is_correct": true, "explanation": "声が耳に自然に入ってくることを表す。「子どもの声が聞こえる」が成り立つ。"}, {"text": "見える", "is_correct": false, "explanation": "視覚で捉える動詞で、声を主語にして「見える」とは言えない。"}, {"text": "聞く", "is_correct": false, "explanation": "意識して耳を傾ける動詞で、声を主語にすると「声を聞く」の形にならず文が成り立たない。"}, {"text": "光る", "is_correct": false, "explanation": "光を放つ動詞で、声には使えないので文に合わない。"}], "explanations": {"聞こえる": "声が耳に自然に入ってくることを表す。「子どもの声が聞こえる」が成り立つ。", "見える": "視覚で捉える動詞で、声を主語にして「見える」とは言えない。", "聞く": "意識して耳を傾ける動詞で、声を主語にすると「声を聞く」の形にならず文が成り立たない。", "光る": "光を放つ動詞で、声には使えないので文に合わない。"}, "sentence_index": 0, "correct_answer": "聞こえる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは、塩がよく聞こえて、とてもおいしい。", "explanation": "ここは〈味がする〉の意味との混同。聞こえるは音が耳に届く意味で、塩の味は舌で感じるものなので合わない。"}, {"text": "この本の文字が、遠くてよく聞こえない。", "explanation": "ここは〈読める〉の意味との混同。聞こえるは音が耳に届く意味で、文字は目で読むものなので合わない。"}, {"text": "窓の向こうに、白い富士山が聞こえた。", "explanation": "ここは〈見える〉との混同。山は目で見るもので、耳に届くものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞こえる", "is_correct": true, "explanation": "音が耳に届くことを表す。「テレビの音が聞こえる」が成り立つ。"}, {"text": "感じる", "is_correct": false, "explanation": "肌や心で受け取る動詞。音を主語にすると「音を感じる」の形が必要になり、文が成り立たない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動詞で、音には使わないので文に合わない。"}, {"text": "測る", "is_correct": false, "explanation": "長さや大きさを量る動詞で、音が測るという文は成り立たない。"}], "explanations": {"聞こえる": "音が耳に届くことを表す。「テレビの音が聞こえる」が成り立つ。", "感じる": "肌や心で受け取る動詞。音を主語にすると「音を感じる」の形が必要になり、文が成り立たない。", "運ぶ": "物を移動させる動詞で、音には使わないので文に合わない。", "測る": "長さや大きさを量る動詞で、音が測るという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "聞こえる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から冷たい風が聞こえた。", "explanation": "ここは〈感じる〉との混同。冷たい風は肌で感じるもので、耳に届く音ではないので合わない。"}, {"text": "窓から焼き魚の香りが聞こえた。", "explanation": "ここは〈匂う〉との混同。香りは鼻で捉えるもので、聞こえるは音に限るので合わない。"}, {"text": "注文した荷物が、明日ようやく聞こえる予定だ。", "explanation": "ここは〈届く〉の意味との混同。聞こえるは音が耳に入る意味で、荷物が手元に着くことには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外から、友だちの声を聞こえる。", "corrected_sentence": "窓の外から、友だちの声が聞こえる。", "error_description": "助詞の誤り。「聞こえる」は自動詞なので、声は「が」で示す。「を」は誤り。正しくは「友だちの声が聞こえる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "聞こえない", "is_correct": true, "explanation": "否定形で、後ろの席では先生の声が届かないという文脈に合う。"}, {"text": "聞こえる", "is_correct": false, "explanation": "肯定の終止形。「後ろの席だと〜よく聞こえる」では文の意味が逆になる。"}, {"text": "聞こえて", "is_correct": false, "explanation": "て形で、文を終えることができない。"}, {"text": "聞こえなく", "is_correct": false, "explanation": "否定の連用形で、文末には置けない。"}], "correct_form": "聞こえない", "base_form": "聞こえる", "form_label": "否定形", "sentence_index": 1, "explanations": {"聞こえない": "否定形で、後ろの席では先生の声が届かないという文脈に合う。", "聞こえる": "肯定の終止形。「後ろの席だと〜よく聞こえる」では文の意味が逆になる。", "聞こえて": "て形で、文を終えることができない。", "聞こえなく": "否定の連用形で、文末には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "さっき、廊下で弟が泣く声が聞こえる。", "corrected_sentence": "さっき、廊下で弟が泣く声が聞こえた。", "error_description": "活用の誤り。「さっき」は過去の出来事なので過去形の「聞こえた」が正しい。現在形の「聞こえる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "聞こえた", "is_correct": true, "explanation": "過去形で、「誰かが名前を呼ぶのが聞こえた」という出来事の文脈に合う。"}, {"text": "聞こえない", "is_correct": false, "explanation": "否定形。名前を呼ぶ声が聞こえなかったという意味になり、文脈と逆になる。"}, {"text": "聞こえず", "is_correct": false, "explanation": "否定の連用形で、文末に置けず、この文は続かない。"}, {"text": "聞こえなかった", "is_correct": false, "explanation": "否定の過去形。声が聞こえなかったという意味になり、文脈と逆になる。"}], "correct_form": "聞こえた", "base_form": "聞こえる", "form_label": "過去形", "sentence_index": 7, "explanations": {"聞こえた": "過去形で、「誰かが名前を呼ぶのが聞こえた」という出来事の文脈に合う。", "聞こえない": "否定形。名前を呼ぶ声が聞こえなかったという意味になり、文脈と逆になる。", "聞こえず": "否定の連用形で、文末に置けず、この文は続かない。", "聞こえなかった": "否定の過去形。声が聞こえなかったという意味になり、文脈と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
