INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35879, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "音が耳に届いて、何であるかと分かる。", "primary_collocate": null, "pronunciation": "きこえる", "ipa": "kikoeɾɯ", "syllable_count": 4, "sentences": [{"text": "遠くから、電車が走る音が聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "遠(とお)くから、電車(でんしゃ)が走(はし)る音(おと)が聞(き)こえる。", "sentence_source": "generated"}, {"text": "朝になると、鳥の鳴き声が聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "朝(あさ)になると、鳥(とり)の鳴(な)き声(ごえ)が聞(き)こえる。", "sentence_source": "generated"}, {"text": "夜、雨が屋根をたたく音が聞こえた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "夜(よる)、雨(あめ)が屋根(やね)をたたく音(おと)が聞(き)こえた。", "sentence_source": "generated"}, {"text": "海の近くの家では、波の音が一日中聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "海(うみ)の近(ちか)くの家(いえ)では、波(なみ)の音(おと)が一日中(いちにちじゅう)聞(き)こえる。", "sentence_source": "generated"}, {"text": "静かな夜は、時計の音が大きく聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "静(しず)かな夜(よる)は、時計(とけい)の音(おと)が大(おお)きく聞(き)こえる。", "sentence_source": "generated"}, {"text": "山の中の寺から、鐘の音が聞こえてきた。", "target_word": "聞こえてきた", "complexity_tier": "T3", "furigana": "山(やま)の中(なか)の寺(てら)から、鐘(かね)の音(おと)が聞(き)こえてきた。", "sentence_source": "generated"}, {"text": "台所から、野菜を切る音が聞こえる。", "target_word": "聞こえる", "complexity_tier": "T3", "furigana": "台所(だいどころ)から、野菜(やさい)を切(き)る音(おと)が聞(き)こえる。", "sentence_source": "generated"}, {"text": "外で救急車のサイレンが聞こえたので、窓を開けた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "外(そと)で救急車(きゅうきゅうしゃ)のサイレンが聞(き)こえたので、窓(まど)を開(あ)けた。", "sentence_source": "generated"}, {"text": "川のそばを歩くと、水の流れる音が聞こえた。", "target_word": "聞こえた", "complexity_tier": "T3", "furigana": "川(かわ)のそばを歩(ある)くと、水(みず)の流(なが)れる音(おと)が聞(き)こえた。", "sentence_source": "generated"}, {"text": "二階から、ピアノの音が聞こえてきた。", "target_word": "聞こえてきた", "complexity_tier": "T3", "furigana": "二階(にかい)から、ピアノの音(おと)が聞(き)こえてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞こえる", "label": "終止形"}, {"form": "聞こえない", "label": "否定形"}, {"form": "聞こえた", "label": "過去形"}, {"form": "聞こえてきた", "label": "て形+きた"}], "register": "標準（普通体）", "sense_fingerprint": "聞こえる（自動詞）：物音・鳴き声などの音が耳に届き、何の音か分かる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35879, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞こえる", "is_correct": true, "explanation": "音が耳に届くことを表す。「電車が走る音が聞こえる」が成り立つ。"}, {"text": "見える", "is_correct": false, "explanation": "視覚で捉える動詞で、音を主語にして「見える」とは言えない。"}, {"text": "聞く", "is_correct": false, "explanation": "意識して耳を傾ける動詞で、音を主語にすると文が成り立たない。"}, {"text": "光る", "is_correct": false, "explanation": "光を放つ動詞で、音には使えないので文に合わない。"}], "explanations": {"聞こえる": "音が耳に届くことを表す。「電車が走る音が聞こえる」が成り立つ。", "見える": "視覚で捉える動詞で、音を主語にして「見える」とは言えない。", "聞く": "意識して耳を傾ける動詞で、音を主語にすると文が成り立たない。", "光る": "光を放つ動詞で、音には使えないので文に合わない。"}, "sentence_index": 0, "correct_answer": "聞こえる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この味噌汁は、だしがよく聞こえて、とてもおいしい。", "explanation": "ここは〈味がする〉の意味との混同。聞こえるは音が耳に届く意味で、だしの味は舌で感じるものなので合わない。"}, {"text": "窓から遠くの山が聞こえる。", "explanation": "ここは〈見える〉との混同。山は目で見るもので、音を聞く動詞とは合わない。"}, {"text": "窓から焼き魚の香りが聞こえる。", "explanation": "ここは〈匂う〉との混同。香りは鼻で捉えるもので、聞こえるは音に限るので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35879, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞こえる", "is_correct": true, "explanation": "音が耳に届くことを表す。「野菜を切る音が聞こえる」が成り立つ。"}, {"text": "感じる", "is_correct": false, "explanation": "肌や心で受け取る動詞。音を主語にすると「音を感じる」の形が必要になり、文が成り立たない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動詞で、音には使わないので文に合わない。"}, {"text": "測る", "is_correct": false, "explanation": "長さや大きさを量る動詞で、音が測るという文は成り立たない。"}], "explanations": {"聞こえる": "音が耳に届くことを表す。「野菜を切る音が聞こえる」が成り立つ。", "感じる": "肌や心で受け取る動詞。音を主語にすると「音を感じる」の形が必要になり、文が成り立たない。", "運ぶ": "物を移動させる動詞で、音には使わないので文に合わない。", "測る": "長さや大きさを量る動詞で、音が測るという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "聞こえる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日届く予定の手紙が、ようやく聞こえてきた。", "explanation": "ここは〈届く〉の意味との混同。聞こえるは音が耳に入る意味で、手紙が手元に着くことには使わないので合わない。"}, {"text": "窓から冷たい風が聞こえてきた。", "explanation": "ここは〈感じる〉との混同。冷たい風は肌で感じるもので、耳に届く音ではないので合わない。"}, {"text": "窓から海の景色が聞こえてきた。", "explanation": "ここは〈眺める〉との混同。景色は目で見るもので、音を聞く動詞とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隣の家から、犬の鳴き声を聞こえる。", "corrected_sentence": "隣の家から、犬の鳴き声が聞こえる。", "error_description": "助詞の誤り。音の主語は「が」で示す。「を」を使うと文が成り立たない。正しくは「犬の鳴き声が聞こえる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "聞こえる", "is_correct": true, "explanation": "終止形で、「朝になると鳥の鳴き声が聞こえる」という習慣的な文脈に合う。"}, {"text": "聞こえたら", "is_correct": false, "explanation": "条件形で、文を言い切れないため、この文は完成しない。"}, {"text": "聞こえて", "is_correct": false, "explanation": "て形で、文を終えることができない。"}, {"text": "聞こえなく", "is_correct": false, "explanation": "否定の連用形で、文末には置けない。"}], "correct_form": "聞こえる", "base_form": "聞こえる", "form_label": "終止形", "sentence_index": 1, "explanations": {"聞こえる": "終止形で、「朝になると鳥の鳴き声が聞こえる」という習慣的な文脈に合う。", "聞こえたら": "条件形で、文を言い切れないため、この文は完成しない。", "聞こえて": "て形で、文を終えることができない。", "聞こえなく": "否定の連用形で、文末には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35879, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の夜、遠くの雷の音が聞こえる。", "corrected_sentence": "昨日の夜、遠くの雷の音が聞こえた。", "error_description": "活用の誤り。「昨日の夜」は過去の出来事なので過去形の「聞こえた」が正しい。現在形の「聞こえる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "聞こえた", "is_correct": true, "explanation": "過去形で、救急車の音が耳に届いたという出来事の文脈に合う。"}, {"text": "聞こえよう", "is_correct": false, "explanation": "意志形で、過去の出来事を述べる文脈と合わず、「ので」にも続かない。"}, {"text": "聞こえず", "is_correct": false, "explanation": "否定の連用形で、「ので」に続けると文が成り立たない。"}, {"text": "聞こえない", "is_correct": false, "explanation": "否定形。サイレンが聞こえなかったという意味になり、窓を開けた理由と逆になる。"}], "correct_form": "聞こえた", "base_form": "聞こえる", "form_label": "過去形", "sentence_index": 7, "explanations": {"聞こえた": "過去形で、救急車の音が耳に届いたという出来事の文脈に合う。", "聞こえよう": "意志形で、過去の出来事を述べる文脈と合わず、「ので」にも続かない。", "聞こえず": "否定の連用形で、「ので」に続けると文が成り立たない。", "聞こえない": "否定形。サイレンが聞こえなかったという意味になり、窓を開けた理由と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「今」を主題として示し、「今は一人一人の体に合う薬です」と対比や話題を提示する。"}, {"text": "を", "is_correct": false, "explanation": "「今を一人一人の体に合う薬です」は目的語の「を」では文が成り立たない。今は動作の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「今で一人一人の体に合う薬です」は場所・手段の「で」で、文の成分が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「今へ一人一人の体に合う薬です」は方向の「へ」で、今は方向を表さないので成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「今」を主題として示し、「今は一人一人の体に合う薬です」と対比や話題を提示する。", "を": "「今を一人一人の体に合う薬です」は目的語の「を」では文が成り立たない。今は動作の対象にならない。", "で": "「今で一人一人の体に合う薬です」は場所・手段の「で」で、文の成分が合わない。", "へ": "「今へ一人一人の体に合う薬です」は方向の「へ」で、今は方向を表さないので成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話している時点を指します。現在の時間。", "primary_collocate": null, "pronunciation": "いま", "ipa": "ima", "syllable_count": 2, "sentences": [{"text": "病院での薬の選び方は、昔と今で違います。", "target_word": "今", "complexity_tier": "T3", "furigana": "病院(びょういん)での薬(くすり)の選(えら)び方(かた)は、昔(むかし)と今(いま)で違(ちが)います。", "sentence_source": "mined"}, {"text": "今は一人一人の体に合う薬です。", "target_word": "今", "complexity_tier": "T3", "furigana": "今(いま)は一人一人(ひとりひとり)の体(からだ)に合(あ)う薬(くすり)です。", "sentence_source": "mined"}, {"text": "昔は手紙が多かったですが、今はメールで連絡します。", "target_word": "今", "complexity_tier": "T3", "furigana": "昔(むかし)は手紙(てがみ)が多(おお)かったですが、今(いま)はメールで連絡(れんらく)します。", "sentence_source": "generated"}, {"text": "今、母は台所で夕飯を作っています。", "target_word": "今", "complexity_tier": "T3", "furigana": "今(いま)、母(はは)は台所(だいどころ)で夕飯(ゆうはん)を作(つく)っています。", "sentence_source": "generated"}, {"text": "さっきまで雨でしたが、今は空が明るくなりました。", "target_word": "今", "complexity_tier": "T3", "furigana": "さっきまで雨(あめ)でしたが、今(いま)は空(そら)が明(あか)るくなりました。", "sentence_source": "generated"}, {"text": "私は去年まで東京に住んでいましたが、今は大阪に住んでいます。", "target_word": "今", "complexity_tier": "T3", "furigana": "私(わたし)は去年(きょねん)まで東京(とうきょう)に住(す)んでいましたが、今(いま)は大阪(おおさか)に住(す)んでいます。", "sentence_source": "generated"}, {"text": "今から出かけても、電車に間に合いません。", "target_word": "今", "complexity_tier": "T3", "furigana": "今(いま)から出(で)かけても、電車(でんしゃ)に間(ま)に合(あ)いません。", "sentence_source": "generated"}, {"text": "子どものころは野菜が嫌いでしたが、今は大好きです。", "target_word": "今", "complexity_tier": "T3", "furigana": "子(こ)どものころは野菜(やさい)が嫌(きら)いでしたが、今(いま)は大好(だいす)きです。", "sentence_source": "generated"}, {"text": "すみません、今は電話に出られないので、あとでかけ直します。", "target_word": "今", "complexity_tier": "T3", "furigana": "すみません、今(いま)は電話(でんわ)に出(で)られないので、あとでかけ直(なお)します。", "sentence_source": "generated"}, {"text": "先週は忙しかったですが、今は少し時間があります。", "target_word": "今", "complexity_tier": "T3", "furigana": "先週(せんしゅう)は忙(いそが)しかったですが、今(いま)は少(すこ)し時間(じかん)があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "今", "label": "基本形"}], "register": "polite", "sense_fingerprint": "話している現在の時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今", "is_correct": true, "explanation": "「昔と今」で現在の時点を表す語。ここに入るのは「今」だけ。"}, {"text": "体", "is_correct": false, "explanation": "「昔と体で違います」は意味が通らない。体は身体を指し、時点の対比には使えない。"}, {"text": "雨", "is_correct": false, "explanation": "「昔と雨で違います」は成立しない。雨は天気を表し、時の対比の相手にはならない。"}, {"text": "医者", "is_correct": false, "explanation": "「昔と医者で違います」は文として成り立たない。医者は人を指し、時点を表さない。"}], "explanations": {"今": "「昔と今」で現在の時点を表す語。ここに入るのは「今」だけ。", "体": "「昔と体で違います」は意味が通らない。体は身体を指し、時点の対比には使えない。", "雨": "「昔と雨で違います」は成立しない。雨は天気を表し、時の対比の相手にはならない。", "医者": "「昔と医者で違います」は文として成り立たない。医者は人を指し、時点を表さない。"}, "sentence_index": 0, "correct_answer": "今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今、三年前に日本へ来ました。", "explanation": "ここは〈今〉の意味。〈今〉を過去の時点の代わりに使っている。過去の時点は〈あの頃〉などで言う。"}, {"text": "今、来年の春に大阪へ引っ越します。", "explanation": "ここは〈今〉の意味。〈今〉を未来の時点の代わりに使っている。未来の時点は〈そのうち〉などで言う。"}, {"text": "私は今ずっと、彼の返事を待っていました。", "explanation": "ここは〈今〉の意味。〈今〉は一点の時間なので、期間の意味で使うのは誤り。期間は〈今まで〉などで言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今", "is_correct": true, "explanation": "「今から出かけても」の「今」。現在の時点から出発する意味になり、文が成り立つ。"}, {"text": "薬", "is_correct": false, "explanation": "「薬から出かけても」は意味が通らない。薬は出発点になる場所や時点ではない。"}, {"text": "電話", "is_correct": false, "explanation": "「電話から出かけても」は成り立たない。電話は時点や場所を表さない。"}, {"text": "名前", "is_correct": false, "explanation": "「名前から出かけても」は不自然で、出発の起点にならない。"}], "explanations": {"今": "「今から出かけても」の「今」。現在の時点から出発する意味になり、文が成り立つ。", "薬": "「薬から出かけても」は意味が通らない。薬は出発点になる場所や時点ではない。", "電話": "「電話から出かけても」は成り立たない。電話は時点や場所を表さない。", "名前": "「名前から出かけても」は不自然で、出発の起点にならない。"}, "sentence_index": 6, "correct_answer": "今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の夜、今すぐ電話をしました。", "explanation": "ここは〈今〉の意味。〈今〉を〈直ちに〉の意味で使い、過去の出来事に合わせている。〈直ちに〉の意味では過去の出来事とは合わない。"}, {"text": "昨日の朝、今、電車に乗りました。", "explanation": "ここは〈今〉の意味。過去の出来事を述べる文に〈今〉は使えない。その時点は〈その時〉などで言う。"}, {"text": "先週は忙しかったですが、今ずっと時間があります。", "explanation": "ここは〈今〉の意味。〈今〉は一点の時間なので、継続の意味で使うのは誤り。継続は〈引き続き〉などで言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は昔、畑で働いていましたが、今で町に住んでいます。", "corrected_sentence": "祖母は昔、畑で働いていましたが、今は町に住んでいます。", "error_description": "「今は」の「は」が「で」になっている。「今で」は場所・手段を表す「で」なので、昔と今を対比する主題が示せない。正しくは「今は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35881, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今へ出かけますので、少し待ってください。", "corrected_sentence": "今から出かけますので、少し待ってください。", "error_description": "「今から」の「から」が「へ」になっている。「今へ出かける」は方向の「へ」が合わず、起点を表す「から」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生活を記録して」の『を』で、記録する対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「生活が」と主語にすると、記録の対象がなくなり、「記録して、本にした」が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、記録する対象は示せず文意が合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す『で』で、「生活で記録して」では記録する対象を示せず文意が合わない。"}], "correct_answer": "を", "explanations": {"を": "「生活を記録して」の『を』で、記録する対象を示す。", "が": "「生活が」と主語にすると、記録の対象がなくなり、「記録して、本にした」が成り立たない。", "へ": "方向を示す『へ』で、記録する対象は示せず文意が合わない。", "で": "手段を示す『で』で、「生活で記録して」では記録する対象を示せず文意が合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す『が』で、『記録がなくなってしまい』と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す『を』で、なくなる主語の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "場所や時点を示す『に』で、主語を表す位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す『と』で、主語の役割にはならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す『が』で、『記録がなくなってしまい』と自然に続く。", "を": "動作の対象を示す『を』で、なくなる主語の位置には入らない。", "に": "場所や時点を示す『に』で、主語を表す位置には合わない。", "と": "相手や並列を示す『と』で、主語の役割にはならない。"}, "error_tags": {"を": "目的語", "に": "場所", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "むかしのことを かくこと。", "primary_collocate": null, "pronunciation": "きろく", "ipa": "kiɾokɯ", "syllable_count": 3, "sentences": [{"text": "昨日の出来事を日記に記録した。", "target_word": "記録", "complexity_tier": "T3", "furigana": "昨日[きのう]の出来事[できごと]を日記[にっき]に記録[きろく]した。", "sentence_source": "generated"}, {"text": "祖父は戦争のころの生活を記録して、本にした。", "target_word": "記録", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争[せんそう]のころの生活[せいかつ]を記録[きろく]して、本[ほん]にした。", "sentence_source": "generated"}, {"text": "会議の内容を、係の人が記録している。", "target_word": "記録", "complexity_tier": "T3", "furigana": "会議[かいぎ]の内容[ないよう]を、係[かかり]の人[ひと]が記録[きろく]している。", "sentence_source": "generated"}, {"text": "古い記録を見ると、百年前の町の様子がわかる。", "target_word": "記録", "complexity_tier": "T3", "furigana": "古[ふる]い記録[きろく]を見[み]ると、百年前[ひゃくねんまえ]の町[まち]の様子[ようす]がわかる。", "sentence_source": "generated"}, {"text": "毎日の天気を記録して、ノートにまとめる。", "target_word": "記録", "complexity_tier": "T3", "furigana": "毎日[まいにち]の天気[てんき]を記録[きろく]して、ノートにまとめる。", "sentence_source": "generated"}, {"text": "この村の歴史は、お寺の記録に残っている。", "target_word": "記録", "complexity_tier": "T3", "furigana": "この村[むら]の歴史[れきし]は、お寺[てら]の記録[きろく]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "旅行の思い出を記録するために、写真を撮った。", "target_word": "記録", "complexity_tier": "T3", "furigana": "旅行[りょこう]の思[おも]い出[で]を記録[きろく]するために、写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "昔の記録がなくなってしまい、調べることができない。", "target_word": "記録", "complexity_tier": "T3", "furigana": "昔[むかし]の記録[きろく]がなくなってしまい、調[しら]べることができない。", "sentence_source": "generated"}, {"text": "先生は生徒の話を記録して、あとで読み返す。", "target_word": "記録", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の話[はなし]を記録[きろく]して、あとで読[よ]み返[かえ]す。", "sentence_source": "generated"}, {"text": "事故の記録を読んで、原因がやっとわかった。", "target_word": "記録", "complexity_tier": "T3", "furigana": "事故[じこ]の記録[きろく]を読[よ]んで、原因[げんいん]がやっとわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "記録", "label": "基本形"}, {"form": "記録する", "label": "する動詞"}, {"form": "記録して", "label": "て形"}, {"form": "記録した", "label": "た形"}, {"form": "記録される", "label": "受身形"}], "register": "中立（普通体）", "sense_fingerprint": "出来事を後に残すために書きとめる、また書きとめたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "記録", "is_correct": true, "explanation": "出来事を書き残す意味で、『日記に記録した』と自然に続く。"}, {"text": "散策", "is_correct": false, "explanation": "あてもなく歩くことで、日記に書く行為とは合わない。"}, {"text": "放棄", "is_correct": false, "explanation": "途中でやめることで、『日記に放棄した』は意味が通らない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除することで、日記の文脈には合わない。"}], "explanations": {"記録": "出来事を書き残す意味で、『日記に記録した』と自然に続く。", "散策": "あてもなく歩くことで、日記に書く行為とは合わない。", "放棄": "途中でやめることで、『日記に放棄した』は意味が通らない。", "清掃": "掃除することで、日記の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "記録"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は、子どものころの記録を大きな声で歌った。", "explanation": "記録は書き残したものを指すので、大きな声で歌う対象にはならない。"}, {"text": "旅行の記録として、お土産を割った。", "explanation": "お土産を割る行為は記録とは結びつかず、文として不自然。"}, {"text": "作文の記録は、とても長かった。", "explanation": "文章の中身は「内容」と言い、記録は書き残した資料を指すので、作文そのものを記録とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "記録", "is_correct": true, "explanation": "思い出を書き残す意味で、『旅行の思い出を記録するために』と自然に続く。"}, {"text": "売買", "is_correct": false, "explanation": "物を売り買いすることで、思い出の文脈には合わない。"}, {"text": "出題", "is_correct": false, "explanation": "問題を出すことで、『思い出を出題する』は意味が通らない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直すことで、思い出の記録とは合わない。"}], "explanations": {"記録": "思い出を書き残す意味で、『旅行の思い出を記録するために』と自然に続く。", "売買": "物を売り買いすることで、思い出の文脈には合わない。", "出題": "問題を出すことで、『思い出を出題する』は意味が通らない。", "修理": "壊れたものを直すことで、思い出の記録とは合わない。"}, "sentence_index": 6, "correct_answer": "記録"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は夢の記録を食べた。", "explanation": "食べ物は食べるものだが、記録は書き残すことを指すので、食べるとは言えない。"}, {"text": "記録の雨が、川を越えて降った。", "explanation": "雨の量の多さは「記録的な雨」と言い、「記録の雨」とは言わない。"}, {"text": "この歌は、記録の声がとても美しい。", "explanation": "声の美しさは記録では表せない。声を残すことは「録音」と言い、記録とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休みの出来事を日記を記録した。", "corrected_sentence": "夏休みの出来事を日記に記録した。", "error_description": "誤り：『を』。正しくは『に』。記録の場所は『に』で表すため、『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35882, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その村では、戦争のころの暮らしを記録ている。", "corrected_sentence": "その村では、戦争のころの暮らしを記録している。", "error_description": "誤り：『記録ている』。正しくは『記録している』。『記録する』はサ変動詞なので、『〜している』の形にするには『する』の活用が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高い", "is_correct": true, "explanation": "音の高さで対になる対義語。"}, {"text": "早い", "is_correct": false, "explanation": "速さの語で、音の高さの対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの語で、音の高さとは対にならない。"}, {"text": "広い", "is_correct": false, "explanation": "広さの語で、音の高さの対義語ではない。"}], "correct_answer": "高い", "explanations": {"高い": "音の高さで対になる対義語。", "早い": "速さの語で、音の高さの対義語ではない。", "軽い": "重さの語で、音の高さとは対にならない。", "広い": "広さの語で、音の高さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
