INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "声や音の高さが普通より下であること。", "primary_collocate": null, "pronunciation": "ひくい", "ipa": "çikɯi", "syllable_count": 3, "sentences": [{"text": "太い弦は、細い弦より音が低い。", "target_word": "低い", "complexity_tier": "T3", "furigana": "太[ふと]い弦[げん]は、細[ほそ]い弦[げん]より音[おと]が低[ひく]い。", "sentence_source": "generated"}, {"text": "彼は声が低いので、電話でもすぐ分かる。", "target_word": "低い", "complexity_tier": "T3", "furigana": "彼[かれ]は声[こえ]が低[ひく]いので、電話[でんわ]でもすぐ分[わ]かる。", "sentence_source": "generated"}, {"text": "この曲は音が低くて、私には歌いやすい。", "target_word": "低く", "complexity_tier": "T3", "furigana": "この曲[きょく]は音[おと]が低[ひく]くて、私[わたし]には歌[うた]いやすい。", "sentence_source": "generated"}, {"text": "男性の声は、女性より低いことが多い。", "target_word": "低い", "complexity_tier": "T3", "furigana": "男性[だんせい]の声[こえ]は、女性[じょせい]より低[ひく]いことが多[おお]い。", "sentence_source": "generated"}, {"text": "チューバはとても低い音を出す楽器だ。", "target_word": "低い", "complexity_tier": "T3", "furigana": "チューバはとても低[ひく]い音[おと]を出[だ]す楽器[がっき]だ。", "sentence_source": "generated"}, {"text": "先生は低い声で、ゆっくり話し始めた。", "target_word": "低い", "complexity_tier": "T3", "furigana": "先生[せんせい]は低[ひく]い声[こえ]で、ゆっくり話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "風邪をひいて、いつもより声が低かった。", "target_word": "低かった", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて、いつもより声[こえ]が低[ひく]かった。", "sentence_source": "generated"}, {"text": "低い音が出ないので、この歌は私には難しい。", "target_word": "低い", "complexity_tier": "T3", "furigana": "低[ひく]い音[おと]が出[で]ないので、この歌[うた]は私[わたし]には難[むずか]しい。", "sentence_source": "generated"}, {"text": "父が低く落ち着いた声で話すと、部屋が静かになった。", "target_word": "低く", "complexity_tier": "T3", "furigana": "父[ちち]が低[ひく]く落[お]ち着[つ]いた声[こえ]で話[はな]すと、部屋[へや]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "低い声で歌うと、高い声のときとは違う雰囲気になる。", "target_word": "低い", "complexity_tier": "T3", "furigana": "低[ひく]い声[こえ]で歌[うた]うと、高[たか]い声[こえ]のときとは違[ちが]う雰囲気[ふんいき]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低い", "label": "終止形・連体形"}, {"form": "低く", "label": "連用形"}, {"form": "低かった", "label": "過去形"}, {"form": "低くない", "label": "否定形"}, {"form": "低ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "声や音の高さが普通より下であるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低い", "is_correct": true, "explanation": "太い弦は細い弦より音の高さが下なので、音が低いと言う。正解。"}, {"text": "早い", "is_correct": false, "explanation": "速さを表す語で、音の高さの比べ方には使わないので合わない。"}, {"text": "暑い", "is_correct": false, "explanation": "温度の語で、音の高さを表す言い方にはならないので合わない。"}, {"text": "狭い", "is_correct": false, "explanation": "広さの語で、音の高さの説明には当てはまらないので合わない。"}], "explanations": {"低い": "太い弦は細い弦より音の高さが下なので、音が低いと言う。正解。", "早い": "速さを表す語で、音の高さの比べ方には使わないので合わない。", "暑い": "温度の語で、音の高さを表す言い方にはならないので合わない。", "狭い": "広さの語で、音の高さの説明には当てはまらないので合わない。"}, "sentence_index": 0, "correct_answer": "低い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事が終わって、帰り道の足取りが低い。", "explanation": "ここは〈軽い〉の意味。足取りが軽いとは言うが、足取りが低いとは言わない。"}, {"text": "雨の量が低いので、畑の水が足りない。", "explanation": "ここは〈少ない〉の意味。量の少なさは少ないで表し、低いとは言わない。"}, {"text": "夜中に何度も目が覚めて、眠りが低い。", "explanation": "ここは〈浅い〉の意味。眠りの浅さは浅いで表し、低いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低かった", "is_correct": true, "explanation": "「いつもより声が低かった」で、風邪による声の低さを表す。"}, {"text": "広かった", "is_correct": false, "explanation": "声の広さは意味が通らず、文が成り立たない。"}, {"text": "速かった", "is_correct": false, "explanation": "声の速さは表さず、文の意味が合わない。"}, {"text": "短かった", "is_correct": false, "explanation": "声の長さは表さず、意味が合わない。"}], "explanations": {"低かった": "「いつもより声が低かった」で、風邪による声の低さを表す。", "広かった": "声の広さは意味が通らず、文が成り立たない。", "速かった": "声の速さは表さず、文の意味が合わない。", "短かった": "声の長さは表さず、意味が合わない。"}, "sentence_index": 6, "correct_answer": "低かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の時間が低かったので、議論が深まらなかった。", "explanation": "ここは〈短い〉の意味。時間の短さは短いで表し、低いとは言わない。"}, {"text": "スープの味が低いので、塩を足した。", "explanation": "ここは〈薄い〉の意味。味の薄さは薄いで表し、低いとは言わない。"}, {"text": "風の勢いが低くて、帆船は進まなかった。", "explanation": "ここは〈弱い〉の意味。勢いの弱さは弱いで表し、低いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "話すとき、声が低いなる人は落ち着いて見える。", "corrected_sentence": "話すとき、声が低くなる人は落ち着いて見える。", "error_description": "形容詞「低い」が「なる」に続くときは連用形「低く」にする。「低いなる」は誤りで、正しくは「低くなる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "低い", "is_correct": true, "explanation": "「声が低いので」と理由を述べる終止形。"}, {"text": "低く", "is_correct": false, "explanation": "連用形で、「ので」の前には置けず文が続かない。"}, {"text": "低くて", "is_correct": false, "explanation": "接続形で、「ので」と直接続かず文が成り立たない。"}, {"text": "低ければ", "is_correct": false, "explanation": "仮定形で、「ので」とは続かない。"}], "correct_form": "低い", "base_form": "低い", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"低い": "「声が低いので」と理由を述べる終止形。", "低く": "連用形で、「ので」の前には置けず文が続かない。", "低くて": "接続形で、「ので」と直接続かず文が成り立たない。", "低ければ": "仮定形で、「ので」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "低い声に話すと、相手に落ち着いた印象を与える。", "corrected_sentence": "低い声で話すと、相手に落ち着いた印象を与える。", "error_description": "話し方の様子を示すのは「で」。「に」は誤りで、正しくは「低い声で話す」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "低い", "is_correct": true, "explanation": "「低い音」と名詞を直接修飾する連体形。"}, {"text": "低かろう", "is_correct": false, "explanation": "推量の形で、名詞の前に直接はつかない。"}, {"text": "低そう", "is_correct": false, "explanation": "様子の形で、名詞の前では「な」が必要になる。"}, {"text": "低さ", "is_correct": false, "explanation": "名詞化した形で、「音」を直接修飾しない。"}], "correct_form": "低い", "base_form": "低い", "form_label": "連体形", "sentence_index": 7, "explanations": {"低い": "「低い音」と名詞を直接修飾する連体形。", "低かろう": "推量の形で、名詞の前に直接はつかない。", "低そう": "様子の形で、名詞の前では「な」が必要になる。", "低さ": "名詞化した形で、「音」を直接修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「変化を表している」で、表す対象を示す格助詞として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「変化に表している」は表す対象を示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「変化と表している」は相手を示す形で、対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「変化へ表している」は方向を示す形で、表す対象とは合わない。"}], "correct_answer": "を", "explanations": {"を": "「変化を表している」で、表す対象を示す格助詞として正しい。", "に": "「変化に表している」は表す対象を示せず、不自然。", "と": "「変化と表している」は相手を示す形で、対象にはならない。", "へ": "「変化へ表している」は方向を示す形で、表す対象とは合わない。"}, "error_tags": {"に": "相手・位置", "と": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「気持ちを表す」で、表す対象を示す格助詞として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「気持ちが表す」は気持ちが表す主体になり、表す対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」で、表す対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、表す対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「気持ちを表す」で、表す対象を示す格助詞として正しい。", "が": "「気持ちが表す」は気持ちが表す主体になり、表す対象にならない。", "より": "比較を示す「より」で、表す対象を示せない。", "から": "起点を示す「から」で、表す対象を示せない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「あらわす」は、なにかを みえるように することです。", "primary_collocate": null, "pronunciation": "あらわす", "ipa": "aɾawasɯ", "syllable_count": 4, "sentences": [{"text": "笑顔は、うれしい気持ちを表している。", "target_word": "表している", "complexity_tier": "T3", "furigana": "笑顔[えがお]は、うれしい気持[きも]ちを表[あらわ]している。", "sentence_source": "generated"}, {"text": "この図は、人口の変化を表している。", "target_word": "表している", "complexity_tier": "T3", "furigana": "この図[ず]は、人口[じんこう]の変化[へんか]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "赤い信号は、止まれという意味を表す。", "target_word": "表す", "complexity_tier": "T3", "furigana": "赤[あか]い信号[しんごう]は、止[と]まれという意味[いみ]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "彼女は言葉ではなく、行動で感謝を表した。", "target_word": "表した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言葉[ことば]ではなく、行動[こうどう]で感謝[かんしゃ]を表[あらわ]した。", "sentence_source": "generated"}, {"text": "地図の青い部分は、海を表している。", "target_word": "表している", "complexity_tier": "T3", "furigana": "地図[ちず]の青[あお]い部分[ぶぶん]は、海[うみ]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "数字で売り上げを表して、グラフにした。", "target_word": "表して", "complexity_tier": "T3", "furigana": "数字[すうじ]で売[う]り上[あ]げを表[あらわ]して、グラフにした。", "sentence_source": "generated"}, {"text": "彼は顔に怒りを表さない人だ。", "target_word": "表さない", "complexity_tier": "T3", "furigana": "彼[かれ]は顔[かお]に怒[いか]りを表[あらわ]さない人[ひと]だ。", "sentence_source": "generated"}, {"text": "言葉で気持ちを表すのは、むずかしい。", "target_word": "表す", "complexity_tier": "T3", "furigana": "言葉[ことば]で気持[きも]ちを表[あらわ]すのは、むずかしい。", "sentence_source": "generated"}, {"text": "この記号は、温度を表している。", "target_word": "表している", "complexity_tier": "T3", "furigana": "この記号[きごう]は、温度[おんど]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "着物の柄は、季節を表している。", "target_word": "表している", "complexity_tier": "T3", "furigana": "着物[きもの]の柄[がら]は、季節[きせつ]を表[あらわ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表す", "label": "辞書形"}, {"form": "表して", "label": "て形"}, {"form": "表している", "label": "ている形"}, {"form": "表した", "label": "た形"}, {"form": "表さない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "気持ち・意味・数量などを形や言葉で見えるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表している", "is_correct": true, "explanation": "状態を表す現在形で、笑顔が気持ちを示している文の内容に合う。"}, {"text": "表さない", "is_correct": false, "explanation": "否定形になり、気持ちを表していると述べる文の内容と矛盾する。"}, {"text": "表した", "is_correct": false, "explanation": "過去形になり、今の状態を述べる文と時制が合わない。"}, {"text": "表して", "is_correct": false, "explanation": "て形のため、ここで文が終わらず、述語として成立しない。"}], "explanations": {"表している": "状態を表す現在形で、笑顔が気持ちを示している文の内容に合う。", "表さない": "否定形になり、気持ちを表していると述べる文の内容と矛盾する。", "表した": "過去形になり、今の状態を述べる文と時制が合わない。", "表して": "て形のため、ここで文が終わらず、述語として成立しない。"}, "sentence_index": 0, "correct_answer": "表している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は十年の研究をまとめて、一冊の本を表した。", "explanation": "ここは〈著す〉（書いて出版する）の意味。表すは気持ちや意味を形にする語なので、本を書く場面では使わない。"}, {"text": "彼は優秀な社員を表して、賞状を渡した。", "explanation": "賞状を渡して人をたたえることは「表彰する」と言い、「表す」とは言わない。"}, {"text": "彼は町を表して、会議に出席した。", "explanation": "人の代わりに立つことは「代表する」と言い、「表す」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表さない", "is_correct": true, "explanation": "否定の連体形で、「顔に怒りを表さない人」という文の内容に合う。"}, {"text": "表している", "is_correct": false, "explanation": "表している人だと、怒りを顔に出している人になり、否定の文脈と矛盾する。"}, {"text": "表した", "is_correct": false, "explanation": "過去形になり、怒りを表した人という意味で、文の内容と矛盾する。"}, {"text": "表す", "is_correct": false, "explanation": "肯定の辞書形で、怒りを表す人という意味になり、否定の文脈と矛盾する。"}], "explanations": {"表さない": "否定の連体形で、「顔に怒りを表さない人」という文の内容に合う。", "表している": "表している人だと、怒りを顔に出している人になり、否定の文脈と矛盾する。", "表した": "過去形になり、怒りを表した人という意味で、文の内容と矛盾する。", "表す": "肯定の辞書形で、怒りを表す人という意味になり、否定の文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "表さない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は来月、運転免許の試験を表すことにした。", "explanation": "試験を受けることは「受ける」と言い、「表す」とは言わない。"}, {"text": "交差点で、前の車を表して走った。", "explanation": "車を抜く動作は「追い越す」と言い、「表す」とは言わない。"}, {"text": "窓辺に花を表した。", "explanation": "花を置いて飾ることは「飾る」と言い、「表す」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は手紙で感謝の気持ちに表している。", "corrected_sentence": "彼は手紙で感謝の気持ちを表している。", "error_description": "「表している」の対象には「を」を使う。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "表している", "is_correct": true, "explanation": "ている形で、今の状態として図が人口の変化を示していると述べる文に合う。"}, {"text": "表して", "is_correct": false, "explanation": "て形のため、ここで文が終わらず、述語として成立しない。"}, {"text": "表した", "is_correct": false, "explanation": "過去形になり、今の状態を述べる文と時制が合わない。"}, {"text": "表さない", "is_correct": false, "explanation": "否定形になり、図が変化を示しているという文の内容と矛盾する。"}], "correct_form": "表している", "base_form": "表す", "form_label": "ている形", "sentence_index": 1, "explanations": {"表している": "ている形で、今の状態として図が人口の変化を示していると述べる文に合う。", "表して": "て形のため、ここで文が終わらず、述語として成立しない。", "表した": "過去形になり、今の状態を述べる文と時制が合わない。", "表さない": "否定形になり、図が変化を示しているという文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は感情に表さない人だ。", "corrected_sentence": "彼は感情を表さない人だ。", "error_description": "「表さない」の対象には「を」を使う。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "表す", "is_correct": true, "explanation": "辞書形で、「〜のは」に続けて主語を説明する文に合う。"}, {"text": "表し", "is_correct": false, "explanation": "連用形のため、「〜のは」に続く名詞句として文が成立しない。"}, {"text": "表そう", "is_correct": false, "explanation": "意志形になり、「〜のは」で続く名詞句にならず、文の形が崩れる。"}, {"text": "表します", "is_correct": false, "explanation": "丁寧形のため、普通体の説明文「〜のは」に続けられない。"}], "correct_form": "表す", "base_form": "表す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"表す": "辞書形で、「〜のは」に続けて主語を説明する文に合う。", "表し": "連用形のため、「〜のは」に続く名詞句として文が成立しない。", "表そう": "意志形になり、「〜のは」で続く名詞句にならず、文の形が崩れる。", "表します": "丁寧形のため、普通体の説明文「〜のは」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
