INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35894, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "じょうぶになるとは、つよくてこわれにくくなることです。", "primary_collocate": null, "pronunciation": "じょうぶになっていく", "ipa": "dʑoːbɯ ninatːe ikɯ", "syllable_count": 9, "sentences": [{"text": "毎日歩いていると、足がだんだん丈夫になっていく。", "target_word": "丈夫になっていく", "complexity_tier": "T3", "furigana": "毎日[まいにち]歩[ある]いていると、足[あし]がだんだん丈夫[じょうぶ]になっていく。", "sentence_source": "generated"}, {"text": "苗木は、水と光で少しずつ丈夫になっていきます。", "target_word": "丈夫になっていきます", "complexity_tier": "T3", "furigana": "苗木[なえぎ]は、水[みず]と光[ひかり]で少[すこ]しずつ丈夫[じょうぶ]になっていきます。", "sentence_source": "generated"}, {"text": "赤ちゃんの骨は、大きくなるにつれて丈夫になっていく。", "target_word": "丈夫になっていく", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの骨[ほね]は、大[おお]きくなるにつれて丈夫[じょうぶ]になっていく。", "sentence_source": "generated"}, {"text": "牛乳を飲む習慣で、子どもの体は丈夫になっていった。", "target_word": "丈夫になっていった", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]を飲[の]む習慣[しゅうかん]で、子[こ]どもの体[からだ]は丈夫[じょうぶ]になっていった。", "sentence_source": "generated"}, {"text": "運動を続けたので、弱かった体も丈夫になっていった。", "target_word": "丈夫になっていった", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けたので、弱[よわ]かった体[からだ]も丈夫[じょうぶ]になっていった。", "sentence_source": "generated"}, {"text": "糸を何本も編むと、ロープは丈夫になっていきます。", "target_word": "丈夫になっていきます", "complexity_tier": "T3", "furigana": "糸[いと]を何本[なんぼん]も編[あ]むと、ロープは丈夫[じょうぶ]になっていきます。", "sentence_source": "generated"}, {"text": "小さかった子犬が、食事のおかげで丈夫になっていく。", "target_word": "丈夫になっていく", "complexity_tier": "T3", "furigana": "小[ちい]さかった子犬[こいぬ]が、食事[しょくじ]のおかげで丈夫[じょうぶ]になっていく。", "sentence_source": "generated"}, {"text": "毎年少しずつ補強して、古い橋は丈夫になっていった。", "target_word": "丈夫になっていった", "complexity_tier": "T3", "furigana": "毎年[まいとし]少[すこ]しずつ補強[ほきょう]して、古[ふる]い橋[はし]は丈夫[じょうぶ]になっていった。", "sentence_source": "generated"}, {"text": "根がしっかり張ると、木は風にも負けないほど丈夫になっていく。", "target_word": "丈夫になっていく", "complexity_tier": "T3", "furigana": "根[ね]がしっかり張[は]ると、木[き]は風[かぜ]にも負[ま]けないほど丈夫[じょうぶ]になっていく。", "sentence_source": "generated"}, {"text": "何度も修理するうちに、この古い家は昔より丈夫になっていった。", "target_word": "丈夫になっていった", "complexity_tier": "T3", "furigana": "何度[なんど]も修理[しゅうり]するうちに、この古[ふる]い家[いえ]は昔[むかし]より丈夫[じょうぶ]になっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "丈夫になっていく", "label": "終止形"}, {"form": "丈夫になっていった", "label": "過去形"}, {"form": "丈夫になっていきます", "label": "丁寧形"}, {"form": "丈夫になっていって", "label": "て形"}, {"form": "丈夫になっていかない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "体や物が少しずつ強くこわれにくく変わっていく意味の「丈夫になっていく」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丈夫になっていく", "is_correct": true, "explanation": "終止形。毎日歩くことで足が強くなる変化を述べる文末として正しい。"}, {"text": "丈夫になっていって", "is_correct": false, "explanation": "て形。文末に置くと文が完結しない。"}, {"text": "丈夫になっていったら", "is_correct": false, "explanation": "仮定形「〜たら」。続きの文が必要で、文末にはならない。"}, {"text": "丈夫になっていくと", "is_correct": false, "explanation": "条件形「〜と」。文末では文が成り立たない。"}], "explanations": {"丈夫になっていく": "終止形。毎日歩くことで足が強くなる変化を述べる文末として正しい。", "丈夫になっていって": "て形。文末に置くと文が完結しない。", "丈夫になっていったら": "仮定形「〜たら」。続きの文が必要で、文末にはならない。", "丈夫になっていくと": "条件形「〜と」。文末では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "丈夫になっていく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この選手は、パワーが丈夫になっていった。", "explanation": "ここは〈強い〉の話。丈夫は壊れにくさを表す語で、力の強さは「強くなっていった」と言う。"}, {"text": "パンが丈夫になっていった。", "explanation": "ここは〈硬い〉の話。パンが硬くなるのを「丈夫になる」とは言わない。"}, {"text": "気温が丈夫になっていった。", "explanation": "ここは〈安定〉の話。気温が落ち着いていく様子は「安定」と言い、丈夫は物や体の強さに使う語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丈夫になっていく", "is_correct": true, "explanation": "終止形。食事のおかげで強くなる変化を述べる文末として正しい。"}, {"text": "丈夫になっていかなければ", "is_correct": false, "explanation": "仮定形「〜ば」。文末に置くと文が完結しない。"}, {"text": "丈夫になっていかなくて", "is_correct": false, "explanation": "否定のて形。文末では文が成り立たない。"}, {"text": "丈夫になっていっても", "is_correct": false, "explanation": "逆接の「〜ても」。続きの文が必要で、文末にはならない。"}], "explanations": {"丈夫になっていく": "終止形。食事のおかげで強くなる変化を述べる文末として正しい。", "丈夫になっていかなければ": "仮定形「〜ば」。文末に置くと文が完結しない。", "丈夫になっていかなくて": "否定のて形。文末では文が成り立たない。", "丈夫になっていっても": "逆接の「〜ても」。続きの文が必要で、文末にはならない。"}, "sentence_index": 6, "correct_answer": "丈夫になっていく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜の雨で、庭の明かりは丈夫になっていった。", "explanation": "ここは〈明るい〉の話。明かりは明るくなるもので、丈夫とは言わない。"}, {"text": "この文章は、読むほど丈夫になっていった。", "explanation": "ここは〈充実する〉の話。文章が読むほど内容が豊かになるのは「充実する」と言い、丈夫は体や物の強さに使う。"}, {"text": "彼女は、話し方が丈夫になっていった。", "explanation": "ここは〈上達〉の話。話し方が上手になるのは「上達する」と言い、丈夫は体や物の強さに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日練習していると、腕がだんだん丈夫にいく。", "corrected_sentence": "毎日練習していると、腕がだんだん丈夫になっていく。", "error_description": "形の誤り。「丈夫になっていく」の「なって」が抜けている。「〜になっていく」の形で変化を表す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丈夫になっていきます", "is_correct": true, "explanation": "丁寧形。水と光で少しずつ変わる様子を丁寧に述べる文末として正しい。"}, {"text": "丈夫になっていけば", "is_correct": false, "explanation": "仮定形「〜ば」。文末に置けず、文が完結しない。"}, {"text": "丈夫になっていって", "is_correct": false, "explanation": "て形。文末には置けず、文が完結しない。"}, {"text": "丈夫になっていったら", "is_correct": false, "explanation": "仮定形「〜たら」。文末に置けず、文が完結しない。"}], "correct_form": "丈夫になっていきます", "base_form": "丈夫になっていく", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"丈夫になっていきます": "丁寧形。水と光で少しずつ変わる様子を丁寧に述べる文末として正しい。", "丈夫になっていけば": "仮定形「〜ば」。文末に置けず、文が完結しない。", "丈夫になっていって": "て形。文末には置けず、文が完結しない。", "丈夫になっていったら": "仮定形「〜たら」。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さかった猫が、おやつのおかげで丈夫になっていくた。", "corrected_sentence": "小さかった猫が、おやつのおかげで丈夫になっていく。", "error_description": "活用の誤り。「丈夫になっていく」の末尾に余計な「た」が付いている。「〜ていく」で終える。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "丈夫になっていった", "is_correct": true, "explanation": "過去形。補強を重ねて強くなった変化を過去として述べる文末として正しい。"}, {"text": "丈夫になっていったら", "is_correct": false, "explanation": "仮定形「〜たら」。文末に置けず、文が完結しない。"}, {"text": "丈夫になっていかなくて", "is_correct": false, "explanation": "否定のて形。文末に置けず、文が完結しない。"}, {"text": "丈夫になっていかなければ", "is_correct": false, "explanation": "仮定形「〜ば」。文末に置くと文が成り立たない。"}], "correct_form": "丈夫になっていった", "base_form": "丈夫になっていく", "form_label": "過去形", "sentence_index": 7, "explanations": {"丈夫になっていった": "過去形。補強を重ねて強くなった変化を過去として述べる文末として正しい。", "丈夫になっていったら": "仮定形「〜たら」。文末に置けず、文が完結しない。", "丈夫になっていかなくて": "否定のて形。文末に置けず、文が完結しない。", "丈夫になっていかなければ": "仮定形「〜ば」。文末に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "発展の対義語。勢いが衰えて悪い方へ向かう意味で、少しずつ良くなる定義と反対になる。"}, {"text": "維持", "is_correct": false, "explanation": "現状を保つ意味で、発展の対義語ではない。"}, {"text": "解消", "is_correct": false, "explanation": "問題や差を取り除く意味で、発展の対義語ではない。"}, {"text": "達成", "is_correct": false, "explanation": "目標を成し遂げる意味で、発展の対義語ではない。"}], "correct_answer": "衰退", "explanations": {"衰退": "発展の対義語。勢いが衰えて悪い方へ向かう意味で、少しずつ良くなる定義と反対になる。", "維持": "現状を保つ意味で、発展の対義語ではない。", "解消": "問題や差を取り除く意味で、発展の対義語ではない。", "達成": "目標を成し遂げる意味で、発展の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "発展の対義語。勢いが衰えて悪い方へ向かう意味で、少しずつ良くなる定義と反対になる。"}, {"text": "停止", "is_correct": false, "explanation": "動きを止める意味で、発展の対義語ではない。"}, {"text": "凍結", "is_correct": false, "explanation": "活動や計画を凍らせて止める意味で、発展の対義語ではない。"}, {"text": "没収", "is_correct": false, "explanation": "財産や物を取り上げる意味で、発展の対義語ではない。"}], "correct_answer": "衰退", "explanations": {"衰退": "発展の対義語。勢いが衰えて悪い方へ向かう意味で、少しずつ良くなる定義と反対になる。", "停止": "動きを止める意味で、発展の対義語ではない。", "凍結": "活動や計画を凍らせて止める意味で、発展の対義語ではない。", "没収": "財産や物を取り上げる意味で、発展の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "過去から現在まで、少しずつ良い方向へ進んできた。", "primary_collocate": null, "pronunciation": "はってんしてくる", "ipa": "hattenɕitekɯɾɯ", "syllable_count": 8, "sentences": [{"text": "この町は、鉄道ができてから大きく発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "この町(まち)は、鉄道(てつどう)ができてから大(おお)きく発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "日本の技術は、長い時間をかけて発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "日本(にほん)の技術(ぎじゅつ)は、長(なが)い時間(じかん)をかけて発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "地域の祭りも、少しずつ発展してきたと思う。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "地域(ちいき)の祭(まつ)りも、少(すこ)しずつ発展(はってん)してきたと思(おも)う。", "sentence_source": "generated"}, {"text": "私たちの会社は、小さな店から発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "私(わたし)たちの会社(かいしゃ)は、小(ちい)さな店(みせ)から発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "医学は、多くの人の努力で発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "医学(いがく)は、多(おお)くの人(ひと)の努力(どりょく)で発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "港町として、この地域は昔から発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "港町(みなとまち)として、この地域(ちいき)は昔(むかし)から発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "この競技は、百年前に生まれて少しずつ発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "この競技(きょうぎ)は、百年前(ひゃくねんまえ)に生(う)まれて少(すこ)しずつ発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "インターネットのおかげで、通信の技術は発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "インターネットのおかげで、通信(つうしん)の技術(ぎじゅつ)は発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "農業を中心に、この村はゆっくり発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "農業(のうぎょう)を中心(ちゅうしん)に、この村(むら)はゆっくり発展(はってん)してきた。", "sentence_source": "generated"}, {"text": "二つの国の関係は、少しずつ発展してきた。", "target_word": "発展してきた", "complexity_tier": "T3", "furigana": "二(ふた)つの国(くに)の関係(かんけい)は、少(すこ)しずつ発展(はってん)してきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発展してくる", "label": "終止形"}, {"form": "発展してきた", "label": "過去形"}, {"form": "発展してきて", "label": "て形"}, {"form": "発展してこない", "label": "否定形"}], "register": "標準（普通体）", "sense_fingerprint": "発展してくる：過去から現在まで、少しずつ良い方向へ進んできたという経過を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947d9c0d-20b2-4311-9f05-a20f8a6414f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発展してきた", "is_correct": true, "explanation": "鉄道の整備以降に少しずつ良くなってきた経過を表す。「大きく発展してきた」が成り立つ。"}, {"text": "解決してきた", "is_correct": false, "explanation": "問題を片付ける意味で、町が大きく良くなっていく文脈には合わない。"}, {"text": "消費してきた", "is_correct": false, "explanation": "物を使い切る意味で、町が大きく発展する文脈とは合わない。"}, {"text": "放置してきた", "is_correct": false, "explanation": "手をつけずに置く意味で、良くなっていく経過を表せない。"}], "explanations": {"発展してきた": "鉄道の整備以降に少しずつ良くなってきた経過を表す。「大きく発展してきた」が成り立つ。", "解決してきた": "問題を片付ける意味で、町が大きく良くなっていく文脈には合わない。", "消費してきた": "物を使い切る意味で、町が大きく発展する文脈とは合わない。", "放置してきた": "手をつけずに置く意味で、良くなっていく経過を表せない。"}, "sentence_index": 0, "correct_answer": "発展してきた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病状が少しずつ発展してきた。", "explanation": "ここは〈進行〉の意味との混同。病気が悪くなる場面に発展は使わないので合わない。"}, {"text": "古い校舎が少しずつ発展してきた。", "explanation": "ここは〈劣化〉の意味との混同。建物が傷んでいく場面に発展は使わないので合わない。"}, {"text": "子どもの身長は少しずつ発展してきた。", "explanation": "ここは〈成長〉の意味との混同。人の体が大きくなる変化には成長を使い、発展は社会や事業の広がりに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発展してきた", "is_correct": true, "explanation": "百年かけて少しずつ良くなってきた経過を表す。「少しずつ発展してきた」が成り立つ。"}, {"text": "誕生してきた", "is_correct": false, "explanation": "生まれるという一度きりの出来事を表すので、少しずつ積み重なる文脈には合わない。"}, {"text": "解散してきた", "is_correct": false, "explanation": "団体がまとまりをやめる意味で、少しずつ良くなる経過とは合わない。"}, {"text": "逮捕してきた", "is_correct": false, "explanation": "捕まえる意味で、競技の成長の文脈には入らない。"}], "explanations": {"発展してきた": "百年かけて少しずつ良くなってきた経過を表す。「少しずつ発展してきた」が成り立つ。", "誕生してきた": "生まれるという一度きりの出来事を表すので、少しずつ積み重なる文脈には合わない。", "解散してきた": "団体がまとまりをやめる意味で、少しずつ良くなる経過とは合わない。", "逮捕してきた": "捕まえる意味で、競技の成長の文脈には入らない。"}, "sentence_index": 6, "correct_answer": "発展してきた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の体力は少しずつ発展してきた。", "explanation": "ここは〈向上〉の意味との混同。発展は社会や技術の広がりに使い、個人の体力が伸びることには使わないので合わない。"}, {"text": "この靴は長く履いて、少しずつ発展してきた。", "explanation": "ここは〈消耗〉の意味との混同。物が使われてすり減る場面に発展は使わないので合わない。"}, {"text": "この牛乳は、夏の間に少しずつ発展してきた。", "explanation": "ここは〈腐る〉の意味との混同。食べ物が傷んでいく変化に発展は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村は、戦後の工業化によって大きく発展してきて。", "corrected_sentence": "この村は、戦後の工業化によって大きく発展してきた。", "error_description": "活用の誤り。文を終えるべき所で「て形」のまま終わっている。正しくは過去形の「発展してきた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "発展してきた", "is_correct": true, "explanation": "過去形で、長い時間をかけて良くなってきた経過を表す文脈に合う。"}, {"text": "発展してきて", "is_correct": false, "explanation": "て形で、文を終えることができない。"}, {"text": "発展してきたら", "is_correct": false, "explanation": "条件形で、文を言い切れず文脈とも合わない。"}, {"text": "発展してこない", "is_correct": false, "explanation": "否定形。良くなってきたという経過と逆の意味になる。"}], "correct_form": "発展してきた", "base_form": "発展してくる", "form_label": "過去形", "sentence_index": 1, "explanations": {"発展してきた": "過去形で、長い時間をかけて良くなってきた経過を表す文脈に合う。", "発展してきて": "て形で、文を終えることができない。", "発展してきたら": "条件形で、文を言い切れず文脈とも合わない。", "発展してこない": "否定形。良くなってきたという経過と逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35908, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この港は、貿易の増加とともに発展しきた。", "corrected_sentence": "この港は、貿易の増加とともに発展してきた。", "error_description": "活用の誤り。「発展してきた」の「て」が抜けている。「発展しきた」は文法的に成り立たない。正しくは「発展してきた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "発展してきた", "is_correct": true, "explanation": "過去形で、インターネットの影響により良くなってきた経過を表す文脈に合う。"}, {"text": "発展してこなかった", "is_correct": false, "explanation": "否定の過去形。良くなってきたという経過と逆の意味になる。"}, {"text": "発展してきたり", "is_correct": false, "explanation": "並列の形で、文を終えることができない。"}, {"text": "発展してきます", "is_correct": false, "explanation": "丁寧語で、普通体で書かれたこの文の調子と合わない。"}], "correct_form": "発展してきた", "base_form": "発展してくる", "form_label": "過去形", "sentence_index": 7, "explanations": {"発展してきた": "過去形で、インターネットの影響により良くなってきた経過を表す文脈に合う。", "発展してこなかった": "否定の過去形。良くなってきたという経過と逆の意味になる。", "発展してきたり": "並列の形で、文を終えることができない。", "発展してきます": "丁寧語で、普通体で書かれたこの文の調子と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed848d40-3489-4681-91c1-79fe346d2be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
