INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35911, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事をするのに、多くの努力や知識が必要で、簡単にはできないこと。", "primary_collocate": null, "pronunciation": "むずかしい", "ipa": "mɯzɯkaɕii", "syllable_count": 5, "sentences": [{"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "難しさ", "complexity_tier": "T4", "furigana": "しかし、そのぶこつながいかんやいじかんりのむずかしさから、げんざいではそのかちがさいひょうかされるいっぽうで、とりこわされるケースもふえています。", "sentence_source": "mined"}, {"text": "この問題は難しくて、先生にも聞かないと分かりません。", "target_word": "難しくて", "complexity_tier": "T3", "furigana": "このもんだいはむずかしくて、せんせいにもきかないとわかりません。", "sentence_source": "generated"}, {"text": "日本語の敬語は、外国人には難しいと言われます。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "にほんごのけいごは、がいこくじんにはむずかしいといわれます。", "sentence_source": "generated"}, {"text": "昨日の試験は難しかったので、時間が足りなかった。", "target_word": "難しかった", "complexity_tier": "T3", "furigana": "きのうのしけんはむずかしかったので、じかんがたりなかった。", "sentence_source": "generated"}, {"text": "初心者が一人で山に登るのは難しいです。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "しょしんしゃがひとりでやまにのぼるのはむずかしいです。", "sentence_source": "generated"}, {"text": "難しい漢字は、ふりがなを付けて読みます。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "むずかしいかんじは、ふりがなをつけてよみます。", "sentence_source": "generated"}, {"text": "彼の気持ちを言葉にするのは難しく、黙ってしまった。", "target_word": "難しく", "complexity_tier": "T3", "furigana": "かれのきもちをことばにするのはむずかしく、だまってしまった。", "sentence_source": "generated"}, {"text": "天気が悪ければ、予定どおりに出発するのは難しいでしょう。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "てんきがわるければ、よていどおりにしゅっぱつするのはむずかしいでしょう。", "sentence_source": "generated"}, {"text": "この本は内容が難しいので、子どもには向きません。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "このほんはないようがむずかしいので、こどもにはむきません。", "sentence_source": "generated"}, {"text": "難しくても、あきらめずに続ければ上達します。", "target_word": "難しく", "complexity_tier": "T3", "furigana": "むずかしくても、あきらめずにつづければじょうたつします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "難しい", "label": "終止形"}, {"form": "難しく", "label": "連用形"}, {"form": "難しくて", "label": "て形"}, {"form": "難しかった", "label": "過去形"}, {"form": "難しくない", "label": "否定形"}, {"form": "難しければ", "label": "仮定形"}, {"form": "難しさ", "label": "名詞化"}], "register": "neutral", "sense_fingerprint": "多くの努力や知識が必要で、簡単にはできない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 無骨 (Zipf 2.69), 外観 (Zipf 3.94), 取り壊さ (Zipf 2.81)']::text[], '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35911, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "難しさ", "is_correct": true, "explanation": "「の」に続けて名詞として使える形。「維持管理の難しさ」で、管理の大変さを表す。"}, {"text": "難しく", "is_correct": false, "explanation": "連用形なので「の」の後には続かず、「維持管理の難しく」は成立しない。"}, {"text": "難しくて", "is_correct": false, "explanation": "て形は文をつなぐ形で、名詞の位置には入らない。"}, {"text": "難しければ", "is_correct": false, "explanation": "仮定形は条件を表す形で、「の」の後の名詞の位置には入らない。"}], "explanations": {"難しさ": "「の」に続けて名詞として使える形。「維持管理の難しさ」で、管理の大変さを表す。", "難しく": "連用形なので「の」の後には続かず、「維持管理の難しく」は成立しない。", "難しくて": "て形は文をつなぐ形で、名詞の位置には入らない。", "難しければ": "仮定形は条件を表す形で、「の」の後の名詞の位置には入らない。"}, "sentence_index": 0, "correct_answer": "難しさ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地方は食べ物が難しい。", "explanation": "ここは〈豊か〉の意味。食べ物の種類や量が多いことは豊かで、難しいは努力や知識が要ることを表すので合わない。"}, {"text": "寒さが難しい冬には、野菜がほとんど育たない。", "explanation": "ここは〈厳しい〉の意味。寒さの程度を表すのは厳しいで、難しいは〈努力や知識が要る〉ことを表すので合わない。"}, {"text": "この部屋は難しくて、三人では寝られない。", "explanation": "ここは〈窮屈〉の意味。空間が狭くて動きにくいことは窮屈で、難しいは努力や知識が要ることを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35911, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "難しく", "is_correct": true, "explanation": "連用形で、「言葉にするのは難しく、黙ってしまった」と文をつなぐ。"}, {"text": "大変", "is_correct": false, "explanation": "形容動詞の語幹。「大変、」とは続けられず、「大変で」になって初めて文をつなぐ。"}, {"text": "静か", "is_correct": false, "explanation": "形容動詞。「静か、」とは続かず、文が成立しない。"}, {"text": "丁寧", "is_correct": false, "explanation": "形容動詞。「丁寧、」と続けると文が成立せず、意味も合わない。"}], "explanations": {"難しく": "連用形で、「言葉にするのは難しく、黙ってしまった」と文をつなぐ。", "大変": "形容動詞の語幹。「大変、」とは続けられず、「大変で」になって初めて文をつなぐ。", "静か": "形容動詞。「静か、」とは続かず、文が成立しない。", "丁寧": "形容動詞。「丁寧、」と続けると文が成立せず、意味も合わない。"}, "sentence_index": 6, "correct_answer": "難しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この図書館は難しくて、勉強に向いている。", "explanation": "ここは〈静か〉の意味。騒がしくないことは静かで、難しいは努力や知識が要ることを表すので合わない。"}, {"text": "別れた恋人のことを思うと、今でも難しくてたまらない。", "explanation": "ここは〈つらい〉の意味。精神的な苦しさは辛いで表し、難しいは努力や知識が要ることを表すので合わない。"}, {"text": "この店の商品は値段が難しいので、学生には手が出ない。", "explanation": "値段の高さを表すのは高いで、難しいは値段には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35911, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計算は難しいくて、一人では解けません。", "corrected_sentence": "この計算は難しくて、一人では解けません。", "error_description": "形容詞「難しい」の連用形「難しく」に「て」を付けた「難しくて」が正しい形。「難しいくて」は誤った活用。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "難しくて", "is_correct": true, "explanation": "「〜て、先生にも聞かないと」と文をつなぐて形。"}, {"text": "難しかった", "is_correct": false, "explanation": "過去形。後ろの「分かりません」という現在の文脈と合わない。"}, {"text": "難しければ", "is_correct": false, "explanation": "仮定形。条件文になり、文の意味が変わってしまう。"}, {"text": "難しくない", "is_correct": false, "explanation": "否定形。「難しい」と述べる文の内容と矛盾する。"}], "correct_form": "難しくて", "base_form": "難しい", "form_label": "て形", "sentence_index": 1, "explanations": {"難しくて": "「〜て、先生にも聞かないと」と文をつなぐて形。", "難しかった": "過去形。後ろの「分かりません」という現在の文脈と合わない。", "難しければ": "仮定形。条件文になり、文の意味が変わってしまう。", "難しくない": "否定形。「難しい」と述べる文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35911, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この仕事は一人では難しさので、誰かに手伝ってほしい。", "corrected_sentence": "この仕事は一人では難しいので、誰かに手伝ってほしい。", "error_description": "「難しさ」は名詞化した形。「ので」に続けるには形容詞の終止形「難しい」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "難しい", "is_correct": true, "explanation": "終止形。「でしょう」の前に入る基本形。"}, {"text": "難しく", "is_correct": false, "explanation": "連用形。「でしょう」の前には入らず、文が成立しない。"}, {"text": "難しくても", "is_correct": false, "explanation": "逆接の形。「でしょう」と続けると文の意味が変わり不自然。"}, {"text": "難しければ", "is_correct": false, "explanation": "仮定形。「でしょう」の前には入らず、文が成立しない。"}], "correct_form": "難しい", "base_form": "難しい", "form_label": "終止形", "sentence_index": 7, "explanations": {"難しい": "終止形。「でしょう」の前に入る基本形。", "難しく": "連用形。「でしょう」の前には入らず、文が成立しない。", "難しくても": "逆接の形。「でしょう」と続けると文の意味が変わり不自然。", "難しければ": "仮定形。「でしょう」の前には入らず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「この法で梅を漬ける」の「で」は手段を示し、文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「この法を梅を漬け」は「を」が二つ続き、目的語の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「この法に梅を漬け」は手段を表せず、不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「この法の梅を漬け」は「の」が梅を修飾するだけで、動詞「漬け」の手段を示せない。"}], "correct_answer": "で", "explanations": {"で": "「この法で梅を漬ける」の「で」は手段を示し、文が自然に成り立つ。", "を": "「この法を梅を漬け」は「を」が二つ続き、目的語の関係が成り立たない。", "に": "「この法に梅を漬け」は手段を表せず、不自然になる。", "の": "「この法の梅を漬け」は「の」が梅を修飾するだけで、動詞「漬け」の手段を示せない。"}, "error_tags": {"で": "手段", "を": "対象", "に": "方向・帰着", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この法のおかげで」の「の」は法を名詞として修飾し、「おかげで」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「この法をおかげで」は「を」が目的語を示すが、後ろに続かない。"}, {"text": "に", "is_correct": false, "explanation": "「この法におかげで」は「〜のおかげで」の形にならない。"}, {"text": "と", "is_correct": false, "explanation": "「この法とおかげで」は並列の相手にならず、文が続かない。"}], "correct_answer": "の", "explanations": {"の": "「この法のおかげで」の「の」は法を名詞として修飾し、「おかげで」と続く。", "を": "「この法をおかげで」は「を」が目的語を示すが、後ろに続かない。", "に": "「この法におかげで」は「〜のおかげで」の形にならない。", "と": "「この法とおかげで」は並列の相手にならず、文が続かない。"}, "error_tags": {"の": "連体修飾", "を": "対象", "に": "方向・帰着", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目的を達成するための、決まったやり方や手続き。", "primary_collocate": null, "pronunciation": "ほう", "ipa": "hoː", "syllable_count": 2, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "法", "complexity_tier": "T5", "furigana": "まず、現場[げんば]や鑑識[かんしき]ラボにおいて、肉眼[にくがん]では捉[とら]えられぬ潜在[せんざい]指紋[しもん]を、シアノアクリレート法[ほう]や光学的[こうがくてき]手法[しゅほう]といったアプローチにより顕在化[けんざいか]させる。", "sentence_source": "mined"}, {"text": "母はこの法で梅を漬け、一年中おいしく食べられるようにしている。", "target_word": "法", "complexity_tier": "T3", "furigana": "母[はは]はこの法[ほう]で梅[うめ]を漬[つ]け、一年中[いちねんじゅう]おいしく食[た]べられるようにしている。", "sentence_source": "generated"}, {"text": "実験では、新たに考えたこの法を使ったところ、誤差がずっと小さくなった。", "target_word": "法", "complexity_tier": "T3", "furigana": "実験[じっけん]では、新[あら]たに考[かんが]えたこの法[ほう]を使[つか]ったところ、誤差[ごさ]がずっと小[ちい]さくなった。", "sentence_source": "generated"}, {"text": "歯の痛みが続いたので、医師と相談して、この法で治療を試すことにした。", "target_word": "法", "complexity_tier": "T3", "furigana": "歯[は]の痛[いた]みが続[つづ]いたので、医師[いし]と相談[そうだん]して、この法[ほう]で治療[ちりょう]を試[ため]すことにした。", "sentence_source": "generated"}, {"text": "単語を覚える際、この法なら忘れにくいので、試験前に役立つ。", "target_word": "法", "complexity_tier": "T3", "furigana": "単語[たんご]を覚[おぼ]える際[さい]、この法[ほう]なら忘[わす]れにくいので、試験[しけん]前[まえ]に役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "先生は、効率よく勉強できるこの法を生徒に紹介した。", "target_word": "法", "complexity_tier": "T3", "furigana": "先生[せんせい]は、効率[こうりつ]よく勉強[べんきょう]できるこの法[ほう]を生徒[せいと]に紹介[しょうかい]した。", "sentence_source": "generated"}, {"text": "従来の方式では時間がかかりすぎるため、工場はこの法で濾過することにした。", "target_word": "法", "complexity_tier": "T3", "furigana": "従来[じゅうらい]の方式[ほうしき]では時間[じかん]がかかりすぎるため、工場[こうじょう]はこの法[ほう]で濾過[ろか]することにした。", "sentence_source": "generated"}, {"text": "祖父から教わったこの法のおかげで、庭のトマトは毎年よく実る。", "target_word": "法", "complexity_tier": "T3", "furigana": "祖父[そふ]から教[おそ]わったこの法[ほう]のおかげで、庭[にわ]のトマトは毎年[まいとし]よく実[みの]る。", "sentence_source": "generated"}, {"text": "料理本には、肉をやわらかく仕上げるこの法が写真つきで載っている。", "target_word": "法", "complexity_tier": "T3", "furigana": "料理本[りょうりぼん]には、肉[にく]をやわらかく仕上[しあ]げるこの法[ほう]が写真[しゃしん]つきで載[の]っている。", "sentence_source": "generated"}, {"text": "実験では、複数の分析を試したが、最も正確だったのはこの法だった。", "target_word": "法", "complexity_tier": "T3", "furigana": "実験[じっけん]では、複数[ふくすう]の分析[ぶんせき]を試[ため]したが、最[もっと]も正確[せいかく]だったのはこの法[ほう]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "法", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "「〜法」の形で、目的のための決まった方法・手順を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: シアノアクリレート (Zipf 1.04)','sentence 1 above tier T1: 3 words above tier T1 (max 2): 漬け (Zipf 3.98), 一年中 (Zipf 3.05), おいしく (Zipf 3.83)']::text[], '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法", "is_correct": true, "explanation": "「シアノアクリレート法」は手法の名称として、「光学的手法」と並ぶ形になる。"}, {"text": "感度", "is_correct": false, "explanation": "感じ取る度合いを表す語で、手法の名称にはならない。"}, {"text": "指数", "is_correct": false, "explanation": "数値の指標を表す語で、手法の名称には入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "持続期間を表す語で、手法の名称には入らない。"}], "explanations": {"法": "「シアノアクリレート法」は手法の名称として、「光学的手法」と並ぶ形になる。", "感度": "感じ取る度合いを表す語で、手法の名称にはならない。", "指数": "数値の指標を表す語で、手法の名称には入らない。", "寿命": "持続期間を表す語で、手法の名称には入らない。"}, "sentence_index": 0, "correct_answer": "法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "船は、まっすぐ東の法へ進んだ。", "explanation": "ここは〈方向〉の意味（進む向き）。同じ読みの「方」は向きを表すが、法は手順の意味なので、進む方角には使わない。"}, {"text": "学生時代の法と、駅前で偶然再会した。", "explanation": "ここは〈友人〉の意味（親しい仲間）。同じ読みの「朋」は友を指すが、法は手順の意味なので人には使わない。"}, {"text": "古い法を磨いて、博物館に飾った。", "explanation": "ここは〈大砲〉の意味（武器）。同じ読みの「砲」は大砲を指すが、法は手順の意味なので武器には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法", "is_correct": true, "explanation": "「この法で濾過する」は方法を示し、文脈に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵では濾過できず、「この鍵で濾過する」は意味が通らない。"}, {"text": "時期", "is_correct": false, "explanation": "時期は濾過の手段にならず、文脈に合わない。"}, {"text": "扇風機", "is_correct": false, "explanation": "扇風機は濾過の方法にならず、文脈に合わない。"}], "explanations": {"法": "「この法で濾過する」は方法を示し、文脈に合う。", "鍵": "鍵では濾過できず、「この鍵で濾過する」は意味が通らない。", "時期": "時期は濾過の手段にならず、文脈に合わない。", "扇風機": "扇風機は濾過の方法にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人は布の法を細かく測った。", "explanation": "ここは〈寸法〉の意味（物の長さや大きさ）。法は手続きの意味で、長さを測る対象にはならない。"}, {"text": "糖の法を上げると、ジャムが固くなる。", "explanation": "ここは〈密度〉の意味（単位あたりの量）。法は手順の意味で、数値として上げ下げできない。"}, {"text": "毎朝、法を量って記録している。", "explanation": "ここは〈体重〉の意味（重さ）。法は手続きの意味で、量って記録する対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母はこの法を味噌を仕込んでいる。", "corrected_sentence": "祖母はこの法で味噌を仕込んでいる。", "error_description": "「この法で〜を仕込む」と手段の「で」をとる。「法を」は誤り。正しくは「法で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35923, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい法を食べて、作業時間を半分にできた。", "corrected_sentence": "新しい法を取り入れて、作業時間を半分にできた。", "error_description": "方法は「取り入れる」「採用する」などと結ぶ。「食べて」は法と結びつかず誤り。正しくは「取り入れて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「習う」の目的語を示す格助詞。「作曲を習っていて」で文が成立する。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「習う」は目的語を取るので「作曲が習っていて」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す。「作曲より習っていて」は比較文にならず意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す。「作曲と習っていて」では並べる相手がなく成立しない。"}], "correct_answer": "を", "explanations": {"を": "「習う」の目的語を示す格助詞。「作曲を習っていて」で文が成立する。", "が": "主語を示すが、「習う」は目的語を取るので「作曲が習っていて」は成り立たない。", "より": "比較の基準を示す。「作曲より習っていて」は比較文にならず意味が通らない。", "と": "並列や共同を示す。「作曲と習っていて」では並べる相手がなく成立しない。"}, "error_tags": {"が": "主語", "より": "比較", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作曲を」の「を」で、「作曲を仕事にしたい」と目的語として続く。"}, {"text": "に", "is_correct": false, "explanation": "帰着点を示すが、「作曲に仕事にしたい」は結びつかず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「作曲へ仕事にしたい」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「仕事にする」は目的語を取るので「作曲が仕事にしたい」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作曲を」の「を」で、「作曲を仕事にしたい」と目的語として続く。", "に": "帰着点を示すが、「作曲に仕事にしたい」は結びつかず不自然。", "へ": "方向を示す。「作曲へ仕事にしたい」は成り立たない。", "が": "主語を示すが、「仕事にする」は目的語を取るので「作曲が仕事にしたい」は成り立たない。"}, "error_tags": {"に": "対象・帰着", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "音楽の曲を作ること。", "primary_collocate": null, "pronunciation": "さっきょく", "ipa": "sakkʲokɯ", "syllable_count": 4, "sentences": [{"text": "彼は毎晩ギターを弾きながら作曲をしている。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "彼[かれ]は毎晩[まいばん]ギターを弾[ひ]きながら作曲[さっきょく]をしている。", "sentence_source": "generated"}, {"text": "姉は作曲を習っていて、来月発表会がある。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "姉[あね]は作曲[さっきょく]を習[なら]っていて、来月[らいげつ]発表会[はっぴょうかい]がある。", "sentence_source": "generated"}, {"text": "この歌は友だちが作曲し、私が歌詞を書いた。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "この歌[うた]は友[とも]だちが作曲[さっきょく]し、私[わたし]が歌詞[かし]を書[か]いた。", "sentence_source": "generated"}, {"text": "作曲には時間がかかるので、毎日少しずつ進めている。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]には時間[じかん]がかかるので、毎日[まいにち]少[すこ]しずつ進[すす]めている。", "sentence_source": "generated"}, {"text": "先生は作曲が得意で、学校の歌も作った。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "先生[せんせい]は作曲[さっきょく]が得意[とくい]で、学校[がっこう]の歌[うた]も作[つく]った。", "sentence_source": "generated"}, {"text": "弟は作曲のアプリを使って、自分の曲を作っている。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "弟[おとうと]は作曲[さっきょく]のアプリを使[つか]って、自分[じぶん]の曲[きょく]を作[つく]っている。", "sentence_source": "generated"}, {"text": "作曲を始めたのは、ピアノが弾けるようになってからだ。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]を始[はじ]めたのは、ピアノが弾[ひ]けるようになってからだ。", "sentence_source": "generated"}, {"text": "彼女は作曲を仕事にしたいと思っている。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は作曲[さっきょく]を仕事[しごと]にしたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "作曲のコンクールに出すために、何度も曲を直した。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]のコンクールに出[だ]すために、何度[なんど]も曲[きょく]を直[なお]した。", "sentence_source": "generated"}, {"text": "父は作曲の経験があり、結婚式の曲を作ってくれた。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "父[ちち]は作曲[さっきょく]の経験[けいけん]があり、結婚式[けっこんしき]の曲[きょく]を作[つく]ってくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作曲", "label": "基本形"}, {"form": "作曲する", "label": "サ変動詞"}, {"form": "作曲した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "作曲: 音楽の曲を作ること(一般的な意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "「をしている」に入る動作名詞。ギターを弾きながら行う創作活動として文に合う。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は書かれた記録の物で、「楽譜をしている」は動作として成り立たない。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音の並びを指す名詞で、「音階をしている」は文として不自然。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の言葉の部分で、「歌詞をしている」は行為にならない。"}], "explanations": {"作曲": "「をしている」に入る動作名詞。ギターを弾きながら行う創作活動として文に合う。", "楽譜": "楽譜は書かれた記録の物で、「楽譜をしている」は動作として成り立たない。", "音階": "音階は音の並びを指す名詞で、「音階をしている」は文として不自然。", "歌詞": "歌詞は歌の言葉の部分で、「歌詞をしている」は行為にならない。"}, "sentence_index": 0, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は曲に合わせて歌詞を作曲し、歌手に渡した。", "explanation": "ここは〈歌詞を書く〉の意味の作詞。作曲はメロディーを作ることなので、歌詞には使わない。"}, {"text": "既に発表された曲を作曲して、テンポを変えた。", "explanation": "ここは〈既存の曲を編曲する〉の意味。作曲は新しく曲を作ることなので、既に発表された曲には合わない。"}, {"text": "ボイスメモに雨の音を作曲した。", "explanation": "ここは〈音を記録する〉の意味の録音。作曲は音楽を作ることなので、雨の音には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "「を始めた」の目的語に入る動作名詞。ピアノが弾けるようになってから取りかかる活動として文に合う。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さの差を表す語で、「音程を始めた」は活動にならず不自然。"}, {"text": "音符", "is_correct": false, "explanation": "音符は音の長さを示す記号で、「音符を始めた」は活動にならず不自然。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子は拍の枠組みを指し、「拍子を始めた」は活動の名詞として不自然。"}], "explanations": {"作曲": "「を始めた」の目的語に入る動作名詞。ピアノが弾けるようになってから取りかかる活動として文に合う。", "音程": "音程は音の高さの差を表す語で、「音程を始めた」は活動にならず不自然。", "音符": "音符は音の長さを示す記号で、「音符を始めた」は活動にならず不自然。", "拍子": "拍子は拍の枠組みを指し、「拍子を始めた」は活動の名詞として不自然。"}, "sentence_index": 6, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、彼女は居間でピアノを作曲した。", "explanation": "ここは〈楽器で曲を弾く〉の意味の演奏。作曲は曲を作ることなので、楽器を対象にはできない。"}, {"text": "指揮者が楽団を作曲して本番に臨んだ。", "explanation": "ここは〈演奏者を導く〉の意味の指揮。作曲は曲を作ることなので、人の集団には使えない。"}, {"text": "彼は録音された歌声を作曲して、楽譜に写した。", "explanation": "ここは〈聞いた音楽を楽譜に書き取る〉の意味の採譜。作曲は新しく作ることなので、既に歌われた歌声には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は去年から作曲に習い、今は自分で曲を作っている。", "corrected_sentence": "彼は去年から作曲を習い、今は自分で曲を作っている。", "error_description": "「習う」は目的語に「を」を取る。「作曲に」は誤りで、正しくは「作曲を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35924, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は作曲を終わったあと、楽譜をコピーして配った。", "corrected_sentence": "弟は作曲を終えたあと、楽譜をコピーして配った。", "error_description": "「終わる」は目的語を取らない自動詞。作曲を目的語に取る「終える」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
