INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「作曲で」は場面や状況を示し、「初めての作曲で、楽譜を書くのに何日もかかった」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "動作の目的語を示す。「作曲を、楽譜を書く」と続くと文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「作曲へ、楽譜を書く」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「作曲と、楽譜を書く」は並列の形になり、ここの状況の意味とずれる。"}], "correct_answer": "で", "explanations": {"で": "「作曲で」は場面や状況を示し、「初めての作曲で、楽譜を書くのに何日もかかった」と自然に続く。", "を": "動作の目的語を示す。「作曲を、楽譜を書く」と続くと文が成り立たない。", "へ": "方向を示す。「作曲へ、楽譜を書く」は意味が通らない。", "と": "並列を示す。「作曲と、楽譜を書く」は並列の形になり、ここの状況の意味とずれる。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "音楽の曲を作ること。特に、メロディーやリズムを考えて、楽譜に書くこと。", "primary_collocate": null, "pronunciation": "さっきょく", "ipa": "sakkʲokɯ", "syllable_count": 4, "sentences": [{"text": "作曲では、まずメロディーを考えてから楽譜に書く。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]では、まずメロディーを考[かんが]えてから楽譜[がくふ]に書[か]く。", "sentence_source": "generated"}, {"text": "彼女はリズムを工夫して作曲し、楽譜を完成させた。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はリズムを工夫[くふう]して作曲[さっきょく]し、楽譜[がくふ]を完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "作曲の授業で、四小節のメロディーを楽譜に書いた。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]の授業[じゅぎょう]で、四小節[よんしょうせつ]のメロディーを楽譜[がくふ]に書[か]いた。", "sentence_source": "generated"}, {"text": "作曲を学ぶには、楽譜の読み書きができることが大切だ。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]を学[まな]ぶには、楽譜[がくふ]の読[よ]み書[か]きができることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼は作曲に集中するため、静かな部屋にこもった。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "彼[かれ]は作曲[さっきょく]に集中[しゅうちゅう]するため、静[しず]かな部屋[へや]にこもった。", "sentence_source": "generated"}, {"text": "この曲は作曲に三か月かかったそうだ。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "この曲[きょく]は作曲[さっきょく]に三[さん]か月[げつ]かかったそうだ。", "sentence_source": "generated"}, {"text": "作曲をするとき、彼はまずリズムから決める。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]をするとき、彼[かれ]はまずリズムから決[き]める。", "sentence_source": "generated"}, {"text": "初めての作曲で、楽譜を書くのに何日もかかった。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "初[はじ]めての作曲[さっきょく]で、楽譜[がくふ]を書[か]くのに何日[なんにち]もかかった。", "sentence_source": "generated"}, {"text": "作曲のヒントを探して、公園を散歩した。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]のヒントを探[さが]して、公園[こうえん]を散歩[さんぽ]した。", "sentence_source": "generated"}, {"text": "作曲を終えたあと、楽譜を先生に見せた。", "target_word": "作曲", "complexity_tier": "T3", "furigana": "作曲[さっきょく]を終[お]えたあと、楽譜[がくふ]を先生[せんせい]に見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作曲", "label": "基本形"}, {"form": "作曲する", "label": "サ変動詞"}, {"form": "作曲した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "作曲: メロディーやリズムを考え楽譜に書く創作作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "メロディーを考えて楽譜に書く創作の工程を指す名詞。「作曲では」で文の主題になる。"}, {"text": "録音", "is_correct": false, "explanation": "録音は音を記録する作業で、メロディーを考えて楽譜に書く流れに合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は既にある曲を弾くことで、考えてから楽譜に書く工程とは合わない。"}, {"text": "指揮", "is_correct": false, "explanation": "指揮は奏者を導く役割で、楽譜を書く工程を指さない。"}], "explanations": {"作曲": "メロディーを考えて楽譜に書く創作の工程を指す名詞。「作曲では」で文の主題になる。", "録音": "録音は音を記録する作業で、メロディーを考えて楽譜に書く流れに合わない。", "演奏": "演奏は既にある曲を弾くことで、考えてから楽譜に書く工程とは合わない。", "指揮": "指揮は奏者を導く役割で、楽譜を書く工程を指さない。"}, "sentence_index": 0, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "既に出来た曲を作曲して、ベースを足した。", "explanation": "ここは〈既存の曲を編み直す〉の意味の編曲。作曲は新しく曲を作ることなので、既に出来た曲には合わない。"}, {"text": "パート譜を作曲して、団員に配った。", "explanation": "ここは〈楽譜を書き写す〉の意味の写譜。作曲は曲を生み出すことなので、既にある楽譜の写しには使えない。"}, {"text": "スタジオで鳥の声を作曲した。", "explanation": "ここは〈音を記録する〉の意味の録音。作曲は音楽を作ることなので、鳥の声には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "「をするとき」に入る作業名詞。リズムから決めるという創作の工程に合う。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は書かれた記録の物で、「楽譜をするとき」は動作として成り立たない。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音の並びを指し、「音階をするとき」は行為にならない。"}, {"text": "和音", "is_correct": false, "explanation": "和音は同時に鳴る音の組み合わせで、「和音をするとき」は不自然。"}], "explanations": {"作曲": "「をするとき」に入る作業名詞。リズムから決めるという創作の工程に合う。", "楽譜": "楽譜は書かれた記録の物で、「楽譜をするとき」は動作として成り立たない。", "音階": "音階は音の並びを指し、「音階をするとき」は行為にならない。", "和音": "和音は同時に鳴る音の組み合わせで、「和音をするとき」は不自然。"}, "sentence_index": 6, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休日、彼は駅前でギターを作曲した。", "explanation": "ここは〈楽器で曲を弾く〉の意味の演奏。作曲は曲を作ることなので、楽器を対象にはできない。"}, {"text": "指揮者が合唱団を作曲して発表会に臨んだ。", "explanation": "ここは〈演奏者を導く〉の意味の指揮。作曲は曲を作ることなので、人の集団には使えない。"}, {"text": "既にある録音を作曲して、楽譜にまとめた。", "explanation": "ここは〈聞いた音楽を楽譜に書き取る〉の意味の採譜。作曲は新しく作ることなので、既にある録音には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作曲を学ぶかったら、まず楽譜の読み方から始めるとよい。", "corrected_sentence": "作曲を学ぶなら、まず楽譜の読み方から始めるとよい。", "error_description": "「学ぶ」の条件形は「学ぶなら」。「学ぶかったら」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35925, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は作曲を集中するため、夜遅くまで机に向かった。", "corrected_sentence": "彼は作曲に集中するため、夜遅くまで机に向かった。", "error_description": "「集中する」は「に」を取る。「作曲を」は誤りで、正しくは「作曲に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「理論」を主題として示し、後ろの「立派だが」に続ける。"}, {"text": "を", "is_correct": false, "explanation": "「理論を立派だ」は成り立たず、形容の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「理論に立派だ」は不自然で、「立派だ」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すので、「理論で立派だ」は文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「理論」を主題として示し、後ろの「立派だが」に続ける。", "を": "「理論を立派だ」は成り立たず、形容の主語にならない。", "に": "「理論に立派だ」は不自然で、「立派だ」と結びつかない。", "で": "手段や場所を表すので、「理論で立派だ」は文に合わない。"}, "error_tags": {"を": "対象の格（述語と合わない）", "に": "帰着・相手の格", "で": "手段・場所の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "実践", "is_correct": true, "explanation": "考えを実際に行うことで、理論と対になる語。"}, {"text": "仮説", "is_correct": false, "explanation": "仮に立てた説明で、対義語ではない。"}, {"text": "感想", "is_correct": false, "explanation": "感じたことを表す語で、対義語ではない。"}, {"text": "体験", "is_correct": false, "explanation": "実際にしたことを表す語で、理論と対になる語ではない。"}], "correct_answer": "実践", "explanations": {"実践": "考えを実際に行うことで、理論と対になる語。", "仮説": "仮に立てた説明で、対義語ではない。", "感想": "感じたことを表す語で、対義語ではない。", "体験": "実際にしたことを表す語で、理論と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「理論」を目的語として「学ぶ」に続ける。"}, {"text": "が", "is_correct": false, "explanation": "「理論が学ぶ」は主語と動詞が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「理論へ学ぶ」は学ぶ対象を示す形ではない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表す形で、「理論と学ぶ」は学習の対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「理論」を目的語として「学ぶ」に続ける。", "が": "「理論が学ぶ」は主語と動詞が合わない。", "へ": "「理論へ学ぶ」は学ぶ対象を示す形ではない。", "と": "並列を表す形で、「理論と学ぶ」は学習の対象として不自然。"}, "error_tags": {"が": "主格（学ぶの主語にならない）", "へ": "方向（学習対象を示さない）", "と": "共同・並列の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "実践", "is_correct": true, "explanation": "考えを実際に行うことで、理論と対になる語。"}, {"text": "直感", "is_correct": false, "explanation": "考えずに感じ取ることで、対義語ではない。"}, {"text": "推測", "is_correct": false, "explanation": "推し量ることで、対義語ではない。"}, {"text": "歴史", "is_correct": false, "explanation": "過去の出来事の流れで、対義語ではない。"}], "correct_answer": "実践", "explanations": {"実践": "考えを実際に行うことで、理論と対になる語。", "直感": "考えずに感じ取ることで、対義語ではない。", "推測": "推し量ることで、対義語ではない。", "歴史": "過去の出来事の流れで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のしくみや考え方を、わかりやすくまとめたもの。", "primary_collocate": null, "pronunciation": "りろん", "ipa": "ɾiɾoɴ", "syllable_count": 3, "sentences": [{"text": "その理論は、実験の結果によって正しいと確かめられた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "その理論[りろん]は、実験[じっけん]の結果[けっか]によって正[ただ]しいと確[たし]かめられた。", "sentence_source": "generated"}, {"text": "理論は立派だが、実際にやってみると難しい。", "target_word": "理論", "complexity_tier": "T3", "furigana": "理論[りろん]は立派[りっぱ]だが、実際[じっさい]にやってみると難[むずか]しい。", "sentence_source": "generated"}, {"text": "先生は、難しい理論を図を使って説明してくれた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "先生[せんせい]は、難[むずか]しい理論[りろん]を図[ず]を使[つか]って説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "彼は新しい理論を発表して、学会で注目された。", "target_word": "理論", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい理論[りろん]を発表[はっぴょう]して、学会[がっかい]で注目[ちゅうもく]された。", "sentence_source": "generated"}, {"text": "理論だけでなく、現場の経験も大切だ。", "target_word": "理論", "complexity_tier": "T3", "furigana": "理論[りろん]だけでなく、現場[げんば]の経験[けいけん]も大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "この理論に従えば、天気の変化をある程度予想できる。", "target_word": "理論", "complexity_tier": "T3", "furigana": "この理論[りろん]に従[したが]えば、天気[てんき]の変化[へんか]をある程度[ていど]予想[よそう]できる。", "sentence_source": "generated"}, {"text": "彼女の理論には、いくつか弱い点がある。", "target_word": "理論", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の理論[りろん]には、いくつか弱[よわ]い点[てん]がある。", "sentence_source": "generated"}, {"text": "経済の理論を学んでも、すぐにお金持ちになれるわけではない。", "target_word": "理論", "complexity_tier": "T3", "furigana": "経済[けいざい]の理論[りろん]を学[まな]んでも、すぐにお金持[かねも]ちになれるわけではない。", "sentence_source": "generated"}, {"text": "理論と実際が合わなかったので、計画を見直した。", "target_word": "理論", "complexity_tier": "T3", "furigana": "理論[りろん]と実際[じっさい]が合[あ]わなかったので、計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "子どもの成長に関する理論は、時代とともに変わってきた。", "target_word": "理論", "complexity_tier": "T3", "furigana": "子[こ]どもの成長[せいちょう]に関[かん]する理論[りろん]は、時代[じだい]とともに変[か]わってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理論", "label": "base"}, {"form": "理論的", "label": "derived adjectival"}], "register": "neutral", "sense_fingerprint": "理論: 物事のしくみを筋道立ててまとめた考え（実践と対になる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理論", "is_correct": true, "explanation": "実験で正しいと確かめられた考えを指し、文に合う。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、実験で正しさを確かめる対象にならない。"}, {"text": "文章", "is_correct": false, "explanation": "文のまとまりを指し、実験で正しさを確かめる対象にならない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を指し、実験で正しいと確かめられる対象として文に合わない。"}], "explanations": {"理論": "実験で正しいと確かめられた考えを指し、文に合う。", "天候": "天気の状態を指し、実験で正しさを確かめる対象にならない。", "文章": "文のまとまりを指し、実験で正しさを確かめる対象にならない。", "機械": "装置を指し、実験で正しいと確かめられる対象として文に合わない。"}, "sentence_index": 0, "correct_answer": "理論"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は理論を注いで、子どもを大切に育てた。", "explanation": "ここは〈愛情〉の意味。「愛情を注ぐ」のように使い、理論は合わないので誤り。"}, {"text": "交通の理論を守って、事故を防ぐ。", "explanation": "ここは〈原則〉の意味。守るべき基本のきまりには原則を使い、理論は合わない。"}, {"text": "彼は理論を乱して、チームの秩序を壊した。", "explanation": "ここは〈秩序〉の意味。集団の決まりや並びには秩序を使い、理論は合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理論", "is_correct": true, "explanation": "彼女の考えの弱点を述べる文として、「理論には弱い点がある」と合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表し、「体重には弱い点がある」は意味をなさない。"}, {"text": "住所", "is_correct": false, "explanation": "居場所を表し、「住所には弱い点がある」は文に合わない。"}, {"text": "残高", "is_correct": false, "explanation": "預金などの残りを表し、「残高には弱い点がある」は文に合わない。"}], "explanations": {"理論": "彼女の考えの弱点を述べる文として、「理論には弱い点がある」と合う。", "体重": "体の重さを表し、「体重には弱い点がある」は意味をなさない。", "住所": "居場所を表し、「住所には弱い点がある」は文に合わない。", "残高": "預金などの残りを表し、「残高には弱い点がある」は文に合わない。"}, "sentence_index": 6, "correct_answer": "理論"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は理論を働かせて、困った人を助けた。", "explanation": "ここは〈知恵〉の意味。「知恵を働かせる」のように使い、理論は合わない。"}, {"text": "その子の笑顔は、強い理論を残した。", "explanation": "ここは〈印象〉の意味。「強い印象を残す」のように使い、理論は合わない。"}, {"text": "彼の手紙は、喜びの理論を伝えていた。", "explanation": "ここは〈感情〉の意味。「喜びの感情を伝える」のように使い、理論は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この理論を従えば、天気をある程度予想できる。", "corrected_sentence": "この理論に従えば、天気をある程度予想できる。", "error_description": "「従う」は「〜に従う」の形を取る。「理論を従えば」の「を」は誤りで、正しくは「理論に従えば」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35952, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その理論な説明は、実際には役に立たない。", "corrected_sentence": "その理論的な説明は、実際には役に立たない。", "error_description": "名詞の「理論」を形容動詞にするには「理論的な」が必要。「理論な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『知らない』の対象になるルールを示すので『を』が正解。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、〈知らない〉の対象にはならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や場所を示し、知る対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示し、知る対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "『知らない』の対象になるルールを示すので『を』が正解。", "と": "「と」は並列や相手を示し、〈知らない〉の対象にはならないので合わない。", "に": "『に』は相手や場所を示し、知る対象にはならない。", "で": "『で』は場所や手段を示し、知る対象には合わない。"}, "error_tags": {"に": "『に』は相手や場所を示し、知る対象にはならない。", "で": "『で』は場所や手段を示し、知る対象には合わない。", "と": "並列・相手の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『忘れる』の対象になるルールを示すので『を』が正解。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、忘れる対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は共にする相手を示し、忘れる対象には合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『忘れる』の対象になるルールを示すので『を』が正解。", "へ": "『へ』は方向を示し、忘れる対象には使えない。", "と": "『と』は共にする相手を示し、忘れる対象には合わない。", "より": "『より』は比較を示し、ここでは文が成り立たない。"}, "error_tags": {"へ": "『へ』は方向を示し、忘れる対象には使えない。", "と": "『と』は共にする相手を示し、忘れる対象には合わない。", "より": "『より』は比較を示し、ここでは文が成り立たない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで決めた、やることの順番ややり方のことです。", "primary_collocate": null, "pronunciation": "るーる", "ipa": "ɾɯːɾɯ", "syllable_count": 3, "sentences": [{"text": "みんなで話して、教室のルールを決めました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "みんなで話[はな]して、教室[きょうしつ]のルールを決[き]めました。", "sentence_source": "generated"}, {"text": "ゲームのルールを知らないので、教えてください。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ゲームのルールを知[し]らないので、教[おし]えてください。", "sentence_source": "generated"}, {"text": "この公園には、犬を放してはいけないルールがあります。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "この公園[こうえん]には、犬[いぬ]を放[はな]してはいけないルールがあります。", "sentence_source": "generated"}, {"text": "ルールを守らないと、友だちと遊べません。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ルールを守[まも]らないと、友[とも]だちと遊[あそ]べません。", "sentence_source": "generated"}, {"text": "新しいルールができて、全員が早く来るようになりました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "新[あたら]しいルールができて、全員[ぜんいん]が早[はや]く来[く]るようになりました。", "sentence_source": "generated"}, {"text": "サッカーのルールは、小さい子にも分かりやすいです。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "サッカーのルールは、小[ちい]さい子[こ]にも分[わ]かりやすいです。", "sentence_source": "generated"}, {"text": "図書館では、静かにするルールです。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "図書館[としょかん]では、静[しず]かにするルールです。", "sentence_source": "generated"}, {"text": "ルールを忘れた弟が、先生に注意されました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ルールを忘[わす]れた弟[おとうと]が、先生[せんせい]に注意[ちゅうい]されました。", "sentence_source": "generated"}, {"text": "家のルールで、夜九時以降はテレビを見られません。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "家[いえ]のルールで、夜[よる]九時[くじ]以降[いこう]はテレビを見[み]られません。", "sentence_source": "generated"}, {"text": "みんなが同じルールに従えば、けんかになりません。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "みんなが同[おな]じルールに従[したが]えば、けんかになりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ルール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "みんなで決めたやり方や決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ルール", "is_correct": true, "explanation": "クラスで決める決まりごとを指すので正解。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、話し合って決める決まりごとではないので合わない。"}, {"text": "ほうき", "is_correct": false, "explanation": "掃除道具で、決まりごとではないので合わない。"}, {"text": "ドア", "is_correct": false, "explanation": "建具で、決まりごとではないので合わない。"}], "explanations": {"ルール": "クラスで決める決まりごとを指すので正解。", "窓": "建具で、話し合って決める決まりごとではないので合わない。", "ほうき": "掃除道具で、決まりごとではないので合わない。", "ドア": "建具で、決まりごとではないので合わない。"}, "sentence_index": 0, "correct_answer": "ルール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合で手を使ったので、ルールを受けました。", "explanation": "ここは〈ペナルティ〉（罰）の意味。ルールは受けるものではないので合わない。"}, {"text": "仕事のルールが速すぎて、ついていけません。", "explanation": "ここは〈ペース〉（進む速さ）の意味。ルールは速さを表さないので合わない。"}, {"text": "今月のルールを達成しました。", "explanation": "ここは〈ノルマ〉（達成すべき量）の意味。ルールは達成するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ルール", "is_correct": true, "explanation": "静かにすることを定めた決まりなので正解。"}, {"text": "黒板", "is_correct": false, "explanation": "教室の備品で、静かにする決まりではないので合わない。"}, {"text": "ベル", "is_correct": false, "explanation": "合図の道具で、静かにする決まりではないので合わない。"}, {"text": "ボール", "is_correct": false, "explanation": "遊具で、静かにする決まりではないので合わない。"}], "explanations": {"ルール": "静かにすることを定めた決まりなので正解。", "黒板": "教室の備品で、静かにする決まりではないので合わない。", "ベル": "合図の道具で、静かにする決まりではないので合わない。", "ボール": "遊具で、静かにする決まりではないので合わない。"}, "sentence_index": 6, "correct_answer": "ルール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "指輪に、赤いルールをはめました。", "explanation": "ここは〈ルビー〉（宝石）の意味。ルールは指輪にはめるものではないので合わない。"}, {"text": "休みの日に、新しいルールを飼いました。", "explanation": "ここは〈ペット〉の意味。ルールは飼えるものではないので合わない。"}, {"text": "サッカーで、ルールを蹴って、ゴールに入れました。", "explanation": "ここは〈ボール〉の意味。ルールは蹴るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が決めたルールを、みんなで従いました。", "corrected_sentence": "先生が決めたルールに、みんなで従いました。", "error_description": "『従う』は『に』を取る。『を』は誤りで、正しくは『に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35958, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この大会のルールが、審判が選手に説明しました。", "corrected_sentence": "この大会のルールを、審判が選手に説明しました。", "error_description": "『説明する』は目的語に『を』を取る。『が』は誤りで、正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ルールを主題として示し、『違う』と述べる文なので『は』が正解。"}, {"text": "を", "is_correct": false, "explanation": "『違う』は目的語を取らないので、『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は『違う』の相手を示すが、ここではルールに続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、〈違う〉の主語にはならないので合わない。"}], "correct_answer": "は", "explanations": {"は": "ルールを主題として示し、『違う』と述べる文なので『は』が正解。", "を": "『違う』は目的語を取らないので、『を』は合わない。", "に": "『に』は『違う』の相手を示すが、ここではルールに続かない。", "へ": "「へ」は方向を示し、〈違う〉の主語にはならないので合わない。"}, "error_tags": {"を": "『違う』は目的語を取らないので、『を』は合わない。", "に": "『に』は『違う』の相手を示すが、ここではルールに続かない。", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "試験のルールを話題として示し、確認を求める文なので『は』が正解。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、ルールを主題として表せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は〈確認してください〉の目的語にならず、文が成り立たないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、ここでは合わない。"}], "correct_answer": "は", "explanations": {"は": "試験のルールを話題として示し、確認を求める文なので『は』が正解。", "へ": "『へ』は方向を示し、ルールを主題として表せない。", "が": "「が」は〈確認してください〉の目的語にならず、文が成り立たないので合わない。", "より": "『より』は比較を示し、ここでは合わない。"}, "error_tags": {"へ": "『へ』は方向を示し、ルールを主題として表せない。", "より": "『より』は比較を示し、ここでは合わない。", "が": "主語の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの、決まった順序や方法。", "primary_collocate": null, "pronunciation": "るーる", "ipa": "ɾɯːɾɯ", "syllable_count": 3, "sentences": [{"text": "会議のルールに従って、順番に意見を言いました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "会議[かいぎ]のルールに従[したが]って、順番[じゅんばん]に意見[いけん]を言[い]いました。", "sentence_source": "generated"}, {"text": "ごみを出すルールは、町ごとに違います。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ごみを出[だ]すルールは、町[まち]ごとに違[ちが]います。", "sentence_source": "generated"}, {"text": "この計算には、決まったルールがあります。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "この計算[けいさん]には、決[き]まったルールがあります。", "sentence_source": "generated"}, {"text": "ルールを変えると、仕事の流れも変わります。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ルールを変[か]えると、仕事[しごと]の流[なが]れも変[か]わります。", "sentence_source": "generated"}, {"text": "会社の新しいルールで、書類は必ずメールで送ります。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の新[あたら]しいルールで、書類[しょるい]は必[かなら]ずメールで送[おく]ります。", "sentence_source": "generated"}, {"text": "道路を渡るときのルールを、学校で習いました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "道路[どうろ]を渡[わた]るときのルールを、学校[がっこう]で習[なら]いました。", "sentence_source": "generated"}, {"text": "ルールが多すぎて、新しい人は覚えきれません。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ルールが多[おお]すぎて、新[あたら]しい人[ひと]は覚[おぼ]えきれません。", "sentence_source": "generated"}, {"text": "試験のルールは、最初の説明で確認してください。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "試験[しけん]のルールは、最初[さいしょ]の説明[せつめい]で確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "ルールどおりに手続きをすれば、問題は起きません。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "ルールどおりに手続[てつづ]きをすれば、問題[もんだい]は起[お]きません。", "sentence_source": "generated"}, {"text": "チームのルールを作って、仕事の順番をはっきりさせました。", "target_word": "ルール", "complexity_tier": "T3", "furigana": "チームのルールを作[つく]って、仕事[しごと]の順番[じゅんばん]をはっきりさせました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ルール", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事を行うときの決まった順序や方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ルール", "is_correct": true, "explanation": "会議で従う決まりや進め方を指すので正解。"}, {"text": "ケーキ", "is_correct": false, "explanation": "菓子で、会議の進め方に従うものではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、従う対象ではないので合わない。"}, {"text": "ほうき", "is_correct": false, "explanation": "掃除道具で、従う対象ではないので合わない。"}], "explanations": {"ルール": "会議で従う決まりや進め方を指すので正解。", "ケーキ": "菓子で、会議の進め方に従うものではないので合わない。", "窓": "建具で、従う対象ではないので合わない。", "ほうき": "掃除道具で、従う対象ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ルール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "書類のルールを、窓口で行いました。", "explanation": "ここは〈手続き〉の意味。ルールは窓口で行うものではないので合わない。"}, {"text": "ルールを押すと、画面が切り替わります。", "explanation": "ここは〈スイッチ〉（押して操作するもの）の意味。ルールは押して操作するものではないので合わない。"}, {"text": "バスのルールを待ちました。", "explanation": "ここは〈順番〉（並ぶ順）の意味。ルールは待つものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ルール", "is_correct": true, "explanation": "覚えにくいほど多い決まりごとを指すので正解。"}, {"text": "雨", "is_correct": false, "explanation": "天候を表す語で、覚える対象ではないので合わない。"}, {"text": "雪", "is_correct": false, "explanation": "天候を表す語で、覚える対象ではないので合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "教室の備品で、覚える対象ではないので合わない。"}], "explanations": {"ルール": "覚えにくいほど多い決まりごとを指すので正解。", "雨": "天候を表す語で、覚える対象ではないので合わない。", "雪": "天候を表す語で、覚える対象ではないので合わない。", "黒板": "教室の備品で、覚える対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "ルール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキのルールを混ぜました。", "explanation": "ここは〈材料〉の意味。ルールは混ぜるものではないので合わない。"}, {"text": "ルールを開けてから、みんなで飲みました。", "explanation": "ここは〈ワイン〉（瓶入りの飲み物）の意味。ルールは開けたり飲んだりするものではないので合わない。"}, {"text": "ルールを鳴らすと、授業が始まります。", "explanation": "ここは〈チャイム〉（合図の音）の意味。ルールは鳴らせないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
