INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいルールが、全員に配りました。", "corrected_sentence": "新しいルールを、全員に配りました。", "error_description": "『配る』は目的語に『を』を取る。『が』は誤りで、正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "行き先を示す「へ」が、お祈りに行く方向を正しく表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、移動する行き先を示せない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」では、行き先を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、行き先と逆の意味になる。"}], "correct_answer": "へ", "explanations": {"へ": "行き先を示す「へ」が、お祈りに行く方向を正しく表す。", "を": "目的語の「を」では、移動する行き先を示せない。", "と": "共同の「と」では、行き先を表せない。", "から": "起点の「から」では、行き先と逆の意味になる。"}, "error_tags": {"を": "目的語", "と": "共同・引用", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "教会に通うという結びつきを示す「に」が入る。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」では、通う先を示す形にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では、通う先を示せず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、通う先と合わない。"}], "correct_answer": "に", "explanations": {"に": "教会に通うという結びつきを示す「に」が入る。", "で": "手段や場所の「で」では、通う先を示す形にならない。", "の": "連体の「の」では、通う先を示せず文が成り立たない。", "より": "比較の「より」では、通う先と合わない。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "教会は、キリスト教の信者が集まってお祈りをする建物です。", "primary_collocate": null, "pronunciation": "きょうかい", "ipa": "kʲoːkai", "syllable_count": 4, "sentences": [{"text": "日曜日の朝、信者たちは教会に集まって祈ります。", "target_word": "教会", "complexity_tier": "T3", "furigana": "日曜日(にちようび)の朝(あさ)、信者(しんじゃ)たちは教会(きょうかい)に集(あつ)まって祈(いの)ります。", "sentence_source": "generated"}, {"text": "私の祖母は毎週、近くの教会へお祈りに行く。", "target_word": "教会", "complexity_tier": "T3", "furigana": "私(わたし)の祖母(そぼ)は毎週(まいしゅう)、近(ちか)くの教会(きょうかい)へお祈(いの)りに行(い)く。", "sentence_source": "generated"}, {"text": "町の教会では、毎朝、鐘が鳴って信者を呼ぶ。", "target_word": "教会", "complexity_tier": "T3", "furigana": "町(まち)の教会(きょうかい)では、毎朝(まいあさ)、鐘(かね)が鳴(な)って信者(しんじゃ)を呼(よ)ぶ。", "sentence_source": "generated"}, {"text": "教会で静かに手を合わせて、家族の健康を祈った。", "target_word": "教会", "complexity_tier": "T3", "furigana": "教会(きょうかい)で静(しず)かに手(て)を合(あ)わせて、家族(かぞく)の健康(けんこう)を祈(いの)った。", "sentence_source": "generated"}, {"text": "雨の日でも、多くの人が教会に来て歌をうたった。", "target_word": "教会", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)でも、多(おお)くの人(ひと)が教会(きょうかい)に来(き)て歌(うた)をうたった。", "sentence_source": "generated"}, {"text": "教会の中は静かで、祈る人の声だけが聞こえた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "教会(きょうかい)の中(なか)は静(しず)かで、祈(いの)る人(ひと)の声(こえ)だけが聞(き)こえた。", "sentence_source": "generated"}, {"text": "旅行中に入った教会で、お祈りをしている人たちを見た。", "target_word": "教会", "complexity_tier": "T3", "furigana": "旅行中(りょこうちゅう)に入(はい)った教会(きょうかい)で、お祈(いの)りをしている人(ひと)たちを見(み)た。", "sentence_source": "generated"}, {"text": "新しい牧師が来てから、教会に通う人が増えた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "新(あたら)しい牧師(ぼくし)が来(き)てから、教会(きょうかい)に通(かよ)う人(ひと)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "友達は教会でボランティアをして、信者の食事を作っている。", "target_word": "教会", "complexity_tier": "T3", "furigana": "友達(ともだち)は教会(きょうかい)でボランティアをして、信者(しんじゃ)の食事(しょくじ)を作(つく)っている。", "sentence_source": "generated"}, {"text": "毎週教会に通うので、日曜日は予定を入れない。", "target_word": "教会", "complexity_tier": "T3", "furigana": "毎週(まいしゅう)教会(きょうかい)に通(かよ)うので、日曜日(にちようび)は予定(よてい)を入(い)れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教会", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "信者が集まって祈る場所としてのキリスト教の建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "信者が集まって祈る建物を指し、集まるという文に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙に集まるという文は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気に集まるとは言えず、文の意味に合わない。"}, {"text": "財布", "is_correct": false, "explanation": "財布に集まるのは不自然で、祈る場所の文脈に合わない。"}], "explanations": {"教会": "信者が集まって祈る建物を指し、集まるという文に合う。", "手紙": "手紙に集まるという文は成り立たない。", "天気": "天気に集まるとは言えず、文の意味に合わない。", "財布": "財布に集まるのは不自然で、祈る場所の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝、教会でお経をあげる。", "explanation": "ここは〈寺〉の意味。お経は仏教の寺で唱えるもので、キリスト教の教会とは合わない。"}, {"text": "毎年、教会で鈴を鳴らして参拝した。", "explanation": "ここは〈神社〉の意味。鈴を鳴らして参拝するのは神社の習慣で、教会とは合わない。"}, {"text": "大事な試験の前に、教会で筆記用具を買った。", "explanation": "ここは〈文房具店〉の意味。筆記用具を買う場面には教会は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "旅行中に入った建物の場所として、祈っている人を見た文に合う。"}, {"text": "切符", "is_correct": false, "explanation": "切符で祈っている人を見たという意味にはならない。"}, {"text": "金庫", "is_correct": false, "explanation": "金庫でお祈りをしている人を見たという文にならず、場所として合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫で祈るという文の内容は成り立たない。"}], "explanations": {"教会": "旅行中に入った建物の場所として、祈っている人を見た文に合う。", "切符": "切符で祈っている人を見たという意味にはならない。", "金庫": "金庫でお祈りをしている人を見たという文にならず、場所として合わない。", "冷蔵庫": "冷蔵庫で祈るという文の内容は成り立たない。"}, "sentence_index": 6, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎週教会に通って治療を受けている。", "explanation": "ここは〈病院〉の意味。治療を受ける場所に教会は使わない。"}, {"text": "毎月教会でカットしてもらう。", "explanation": "ここは〈美容院〉の意味。髪を切る店に教会は使わない。"}, {"text": "出発の時刻まで、教会で飛行機を待った。", "explanation": "ここは〈空港〉の意味。飛行機を待つ場所は空港で、教会ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎週、友人と教会を行く。", "corrected_sentence": "毎週、友人と教会に行く。", "error_description": "「行く」の行き先は「に」で示す。「教会を行く」は誤りで、「教会に行く」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35966, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の教会を、毎週日曜日、鐘が鳴って信者を呼ぶ。", "corrected_sentence": "町の教会では、毎週日曜日、鐘が鳴って信者を呼ぶ。", "error_description": "鐘が鳴る場所は「教会では」の「では」で示す。「教会を」は目的語となり、場所を表せず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を表す「で」。行事が行われる会場を示すので、「教会で行われた」が自然。"}, {"text": "に", "is_correct": false, "explanation": "着点や存在の場所を示す「に」。「行われた」の会場には「で」が必要なので合わない。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す「を」。「行われた」は対象を取らないので、「教会を行われた」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「教会へ行われた」では行事の会場という意味にならない。"}], "correct_answer": "で", "explanations": {"で": "場所を表す「で」。行事が行われる会場を示すので、「教会で行われた」が自然。", "に": "着点や存在の場所を示す「に」。「行われた」の会場には「で」が必要なので合わない。", "を": "動作の対象を示す「を」。「行われた」は対象を取らないので、「教会を行われた」は成り立たない。", "へ": "方向を示す「へ」。「教会へ行われた」では行事の会場という意味にならない。"}, "error_tags": {"に": "着点・存在", "を": "動作の対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「教会の中」で、教会の内部という関係を表す。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を表す「と」。「教会と中では」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を表す「より」。「教会より中では」では位置関係が合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点や経由を表す「から」。「教会から中では」では場所の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「教会の中」で、教会の内部という関係を表す。", "と": "並列や共同を表す「と」。「教会と中では」では意味が通らない。", "より": "比較や起点を表す「より」。「教会より中では」では位置関係が合わない。", "から": "起点や経由を表す「から」。「教会から中では」では場所の関係が成り立たない。"}, "error_tags": {"と": "並列・共同", "より": "比較・起点", "から": "起点・経由"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "キリスト教の礼拝や儀式が行われる建物。", "primary_collocate": null, "pronunciation": "きょうかい", "ipa": "kʲoːkai", "syllable_count": 4, "sentences": [{"text": "二人は海の近くの教会で結婚式を挙げた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "二人(ふたり)は海(うみ)の近(ちか)くの教会(きょうかい)で結婚式(けっこんしき)を挙(あ)げた。", "sentence_source": "generated"}, {"text": "祖父の葬式は、町の古い教会で行われた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "祖父(そふ)の葬式(そうしき)は、町(まち)の古(ふる)い教会(きょうかい)で行(おこな)われた。", "sentence_source": "generated"}, {"text": "この教会は、石を積んで百年前に建てられた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "この教会(きょうかい)は、石(いし)を積(つ)んで百年(ひゃくねん)前(まえ)に建(た)てられた。", "sentence_source": "generated"}, {"text": "教会のステンドグラスから、美しい光が差していた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "教会(きょうかい)のステンドグラスから、美(うつく)しい光(ひかり)が差(さ)していた。", "sentence_source": "generated"}, {"text": "クリスマスの夜、教会で特別な礼拝が行われる。", "target_word": "教会", "complexity_tier": "T3", "furigana": "クリスマスの夜(よる)、教会(きょうかい)で特別(とくべつ)な礼拝(れいはい)が行(おこな)われる。", "sentence_source": "generated"}, {"text": "教会の高い塔は、遠くからでもよく見える。", "target_word": "教会", "complexity_tier": "T3", "furigana": "教会(きょうかい)の高(たか)い塔(とう)は、遠(とお)くからでもよく見(み)える。", "sentence_source": "generated"}, {"text": "赤ちゃんの洗礼は、家の近くの教会で受けた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんの洗礼(せんれい)は、家(いえ)の近(ちか)くの教会(きょうかい)で受(う)けた。", "sentence_source": "generated"}, {"text": "古い教会の中では、パイプオルガンの音が響いた。", "target_word": "教会", "complexity_tier": "T3", "furigana": "古(ふる)い教会(きょうかい)の中(なか)では、パイプオルガンの音(おと)が響(ひび)いた。", "sentence_source": "generated"}, {"text": "観光客が多いので、この教会は昼間だけ見学できる。", "target_word": "教会", "complexity_tier": "T3", "furigana": "観光客(かんこうきゃく)が多(おお)いので、この教会(きょうかい)は昼間(ひるま)だけ見学(けんがく)できる。", "sentence_source": "generated"}, {"text": "戦争で壊れた教会が、ようやく建て直された。", "target_word": "教会", "complexity_tier": "T3", "furigana": "戦争(せんそう)で壊(こわ)れた教会(きょうかい)が、ようやく建(た)て直(なお)された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教会", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "礼拝・結婚式・葬式などの儀式が行われる、塔や窓のあるキリスト教の建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: パイプオルガン (Zipf 2.49)','sentence 9 above tier T2: contains vocabulary far above tier T2: 建て直さ (Zipf 1.69)']::text[], 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正解。キリスト教式の結婚式が行われる建物として文に合う。"}, {"text": "図書館", "is_correct": false, "explanation": "図書館は結婚式の会場にならないので、文脈に合わない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は医療施設で、結婚式を挙げる場所としては合わない。"}, {"text": "空港", "is_correct": false, "explanation": "空港は飛行機の発着場で、結婚式の会場としては合わない。"}], "explanations": {"教会": "正解。キリスト教式の結婚式が行われる建物として文に合う。", "図書館": "図書館は結婚式の会場にならないので、文脈に合わない。", "病院": "病院は医療施設で、結婚式を挙げる場所としては合わない。", "空港": "空港は飛行機の発着場で、結婚式の会場としては合わない。"}, "sentence_index": 0, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本サッカー教会が、新しい試合の規則を発表した。", "explanation": "ここは〈協会〉（団体）の意味。教会は礼拝の建物を指すので、規則を発表する団体の名前には合わない。"}, {"text": "この教会では、住職が読経して法要を行う。", "explanation": "ここは仏教の寺院の場面で、教会（キリスト教の礼拝所）の語義ではない。住職や読経は教会には合わない。"}, {"text": "教会の鳥居をくぐり、拝殿で賽銭を入れた。", "explanation": "ここは神社の場面で、教会（キリスト教の礼拝所）の語義ではない。鳥居・拝殿・賽銭は教会には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正解。洗礼を受ける場所として文に合う。"}, {"text": "駅", "is_correct": false, "explanation": "駅は乗降や乗り換えの場所で、洗礼を受ける場所としては合わない。"}, {"text": "体育館", "is_correct": false, "explanation": "体育館はスポーツ施設で、洗礼の場所としては合わない。"}, {"text": "動物園", "is_correct": false, "explanation": "動物園は動物を見る施設で、洗礼の場所としては合わない。"}], "explanations": {"教会": "正解。洗礼を受ける場所として文に合う。", "駅": "駅は乗降や乗り換えの場所で、洗礼を受ける場所としては合わない。", "体育館": "体育館はスポーツ施設で、洗礼の場所としては合わない。", "動物園": "動物園は動物を見る施設で、洗礼の場所としては合わない。"}, "sentence_index": 6, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この教会では、金曜の昼に皆で集まり、メッカに向かって礼拝する。", "explanation": "ここはイスラム教の礼拝所の場面で、教会（キリスト教）の語義ではない。金曜礼拝やメッカへの礼拝は教会には合わない。"}, {"text": "全国の教会が集まり、新しい会長を選んだ。", "explanation": "ここは〈協会〉（団体）の意味。会長を選ぶ団体の話で、礼拝の建物である教会とは別の語義。"}, {"text": "教会の前で、巫女が舞を奉納した。", "explanation": "ここは神道の神殿の場面で、教会（キリスト教）の語義ではない。巫女や舞の奉納は教会には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は毎週日曜日に教会に通ている。", "corrected_sentence": "彼女は毎週日曜日に教会に通っている。", "error_description": "正しくは「通っている」。促音の「っ」を落として「通ている」にすると誤った形になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35967, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人は町外れの小さな教会に式を挙げた。", "corrected_sentence": "友人は町外れの小さな教会で式を挙げた。", "error_description": "正しくは「教会で式を挙げた」。「挙げる」の場所を表すのは「で」で、「に」にすると誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不要", "is_correct": true, "explanation": "正解。「必要」の対義語で、必要ではない、いらないという意味になる。"}, {"text": "自由", "is_correct": false, "explanation": "束縛されない状態を表す語で、「必要」の対義語ではない。"}, {"text": "幸福", "is_correct": false, "explanation": "満ち足りた状態を表す語で、「必要」とは対義関係にない。"}, {"text": "静寂", "is_correct": false, "explanation": "物音がない状態を表す語で、「必要」とは反対の関係にない。"}], "correct_answer": "不要", "explanations": {"不要": "正解。「必要」の対義語で、必要ではない、いらないという意味になる。", "自由": "束縛されない状態を表す語で、「必要」の対義語ではない。", "幸福": "満ち足りた状態を表す語で、「必要」とは対義関係にない。", "静寂": "物音がない状態を表す語で、「必要」とは反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不要", "is_correct": true, "explanation": "正解。「必要」の対義語で、いらないという反対の意味になる。"}, {"text": "愛情", "is_correct": false, "explanation": "相手を大切に思う気持ちを表す語で、「必要」の対義語ではない。"}, {"text": "音楽", "is_correct": false, "explanation": "音を組み合わせた芸術を表す語で、「必要」とは対義関係にない。"}, {"text": "結果", "is_correct": false, "explanation": "物事の終わりの状態を表す語で、「必要」の対義語ではない。"}], "correct_answer": "不要", "explanations": {"不要": "正解。「必要」の対義語で、いらないという反対の意味になる。", "愛情": "相手を大切に思う気持ちを表す語で、「必要」の対義語ではない。", "音楽": "音を組み合わせた芸術を表す語で、「必要」とは対義関係にない。", "結果": "物事の終わりの状態を表す語で、「必要」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、それがなくてはならないこと。", "primary_collocate": null, "pronunciation": "ひつよう", "ipa": "çit͡sɯjoː", "syllable_count": 4, "sentences": [{"text": "海外に行くには、パスポートが必要です。", "target_word": "必要", "complexity_tier": "T3", "furigana": "海外(かいがい)に行(い)くには、パスポートが必要(ひつよう)です。", "sentence_source": "generated"}, {"text": "傘は必要ないと思ったが、帰りに雨が降ってきた。", "target_word": "必要", "complexity_tier": "T3", "furigana": "傘(かさ)は必要(ひつよう)ないと思(おも)ったが、帰(かえ)りに雨(あめ)が降(ふ)ってきた。", "sentence_source": "generated"}, {"text": "明日は早く起きる必要があるので、今夜は早く寝る。", "target_word": "必要", "complexity_tier": "T3", "furigana": "明日(あした)は早(はや)く起(お)きる必要(ひつよう)があるので、今夜(こんや)は早(はや)く寝(ね)る。", "sentence_source": "generated"}, {"text": "薬を飲むときは、水が必要だ。", "target_word": "必要", "complexity_tier": "T3", "furigana": "薬(くすり)を飲(の)むときは、水(みず)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "この仕事には、毎日の練習が必要になる。", "target_word": "必要", "complexity_tier": "T3", "furigana": "この仕事(しごと)には、毎日(まいにち)の練習(れんしゅう)が必要(ひつよう)になる。", "sentence_source": "generated"}, {"text": "買い物のとき、袋が必要なら言ってください。", "target_word": "必要", "complexity_tier": "T3", "furigana": "買(か)い物(もの)のとき、袋(ふくろ)が必要(ひつよう)なら言(い)ってください。", "sentence_source": "generated"}, {"text": "手伝いが必要なときは、いつでも呼んでください。", "target_word": "必要", "complexity_tier": "T3", "furigana": "手伝(てつだ)いが必要(ひつよう)なときは、いつでも呼(よ)んでください。", "sentence_source": "generated"}, {"text": "この機械は簡単なので、説明書を全部読む必要はありません。", "target_word": "必要", "complexity_tier": "T3", "furigana": "この機械(きかい)は簡単(かんたん)なので、説明書(せつめいしょ)を全部(ぜんぶ)読(よ)む必要(ひつよう)はありません。", "sentence_source": "generated"}, {"text": "会議の前に、資料を準備する必要がある。", "target_word": "必要", "complexity_tier": "T3", "furigana": "会議(かいぎ)の前(まえ)に、資料(しりょう)を準備(じゅんび)する必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "必要なものだけを、かばんに入れて出かけた。", "target_word": "必要", "complexity_tier": "T3", "furigana": "必要(ひつよう)なものだけを、かばんに入(い)れて出(で)かけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "必要", "label": "基本形"}, {"form": "必要だ", "label": "断定形"}, {"form": "必要な", "label": "連体形"}, {"form": "必要で", "label": "連用形"}, {"form": "必要に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "ある目的のために、それがなければ困るという欠かせなさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正解。パスポートが行くのに欠かせないという文脈に合う。"}, {"text": "有名", "is_correct": false, "explanation": "「パスポートが有名だ」では文が成り立たず、欠かせなさの意味にならない。"}, {"text": "静か", "is_correct": false, "explanation": "静かは様子を表す語で、パスポートの性質としては合わない。"}, {"text": "大量", "is_correct": false, "explanation": "大量は数の多さを表し、必要性の意味にならないので合わない。"}], "explanations": {"必要": "正解。パスポートが行くのに欠かせないという文脈に合う。", "有名": "「パスポートが有名だ」では文が成り立たず、欠かせなさの意味にならない。", "静か": "静かは様子を表す語で、パスポートの性質としては合わない。", "大量": "大量は数の多さを表し、必要性の意味にならないので合わない。"}, "sentence_index": 0, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもを助けるため、必要に走った。", "explanation": "ここは別の語「必死」（全力で）の語を当てた誤用。「必要」にはこの意味はなく、副詞としても使えない。"}, {"text": "決勝は必要の気持ちで臨もう。", "explanation": "ここは別の語「必勝」（必ず勝つ）の語を当てた誤用。「必要」にはこの意味はない。"}, {"text": "矢は必要を狙って放たれた。", "explanation": "ここは別の語「必中」（必ず命中する）の語を当てた誤用。「必要」にはこの意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正解。手伝いが欠かせない場合を表し、文に合う。"}, {"text": "上品", "is_correct": false, "explanation": "上品は品のよさを表す語で、「手伝いが上品なとき」では意味が通らない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るい性格を表す語で、手伝いの状況には合わない。"}, {"text": "不可解", "is_correct": false, "explanation": "不可解は理解できないことを表し、「手伝いが不可解なとき」では文が成り立たない。"}], "explanations": {"必要": "正解。手伝いが欠かせない場合を表し、文に合う。", "上品": "上品は品のよさを表す語で、「手伝いが上品なとき」では意味が通らない。", "陽気": "陽気は明るい性格を表す語で、手伝いの状況には合わない。", "不可解": "不可解は理解できないことを表し、「手伝いが不可解なとき」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故は必要に起きた。", "explanation": "ここは別の語「必然」（避けられず起こる）を当てた誤用。「必要」にはこの意味はなく、副詞としても使えない。"}, {"text": "英語は必要に履修する科目だ。", "explanation": "ここは別の語「必修」（必ず履修する）を当てた誤用。「必要」にはこの意味はない。"}, {"text": "応募書類は締め切りまでに必要に届くよう送ってください。", "explanation": "ここは別の語「必着」（期限までに届く）を当てた誤用。「必要」にはこの意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日の朝は、早く起きる必要にあります。", "corrected_sentence": "明日の朝は、早く起きる必要があります。", "error_description": "正しくは「必要がある」。「必要」に続く助詞は「が」で、「に」にすると「必要にある」となり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35968, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事前に必要だ書類をそろえてください。", "corrected_sentence": "事前に必要な書類をそろえてください。", "error_description": "正しくは「必要な書類」。名詞を修飾する形は「必要な」で、「必要だ」は名詞に直接続けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒む", "is_correct": true, "explanation": "正解。依頼や誘いを受けず退ける意味で、「応ずる」の対義語。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、「応ずる」と対義関係にない。"}, {"text": "磨く", "is_correct": false, "explanation": "物をみがく動詞で、「応ずる」と対義関係にない。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える動詞で、「応ずる」と対義関係にない。"}], "correct_answer": "拒む", "explanations": {"拒む": "正解。依頼や誘いを受けず退ける意味で、「応ずる」の対義語。", "眠る": "睡眠を表す動詞で、「応ずる」と対義関係にない。", "磨く": "物をみがく動詞で、「応ずる」と対義関係にない。", "数える": "数を数える動詞で、「応ずる」と対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒む", "is_correct": true, "explanation": "正解。市民の声を受けず退ける意味で、「応ずる」の対義語。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出して歌う動詞で、「応ずる」と対義関係にない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水中で体を動かす動詞で、「応ずる」と対義関係にない。"}, {"text": "削る", "is_correct": false, "explanation": "物を削る動詞で、「応ずる」と対義関係にない。"}], "correct_answer": "拒む", "explanations": {"拒む": "正解。市民の声を受けず退ける意味で、「応ずる」の対義語。", "歌う": "声を出して歌う動詞で、「応ずる」と対義関係にない。", "泳ぐ": "水中で体を動かす動詞で、「応ずる」と対義関係にない。", "削る": "物を削る動詞で、「応ずる」と対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かに心や体を動かして、ちゃんと反応すること。", "primary_collocate": null, "pronunciation": "おうずる", "ipa": "oːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "彼は私の呼びかけに応ずるため、すぐに振り返った。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の呼[よ]びかけに応[おう]ずるため、すぐに振[ふ]り返[かえ]った。", "sentence_source": "generated"}, {"text": "社長はインタビューの依頼に快く応ずることにした。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "社長[しゃちょう]はインタビューの依頼[いらい]に快[こころよ]く応[おう]ずることにした。", "sentence_source": "generated"}, {"text": "警察の呼び出しに応ずることなく、男は翌日逮捕された。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "警察[けいさつ]の呼[よ]び出[だ]しに応[おう]ずることなく、男[おとこ]は翌日[よくじつ]逮捕[たいほ]された。", "sentence_source": "generated"}, {"text": "友達の誘いに応ずる形で、日曜日のコンサートへ行った。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "友達[ともだち]の誘[さそ]いに応[おう]ずる形[かたち]で、日曜日[にちようび]のコンサートへ行[い]った。", "sentence_source": "generated"}, {"text": "先生の合図に、子どもたちは元気な声で応ずることができた。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "先生[せんせい]の合図[あいず]に、子[こ]どもたちは元気[げんき]な声[こえ]で応[おう]ずることができた。", "sentence_source": "generated"}, {"text": "相手が挑発しても、彼女は決して応ずることはなかった。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "相手[あいて]が挑発[ちょうはつ]しても、彼女[かのじょ]は決[けっ]して応[おう]ずることはなかった。", "sentence_source": "generated"}, {"text": "彼は質問に応ずるかのように、小さくうなずいた。", "target_word": "応ずる", "complexity_tier": "T4", "furigana": "彼[かれ]は質問[しつもん]に応[おう]ずるかのように、小[ちい]さくうなずいた。", "sentence_source": "generated"}, {"text": "電話で何度も頼んだが、相手は話し合いに応ずる気配さえ見せない。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "電話[でんわ]で何度[なんど]も頼[たの]んだが、相手[あいて]は話[はな]し合[あ]いに応[おう]ずる気配[けはい]さえ見[み]せない。", "sentence_source": "generated"}, {"text": "犬は名前を呼ぶと、しっぽを振って応ずる。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "犬[いぬ]は名前[なまえ]を呼[よ]ぶと、しっぽを振[ふ]って応[おう]ずる。", "sentence_source": "generated"}, {"text": "市民の声に応ずるため、市長は会見を開いた。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "市民[しみん]の声[こえ]に応[おう]ずるため、市長[しちょう]は会見[かいけん]を開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "応ずる", "label": "終止形"}, {"form": "応じます", "label": "ます形"}, {"form": "応じて", "label": "て形"}, {"form": "応じた", "label": "た形"}, {"form": "応じない", "label": "ない形"}, {"form": "応ずれば", "label": "仮定形"}], "register": "やや硬い標準語", "sense_fingerprint": "呼びかけ・誘い・依頼などに対して、答えたり行動したりして反応する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。呼びかけに答えて反応するという意味で文に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "「呼びかけに眠る」では文が成り立たず、反応の意味にならない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは物を研ぐ動作で、呼びかけへの反応には合わない。"}, {"text": "数える", "is_correct": false, "explanation": "数えるは数を確かめる動作で、呼びかけには合わない。"}], "explanations": {"応ずる": "正解。呼びかけに答えて反応するという意味で文に合う。", "眠る": "「呼びかけに眠る」では文が成り立たず、反応の意味にならない。", "磨く": "磨くは物を研ぐ動作で、呼びかけへの反応には合わない。", "数える": "数えるは数を確かめる動作で、呼びかけには合わない。"}, "sentence_index": 0, "correct_answer": "応ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客の数に応ずるため、店員の人数を変える。", "explanation": "ここは〈状況に合わせる〉（別の語義）の意味。数量に合わせる用法で、呼びかけや依頼への反応ではない。"}, {"text": "年齢に応ずる運動を続けることが大切だ。", "explanation": "ここは〈状況に合わせる〉（別の語義）の意味。年齢に合わせる用法で、呼びかけや依頼への反応ではない。"}, {"text": "予算に応ずる旅行プランを旅行会社が出してくれた。", "explanation": "ここは〈状況に合わせる〉（別の語義）の意味。予算に合わせる用法で、依頼への反応ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。質問に答える反応として「かのように」に続く文に合う。"}, {"text": "光る", "is_correct": false, "explanation": "「質問に光るかのように」では文が成り立たない。"}, {"text": "煮る", "is_correct": false, "explanation": "煮るは料理の動作で、質問への反応には合わない。"}, {"text": "測る", "is_correct": false, "explanation": "測るは長さや量を計る動作で、質問への反応には合わない。"}], "explanations": {"応ずる": "正解。質問に答える反応として「かのように」に続く文に合う。", "光る": "「質問に光るかのように」では文が成り立たない。", "煮る": "煮るは料理の動作で、質問への反応には合わない。", "測る": "測るは長さや量を計る動作で、質問への反応には合わない。"}, "sentence_index": 6, "correct_answer": "応ずる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その日の天気に応ずるよう、服を選びます。", "explanation": "ここは〈状況に合わせる〉（別の語義）の意味。天気に合わせる用法で、呼びかけや依頼への反応ではない。"}, {"text": "寝坊に応ずるため、朝早く起きた。", "explanation": "「寝坊に応ずる」は成り立たず、〈対処する〉の語義はない。呼びかけへの反応でもなく、誤用の文。"}, {"text": "場面に応ずる態度を身につけるのが、社会人の第一歩だ。", "explanation": "ここは〈状況に合わせる〉（別の語義）の意味。場面に合わせる用法で、呼びかけへの反応ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は依頼を応じて、すぐに資料を送った。", "corrected_sentence": "彼女は依頼に応じて、すぐに資料を送った。", "error_description": "正しくは「依頼に応じて」。「応ずる」は「〜に応ずる」と相手や依頼を「に」で受けるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。連体形で、「ことにした」に続く形。"}, {"text": "応じよう", "is_correct": false, "explanation": "意向形で、「ことにした」の前には置けない。"}, {"text": "応じない", "is_correct": false, "explanation": "ない形の否定で、文の「応じることにした」の意味に反する。"}, {"text": "応じて", "is_correct": false, "explanation": "て形で、「ことにした」に直接続かない。"}], "correct_form": "応ずる", "base_form": "応ずる", "form_label": "連体形", "sentence_index": 1, "explanations": {"応ずる": "正解。連体形で、「ことにした」に続く形。", "応じよう": "意向形で、「ことにした」の前には置けない。", "応じない": "ない形の否定で、文の「応じることにした」の意味に反する。", "応じて": "て形で、「ことにした」に直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35970, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手の提案に応じるて、対応を変えた。", "corrected_sentence": "相手の提案に応じて、対応を変えた。", "error_description": "正しくは「応じて」。て形は「応じ」＋「て」で、「応じるて」は活用の形が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。連体形で、名詞「気配」を修飾する形。"}, {"text": "応じます", "is_correct": false, "explanation": "ます形の丁寧語で、「気配」を修飾できないので合わない。"}, {"text": "応ずれば", "is_correct": false, "explanation": "仮定形で「ば」が続く形のため、名詞を修飾できない。"}, {"text": "応じよ", "is_correct": false, "explanation": "命令形で、名詞「気配」を修飾する形ではない。"}], "correct_form": "応ずる", "base_form": "応ずる", "form_label": "連体形", "sentence_index": 7, "explanations": {"応ずる": "正解。連体形で、名詞「気配」を修飾する形。", "応じます": "ます形の丁寧語で、「気配」を修飾できないので合わない。", "応ずれば": "仮定形で「ば」が続く形のため、名詞を修飾できない。", "応じよ": "命令形で、名詞「気配」を修飾する形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「客の数に応ずる」は、応ずる条件を示す「に」で自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「応ずる」は「を」で目的語を取らないため、「客の数を応ずる」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すため、条件を示す「客の数へ応ずる」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「客の数より応ずるため」では文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「客の数に応ずる」は、応ずる条件を示す「に」で自然に成り立つ。", "を": "「応ずる」は「を」で目的語を取らないため、「客の数を応ずる」は成り立たない。", "へ": "「へ」は向かう先を表すため、条件を示す「客の数へ応ずる」は意味が通らない。", "より": "「より」は比較の助詞で、「客の数より応ずるため」では文として成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「変化に応ずる」は、応ずる条件を示す「に」で自然に成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」だが、「変化で応ずる」では手段として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」だが、「変化から応ずる」では起点として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す「と」だが、「変化と応ずる」では相手として不自然で意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「変化に応ずる」は、応ずる条件を示す「に」で自然に成り立つ。", "で": "手段や場所を表す「で」だが、「変化で応ずる」では手段として意味が通らない。", "から": "起点を表す「から」だが、「変化から応ずる」では起点として成り立たない。", "と": "相手や並列を表す「と」だが、「変化と応ずる」では相手として不自然で意味が通らない。"}, "error_tags": {"で": "手段", "から": "起点", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "相手からの働きかけや状況に対して、ふさわしい行動や態度をとる。", "primary_collocate": null, "pronunciation": "おうずる", "ipa": "oːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "その日の天気に応ずるよう、服を選びます。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "その日[ひ]の天気[てんき]に応[おう]ずるよう、服[ふく]を選[えら]びます。", "sentence_source": "generated"}, {"text": "客の数に応ずるため、店員の人数を変える。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "客[きゃく]の数[かず]に応[おう]ずるため、店員[てんいん]の人数[にんずう]を変[か]える。", "sentence_source": "generated"}, {"text": "年齢に応ずる運動を続けることが大切だ。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "年齢[ねんれい]に応[おう]ずる運動[うんどう]を続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "収入に応ずる形で、税金の額が決まる。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]に応[おう]ずる形[かたち]で、税金[ぜいきん]の額[がく]が決[き]まる。", "sentence_source": "generated"}, {"text": "状況に応ずるよう、計画を変更してください。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "状況[じょうきょう]に応[おう]ずるよう、計画[けいかく]を変更[へんこう]してください。", "sentence_source": "generated"}, {"text": "彼は相手の性格に応ずる話し方ができる。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の性格[せいかく]に応[おう]ずる話[はな]し方[かた]ができる。", "sentence_source": "generated"}, {"text": "予算に応ずる旅行プランを旅行会社が出してくれた。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "予算[よさん]に応[おう]ずる旅行[りょこう]プランを旅行会社[りょこうがいしゃ]が出[だ]してくれた。", "sentence_source": "generated"}, {"text": "変化に応ずることのできない会社は、だんだん売れなくなる。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "変化[へんか]に応[おう]ずることのできない会社[かいしゃ]は、だんだん売[う]れなくなる。", "sentence_source": "generated"}, {"text": "子どもの成長に応ずるよう、机の高さを変えた。", "target_word": "応ずる", "complexity_tier": "T3", "furigana": "子[こ]どもの成長[せいちょう]に応[おう]ずるよう、机[つくえ]の高[たか]さを変[か]えた。", "sentence_source": "generated"}, {"text": "場面に応ずる態度を身につけるのが、社会人の第一歩だ。", "target_word": "応ずる", "complexity_tier": "T4", "furigana": "場面[ばめん]に応[おう]ずる態度[たいど]を身[み]につけるのが、社会人[しゃかいじん]の第一歩[だいいっぽ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "応ずる", "label": "終止形"}, {"form": "応じます", "label": "ます形"}, {"form": "応じて", "label": "て形"}, {"form": "応じた", "label": "た形"}, {"form": "応じない", "label": "ない形"}, {"form": "応ずれば", "label": "仮定形"}], "register": "やや硬い標準語", "sense_fingerprint": "状況・条件・相手に合わせて、ふさわしいやり方や量に調整する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。天気に合わせてという意味で、「応ずるよう」に続く文に合う。"}, {"text": "掘る", "is_correct": false, "explanation": "掘るは地面を掘る動作で、天気に合わせる意味にならない。"}, {"text": "叩く", "is_correct": false, "explanation": "叩くは物を打つ動作で、天気に合わせる意味にならない。"}, {"text": "転ぶ", "is_correct": false, "explanation": "転ぶは倒れる動作で、「天気に転ぶよう」では文が成り立たない。"}], "explanations": {"応ずる": "正解。天気に合わせてという意味で、「応ずるよう」に続く文に合う。", "掘る": "掘るは地面を掘る動作で、天気に合わせる意味にならない。", "叩く": "叩くは物を打つ動作で、天気に合わせる意味にならない。", "転ぶ": "転ぶは倒れる動作で、「天気に転ぶよう」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "応ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "困ったときは家族に応ずる。", "explanation": "「応ずる」に〈頼る〉の語義はなく、この文は誤用。状況に合わせる語義にも当たらない。"}, {"text": "この色はあなたによく応ずる。", "explanation": "「応ずる」に〈似合う〉の語義はなく、この文は誤用。"}, {"text": "重要な件は友人に応ずる。", "explanation": "「応ずる」に〈相談する〉の語義はなく、この文は誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。予算に合わせた旅行プランという意味で、文に合う。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "叫ぶは大声を出す動作で、「予算に叫ぶ旅行プラン」では意味が通らない。"}, {"text": "焼く", "is_correct": false, "explanation": "焼くは火で加熱する動作で、予算に合わせる意味にならない。"}, {"text": "植える", "is_correct": false, "explanation": "植えるは草木を植える動作で、「予算に植える」は成り立たない。"}], "explanations": {"応ずる": "正解。予算に合わせた旅行プランという意味で、文に合う。", "叫ぶ": "叫ぶは大声を出す動作で、「予算に叫ぶ旅行プラン」では意味が通らない。", "焼く": "焼くは火で加熱する動作で、予算に合わせる意味にならない。", "植える": "植えるは草木を植える動作で、「予算に植える」は成り立たない。"}, "sentence_index": 6, "correct_answer": "応ずる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼らは山頂に応ずるため、朝早く出発した。", "explanation": "「応ずる」に〈目指す〉の語義はなく、この文は誤用。"}, {"text": "眠りに応ずるため、布団に入った。", "explanation": "「応ずる」に〈眠る〉の語義はなく、この文は誤用。"}, {"text": "海に応ずるため、朝から泳いだ。", "explanation": "「応ずる」に〈泳ぐ〉の語義はなく、この文は誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの体力を応じて、運動の量を決める。", "corrected_sentence": "子どもの体力に応じて、運動の量を決める。", "error_description": "正しくは「体力に応じて」。「応ずる」は「〜に応ずる」と条件を「に」で受けるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。連体形で、「ため」に続く形。"}, {"text": "応じて", "is_correct": false, "explanation": "て形で、「ため」に直接続かない。"}, {"text": "応じない", "is_correct": false, "explanation": "ない形の否定で、「調整するため」の意味に反する。"}, {"text": "応ずれば", "is_correct": false, "explanation": "仮定形で「ば」が必要になり、「ため」には続かない。"}], "correct_form": "応ずる", "base_form": "応ずる", "form_label": "連体形", "sentence_index": 1, "explanations": {"応ずる": "正解。連体形で、「ため」に続く形。", "応じて": "て形で、「ため」に直接続かない。", "応じない": "ない形の否定で、「調整するため」の意味に反する。", "応ずれば": "仮定形で「ば」が必要になり、「ため」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35971, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気に応じるて、服装を選ぶのが大切だ。", "corrected_sentence": "天気に応じて、服装を選ぶのが大切だ。", "error_description": "正しくは「応じて」。て形は「応じ」＋「て」で、「応じるて」は活用の形が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "応ずる", "is_correct": true, "explanation": "正解。連体形で、「ことのできない」を修飾する形。"}, {"text": "応じて", "is_correct": false, "explanation": "て形で、名詞句「ことのできない」に直接続かない。"}, {"text": "応じます", "is_correct": false, "explanation": "ます形の丁寧語で、名詞句「こと」を修飾する形ではない。"}, {"text": "応じよ", "is_correct": false, "explanation": "命令形で、名詞句を修飾する形にはならない。"}], "correct_form": "応ずる", "base_form": "応ずる", "form_label": "連体形", "sentence_index": 7, "explanations": {"応ずる": "正解。連体形で、「ことのできない」を修飾する形。", "応じて": "て形で、名詞句「ことのできない」に直接続かない。", "応じます": "ます形の丁寧語で、名詞句「こと」を修飾する形ではない。", "応じよ": "命令形で、名詞句を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「合唱が響いた」は、響く主体を示す「が」で、自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「響く」は目的語を取らない自動詞なので、「合唱を響いた」とはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を表すため、響く主体である合唱には当てはまらない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「合唱より響いた」では文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「合唱が響いた」は、響く主体を示す「が」で、自然に成り立つ。", "を": "「響く」は目的語を取らない自動詞なので、「合唱を響いた」とはならない。", "へ": "「へ」は行き先を表すため、響く主体である合唱には当てはまらない。", "より": "「より」は比較の助詞で、「合唱より響いた」では文の意味が通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
