INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が声を合わせて歌うこと。", "primary_collocate": null, "pronunciation": "がっしょう", "ipa": "ɡaɕːoː", "syllable_count": 4, "sentences": [{"text": "卒業式で、全員が校歌を合唱した。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]で、全員[ぜんいん]が校歌[こうか]を合唱[がっしょう]した。", "sentence_source": "generated"}, {"text": "体育館に、生徒たちの合唱が響いた。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "体育館[たいいくかん]に、生徒[せいと]たちの合唱[がっしょう]が響[ひび]いた。", "sentence_source": "generated"}, {"text": "町の人が集まって、みんなで合唱するのが楽しみだ。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]が集[あつ]まって、みんなで合唱[がっしょう]するのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "子どもたちの合唱を聞いて、母は涙を流した。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "子[こ]どもたちの合唱[がっしょう]を聞[き]いて、母[はは]は涙[なみだ]を流[なが]した。", "sentence_source": "generated"}, {"text": "クラス全員で合唱したので、声がよくそろった。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "クラス全員[ぜんいん]で合唱[がっしょう]したので、声[こえ]がよくそろった。", "sentence_source": "generated"}, {"text": "駅前で、小学生が合唱をして募金を呼びかけていた。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "駅前[えきまえ]で、小学生[しょうがくせい]が合唱[がっしょう]をして募金[ぼきん]を呼[よ]びかけていた。", "sentence_source": "generated"}, {"text": "大勢の合唱は、一人で歌うより迫力がある。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "大勢[おおぜい]の合唱[がっしょう]は、一人[ひとり]で歌[うた]うより迫力[はくりょく]がある。", "sentence_source": "generated"}, {"text": "私は毎週土曜日に、地域の合唱に参加している。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "私[わたし]は毎週[まいしゅう]土曜日[どようび]に、地域[ちいき]の合唱[がっしょう]に参加[さんか]している。", "sentence_source": "generated"}, {"text": "運動会の前に、みんなで応援歌を合唱した。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前[まえ]に、みんなで応援歌[おうえんか]を合唱[がっしょう]した。", "sentence_source": "generated"}, {"text": "山の上で、仲間と一緒に合唱すると気持ちがいい。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で、仲間[なかま]と一緒[いっしょ]に合唱[がっしょう]すると気持[きも]ちがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合唱", "label": "基本形"}, {"form": "合唱する", "label": "する動詞の終止形"}, {"form": "合唱した", "label": "た形"}, {"form": "合唱して", "label": "て形"}, {"form": "合唱しない", "label": "ない形"}], "register": "中立的な標準語", "sense_fingerprint": "大勢が声をそろえて一緒に歌う行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合唱", "is_correct": true, "explanation": "「校歌を合唱した」は、大勢で声を合わせて歌うという意味で、空所にそのまま入る。"}, {"text": "欠席", "is_correct": false, "explanation": "「校歌を欠席した」は意味が通らない。欠席は授業や行事に出ないことで、歌の対象にはならない。"}, {"text": "購入", "is_correct": false, "explanation": "「校歌を購入した」は不自然。購入は物を買うことで、歌の文脈とは合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "「校歌を清掃した」は意味が通らない。清掃は場所や物をきれいにすることで、歌には使えない。"}], "explanations": {"合唱": "「校歌を合唱した」は、大勢で声を合わせて歌うという意味で、空所にそのまま入る。", "欠席": "「校歌を欠席した」は意味が通らない。欠席は授業や行事に出ないことで、歌の対象にはならない。", "購入": "「校歌を購入した」は不自然。購入は物を買うことで、歌の文脈とは合わない。", "清掃": "「校歌を清掃した」は意味が通らない。清掃は場所や物をきれいにすることで、歌には使えない。"}, "sentence_index": 0, "correct_answer": "合唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吹奏楽部が、フルートとトランペットで合唱を披露した。", "explanation": "ここは〈合奏〉の意味。合唱は声で歌うことなので、楽器の演奏には使わない。"}, {"text": "彼は一人でステージに立ち、堂々と合唱した。", "explanation": "ここは〈独唱〉の意味。合唱は大勢が声を合わせることなので、一人で歌う場面には使わない。"}, {"text": "先生が教科書を合唱して、生徒に読ませた。", "explanation": "ここは〈朗読〉の意味。合唱は歌うことで、文章を読み上げる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合唱", "is_correct": true, "explanation": "「大勢の合唱は、一人で歌うより迫力がある」は、大勢で歌う形態を指し、空所に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "「大勢の郵便は、一人で歌うより迫力がある」は意味が通らない。郵便は手紙などを届ける仕組みで、歌とは関係しない。"}, {"text": "天気", "is_correct": false, "explanation": "「大勢の天気は」は成り立たない。天気は空の状態で、歌の迫力を比べる対象にはならない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「大勢の洗濯は」は不自然。洗濯は衣類を洗う家事で、歌の迫力とは結びつかない。"}], "explanations": {"合唱": "「大勢の合唱は、一人で歌うより迫力がある」は、大勢で歌う形態を指し、空所に合う。", "郵便": "「大勢の郵便は、一人で歌うより迫力がある」は意味が通らない。郵便は手紙などを届ける仕組みで、歌とは関係しない。", "天気": "「大勢の天気は」は成り立たない。天気は空の状態で、歌の迫力を比べる対象にはならない。", "洗濯": "「大勢の洗濯は」は不自然。洗濯は衣類を洗う家事で、歌の迫力とは結びつかない。"}, "sentence_index": 6, "correct_answer": "合唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の上で、仲間と一緒に合唱を登った。", "explanation": "ここは〈場所・物〉としての意味。合唱は歌うことを指すので、山のように登る対象にはならない。"}, {"text": "放課後、仲間と一緒に合唱して、進路を相談した。", "explanation": "ここは〈相談する〉の意味。合唱は声を合わせて歌うことで、話し合って決める行為には使わない。"}, {"text": "日曜日、仲間と一緒に合唱して、昼寝をした。", "explanation": "ここは〈昼寝〉の意味。合唱は歌うことを指し、眠って休む行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月の発表会で、みんなで合唱した予定だ。", "corrected_sentence": "来月の発表会で、みんなで合唱する予定だ。", "error_description": "「来月」「予定」は未来の出来事なので、動詞は辞書形の「合唱する」にする。「合唱した」は過去形で、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35972, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、合唱を始まるのを待っている。", "corrected_sentence": "先生は、合唱が始まるのを待っている。", "error_description": "「始まる」は自動詞で、主語に「が」を使う。「合唱を」は誤りで、正しくは「合唱が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「選ぶ」の対象を示す「を」で、「合唱を選んだ」が自然になる。"}, {"text": "が", "is_correct": false, "explanation": "選んだ主語は先生なので、「合唱が選んだ」では主語と動詞が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は「〜と一緒に」の意味になり、選ぶ対象を示すことができない。"}, {"text": "に", "is_correct": false, "explanation": "「選んだ」は「AをBに選ぶ」の形で、「合唱に選んだ」は目的語が欠けて不自然。"}], "correct_answer": "を", "explanations": {"を": "「選ぶ」の対象を示す「を」で、「合唱を選んだ」が自然になる。", "が": "選んだ主語は先生なので、「合唱が選んだ」では主語と動詞が合わない。", "と": "「と」は「〜と一緒に」の意味になり、選ぶ対象を示すことができない。", "に": "「選んだ」は「AをBに選ぶ」の形で、「合唱に選んだ」は目的語が欠けて不自然。"}, "error_tags": {"が": "主語", "と": "相手", "に": "選択先"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人がそれぞれのパートを担当し、同時に歌う音楽の形式。また、そのための楽曲。", "primary_collocate": null, "pronunciation": "がっしょう", "ipa": "ɡaɕːoː", "syllable_count": 4, "sentences": [{"text": "この合唱は、ソプラノとアルトとテノールの三つのパートに分かれている。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "この合唱[がっしょう]は、ソプラノとアルトとテノールの三[みっ]つのパートに分[わ]かれている。", "sentence_source": "generated"}, {"text": "先生は、有名な作曲家が書いた合唱を選んだ。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "先生[せんせい]は、有名[ゆうめい]な作曲家[さっきょくか]が書[か]いた合唱[がっしょう]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "合唱では、パートごとに違う旋律を歌って一つの和音を作る。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "合唱[がっしょう]では、パートごとに違[ちが]う旋律[せんりつ]を歌[うた]って一[ひと]つの和音[わおん]を作[つく]る。", "sentence_source": "generated"}, {"text": "来月の発表会で、バッハの合唱を歌うことになった。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "来月[らいげつ]の発表会[はっぴょうかい]で、バッハの合唱[がっしょう]を歌[うた]うことになった。", "sentence_source": "generated"}, {"text": "この合唱は、ピアノの伴奏がなくても歌える。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "この合唱[がっしょう]は、ピアノの伴奏[ばんそう]がなくても歌[うた]える。", "sentence_source": "generated"}, {"text": "彼女は合唱のために、新しい曲を書いた。", "target_word": "合唱", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は合唱[がっしょう]のために、新[あたら]しい曲[きょく]を書[か]いた。", "sentence_source": "generated"}, {"text": "楽譜を見ると、この合唱は後半で急に速くなる。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "楽譜[がくふ]を見[み]ると、この合唱[がっしょう]は後半[こうはん]で急[きゅう]に速[はや]くなる。", "sentence_source": "generated"}, {"text": "オペラの中の合唱は、物語の場面を盛り上げる。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "オペラの中[なか]の合唱[がっしょう]は、物語[ものがたり]の場面[ばめん]を盛[も]り上[あ]げる。", "sentence_source": "generated"}, {"text": "合唱は、パートが重なって響くところが魅力だ。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "合唱[がっしょう]は、パートが重[かさ]なって響[ひび]くところが魅力[みりょく]だ。", "sentence_source": "generated"}, {"text": "低い声の人は、合唱でバスのパートを担当する。", "target_word": "合唱", "complexity_tier": "T4", "furigana": "低[ひく]い声[こえ]の人[ひと]は、合唱[がっしょう]でバスのパートを担当[たんとう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合唱", "label": "基本形"}, {"form": "合唱する", "label": "する動詞の終止形"}, {"form": "合唱した", "label": "た形"}, {"form": "合唱して", "label": "て形"}, {"form": "合唱しない", "label": "ない形"}], "register": "中立的な標準語", "sense_fingerprint": "パートに分かれて同時に歌う音楽の形式、またはその曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合唱", "is_correct": true, "explanation": "「この合唱は、三つのパートに分かれている」は、パートに分かれた音楽形式を指し、空所に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "「この郵便は、三つのパートに分かれている」は成り立たない。郵便は物を届ける仕組みで、パートには分かれない。"}, {"text": "天気", "is_correct": false, "explanation": "「この天気は、三つのパートに分かれている」は意味が通らない。天気は空の状態で、パートという概念がない。"}, {"text": "配送", "is_correct": false, "explanation": "「この配送は、三つのパートに分かれている」は不自然。配送は荷物を運ぶことで、音楽の構造には当てはまらない。"}], "explanations": {"合唱": "「この合唱は、三つのパートに分かれている」は、パートに分かれた音楽形式を指し、空所に合う。", "郵便": "「この郵便は、三つのパートに分かれている」は成り立たない。郵便は物を届ける仕組みで、パートには分かれない。", "天気": "「この天気は、三つのパートに分かれている」は意味が通らない。天気は空の状態で、パートという概念がない。", "配送": "「この配送は、三つのパートに分かれている」は不自然。配送は荷物を運ぶことで、音楽の構造には当てはまらない。"}, "sentence_index": 0, "correct_answer": "合唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の発表会で、バッハの合唱に合格することになった。", "explanation": "ここは〈合格〉の意味。試験や審査に通ることは合格で、合唱は歌う形式なので、そこに合格するとは言わない。"}, {"text": "来月の発表会で、バッハの合唱を一人で歌うことになった。", "explanation": "ここは〈独唱曲〉の意味。合唱は複数の人がパートを分けて歌う形式なので、一人の歌には使わない。"}, {"text": "来月の発表会で、バッハの合唱を暗唱することになった。", "explanation": "ここは〈暗唱〉の意味。覚えた文章を声に出す行為で、音楽の形式を指す合唱とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合唱", "is_correct": true, "explanation": "「この合唱は後半で急に速くなる」は、曲の進行を述べる文として自然で、空所に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "「この洗濯は後半で急に速くなる」は意味が通らない。洗濯は家事で、曲の速さとは関係しない。"}, {"text": "交通", "is_correct": false, "explanation": "「この交通は後半で急に速くなる」は不自然。交通は人や物の移動のことで、楽譜の文脈とは合わない。"}, {"text": "包装", "is_correct": false, "explanation": "「この包装は後半で急に速くなる」は成り立たない。包装は物を包むことで、速さの変化を示さない。"}], "explanations": {"合唱": "「この合唱は後半で急に速くなる」は、曲の進行を述べる文として自然で、空所に合う。", "洗濯": "「この洗濯は後半で急に速くなる」は意味が通らない。洗濯は家事で、曲の速さとは関係しない。", "交通": "「この交通は後半で急に速くなる」は不自然。交通は人や物の移動のことで、楽譜の文脈とは合わない。", "包装": "「この包装は後半で急に速くなる」は成り立たない。包装は物を包むことで、速さの変化を示さない。"}, "sentence_index": 6, "correct_answer": "合唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "低い声の人は、合唱で悪役を担当する。", "explanation": "ここは〈役〉の意味。合唱には配役がなく、悪役のような役割を担当するという使い方はしない。"}, {"text": "低い声の人は、合唱で配達を担当する。", "explanation": "ここは〈仕事〉の意味。合唱は音楽の形式で、配達のような業務を指すことはない。"}, {"text": "低い声の人は、合唱でチューバのパートを担当する。", "explanation": "ここは〈合奏〉の意味。チューバのような楽器のパートは合奏の話で、合唱は歌うことなので楽器のパートを持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、この合唱を来月歌った予定だ。", "corrected_sentence": "先生は、この合唱を来月歌う予定だ。", "error_description": "「来月」「予定」は未来の出来事なので、動詞は「歌う」にする。「歌った」は過去形で、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35973, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、新しい合唱が取り組むことにした。", "corrected_sentence": "先生は、新しい合唱に取り組むことにした。", "error_description": "「取り組む」は「〜に取り組む」の形を取る。「合唱が」は誤りで、正しくは「合唱に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「要素だけを残す」と、「を」で残す対象を示します。"}, {"text": "へ", "is_correct": false, "explanation": "「だけへ残す」は文として成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「だけの残す」は文として成り立ちません。"}, {"text": "や", "is_correct": false, "explanation": "「だけや残す」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「要素だけを残す」と、「を」で残す対象を示します。", "へ": "「だけへ残す」は文として成り立ちません。", "の": "「だけの残す」は文として成り立ちません。", "や": "「だけや残す」は文として成り立ちません。"}, "error_tags": {"へ": "direction", "の": "possessive", "や": "listing"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "捨てる", "is_correct": true, "explanation": "「捨てる」は、とっておく「残す」と反対の関係です。"}, {"text": "書く", "is_correct": false, "explanation": "「書く」は反対の意味ではありません。"}, {"text": "買う", "is_correct": false, "explanation": "「買う」は反対の意味ではありません。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は反対の意味ではありません。"}], "correct_answer": "捨てる", "explanations": {"捨てる": "「捨てる」は、とっておく「残す」と反対の関係です。", "書く": "「書く」は反対の意味ではありません。", "買う": "「買う」は反対の意味ではありません。", "運ぶ": "「運ぶ」は反対の意味ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自然を残す」と、「を」で残す対象を示します。"}, {"text": "の", "is_correct": false, "explanation": "「自然の残してあげたい」は文として成り立ちません。"}, {"text": "や", "is_correct": false, "explanation": "「自然や残してあげたい」は文として成り立ちません。"}, {"text": "か", "is_correct": false, "explanation": "「自然か残してあげたい」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「自然を残す」と、「を」で残す対象を示します。", "の": "「自然の残してあげたい」は文として成り立ちません。", "や": "「自然や残してあげたい」は文として成り立ちません。", "か": "「自然か残してあげたい」は文として成り立ちません。"}, "error_tags": {"の": "possessive", "や": "listing", "か": "question"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「壊す」は、町並みを守って残す「残す」と反対の関係です。"}, {"text": "作る", "is_correct": false, "explanation": "「作る」は反対の意味ではありません。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は反対の意味ではありません。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は反対の意味ではありません。"}], "correct_answer": "壊す", "explanations": {"壊す": "「壊す」は、町並みを守って残す「残す」と反対の関係です。", "作る": "「作る」は反対の意味ではありません。", "運ぶ": "「運ぶ」は反対の意味ではありません。", "洗う": "「洗う」は反対の意味ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものをなくさないで、あとにのこす。または、きろくとしてのこす。", "primary_collocate": null, "pronunciation": "のこす", "ipa": "nokosɯ", "syllable_count": 3, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "残す", "complexity_tier": "T6", "furigana": "ミニマリストの思想[しそう]に基[もと]づき、必要[ひつよう]な要素[ようそ]だけを残[のこ]すことで、居住者[きょじゅうしゃ]はより穏[おだ]やかな日常[にちじょう]を送[おく]ることができます。", "sentence_source": "mined"}, {"text": "ご飯を残す。", "target_word": "残す", "complexity_tier": "T1", "furigana": "ご飯[はん]を残[のこ]す。", "sentence_source": "generated"}, {"text": "友だちにメモを残しました。", "target_word": "残しました", "complexity_tier": "T2", "furigana": "友[とも]だちにメモを残[のこ]しました。", "sentence_source": "generated"}, {"text": "ご飯を残さないでください。", "target_word": "残さない", "complexity_tier": "T3", "furigana": "ご飯[はん]を残[のこ]さないでください。", "sentence_source": "generated"}, {"text": "大切な写真を、ずっと残しておく。", "target_word": "残して", "complexity_tier": "T3", "furigana": "大切[たいせつ]な写真[しゃしん]を、ずっと残[のこ]しておく。", "sentence_source": "generated"}, {"text": "昔の建物を残すために、お金を集めている。", "target_word": "残す", "complexity_tier": "T3", "furigana": "昔[むかし]の建物[たてもの]を残[のこ]すために、お金[かね]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "彼は日記に毎日の出来事を残している。", "target_word": "残している", "complexity_tier": "T3", "furigana": "彼[かれ]は日記[にっき]に毎日[まいにち]の出来事[できごと]を残[のこ]している。", "sentence_source": "generated"}, {"text": "子どもたちに美しい自然を残してあげたい。", "target_word": "残して", "complexity_tier": "T4", "furigana": "子[こ]どもたちに美[うつく]しい自然[しぜん]を残[のこ]してあげたい。", "sentence_source": "generated"}, {"text": "先生が残した言葉は、今も私の心の中に生きている。", "target_word": "残した", "complexity_tier": "T4", "furigana": "先生[せんせい]が残[のこ]した言葉[ことば]は、今[いま]も私[わたし]の心[こころ]の中[なか]に生[い]きている。", "sentence_source": "generated"}, {"text": "古い町並みを残すかどうかについて、住民の意見が分かれている。", "target_word": "残す", "complexity_tier": "T5", "furigana": "古[ふる]い町並[まちな]みを残[のこ]すかどうかについて、住民[じゅうみん]の意見[いけん]が分[わ]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残した", "label": "活用"}, {"form": "残して", "label": "活用"}, {"form": "残さない", "label": "活用"}, {"form": "残される", "label": "活用"}, {"form": "残り", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | ものをなくさずあとに残すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "残す", "is_correct": true, "explanation": "見出し語の「のこす」そのものです。"}, {"text": "起こす", "is_correct": false, "explanation": "「おこす」は1音目が「の」ではなく「お」で、1モーラ違います。"}, {"text": "伸ばす", "is_correct": false, "explanation": "「のばす」は2音目が「こ」ではなく「ば」で、1モーラ違います。"}, {"text": "飲ます", "is_correct": false, "explanation": "「のます」は2音目が「こ」ではなく「ま」で、1モーラ違います。"}], "explanations": {"残す": "見出し語の「のこす」そのものです。", "起こす": "「おこす」は1音目が「の」ではなく「お」で、1モーラ違います。", "伸ばす": "「のばす」は2音目が「こ」ではなく「ば」で、1モーラ違います。", "飲ます": "「のます」は2音目が「こ」ではなく「ま」で、1モーラ違います。"}, "sentence_index": null, "correct_answer": "残す"}, "level_3": {"options": [{"text": "残す", "is_correct": true, "explanation": "必要な要素だけを「残す」は、意味が通ります。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが意味が合わない。要素を洗うことで穏やかな日常にはなりません。"}, {"text": "折る", "is_correct": false, "explanation": "形は合うが意味が合わない。要素を折るという意味は文脈に合いません。"}, {"text": "割る", "is_correct": false, "explanation": "形は合うが意味が合わない。要素を割るという意味は文脈に合いません。"}], "explanations": {"残す": "必要な要素だけを「残す」は、意味が通ります。", "洗う": "形は合うが意味が合わない。要素を洗うことで穏やかな日常にはなりません。", "折る": "形は合うが意味が合わない。要素を折るという意味は文脈に合いません。", "割る": "形は合うが意味が合わない。要素を割るという意味は文脈に合いません。"}, "sentence_index": 0, "correct_answer": "残す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、駅で電車を残してから会社へ行く。", "explanation": "「残す」は電車を降りたり待ったりする意味では使えません。"}, {"text": "窓を残して、部屋の空気を入れ替えた。", "explanation": "「残す」は窓を開ける意味にはなりません。"}, {"text": "風が強くて、木の葉が窓に残している。", "explanation": "「残す」は他動詞で、葉が風で付くという自然現象には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残している", "is_correct": true, "explanation": "日記に出来事を記録として「残している」は自然です。"}, {"text": "洗っている", "is_correct": false, "explanation": "形は合うが意味が合わない。日記に出来事を洗うことはできません。"}, {"text": "折っている", "is_correct": false, "explanation": "形は合うが意味が合わない。日記に出来事を折るとは言えません。"}, {"text": "割っている", "is_correct": false, "explanation": "形は合うが意味が合わない。日記に出来事を割るとは言えません。"}], "explanations": {"残している": "日記に出来事を記録として「残している」は自然です。", "洗っている": "形は合うが意味が合わない。日記に出来事を洗うことはできません。", "折っている": "形は合うが意味が合わない。日記に出来事を折るとは言えません。", "割っている": "形は合うが意味が合わない。日記に出来事を割るとは言えません。"}, "sentence_index": 6, "correct_answer": "残している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の上から町をきれいに残した。", "explanation": "「残す」は景色を見る意味では使えません。"}, {"text": "二人は公園で長い時間を残して話した。", "explanation": "「残す」は時間を過ごす意味ではありません。"}, {"text": "電気を残して部屋を暗くした。", "explanation": "「残す」は電気を消す意味にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は机の上に手紙を残しって、出かけた。", "corrected_sentence": "兄は机の上に手紙を残して、出かけた。", "error_description": "「残す」のて形は「残しって」ではなく「残して」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "残す", "is_correct": true, "explanation": "「ご飯を残す。」の文末は終止形が自然です。"}, {"text": "残さ", "is_correct": false, "explanation": "「残さ」は未然形の語幹で、単独では文が終わりません。"}, {"text": "残し", "is_correct": false, "explanation": "「残し」は連用形で、単独では文が終わりません。"}, {"text": "残され", "is_correct": false, "explanation": "「残され」は受身形の連用形で、単独では文が終わりません。"}], "correct_form": "残す", "base_form": "残す", "form_label": "終止形", "sentence_index": 1, "explanations": {"残す": "「ご飯を残す。」の文末は終止形が自然です。", "残さ": "「残さ」は未然形の語幹で、単独では文が終わりません。", "残し": "「残し」は連用形で、単独では文が終わりません。", "残され": "「残され」は受身形の連用形で、単独では文が終わりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35975, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は田舎の家がそのまま残している。", "corrected_sentence": "祖父は田舎の家をそのまま残している。", "error_description": "「残す」の対象は「が」ではなく「を」で示します。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "残して", "is_correct": true, "explanation": "「残してあげたい」は、て形で「あげる」につながります。"}, {"text": "残す", "is_correct": false, "explanation": "「残すあげたい」は「あげたい」に直接つながりません。"}, {"text": "残さ", "is_correct": false, "explanation": "「残さあげたい」は「あげたい」につながりません。"}, {"text": "残した", "is_correct": false, "explanation": "「残したあげたい」は「あげたい」につながりません。"}], "correct_form": "残して", "base_form": "残す", "form_label": "て形", "sentence_index": 7, "explanations": {"残して": "「残してあげたい」は、て形で「あげる」につながります。", "残す": "「残すあげたい」は「あげたい」に直接つながりません。", "残さ": "「残さあげたい」は「あげたい」につながりません。", "残した": "「残したあげたい」は「あげたい」につながりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
