INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35988, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "何かが、どんどんと続けて出てくるようす。", "primary_collocate": null, "pronunciation": "つぎつぎ", "ipa": "t͡sɯɡɯt͡sɯɡɯ", "syllable_count": 4, "sentences": [{"text": "開店と同時に、お客さんが次々に入ってきた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "開店[かいてん]と同時[どうじ]に、お客[きゃく]さんが次々[つぎつぎ]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "料理が次々と運ばれてきて、テーブルがいっぱいになった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "料理[りょうり]が次々[つぎつぎ]と運[はこ]ばれてきて、テーブルがいっぱいになった。", "sentence_source": "generated"}, {"text": "春になると、公園の桜が次々に咲く。", "target_word": "次々", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]の桜[さくら]が次々[つぎつぎ]に咲[さ]く。", "sentence_source": "generated"}, {"text": "質問が次々に出て、先生は答えるのに忙しかった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "質問[しつもん]が次々[つぎつぎ]に出[で]て、先生[せんせい]は答[こた]えるのに忙[いそが]しかった。", "sentence_source": "generated"}, {"text": "箱から、おもちゃが次々と出てきた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "箱[はこ]から、おもちゃが次々[つぎつぎ]と出[で]てきた。", "sentence_source": "generated"}, {"text": "新しい店が、駅の前に次々にできている。", "target_word": "次々", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]が、駅[えき]の前[まえ]に次々[つぎつぎ]にできている。", "sentence_source": "generated"}, {"text": "彼はアイデアを次々に思いついて、ノートに書いた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "彼[かれ]はアイデアを次々[つぎつぎ]に思[おも]いついて、ノートに書[か]いた。", "sentence_source": "generated"}, {"text": "ゴールをめざして、選手が次々とスタートした。", "target_word": "次々", "complexity_tier": "T3", "furigana": "ゴールをめざして、選手[せんしゅ]が次々[つぎつぎ]とスタートした。", "sentence_source": "generated"}, {"text": "窓の外を、電車が次々と通り過ぎていった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]を、電車[でんしゃ]が次々[つぎつぎ]と通[とお]り過[す]ぎていった。", "sentence_source": "generated"}, {"text": "手紙が次々に届いて、机の上に積まれた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "手紙[てがみ]が次々[つぎつぎ]に届[とど]いて、机[つくえ]の上[うえ]に積[つ]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "次々", "label": "base"}, {"form": "次々に", "label": "adverbial"}, {"form": "次々と", "label": "adverbial (と)"}], "register": "neutral", "sense_fingerprint": "次々: 人や物が続けて現れる・出てくるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35988, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次々", "is_correct": true, "explanation": "「次々に入ってきた」で、人が続けて現れるさまを表す。空所に入る唯一の語。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "ぐっすりは深く眠るさまを表し、客が入ってくる場面には合わない。"}, {"text": "さっぱり", "is_correct": false, "explanation": "さっぱりは気分が清々しいさまや全く〜ない意味で、入ってくる動作を修飾しない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "きっぱりは決断や言い切るさまを表し、人が入ってくる様子には使えない。"}], "explanations": {"次々": "「次々に入ってきた」で、人が続けて現れるさまを表す。空所に入る唯一の語。", "ぐっすり": "ぐっすりは深く眠るさまを表し、客が入ってくる場面には合わない。", "さっぱり": "さっぱりは気分が清々しいさまや全く〜ない意味で、入ってくる動作を修飾しない。", "きっぱり": "きっぱりは決断や言い切るさまを表し、人が入ってくる様子には使えない。"}, "sentence_index": 0, "correct_answer": "次々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空が次々に暗くなっていった。", "explanation": "ここは〈次第に〉の意味。次々は別々の出来事が続く様子を表すので、少しずつ進む変化には合わない。"}, {"text": "号令がかかると、全員が次々に一斉に立ち上がった。", "explanation": "ここは〈そろって〉の意味。次々は間をおいて続く様子なので、全員が足並みをそろえて立つ場面には合わない。"}, {"text": "その店には、次々に一度だけ行った。", "explanation": "ここは〈唯一〉の意味。次々は同じ動きが続く様子なので、一回きりの場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35988, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次々", "is_correct": true, "explanation": "「アイデアを次々に思いついて」で、考えが続けて浮かぶさまを表す。空所に入る唯一の語。"}, {"text": "のんびり", "is_correct": false, "explanation": "のんびりは急がずゆったりしたさまで、アイデアを思いつく動作を修飾すると不自然。"}, {"text": "まったく", "is_correct": false, "explanation": "まったくは全然〜ない・完全にの意味で、「アイデアをまったく思いついて」とは続かない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "きっぱりは決然としたさまで、アイデアを思いつく動作には使えない。"}], "explanations": {"次々": "「アイデアを次々に思いついて」で、考えが続けて浮かぶさまを表す。空所に入る唯一の語。", "のんびり": "のんびりは急がずゆったりしたさまで、アイデアを思いつく動作を修飾すると不自然。", "まったく": "まったくは全然〜ない・完全にの意味で、「アイデアをまったく思いついて」とは続かない。", "きっぱり": "きっぱりは決然としたさまで、アイデアを思いつく動作には使えない。"}, "sentence_index": 6, "correct_answer": "次々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三つのボタンを次々に同時に押すと、扉が開いた。", "explanation": "ここは〈いっせいに〉の意味。次々は間をおいて続く様子なので、三つを一斉に押す場面には合わない。"}, {"text": "宿題を次々に一気に終わらせた。", "explanation": "ここは〈一度に〉の意味。次々は一つずつ続く様子を表すので、まとめて一度に終える場面には合わない。"}, {"text": "荷物を次々に全部まとめて運んだ。", "explanation": "ここは〈ひとまとめに〉の意味。次々は一つずつ順に続く様子なので、ひとまとめに運ぶ場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35988, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械が次々が導入されて、作業が速くなった。", "corrected_sentence": "新しい機械が次々と導入されて、作業が速くなった。", "error_description": "副詞「次々」は格助詞「が」を取れず、動詞を修飾するには「と」が必要。誤りの箇所は「が」→「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35988, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "注文が次々と入れてきて、厨房が忙しくなった。", "corrected_sentence": "注文が次々と入ってきて、厨房が忙しくなった。", "error_description": "「注文が入る」は自動詞「入る」が正しく、「入れる」は他動詞で主語の注文とは結びつかない。誤りの箇所は「入れて」→「入って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
