INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35989, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "同じようなことが、間をおかずに次から次へと起こるさま。", "primary_collocate": null, "pronunciation": "つぎつぎ", "ipa": "t͡sɯɡɯt͡sɯɡɯ", "syllable_count": 4, "sentences": [{"text": "今年は台風が次々に来て、畑の被害が大きかった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "今年[ことし]は台風[たいふう]が次々[つぎつぎ]に来[き]て、畑[はたけ]の被害[ひがい]が大[おお]きかった。", "sentence_source": "generated"}, {"text": "悪いニュースが次々と続いて、気持ちが暗くなった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "悪[わる]いニュースが次々[つぎつぎ]と続[つづ]いて、気持[きも]ちが暗[くら]くなった。", "sentence_source": "generated"}, {"text": "彼の家では、トラブルが次々に起こる。", "target_word": "次々", "complexity_tier": "T3", "furigana": "彼[かれ]の家[いえ]では、トラブルが次々[つぎつぎ]に起[お]こる。", "sentence_source": "generated"}, {"text": "夏休みの前に、テストが次々にあって大変だった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの前[まえ]に、テストが次々[つぎつぎ]にあって大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "事件が次々と起こり、警察は休む暇がなかった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "事件[じけん]が次々[つぎつぎ]と起[お]こり、警察[けいさつ]は休[やす]む暇[ひま]がなかった。", "sentence_source": "generated"}, {"text": "病気が次々にうつって、クラスの半分が休んだ。", "target_word": "次々", "complexity_tier": "T3", "furigana": "病気[びょうき]が次々[つぎつぎ]にうつって、クラスの半分[はんぶん]が休[やす]んだ。", "sentence_source": "generated"}, {"text": "工場で故障が次々に見つかり、生産が止まった。", "target_word": "次々", "complexity_tier": "T3", "furigana": "工場[こうじょう]で故障[こしょう]が次々[つぎつぎ]に見[み]つかり、生産[せいさん]が止[と]まった。", "sentence_source": "generated"}, {"text": "友達の結婚の知らせが次々に届いた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "友達[ともだち]の結婚[けっこん]の知[し]らせが次々[つぎつぎ]に届[とど]いた。", "sentence_source": "generated"}, {"text": "問題が次々と起きて、会議は夜まで続いた。", "target_word": "次々", "complexity_tier": "T3", "furigana": "問題[もんだい]が次々[つぎつぎ]と起[お]きて、会議[かいぎ]は夜[よる]まで続[つづ]いた。", "sentence_source": "generated"}, {"text": "忙しい時期には、仕事が次々に入ってくる。", "target_word": "次々", "complexity_tier": "T3", "furigana": "忙[いそが]しい時期[じき]には、仕事[しごと]が次々[つぎつぎ]に入[はい]ってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "次々", "label": "base"}, {"form": "次々に", "label": "adverbial"}, {"form": "次々と", "label": "adverbial (と)"}], "register": "neutral", "sense_fingerprint": "次々: 出来事・問題が間をおかず次から次へと起こるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35989, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次々", "is_correct": true, "explanation": "「台風が次々に来て」で、同じ出来事が間をおかず続く様子を表す。空所に入る唯一の語。"}, {"text": "のんびり", "is_correct": false, "explanation": "のんびりは急がずゆったりしたさまで、台風が来る様子を表す語ではない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "ぐっすりは深く眠るさまで、台風が来る様子には合わない。"}, {"text": "まったく", "is_correct": false, "explanation": "まったくは完全に・全然の意味で、「台風がまったくに来て」とは続かない。"}], "explanations": {"次々": "「台風が次々に来て」で、同じ出来事が間をおかず続く様子を表す。空所に入る唯一の語。", "のんびり": "のんびりは急がずゆったりしたさまで、台風が来る様子を表す語ではない。", "ぐっすり": "ぐっすりは深く眠るさまで、台風が来る様子には合わない。", "まったく": "まったくは完全に・全然の意味で、「台風がまったくに来て」とは続かない。"}, "sentence_index": 0, "correct_answer": "次々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の暑さが次々に増していった。", "explanation": "ここは〈次第に〉の意味。次々は別々の出来事が続く様子を表すので、少しずつ進む変化には合わない。"}, {"text": "合図で、全員が次々に一斉にテストを始めた。", "explanation": "ここは〈そろって〉の意味。次々は間をおいて続く様子なので、全員が足並みをそろえて始める場面には合わない。"}, {"text": "夏休みの前に、テストが一つだけ次々にあった。", "explanation": "ここは〈唯一〉の意味。次々は同じことが続く様子で、一つだけの場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35989, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次々", "is_correct": true, "explanation": "「故障が次々に見つかり」で、故障が続けて判明する様子を表す。空所に入る唯一の語。"}, {"text": "きっぱり", "is_correct": false, "explanation": "きっぱりは決然としたさまで、故障が見つかる状況を修飾すると不自然。"}, {"text": "ぐったり", "is_correct": false, "explanation": "ぐったりは疲れて力が抜けたさまで、故障が見つかる状況には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "ぴかぴかは光って輝くさまで、故障が見つかる文脈には合わない。"}], "explanations": {"次々": "「故障が次々に見つかり」で、故障が続けて判明する様子を表す。空所に入る唯一の語。", "きっぱり": "きっぱりは決然としたさまで、故障が見つかる状況を修飾すると不自然。", "ぐったり": "ぐったりは疲れて力が抜けたさまで、故障が見つかる状況には合わない。", "ぴかぴか": "ぴかぴかは光って輝くさまで、故障が見つかる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "次々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三人の選手が次々に同時にスタートした。", "explanation": "ここは〈いっせいに〉の意味。次々は間をおかずに続く様子なので、三人が一斉に走り出す場面には合わない。"}, {"text": "仕事が次々に一気に入ってくる。", "explanation": "ここは〈一度に〉の意味。次々は一件ずつ続いて来る様子なので、まとめて一度に入る場面には合わない。"}, {"text": "仕事が全部まとめて次々に入ってくる。", "explanation": "ここは〈ひとまとめに〉の意味。次々は一件ずつ続く様子なので、ひとまとめに入る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35989, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相談が次々を寄せられて、担当者は休む暇がなかった。", "corrected_sentence": "相談が次々と寄せられて、担当者は休む暇がなかった。", "error_description": "副詞「次々」は格助詞「を」を取れず、動詞「寄せられる」を修飾するには「と」が必要。誤りの箇所は「を」→「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35989, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連絡が次々と入れて、会社は慌ただしかった。", "corrected_sentence": "連絡が次々と入って、会社は慌ただしかった。", "error_description": "「連絡が入る」は自動詞「入る」の形が正しく、「入れる」は他動詞で主語の連絡とは結びつかない。誤りの箇所は「入れて」→「入って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「椅子を作り出した」は、作り出す対象を示す「を」で自然に成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、作り出す対象である椅子を示すことができない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「椅子より作り出した」では文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は「〜と一緒に」の意味になり、作り出す対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「椅子を作り出した」は、作り出す対象を示す「を」で自然に成り立つ。", "へ": "「へ」は方向を表すため、作り出す対象である椅子を示すことができない。", "より": "「より」は比較の助詞で、「椅子より作り出した」では文の意味が通らない。", "と": "「と」は「〜と一緒に」の意味になり、作り出す対象にはならない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
