INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "材料や力を使って、物や電気などを作って生み出すこと。", "primary_collocate": null, "pronunciation": "つくりだす", "ipa": "tsɯkɯɾidasɯ", "syllable_count": 5, "sentences": [{"text": "この工場では、毎日千個のパンを作り出している。", "target_word": "作り出して", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、毎日[まいにち]千個[せんこ]のパンを作[つく]り出[だ]している。", "sentence_source": "generated"}, {"text": "その会社は、新しい素材で軽い椅子を作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "その会社は、新しい素材で軽い椅子を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "機械は、一日で大量の部品を作り出す。", "target_word": "作り出す", "complexity_tier": "T3", "furigana": "機械[きかい]は、一日[いちにち]で大量[たいりょう]の部品[ぶひん]を作[つく]り出[だ]す。", "sentence_source": "generated"}, {"text": "風車は風の力で電気を作り出す。", "target_word": "作り出す", "complexity_tier": "T3", "furigana": "風車[ふうしゃ]は風[かぜ]の力[ちから]で電気[でんき]を作[つく]り出[だ]す。", "sentence_source": "generated"}, {"text": "母は残りの野菜から、おいしいスープを作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "母[はは]は残[のこ]りの野菜[やさい]から、おいしいスープを作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "彼らは、ひと晩でこの大きな舞台を作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "彼[かれ]らは、ひと晩[ばん]でこの大[おお]きな舞台[ぶたい]を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "火山の熱を使って、電気を作り出す国もある。", "target_word": "作り出す", "complexity_tier": "T3", "furigana": "火山[かざん]の熱[ねつ]を使[つか]って、電気[でんき]を作[つく]り出[だ]す国[くに]もある。", "sentence_source": "generated"}, {"text": "この機械を使えば、安いおもちゃを作り出せる。", "target_word": "作り出せる", "complexity_tier": "T3", "furigana": "この機械[きかい]を使[つか]えば、安[やす]いおもちゃを作[つく]り出[だ]せる。", "sentence_source": "generated"}, {"text": "蜂は花の蜜から、甘い蜂蜜を作り出す。", "target_word": "作り出す", "complexity_tier": "T4", "furigana": "蜂[はち]は花[はな]の蜜[みつ]から、甘[あま]い蜂蜜[はちみつ]を作[つく]り出[だ]す。", "sentence_source": "generated"}, {"text": "子どもたちは、粘土でいろいろな動物を作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、粘土[ねんど]でいろいろな動物[どうぶつ]を作[つく]り出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作り出す", "label": "終止形"}, {"form": "作り出します", "label": "ます形"}, {"form": "作り出して", "label": "て形"}, {"form": "作り出した", "label": "た形"}, {"form": "作り出さない", "label": "ない形"}, {"form": "作り出せる", "label": "可能形"}], "register": "中立的な標準語", "sense_fingerprint": "材料や力を使って、物や電気などを作って生み出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: ひと晩 (Zipf 1.5)']::text[], 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作り出して", "is_correct": true, "explanation": "「作り出している」は「作り出して」＋「いる」の形で、「毎日千個のパンを作り出している」が自然になる。"}, {"text": "作り出さない", "is_correct": false, "explanation": "「作り出さないいる」は文として成り立たない。ない形は「いる」と直接つながらない。"}, {"text": "作り出す", "is_correct": false, "explanation": "「作り出すいる」は不自然。辞書形の後に「いる」を直接続けることはできない。"}, {"text": "作り出した", "is_correct": false, "explanation": "「作り出したいる」は成り立たない。た形の後に「いる」は続かない。"}], "explanations": {"作り出して": "「作り出している」は「作り出して」＋「いる」の形で、「毎日千個のパンを作り出している」が自然になる。", "作り出さない": "「作り出さないいる」は文として成り立たない。ない形は「いる」と直接つながらない。", "作り出す": "「作り出すいる」は不自然。辞書形の後に「いる」を直接続けることはできない。", "作り出した": "「作り出したいる」は成り立たない。た形の後に「いる」は続かない。"}, "sentence_index": 0, "correct_answer": "作り出して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は鞄から、新しい理論のメモを作り出した。", "explanation": "ここは〈取り出す〉の意味。鞄の中にある物を出すのは取り出すで、作り出すとは言わない。"}, {"text": "作業員は、古い機械の電源を作り出した。", "explanation": "ここは〈切る〉の意味。電源を入れたり切ったりするのは操作で、作り出すとは言わない。"}, {"text": "先生は、宿題の答えを作り出した。", "explanation": "ここは〈導き出す〉の意味。答えは考えて見つけるものなので、作り出すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作り出す", "is_correct": true, "explanation": "「電気を作り出す国もある」は、電気を生み出す国という意味で、名詞を修飾する形として自然。"}, {"text": "作り出して", "is_correct": false, "explanation": "て形は名詞を修飾できず、「電気を作り出して国もある」は成り立たない。"}, {"text": "作り出そう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「作り出そう国」は不自然。"}, {"text": "作り出します", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できず、「作り出します国」は文として成り立たない。"}], "explanations": {"作り出す": "「電気を作り出す国もある」は、電気を生み出す国という意味で、名詞を修飾する形として自然。", "作り出して": "て形は名詞を修飾できず、「電気を作り出して国もある」は成り立たない。", "作り出そう": "意志形は名詞を修飾できず、「作り出そう国」は不自然。", "作り出します": "丁寧形は名詞を直接修飾できず、「作り出します国」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "作り出す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、騒いだ生徒を教室から作り出した。", "explanation": "ここは〈追い出す〉の意味。生徒を外へ出すのは追い出すで、作り出すとは言わない。"}, {"text": "ハンターは、畑の害獣を作り出した。", "explanation": "ここは〈退治する〉の意味。害獣を倒すのは退治で、作り出すとは言わない。"}, {"text": "作業員は、古い看板の汚れを作り出した。", "explanation": "ここは〈落とす〉の意味。汚れを取り除くのは落とすで、作り出すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月の工場では、新しい部品を作り出した予定だ。", "corrected_sentence": "来月の工場では、新しい部品を作り出す予定だ。", "error_description": "「来月」「予定」は未来の出来事なので、動詞は辞書形の「作り出す」にする。「作り出した」は過去形で、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "作り出した", "is_correct": true, "explanation": "た形で、会社が椅子を作り出したという完了した出来事を表す。"}, {"text": "作り出す", "is_correct": false, "explanation": "辞書形は現在や未来の動作を表すため、過去の出来事を述べる文には合わない。"}, {"text": "作り出して", "is_correct": false, "explanation": "て形は文末では使えず、「作り出して。」では文が完結しない。"}, {"text": "作り出さない", "is_correct": false, "explanation": "ない形は否定を表すため、椅子を作ったという肯定の出来事とは意味が逆になる。"}], "correct_form": "作り出した", "base_form": "作り出す", "form_label": "た形", "sentence_index": 1, "explanations": {"作り出した": "た形で、会社が椅子を作り出したという完了した出来事を表す。", "作り出す": "辞書形は現在や未来の動作を表すため、過去の出来事を述べる文には合わない。", "作り出して": "て形は文末では使えず、「作り出して。」では文が完結しない。", "作り出さない": "ない形は否定を表すため、椅子を作ったという肯定の出来事とは意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35990, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は、大量の電気を作り出る。", "corrected_sentence": "この機械は、大量の電気を作り出す。", "error_description": "「作り出す」は他動詞で、電気などを生み出す意味。「作り出る」という動詞は存在せず、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "作り出せる", "is_correct": true, "explanation": "可能形で、機械を使えばおもちゃを作れるという能力や可能性を表す。"}, {"text": "作り出します", "is_correct": false, "explanation": "ます形は丁寧な言い方で、可能の意味を表せない。"}, {"text": "作り出そう", "is_correct": false, "explanation": "意志形は話し手の意志や勧誘を表し、可能の意味にはならない。"}, {"text": "作り出した", "is_correct": false, "explanation": "た形は過去の出来事を表すため、「使えば」の仮定とは合わない。"}], "correct_form": "作り出せる", "base_form": "作り出す", "form_label": "可能形", "sentence_index": 7, "explanations": {"作り出せる": "可能形で、機械を使えばおもちゃを作れるという能力や可能性を表す。", "作り出します": "ます形は丁寧な言い方で、可能の意味を表せない。", "作り出そう": "意志形は話し手の意志や勧誘を表し、可能の意味にはならない。", "作り出した": "た形は過去の出来事を表すため、「使えば」の仮定とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
