INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アイデアを作り出そう」は、作り出す対象を示す「を」で自然に成り立つ。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「アイデアの作り出そう」では動詞の対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を表し、作り出す対象にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「アイデアが作り出そう」は、意志形の文で主語と意志が合わず不自然。"}], "correct_answer": "を", "explanations": {"を": "「アイデアを作り出そう」は、作り出す対象を示す「を」で自然に成り立つ。", "の": "「の」は名詞をつなぐ助詞で、「アイデアの作り出そう」では動詞の対象を示せない。", "に": "「に」は到達点や相手を表し、作り出す対象にはならない。", "が": "「アイデアが作り出そう」は、意志形の文で主語と意志が合わず不自然。"}, "error_tags": {"の": "連体", "に": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "新しいものや考えを、自分の力でつくること。", "primary_collocate": null, "pronunciation": "つくりだす", "ipa": "tsɯkɯɾidasɯ", "syllable_count": 5, "sentences": [{"text": "彼は、これまでにない新しい遊びを作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "彼[かれ]は、これまでにない新[あたら]しい遊[あそ]びを作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "若い研究者が、世界を変える技術を作り出した。", "target_word": "作り出した", "complexity_tier": "T4", "furigana": "若[わか]い研究者[けんきゅうしゃ]が、世界[せかい]を変[か]える技術[ぎじゅつ]を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "自分の力で新しい仕事を作り出すのは簡単ではない。", "target_word": "作り出す", "complexity_tier": "T4", "furigana": "自分[じぶん]の力[ちから]で新[あたら]しい仕事[しごと]を作[つく]り出[だ]すのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "この画家は、独特の色づかいで新しい世界を作り出した。", "target_word": "作り出した", "complexity_tier": "T4", "furigana": "この画家[がか]は、独特[どくとく]の色[いろ]づかいで新[あたら]しい世界[せかい]を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "失敗を恐れなければ、新しい考えを作り出せる。", "target_word": "作り出せる", "complexity_tier": "T4", "furigana": "失敗[しっぱい]を恐[おそ]れなければ、新[あたら]しい考[かんが]えを作[つく]り出[だ]せる。", "sentence_source": "generated"}, {"text": "彼女は物語の中で、不思議な国を作り出した。", "target_word": "作り出した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は物語[ものがたり]の中[なか]で、不思議[ふしぎ]な国[くに]を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "会社は、若者向けの新しい流行を作り出そうとしている。", "target_word": "作り出そう", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、若者向[わかものむ]けの新[あたら]しい流行[りゅうこう]を作[つく]り出[だ]そうとしている。", "sentence_source": "generated"}, {"text": "一人で悩まず、みんなで新しいアイデアを作り出そう。", "target_word": "作り出そう", "complexity_tier": "T3", "furigana": "一人[ひとり]で悩[なや]まず、みんなで新[あたら]しいアイデアを作[つく]り出[だ]そう。", "sentence_source": "generated"}, {"text": "発明家は、だれも考えなかった道具を作り出した。", "target_word": "作り出した", "complexity_tier": "T4", "furigana": "発明家[はつめいか]は、だれも考[かんが]えなかった道具[どうぐ]を作[つく]り出[だ]した。", "sentence_source": "generated"}, {"text": "料理人は、古い味に工夫を加えて、新しい料理を作り出した。", "target_word": "作り出した", "complexity_tier": "T4", "furigana": "料理人[りょうりにん]は、古[ふる]い味[あじ]に工夫[くふう]を加[くわ]えて、新[あたら]しい料理[りょうり]を作[つく]り出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作り出す", "label": "終止形"}, {"form": "作り出します", "label": "ます形"}, {"form": "作り出して", "label": "て形"}, {"form": "作り出した", "label": "た形"}, {"form": "作り出さない", "label": "ない形"}, {"form": "作り出せる", "label": "可能形"}], "register": "中立的な標準語", "sense_fingerprint": "今までになかった新しい物・考え・流れを、自分の工夫で生み出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 色づか (Zipf 1.64)']::text[], 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作り出した", "is_correct": true, "explanation": "「彼は、これまでにない新しい遊びを作り出した」は過去の出来事として完結し、空所に合う。"}, {"text": "作り出し", "is_correct": false, "explanation": "「新しい遊びを作り出し。」は文が完結せず、成り立たない。"}, {"text": "作り出さ", "is_correct": false, "explanation": "「作り出さ」は語幹の途中で、単独では文末に置けない。"}, {"text": "作り出せ", "is_correct": false, "explanation": "「作り出せ」は命令形となり、「彼は…遊びを作り出せ。」は文として不自然。"}], "explanations": {"作り出した": "「彼は、これまでにない新しい遊びを作り出した」は過去の出来事として完結し、空所に合う。", "作り出し": "「新しい遊びを作り出し。」は文が完結せず、成り立たない。", "作り出さ": "「作り出さ」は語幹の途中で、単独では文末に置けない。", "作り出せ": "「作り出せ」は命令形となり、「彼は…遊びを作り出せ。」は文として不自然。"}, "sentence_index": 0, "correct_answer": "作り出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、ほどけた靴ひもを作り出した。", "explanation": "ここは〈結び直す〉の意味。ほどけたものをもう一度結ぶのは結び直すで、作り出すとは言わない。"}, {"text": "探検家は、海の底から古い船を作り出した。", "explanation": "ここは〈引き上げる〉の意味。海の底の物を持ち上げるのは引き上げるで、作り出すとは言わない。"}, {"text": "彼は、昔の友達の名前を作り出した。", "explanation": "ここは〈思い出す〉の意味。記憶から引き出すことは思い出すで、作り出すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作り出そう", "is_correct": true, "explanation": "「作り出そうとしている」は、会社が流行を生み出そうとしている意味で、空所に合う。"}, {"text": "作り出して", "is_correct": false, "explanation": "「作り出してとしている」は成り立たない。て形は「としている」と続かない。"}, {"text": "作り出します", "is_correct": false, "explanation": "丁寧形は「としている」と続けられず、文が不自然になる。"}, {"text": "作り出せ", "is_correct": false, "explanation": "命令形は「としている」に続かず、文として成り立たない。"}], "explanations": {"作り出そう": "「作り出そうとしている」は、会社が流行を生み出そうとしている意味で、空所に合う。", "作り出して": "「作り出してとしている」は成り立たない。て形は「としている」と続かない。", "作り出します": "丁寧形は「としている」と続けられず、文が不自然になる。", "作り出せ": "命令形は「としている」に続かず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "作り出そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、英語の本を作り出して、日本語にした。", "explanation": "ここは〈翻訳する〉の意味。既にある文章を別の言語に移すのは翻訳で、作り出すとは言わない。"}, {"text": "店員は、保存された映像を作り出して、すぐに寝た。", "explanation": "ここは〈再生する〉の意味。保存された映像を映すのは再生で、作り出すとは言わない。"}, {"text": "観客は、名画を作り出して楽しんだ。", "explanation": "ここは〈鑑賞する〉の意味。作品を味わうことは鑑賞で、作り出すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この大学では、新しい研究を作り出した計画だ。", "corrected_sentence": "この大学では、新しい研究を作り出す計画だ。", "error_description": "「計画」は未来の予定を表すので、動詞は辞書形の「作り出す」にする。「作り出した」は過去形で、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "作り出した", "is_correct": true, "explanation": "た形で、若い研究者が技術を生み出したという完了した出来事を表す。"}, {"text": "作り出す", "is_correct": false, "explanation": "辞書形は現在や未来の動作を表すため、過去の成果を述べる文には合わない。"}, {"text": "作り出して", "is_correct": false, "explanation": "て形は文末では使えず、文が完結しない。"}, {"text": "作り出せる", "is_correct": false, "explanation": "可能形は能力や可能性を表すため、既に成し遂げた出来事とは意味が合わない。"}], "correct_form": "作り出した", "base_form": "作り出す", "form_label": "た形", "sentence_index": 1, "explanations": {"作り出した": "た形で、若い研究者が技術を生み出したという完了した出来事を表す。", "作り出す": "辞書形は現在や未来の動作を表すため、過去の成果を述べる文には合わない。", "作り出して": "て形は文末では使えず、文が完結しない。", "作り出せる": "可能形は能力や可能性を表すため、既に成し遂げた出来事とは意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35991, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若者は、新しい流行が作り出そうとしている。", "corrected_sentence": "若者は、新しい流行を作り出そうとしている。", "error_description": "「作り出す」は目的語に「を」を取る。「新しい流行が」は誤りで、正しくは「新しい流行を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "作り出そう", "is_correct": true, "explanation": "意志形で、みんなで新しいアイデアを生み出そうという勧誘を表す。"}, {"text": "作り出します", "is_correct": false, "explanation": "ます形は丁寧な言い方で、勧誘の意味を表せない。"}, {"text": "作り出さない", "is_correct": false, "explanation": "ない形は否定を表し、「作り出さない」では勧誘の意味が逆になる。"}, {"text": "作り出した", "is_correct": false, "explanation": "た形は過去の出来事を表すため、これから行う勧誘とは合わない。"}], "correct_form": "作り出そう", "base_form": "作り出す", "form_label": "意志形", "sentence_index": 7, "explanations": {"作り出そう": "意志形で、みんなで新しいアイデアを生み出そうという勧誘を表す。", "作り出します": "ます形は丁寧な言い方で、勧誘の意味を表せない。", "作り出さない": "ない形は否定を表し、「作り出さない」では勧誘の意味が逆になる。", "作り出した": "た形は過去の出来事を表すため、これから行う勧誘とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「形が犬に似ていて」で、似ているものの主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「形を犬に似ていて」は「似る」の目的語にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「形へ犬に似ていて」は方向の意味にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「形の犬に似ていて」は連体修飾として不自然で、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「形が犬に似ていて」で、似ているものの主語を示す「が」。", "を": "「形を犬に似ていて」は「似る」の目的語にならず、不自然。", "へ": "「形へ犬に似ていて」は方向の意味にならず、文が成り立たない。", "の": "「形の犬に似ていて」は連体修飾として不自然で、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「形を作って」で、作る対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「形が作って」では、作る対象にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「形と作って」は並列の意味にならず、文の流れが合わない。"}, {"text": "より", "is_correct": false, "explanation": "「形より作って」は比較の文にならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「形を作って」で、作る対象を示す「を」。", "が": "「形が作って」では、作る対象にならず、文が成り立たない。", "と": "「形と作って」は並列の意味にならず、文の流れが合わない。", "より": "「形より作って」は比較の文にならず、不自然。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものが見えるとおりの、外のようす。", "primary_collocate": null, "pronunciation": "かたち", "ipa": "katat͡ɕi", "syllable_count": 3, "sentences": [{"text": "この石は丸い形をしていて、手に持つと気持ちがいいです。", "target_word": "形", "complexity_tier": "T3", "furigana": "この石[いし]は丸[まる]い形[かたち]をしていて、手[て]に持[も]つと気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "雲の形が犬に似ていて、子どもたちは笑いました。", "target_word": "形", "complexity_tier": "T3", "furigana": "雲[くも]の形[かたち]が犬[いぬ]に似[に]ていて、子[こ]どもたちは笑[わら]いました。", "sentence_source": "generated"}, {"text": "雨に濡れて、帽子の形が変わってしまいました。", "target_word": "形", "complexity_tier": "T3", "furigana": "雨[あめ]に濡[ぬ]れて、帽子[ぼうし]の形[かたち]が変[か]わってしまいました。", "sentence_source": "generated"}, {"text": "母は野菜をいろいろな形に切って、お弁当に入れました。", "target_word": "形", "complexity_tier": "T3", "furigana": "母[はは]は野菜[やさい]をいろいろな形[かたち]に切[き]って、お弁当[べんとう]に入[い]れました。", "sentence_source": "generated"}, {"text": "ケーキは星の形で、とてもかわいかったです。", "target_word": "形", "complexity_tier": "T3", "furigana": "ケーキは星[ほし]の形[かたち]で、とてもかわいかったです。", "sentence_source": "generated"}, {"text": "暗くて色はわかりませんでしたが、窓の外に人の形が見えました。", "target_word": "形", "complexity_tier": "T3", "furigana": "暗[くら]くて色[いろ]はわかりませんでしたが、窓[まど]の外[そと]に人[ひと]の形[かたち]が見[み]えました。", "sentence_source": "generated"}, {"text": "このびんは形が変わっているので、すぐ見つかります。", "target_word": "形", "complexity_tier": "T3", "furigana": "このびんは形[かたち]が変[か]わっているので、すぐ見[み]つかります。", "sentence_source": "generated"}, {"text": "粘土で好きな形を作って、焼くとカップになります。", "target_word": "形", "complexity_tier": "T3", "furigana": "粘土[ねんど]で好[す]きな形[かたち]を作[つく]って、焼[や]くとカップになります。", "sentence_source": "generated"}, {"text": "古い建物ですが、百年前の形のまま残っています。", "target_word": "形", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]ですが、百年前[ひゃくねんまえ]の形[かたち]のまま残[のこ]っています。", "sentence_source": "generated"}, {"text": "箱の形はちがっても、中身は同じお菓子です。", "target_word": "形", "complexity_tier": "T3", "furigana": "箱[はこ]の形[かたち]はちがっても、中身[なかみ]は同[おな]じお菓子[かし]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形", "label": "基本形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "目で見える物の外側のようす。丸い・四角いなどの輪郭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形", "is_correct": true, "explanation": "「丸い形をしている」で、目に見える外のようすを表す。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、「丸い味」とは言わない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いには形がないので、「丸い匂い」とは続かない。"}, {"text": "温度", "is_correct": false, "explanation": "温度には形がないので、「丸い温度」とは言わない。"}], "explanations": {"形": "「丸い形をしている」で、目に見える外のようすを表す。", "味": "味は食べ物の性質で、「丸い味」とは言わない。", "匂い": "匂いには形がないので、「丸い匂い」とは続かない。", "温度": "温度には形がないので、「丸い温度」とは言わない。"}, "sentence_index": 0, "correct_answer": "形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツは形が赤くて、夏らしい感じがします。", "explanation": "ここは〈色〉の意味。「赤い」は色を表すので、目に見える外のようすを指す形とは合わない。"}, {"text": "彼は形がまじめで、約束を守ります。", "explanation": "ここは〈性格〉の意味。形は外のようすなので、人の性格を表して「まじめ」とは言わない。"}, {"text": "このスープは、塩の形がきいています。", "explanation": "ここは〈味〉の意味。形は目に見えるようすなので、味がきいているとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形", "is_correct": true, "explanation": "「形が変わる」で、外のようすの変化を表す。"}, {"text": "電話", "is_correct": false, "explanation": "電話は物の状態が変わるものではなく、「電話が変わっている」は文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆はびんの変化の主語にならず、文脈に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓はびんの変化を表す語ではなく、文脈に合わない。"}], "explanations": {"形": "「形が変わる」で、外のようすの変化を表す。", "電話": "電話は物の状態が変わるものではなく、「電話が変わっている」は文脈に合わない。", "鉛筆": "鉛筆はびんの変化の主語にならず、文脈に合わない。", "窓": "窓はびんの変化を表す語ではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は堂々とした形で舞台に立ちました。", "explanation": "ここは〈姿〉の意味。形は物の外のようすを指し、人の立ち居ふるまいには使わない。"}, {"text": "ピアノの形が、部屋中に響きました。", "explanation": "ここは〈音〉の意味。形は目に見えるようすなので、音が響くとは言わない。"}, {"text": "この花は形が強くて、部屋中に広がりました。", "explanation": "ここは〈におい〉の意味。「強い」「広がる」はにおいに使うが、形は目に見えるようすなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空に浮かぶ雲の形が見て、明日は晴れると思いました。", "corrected_sentence": "空に浮かぶ雲の形を見て、明日は晴れると思いました。", "error_description": "「見る」の対象には「を」を使う。「が」は誤りで、正しくは「雲の形を見て」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35994, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パンを、ハートの形を切りました。", "corrected_sentence": "パンを、ハートの形に切りました。", "error_description": "「切る」の仕上がりの形を示すには「に」を使う。「を」は誤りで、正しくは「ハートの形に切りました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
