INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35996, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが全部の部分を終えて、最後の形になること。", "primary_collocate": null, "pronunciation": "できあがる", "ipa": "dekiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "料理が出来上がったら、みんなで食べましょう。", "target_word": "出来上がった", "complexity_tier": "T3", "furigana": "料理[りょうり]が出来上[できあ]がったら、みんなで食[た]べましょう。", "sentence_source": "generated"}, {"text": "三か月かけて、大きな絵がやっと出来上がりました。", "target_word": "出来上がり", "complexity_tier": "T3", "furigana": "三[さん]か月[げつ]かけて、大[おお]きな絵[え]がやっと出来上[できあ]がりました。", "sentence_source": "generated"}, {"text": "注文したスーツは、来週には出来上がる予定です。", "target_word": "出来上がる", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]したスーツは、来週[らいしゅう]には出来上[できあ]がる予定[よてい]です。", "sentence_source": "generated"}, {"text": "模型が出来上がったので、棚の上にかざりました。", "target_word": "出来上がった", "complexity_tier": "T3", "furigana": "模型[もけい]が出来上[できあ]がったので、棚[たな]の上[うえ]にかざりました。", "sentence_source": "generated"}, {"text": "セーターが出来上がるまで、あと二日かかります。", "target_word": "出来上がる", "complexity_tier": "T3", "furigana": "セーターが出来上[できあ]がるまで、あと二日[ふつか]かかります。", "sentence_source": "generated"}, {"text": "パンが出来上がると、店中にいい匂いが広がります。", "target_word": "出来上がる", "complexity_tier": "T3", "furigana": "パンが出来上[できあ]がると、店中[みせじゅう]にいい匂[にお]いが広[ひろ]がります。", "sentence_source": "generated"}, {"text": "写真が出来上がっているか、店に聞いてみます。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "写真[しゃしん]が出来上[できあ]がっているか、店[みせ]に聞[き]いてみます。", "sentence_source": "generated"}, {"text": "出来上がった作品を見て、先生は大きくうなずきました。", "target_word": "出来上がった", "complexity_tier": "T3", "furigana": "出来上[できあ]がった作品[さくひん]を見[み]て、先生[せんせい]は大[おお]きくうなずきました。", "sentence_source": "generated"}, {"text": "ケーキはまだ出来上がっていないので、少し待ってください。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "ケーキはまだ出来上[できあ]がっていないので、少[すこ]し待[ま]ってください。", "sentence_source": "generated"}, {"text": "橋が出来上がって、川の向こうへ歩いて行けるようになりました。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "橋[はし]が出来上[できあ]がって、川[かわ]の向[む]こうへ歩[ある]いて行[い]けるようになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出来上がる", "label": "基本形"}, {"form": "出来上がらない", "label": "否定形"}, {"form": "出来上がります", "label": "ます形"}, {"form": "出来上がった", "label": "過去形"}, {"form": "出来上がって", "label": "て形"}, {"form": "出来上がれば", "label": "仮定形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "料理・絵・服など作っている物が仕上がって完成する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35996, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出来上がった", "is_correct": true, "explanation": "「出来上がったら」で、完成した後の条件を表す。"}, {"text": "出来上がらない", "is_correct": false, "explanation": "否定形で、「出来上がらないら」とは続かない。"}, {"text": "出来上がります", "is_correct": false, "explanation": "ます形で、「出来上がりますら」とは続かず文が成り立たない。"}, {"text": "出来上がり", "is_correct": false, "explanation": "連用形で、「出来上がりら」とは続かず文が成り立たない。"}], "explanations": {"出来上がった": "「出来上がったら」で、完成した後の条件を表す。", "出来上がらない": "否定形で、「出来上がらないら」とは続かない。", "出来上がります": "ます形で、「出来上がりますら」とは続かず文が成り立たない。", "出来上がり": "連用形で、「出来上がりら」とは続かず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "出来上がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議が出来上がって、みんな帰りました。", "explanation": "ここは〈終わる〉の意味。出来上がるは物や作品が完成することに使うので、会議には合わない。"}, {"text": "庭の花が出来上がって、家中に香りが広がりました。", "explanation": "ここは〈咲く〉の意味。出来上がるは完成した物に使うので、花が開くことには合わない。"}, {"text": "子どもが出来上がって、家が静かになりました。", "explanation": "ここは〈寝る〉の意味。出来上がるは物や作品の完成に使うので、人が眠ることには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35996, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出来上がって", "is_correct": true, "explanation": "「出来上がっている」の形で、完成した状態を表す。"}, {"text": "出来上がる", "is_correct": false, "explanation": "基本形で、「出来上がるいるか」とは続かず文が成り立たない。"}, {"text": "出来上がろう", "is_correct": false, "explanation": "意志形で、「出来上がろういるか」は文が成り立たない。"}, {"text": "出来上がらず", "is_correct": false, "explanation": "否定の連用形で、「出来上がらずいるか」とは続かず不自然。"}], "explanations": {"出来上がって": "「出来上がっている」の形で、完成した状態を表す。", "出来上がる": "基本形で、「出来上がるいるか」とは続かず文が成り立たない。", "出来上がろう": "意志形で、「出来上がろういるか」は文が成り立たない。", "出来上がらず": "否定の連用形で、「出来上がらずいるか」とは続かず不自然。"}, "sentence_index": 6, "correct_answer": "出来上がって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が出来上がって、外で遊べるようになりました。", "explanation": "ここは〈やむ〉の意味。出来上がるは物や作品の完成に使うので、雨が止むことには合わない。"}, {"text": "急に時間が出来上がって、映画を見に行きました。", "explanation": "ここは〈出来る〉（時間が空く）の意味。出来上がるは物や作品が完成することに使うので、空いた時間には合わない。"}, {"text": "涙が出来上がって、声がかすれました。", "explanation": "ここは〈出る〉の意味。出来上がるは物や作品の完成に使うので、涙が出ることには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35996, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンが出来上がらったら、すぐ食べてください。", "corrected_sentence": "パンが出来上がったら、すぐ食べてください。", "error_description": "「〜たら」には過去形「出来上がった」を使う。「出来上がらった」は活用を誤っているので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出来上がり", "is_correct": true, "explanation": "「出来上がりました」の語幹で、ます形の連用形。"}, {"text": "出来上がらない", "is_correct": false, "explanation": "否定形で、「ました」の前には来ないので文が成り立たない。"}, {"text": "出来上がった", "is_correct": false, "explanation": "過去形で、「ました」と重なるため文法的に不自然。"}, {"text": "出来上がって", "is_correct": false, "explanation": "て形で、「ました」の前には入らないので文が成り立たない。"}], "correct_form": "出来上がり", "base_form": "出来上がる", "form_label": "連用形（ます形の語幹）", "sentence_index": 1, "explanations": {"出来上がり": "「出来上がりました」の語幹で、ます形の連用形。", "出来上がらない": "否定形で、「ました」の前には来ないので文が成り立たない。", "出来上がった": "過去形で、「ました」と重なるため文法的に不自然。", "出来上がって": "て形で、「ました」の前には入らないので文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35996, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "準備が出来上がるたら、すぐに出発しましょう。", "corrected_sentence": "準備が出来上がったら、すぐに出発しましょう。", "error_description": "「〜たら」には過去形「出来上がった」を使う。基本形「出来上がる」は誤りで、正しくは「出来上がったら」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出来上がった", "is_correct": true, "explanation": "「作品」を修飾する過去形（た形）で、完成済みの作品を表す。"}, {"text": "出来上がって", "is_correct": false, "explanation": "て形は名詞「作品」を直接修飾できず、文が成り立たない。"}, {"text": "出来上がろう", "is_correct": false, "explanation": "意志形で名詞を修飾できず、「作品」の前には入らない。"}, {"text": "出来上がらず", "is_correct": false, "explanation": "否定の連用形で、「作品」を修飾して完成の意味にはならない。"}], "correct_form": "出来上がった", "base_form": "出来上がる", "form_label": "過去形（連体修飾）", "sentence_index": 7, "explanations": {"出来上がった": "「作品」を修飾する過去形（た形）で、完成済みの作品を表す。", "出来上がって": "て形は名詞「作品」を直接修飾できず、文が成り立たない。", "出来上がろう": "意志形で名詞を修飾できず、「作品」の前には入らない。", "出来上がらず": "否定の連用形で、「作品」を修飾して完成の意味にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「体が」で、出来上がる の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "出来上がるは自動詞なので、目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「体で出来上がる」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、体が出来上がる対象ではない。"}], "correct_answer": "が", "explanations": {"が": "「体が」で、出来上がる の主語を示す。", "を": "出来上がるは自動詞なので、目的語の「を」は取らない。", "で": "手段や場所を示すが、「体で出来上がる」とは言えない。", "へ": "方向を示すが、体が出来上がる対象ではない。"}, "error_tags": {"を": "目的格（自動詞）", "で": "手段・場所（文脈に合わない）", "へ": "方向（出来上がる対象ではない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「作戦が」で、出来上がらない の主語を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、主語の役割を果たさない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、文の流れに合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、作戦が主語になる文の流れに合わない。"}], "correct_answer": "が", "explanations": {"が": "「作戦が」で、出来上がらない の主語を示す。", "の": "連体修飾の「の」で、主語の役割を果たさない。", "より": "比較を示すが、文の流れに合わない。", "から": "起点を示すが、作戦が主語になる文の流れに合わない。"}, "error_tags": {"の": "連体修飾（主語にならない）", "より": "比較（文の流れに合わない）", "から": "起点（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事が最後まで行われて、完全な状態になること。", "primary_collocate": null, "pronunciation": "できあがる", "ipa": "dekiaɡaɾɯ", "syllable_count": 5, "sentences": [{"text": "旅行の計画が出来上がったので、みんなに送ります。", "target_word": "出来上がった", "complexity_tier": "T3", "furigana": "旅行[りょこう]の計画[けいかく]が出来上[できあ]がったので、みんなに送[おく]ります。", "sentence_source": "generated"}, {"text": "毎日の練習で、試合に出られる体が出来上がってきました。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "毎日[まいにち]の練習[れんしゅう]で、試合[しあい]に出[で]られる体[からだ]が出来上[できあ]がってきました。", "sentence_source": "generated"}, {"text": "準備はすっかり出来上がっているので、安心してください。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "準備[じゅんび]はすっかり出来上[できあ]がっているので、安心[あんしん]してください。", "sentence_source": "generated"}, {"text": "長い話し合いの末、新しい規則が出来上がりました。", "target_word": "出来上がり", "complexity_tier": "T3", "furigana": "長[なが]い話[はな]し合[あ]いの末[すえ]、新[あたら]しい規則[きそく]が出来上[できあ]がりました。", "sentence_source": "generated"}, {"text": "十年かけて、この町の静かな雰囲気が出来上がりました。", "target_word": "出来上がり", "complexity_tier": "T3", "furigana": "十年[じゅうねん]かけて、この町[まち]の静[しず]かな雰囲気[ふんいき]が出来上[できあ]がりました。", "sentence_source": "generated"}, {"text": "練習を重ねて、チームがようやく出来上がってきました。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を重[かさ]ねて、チームがようやく出来上[できあ]がってきました。", "sentence_source": "generated"}, {"text": "彼はもう出来上がった考えを持っていて、人の意見を聞きません。", "target_word": "出来上がった", "complexity_tier": "T3", "furigana": "彼[かれ]はもう出来上[できあ]がった考[かんが]えを持[も]っていて、人[ひと]の意見[いけん]を聞[き]きません。", "sentence_source": "generated"}, {"text": "会議の前に作戦が出来上がらなくて、とても焦りました。", "target_word": "出来上がらなくて", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に作戦[さくせん]が出来上[できあ]がらなくて、とても焦[あせ]りました。", "sentence_source": "generated"}, {"text": "二人の間には、深い信頼関係が出来上がっています。", "target_word": "出来上がって", "complexity_tier": "T3", "furigana": "二人[ふたり]の間[あいだ]には、深[ふか]い信頼関係[しんらいかんけい]が出来上[できあ]がっています。", "sentence_source": "generated"}, {"text": "決まりきった習慣が出来上がると、変えるのは大変です。", "target_word": "出来上がる", "complexity_tier": "T3", "furigana": "決[き]まりきった習慣[しゅうかん]が出来上[できあ]がると、変[か]えるのは大変[たいへん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出来上がる", "label": "基本形"}, {"form": "出来上がらない", "label": "否定形"}, {"form": "出来上がります", "label": "ます形"}, {"form": "出来上がった", "label": "過去形"}, {"form": "出来上がって", "label": "て形"}, {"form": "出来上がれば", "label": "仮定形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "計画・体・雰囲気・関係など形のない物事が整って完全な状態になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出来上がった", "is_correct": true, "explanation": "「ので」の前に完成した状態を表す過去形が入り、完成した計画を送る理由になる。"}, {"text": "出来上がろう", "is_correct": false, "explanation": "意志形で、「出来上がろうので」とは続かず文が成り立たない。"}, {"text": "出来上がれば", "is_correct": false, "explanation": "仮定形で、「出来上がれば〜ので」とは続かず文が成り立たない。"}, {"text": "忘れた", "is_correct": false, "explanation": "「計画が忘れた」は主語と動詞が合わず、文が成り立たない。"}], "explanations": {"出来上がった": "「ので」の前に完成した状態を表す過去形が入り、完成した計画を送る理由になる。", "出来上がろう": "意志形で、「出来上がろうので」とは続かず文が成り立たない。", "出来上がれば": "仮定形で、「出来上がれば〜ので」とは続かず文が成り立たない。", "忘れた": "「計画が忘れた」は主語と動詞が合わず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "出来上がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強風で、看板が出来上がって道をふさいだ。", "explanation": "ここは〈倒れる〉の意味。出来上がるは完成を表すので、看板が倒れて道をふさぐ出来事には合わない。"}, {"text": "昨日の強風で、庭の塀が出来上がってしまった。", "explanation": "ここは〈壊れる〉の意味。出来上がるは作って完成することなので、強風で壊れた塀には合わない。"}, {"text": "冷蔵庫の牛乳が、いつの間にか出来上がっていた。", "explanation": "ここは〈腐る〉の意味。出来上がるは物事の完成を表すので、食品が傷む変化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出来上がった", "is_correct": true, "explanation": "名詞「考え」を修飾する連体形で、完成した考えを表す。"}, {"text": "出来上がって", "is_correct": false, "explanation": "て形は名詞を直接修飾できないので、「考え」の前に入らない。"}, {"text": "出来上がれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できないので、「考えを持っていて」の前には入らない。"}, {"text": "出来上がります", "is_correct": false, "explanation": "丁寧形は名詞を修飾できないので、「考え」の前には入らない。"}], "explanations": {"出来上がった": "名詞「考え」を修飾する連体形で、完成した考えを表す。", "出来上がって": "て形は名詞を直接修飾できないので、「考え」の前に入らない。", "出来上がれば": "仮定形は名詞を修飾できないので、「考えを持っていて」の前には入らない。", "出来上がります": "丁寧形は名詞を修飾できないので、「考え」の前には入らない。"}, "sentence_index": 6, "correct_answer": "出来上がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方になって、街の明かりが出来上がった。", "explanation": "ここは〈消える〉の意味。出来上がるは完成を表すので、明かりが消える変化には合わない。"}, {"text": "虫に刺されて、足が出来上がった。", "explanation": "ここは〈腫れる〉の意味。出来上がるは物事の完成を表すので、体が腫れる変化には合わない。"}, {"text": "強い風で、木の枝が出来上がった。", "explanation": "ここは〈折れる〉の意味。出来上がるは作って完成することなので、枝が折れる出来事には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "資料の準備が出来上がってので、明日配ります。", "corrected_sentence": "資料の準備が出来上がったので、明日配ります。", "error_description": "「出来上がった」が正しい過去形。「出来上がってので」は、て形に「ので」を続けた誤りで、接続が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出来上がって", "is_correct": true, "explanation": "「てきました」の前に必要なて形。"}, {"text": "出来上がらない", "is_correct": false, "explanation": "否定形で、完成へ変化したことを述べる文に合わない。"}, {"text": "出来上がれば", "is_correct": false, "explanation": "仮定形で、「てきました」に続かない。"}, {"text": "出来上がった", "is_correct": false, "explanation": "過去形で、「てきました」の前には入らない。"}], "correct_form": "出来上がって", "base_form": "出来上がる", "form_label": "て形", "sentence_index": 1, "explanations": {"出来上がって": "「てきました」の前に必要なて形。", "出来上がらない": "否定形で、完成へ変化したことを述べる文に合わない。", "出来上がれば": "仮定形で、「てきました」に続かない。", "出来上がった": "過去形で、「てきました」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "準備がまだ出来上がっていなくで、少し待ってください。", "corrected_sentence": "準備がまだ出来上がっていないので、少し待ってください。", "error_description": "「出来上がっていない」に理由を続ける「ので」が正しい形。「なくで」は接続の形として存在せず、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出来上がらなくて", "is_correct": true, "explanation": "否定のて形。理由を述べる文に合う。"}, {"text": "出来上がります", "is_correct": false, "explanation": "丁寧な終止形で、「て」でつながる形ではないので、「焦りました」へ続かない。"}, {"text": "出来上がる", "is_correct": false, "explanation": "基本形で、後ろの「焦りました」へ理由としてつなげられない。"}, {"text": "出来上がらせて", "is_correct": false, "explanation": "使役形で、「作戦が」と合わず文が成り立たない。"}], "correct_form": "出来上がらなくて", "base_form": "出来上がる", "form_label": "否定のて形", "sentence_index": 7, "explanations": {"出来上がらなくて": "否定のて形。理由を述べる文に合う。", "出来上がります": "丁寧な終止形で、「て」でつながる形ではないので、「焦りました」へ続かない。", "出来上がる": "基本形で、後ろの「焦りました」へ理由としてつなげられない。", "出来上がらせて": "使役形で、「作戦が」と合わず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「体系がつくられている」の主語。作られる側の体系が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「体系をつくられている」は受身の主語にできず、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「体系につくられている」は作る対象を示す「に」と合わず、受身の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「体系とつくられている」は並列の「と」になり、作られる主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「体系がつくられている」の主語。作られる側の体系が主語になる。", "を": "「体系をつくられている」は受身の主語にできず、文として成り立たない。", "に": "「体系につくられている」は作る対象を示す「に」と合わず、受身の主語にならない。", "と": "「体系とつくられている」は並列の「と」になり、作られる主語を示せない。"}, "error_tags": {"を": "対象化", "に": "対象", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「音の体系がある」の主語。存在を示す「が」。"}, {"text": "へ", "is_correct": false, "explanation": "「体系へある」は方向の「へ」になり、存在を表す文と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「体系よりある」は比較の「より」になり、存在の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「体系からある」は起点の「から」になり、存在を表す文と合わない。"}], "correct_answer": "が", "explanations": {"が": "「音の体系がある」の主語。存在を示す「が」。", "へ": "「体系へある」は方向の「へ」になり、存在を表す文と合わない。", "より": "「体系よりある」は比較の「より」になり、存在の主語にならない。", "から": "「体系からある」は起点の「から」になり、存在を表す文と合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが、まとまって、もののしくみをつくっていること。", "primary_collocate": null, "pronunciation": "たいけい", "ipa": "taikeː", "syllable_count": 4, "sentences": [{"text": "太陽と惑星は、たがいに引き合って一つの体系をなしている。", "target_word": "体系", "complexity_tier": "T3", "furigana": "太陽(たいよう)と惑星(わくせい)は、たがいに引(ひ)き合(あ)って一(ひと)つの体系(たいけい)をなしている。", "sentence_source": "generated"}, {"text": "学校の勉強は、やさしいことから順に学べるよう体系がつくられている。", "target_word": "体系", "complexity_tier": "T3", "furigana": "学校(がっこう)の勉強(べんきょう)は、やさしいことから順(じゅん)に学(まな)べるよう体系(たいけい)がつくられている。", "sentence_source": "generated"}, {"text": "図鑑は、動物を分類の体系に沿って並べてあるので、目当ての種が探しやすい。", "target_word": "体系", "complexity_tier": "T3", "furigana": "図鑑(ずかん)は、動物(どうぶつ)を分類(ぶんるい)の体系(たいけい)に沿(そ)って並(なら)べてあるので、目当(めあ)ての種(たね)が探(さが)しやすい。", "sentence_source": "generated"}, {"text": "道路や線路や駅が結びつき、町の交通の体系ができている。", "target_word": "体系", "complexity_tier": "T3", "furigana": "道路(どうろ)や線路(せんろ)や駅(えき)が結(むす)びつき、町(まち)の交通(こうつう)の体系(たいけい)ができている。", "sentence_source": "generated"}, {"text": "漢字は、形と音と意味が関係し合う体系を持っている。", "target_word": "体系", "complexity_tier": "T3", "furigana": "漢字(かんじ)は、形(かたち)と音(おん)と意味(いみ)が関係(かんけい)し合(あ)う体系(たいけい)を持(も)っている。", "sentence_source": "generated"}, {"text": "血管や心臓が一つの体系をつくり、血を全身に運ぶ。", "target_word": "体系", "complexity_tier": "T3", "furigana": "血管(けっかん)や心臓(しんぞう)が一(ひと)つの体系(たいけい)をつくり、血(ち)を全身(ぜんしん)に運(はこ)ぶ。", "sentence_source": "generated"}, {"text": "この本は、料理の基本から応用までを一つの体系にまとめている。", "target_word": "体系", "complexity_tier": "T3", "furigana": "この本(ほん)は、料理(りょうり)の基本(きほん)から応用(おうよう)までを一(ひと)つの体系(たいけい)にまとめている。", "sentence_source": "generated"}, {"text": "音楽には、ドレミのような音の体系がある。", "target_word": "体系", "complexity_tier": "T2", "furigana": "音楽(おんがく)には、ドレミのような音(おと)の体系(たいけい)がある。", "sentence_source": "generated"}, {"text": "ルールが一つの体系にまとまっていれば、ゲームの遊び方を覚えやすい。", "target_word": "体系", "complexity_tier": "T3", "furigana": "ルールが一(ひと)つの体系(たいけい)にまとまっていれば、ゲームの遊(あそ)び方(かた)を覚(おぼ)えやすい。", "sentence_source": "generated"}, {"text": "昔の人は、季節の変化をもとに暦の体系をつくった。", "target_word": "体系", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、季節(きせつ)の変化(へんか)をもとに暦(こよみ)の体系(たいけい)をつくった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体系", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "いくつかのものがまとまって一つのしくみをつくっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 引き合っ (Zipf 1.59)']::text[], '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "「一つの体系をなしている」は要素がまとまって仕組みを作る意味で、天体の文に合う。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きを指し、天体がなす仕組みを表さないため文に合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は存続期間を指し、「一つの寿命をなしている」は成り立たない。"}, {"text": "紙幣", "is_correct": false, "explanation": "紙幣は紙のお金を指し、天体の仕組みには結びつかないため文に合わない。"}], "explanations": {"体系": "「一つの体系をなしている」は要素がまとまって仕組みを作る意味で、天体の文に合う。", "感情": "感情は心の動きを指し、天体がなす仕組みを表さないため文に合わない。", "寿命": "寿命は存続期間を指し、「一つの寿命をなしている」は成り立たない。", "紙幣": "紙幣は紙のお金を指し、天体の仕組みには結びつかないため文に合わない。"}, "sentence_index": 0, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この馬は名馬の体系を受け継いでいて、速く走る。", "explanation": "ここは〈系統〉の意味。体系は要素が結びついた仕組みを指し、血統の意味では使わない。"}, {"text": "店の前に、朝から長い体系ができている。", "explanation": "ここは〈行列〉の意味。体系は要素のつながりを指し、人が並んだ列には使わない。"}, {"text": "この教室の体系は三十人で、先生の目が届きやすい。", "explanation": "ここは〈人数〉の意味。体系は仕組みのまとまりを指し、人の数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "「一つの体系にまとめている」は要素を一つの仕組みにまとめる意味で、料理の本の文に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度を指し、料理の本をまとめる対象にならない。"}, {"text": "火山", "is_correct": false, "explanation": "火山は地形の一種を指し、「一つの火山にまとめている」は成り立たない。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることを指し、本の内容を一つにまとめる対象にならない。"}], "explanations": {"体系": "「一つの体系にまとめている」は要素を一つの仕組みにまとめる意味で、料理の本の文に合う。", "体温": "体温は体の温度を指し、料理の本をまとめる対象にならない。", "火山": "火山は地形の一種を指し、「一つの火山にまとめている」は成り立たない。", "睡眠": "睡眠は眠ることを指し、本の内容を一つにまとめる対象にならない。"}, "sentence_index": 6, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子は体系が十歳になった。", "explanation": "ここは〈年齢〉の意味。体系は仕組みのまとまりを指し、人の年の数には使わない。"}, {"text": "この子は体系が二・〇ある。", "explanation": "ここは〈視力〉の意味。体系は仕組みを指し、目の見える程度には使わない。"}, {"text": "この子は体系が広く、歩くのが速い。", "explanation": "ここは〈体型〉の意味。体系は仕組みのまとまりを指し、体つきには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この図は、惑星の体系に示している。", "corrected_sentence": "この図は、惑星の体系を示している。", "error_description": "正しくは「体系を示している」。「示す」は示す対象を「を」で受けるので、「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暦の体系を、季節の変化をもとに作られた。", "corrected_sentence": "暦の体系は、季節の変化をもとに作られた。", "error_description": "正しくは「暦の体系は、…作られた」。受身文の主語は「は」で示し、「を」は受身の主語にできず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「体系として」の「と」。体系という立場・資格で整えられたことを示す。"}, {"text": "を", "is_correct": false, "explanation": "「体系を整えられている」は整える対象を主語にできず、受身の形と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「体系へ整えられている」は方向の「へ」になり、整えた結果の形を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「体系の整えられている」は連体修飾になり、受身文の主語にならない。"}], "correct_answer": "と", "explanations": {"と": "「体系として」の「と」。体系という立場・資格で整えられたことを示す。", "を": "「体系を整えられている」は整える対象を主語にできず、受身の形と合わない。", "へ": "「体系へ整えられている」は方向の「へ」になり、整えた結果の形を示せない。", "の": "「体系の整えられている」は連体修飾になり、受身文の主語にならない。"}, "error_tags": {"を": "対象化", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素が互いに関係し合って、一つのまとまった全体を構成する仕組み。", "primary_collocate": null, "pronunciation": "たいけい", "ipa": "taikeː", "syllable_count": 4, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "体系", "complexity_tier": "T5", "furigana": "かかる感覚的(かんかくてき)知見(ちけん)の蓄積(ちくせき)は、単一(たんいつ)品種(ひんしゅ)を基準(きじゅん)とした旧来(きゅうらい)の分類(ぶんるい)体系(たいけい)を相対化(そうたいか)し、微細(びさい)な区画(くかく)ごとの個性(こせい)を階層的(かいそうてき)に位置(いち)づけるアペラシオンの概念(がいねん)を、より厳密(げんみつ)かつ動的(どうてき)なヒエラルキーへと昇華(しょうか)させ、ワインの価値(かち)評価(ひょうか)基準(きじゅん)そのものを哲学的(てつがくてき)かつ実践的(じっせんてき)に再定義(さいていぎ)しているのである。", "sentence_source": "mined"}, {"text": "法律は一つの体系として整えられているので、一部だけを変えると全体に影響が出る。", "target_word": "体系", "complexity_tier": "T4", "furigana": "法律(ほうりつ)は一(ひと)つの体系(たいけい)として整(ととの)えられているので、一部(いちぶ)だけを変(か)えると全体(ぜんたい)に影響(えいきょう)が出(で)る。", "sentence_source": "generated"}, {"text": "彼は十年かけて、自分の研究を理論の体系にまとめあげた。", "target_word": "体系", "complexity_tier": "T4", "furigana": "彼(かれ)は十年(じゅうねん)かけて、自分(じぶん)の研究(けんきゅう)を理論(りろん)の体系(たいけい)にまとめあげた。", "sentence_source": "generated"}, {"text": "この辞典は、語を意味の体系に沿って並べているので、類義語を探しやすい。", "target_word": "体系", "complexity_tier": "T4", "furigana": "この辞典(じてん)は、語(ご)を意味(いみ)の体系(たいけい)に沿(そ)って並(なら)べているので、類義語(るいぎご)を探(さが)しやすい。", "sentence_source": "generated"}, {"text": "税の体系が複雑すぎて、一般の人には全体がつかめない。", "target_word": "体系", "complexity_tier": "T3", "furigana": "税(ぜい)の体系(たいけい)が複雑(ふくざつ)すぎて、一般(いっぱん)の人(ひと)には全体(ぜんたい)がつかめない。", "sentence_source": "generated"}, {"text": "東洋医学には、西洋医学とは異なる独自の体系がある。", "target_word": "体系", "complexity_tier": "T3", "furigana": "東洋医学(とうよういがく)には、西洋医学(せいよういがく)とは異(こと)なる独自(どくじ)の体系(たいけい)がある。", "sentence_source": "generated"}, {"text": "教育の体系が整っていないと、学年が上がるにつれて学習に抜けが出る。", "target_word": "体系", "complexity_tier": "T4", "furigana": "教育(きょういく)の体系(たいけい)が整(ととの)っていないと、学年(がくねん)が上(あ)がるにつれて学習(がくしゅう)に抜(ぬ)けが出(で)る。", "sentence_source": "generated"}, {"text": "言語は音と文法と語彙が結びついた体系であり、単語の寄せ集めではない。", "target_word": "体系", "complexity_tier": "T4", "furigana": "言語(げんご)は音(おと)と文法(ぶんぽう)と語彙(ごい)が結(むす)びついた体系(たいけい)であり、単語(たんご)の寄(よ)せ集(あつ)めではない。", "sentence_source": "generated"}, {"text": "会社は給与の体系を見直し、年齢より成果を重んじることにした。", "target_word": "体系", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は給与(きゅうよ)の体系(たいけい)を見直(みなお)し、年齢(ねんれい)より成果(せいか)を重(おも)んじることにした。", "sentence_source": "generated"}, {"text": "彼女の知識は断片的で、一つの体系としてつながっていないため、応用問題が解けない。", "target_word": "体系", "complexity_tier": "T4", "furigana": "彼女(かのじょ)の知識(ちしき)は断片的(だんぺんてき)で、一(ひと)つの体系(たいけい)としてつながっていないため、応用問題(おうようもんだい)が解(と)けない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体系", "label": "基本形"}], "register": "formal", "sense_fingerprint": "要素が互いに結びついて全体を成す、理論・制度・知識などの仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "「旧来の分類体系」は要素が結びついた分類の仕組みを指し、文の「相対化」と合う。"}, {"text": "紙幣", "is_correct": false, "explanation": "紙幣は紙のお金を指し、「旧来の分類紙幣」は意味が通らない。"}, {"text": "火山", "is_correct": false, "explanation": "火山は地形の一種を指し、分類の仕組みを表さないため文に合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の言葉を指し、「旧来の分類歌詞」は成り立たない。"}], "explanations": {"体系": "「旧来の分類体系」は要素が結びついた分類の仕組みを指し、文の「相対化」と合う。", "紙幣": "紙幣は紙のお金を指し、「旧来の分類紙幣」は意味が通らない。", "火山": "火山は地形の一種を指し、分類の仕組みを表さないため文に合わない。", "歌詞": "歌詞は歌の言葉を指し、「旧来の分類歌詞」は成り立たない。"}, "sentence_index": 0, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は体系が大きいので、既製服のサイズが合いにくい。", "explanation": "ここは〈体型〉の意味。体系は要素のまとまった仕組みを指し、身体つきには使わない。"}, {"text": "この犬は祖父の体系を受け継いでいて、毛の色も同じだ。", "explanation": "ここは〈系統〉の意味。体系は要素が結びついた仕組みを指し、血筋や家系には使わない。"}, {"text": "ダイエットを始めて、体系が三キロ減った。", "explanation": "ここは〈体重〉の意味。体系は仕組みのまとまりを指し、体の重さを表さないので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "「教育の体系」は教育の仕組み全体を指し、「整っていないと」と文脈で合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、「教育の天気が整っていない」は意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合を指し、教育の仕組みを表さない。"}, {"text": "音色", "is_correct": false, "explanation": "音色は音の質を指し、教育の仕組みとは結びつかないため文に合わない。"}], "explanations": {"体系": "「教育の体系」は教育の仕組み全体を指し、「整っていないと」と文脈で合う。", "天気": "天気は空模様を指し、「教育の天気が整っていない」は意味が通らない。", "湿度": "湿度は空気中の水分の割合を指し、教育の仕組みを表さない。", "音色": "音色は音の質を指し、教育の仕組みとは結びつかないため文に合わない。"}, "sentence_index": 6, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は体系が一番高く、バレーボールの選手になった。", "explanation": "ここは〈身長〉の意味。体系は要素のまとまった仕組みを指し、背の高さには使わない。"}, {"text": "この犬は体系が長く、二十年近く生きた。", "explanation": "ここは〈寿命〉の意味。体系は仕組みのまとまりを指し、存続期間には使わない。"}, {"text": "熱が出て、彼女の体系は三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。体系は仕組みを指し、体の温度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は、給与の体系が見直す計画だ。", "corrected_sentence": "この会社は、給与の体系を見直す計画だ。", "error_description": "正しくは「体系を見直す」。「見直す」の対象は「を」で示すので、「が」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35999, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "知識は、一つの体系とまとめている。", "corrected_sentence": "知識は、一つの体系にまとめている。", "error_description": "正しくは「一つの体系にまとめている」。「まとめる」は結果を「に」で示すので、「と」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「空間が」で、「ある」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示すが、文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、存在を表す文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "「空間が」で、「ある」の主語を示す。", "を": "「ある」は目的語を取らないので、「を」は合わない。", "と": "並列や引用を示すが、文の流れに合わない。", "へ": "方向を示すが、存在を表す文脈に合わない。"}, "error_tags": {"を": "目的格（「ある」は目的語を取らない）", "と": "並列・引用（文の流れに合わない）", "へ": "方向（存在の文脈に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「空間が」で、「足りなくて」の主語を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「足りない」の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「足りない」の文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「足りない」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「空間が」で、「足りなくて」の主語を示す。", "の": "連体修飾の「の」で、「足りない」の主語にならない。", "より": "比較を示すが、「足りない」の文脈に合わない。", "から": "起点を示すが、「足りない」の主語にはならない。"}, "error_tags": {"の": "連体修飾（「足りない」の主語にならない）", "より": "比較（文の流れに合わない）", "から": "起点（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを置いたり人が動いたりできる、何もない広がりや場所。", "primary_collocate": null, "pronunciation": "くうかん", "ipa": "kɯːkaɴ", "syllable_count": 4, "sentences": [{"text": "この部屋は空間が広くて、大きな机を置いても楽です。", "target_word": "空間", "complexity_tier": "T3", "furigana": "この部屋[へや]は空間[くうかん]が広[ひろ]くて、大[おお]きな机[つくえ]を置[お]いても楽[らく]です。", "sentence_source": "generated"}, {"text": "本棚の横に小さな空間があるので、観葉植物を置きます。", "target_word": "空間", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の横[よこ]に小[ちい]さな空間[くうかん]があるので、観葉植物[かんようしょくぶつ]を置[お]きます。", "sentence_source": "generated"}, {"text": "箱の中の空間を上手に使って、荷物を全部入れました。", "target_word": "空間", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]の空間[くうかん]を上手[じょうず]に使[つか]って、荷物[にもつ]を全部[ぜんぶ]入[い]れました。", "sentence_source": "generated"}, {"text": "家具が多すぎて、部屋に歩く空間がありません。", "target_word": "空間", "complexity_tier": "T3", "furigana": "家具[かぐ]が多[おお]すぎて、部屋[へや]に歩[ある]く空間[くうかん]がありません。", "sentence_source": "generated"}, {"text": "白い壁と大きな窓が、明るい空間を作っています。", "target_word": "空間", "complexity_tier": "T3", "furigana": "白[しろ]い壁[かべ]と大[おお]きな窓[まど]が、明[あか]るい空間[くうかん]を作[つく]っています。", "sentence_source": "generated"}, {"text": "壁をなくしたら、台所とリビングが一つの広い空間になりました。", "target_word": "空間", "complexity_tier": "T3", "furigana": "壁[かべ]をなくしたら、台所[だいどころ]とリビングが一[ひと]つの広[ひろ]い空間[くうかん]になりました。", "sentence_source": "generated"}, {"text": "建築家は、人が落ち着ける空間を考えて図面を引きました。", "target_word": "空間", "complexity_tier": "T3", "furigana": "建築家[けんちくか]は、人[ひと]が落[お]ち着[つ]ける空間[くうかん]を考[かんが]えて図面[ずめん]を引[ひ]きました。", "sentence_source": "generated"}, {"text": "車の後ろに荷物を置く空間が足りなくて、一部を家に置いていきました。", "target_word": "空間", "complexity_tier": "T3", "furigana": "車[くるま]の後[うし]ろに荷物[にもつ]を置[お]く空間[くうかん]が足[た]りなくて、一部[いちぶ]を家[いえ]に置[お]いていきました。", "sentence_source": "generated"}, {"text": "図書館には、静かに本を読むための空間があります。", "target_word": "空間", "complexity_tier": "T3", "furigana": "図書館[としょかん]には、静[しず]かに本[ほん]を読[よ]むための空間[くうかん]があります。", "sentence_source": "generated"}, {"text": "宇宙には、星のない広い空間が続いています。", "target_word": "空間", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]には、星[ほし]のない広[ひろ]い空間[くうかん]が続[つづ]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空間", "label": "基本形"}], "register": "標準（です・ます体中心）", "sense_fingerprint": "物を置いたり人が動いたりできる、何もない広がりや場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空間", "is_correct": true, "explanation": "部屋の広さを表す主語として、「広くて」と合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は広さを持たないので、「料理が広くて」と合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気には広さがなく、部屋の主語にならない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽には広さがなく、「広くて」と続かない。"}], "explanations": {"空間": "部屋の広さを表す主語として、「広くて」と合う。", "料理": "料理は広さを持たないので、「料理が広くて」と合わない。", "天気": "天気には広さがなく、部屋の主語にならない。", "音楽": "音楽には広さがなく、「広くて」と続かない。"}, "sentence_index": 0, "correct_answer": "空間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この服は、空間が高いので買えなかった。", "explanation": "ここは〈値段〉の意味。空間は場所の広がりなので、品物の値段の高さには合わない。"}, {"text": "隣の部屋から、空間が聞こえてくる。", "explanation": "ここは〈音〉の意味。空間は場所の広がりなので、耳に届く音そのものは指さないので合わない。"}, {"text": "このスープは、空間が濃くておいしい。", "explanation": "ここは〈味〉の意味。空間は場所の広がりなので、味の濃さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空間", "is_correct": true, "explanation": "人が落ち着ける場所を指し、考える対象として合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は図面を引く対象にならず、考えて図面を引く流れに合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は場所ではないので、人が落ち着ける対象にならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は場所ではないので、人が落ち着ける図面の対象にならない。"}], "explanations": {"空間": "人が落ち着ける場所を指し、考える対象として合う。", "手紙": "手紙は図面を引く対象にならず、考えて図面を引く流れに合わない。", "味": "味は場所ではないので、人が落ち着ける対象にならない。", "天気": "天気は場所ではないので、人が落ち着ける図面の対象にならない。"}, "sentence_index": 6, "correct_answer": "空間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後の空間がゆっくり流れていく。", "explanation": "ここは〈時間〉の意味。時間の流れは表せるが、空間は流れるものではないので合わない。"}, {"text": "車の空間が急に上がった。", "explanation": "ここは〈速度〉の意味。空間は場所の広がりなので、速さの変化には合わない。"}, {"text": "レポートの空間を読んで、感想を書いた。", "explanation": "ここは〈内容〉の意味。空間は場所の広がりなので、文章の中身を読むことには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は空間を広くて、ベッドを置いても十分です。", "corrected_sentence": "この部屋は空間が広くて、ベッドを置いても十分です。", "error_description": "「広い」の主語は「空間」なので「が」が必要。「を」は目的語を取る用法で、形容詞「広い」には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
