INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「次元を」で、「変えて」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「変える」は他動詞なので、主語の「が」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「変えて」の目的語にならず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "引用や並列を示すが、「変える」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「次元を」で、「変えて」の目的語を示す。", "が": "「変える」は他動詞なので、主語の「が」は合わない。", "の": "連体修飾の「の」で、「変えて」の目的語にならず文が成り立たない。", "と": "引用や並列を示すが、「変える」の目的語にならない。"}, "error_tags": {"が": "主語（「変える」は他動詞）", "と": "引用（「変える」の目的語にならない）", "の": "連体修飾（名詞を受けず「変えて」に続かない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「次元を」で、「増やす」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「増やす」の対象ではない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「増やす」の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「次元と増やす」は「増やす」の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「次元を」で、「増やす」の目的語を示す。", "へ": "方向を示すが、「増やす」の対象ではない。", "の": "連体修飾の「の」で、「増やす」の目的語にならない。", "と": "並列を示すが、「次元と増やす」は「増やす」の対象にならない。"}, "error_tags": {"へ": "方向（「増やす」の対象ではない）", "の": "連体修飾（「増やす」の目的語にならない）", "と": "並列（「増やす」の対象にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を考えるときの、ある方向や角度のこと。", "primary_collocate": null, "pronunciation": "じげん", "ipa": "dʑiɡeɴ", "syllable_count": 3, "sentences": [{"text": "この問題は、別の次元から考えると答えが見えてくる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、別[べつ]の次元[じげん]から考[かんが]えると答[こた]えが見[み]えてくる。", "sentence_source": "generated"}, {"text": "次元を変えて考えれば、新しい解決策が見つかるかもしれない。", "target_word": "次元", "complexity_tier": "T3", "furigana": "次元[じげん]を変[か]えて考[かんが]えれば、新[あたら]しい解決策[かいけつさく]が見[み]つかるかもしれない。", "sentence_source": "generated"}, {"text": "二人は話す次元が違うので、議論がかみ合わない。", "target_word": "次元", "complexity_tier": "T3", "furigana": "二人[ふたり]は話[はな]す次元[じげん]が違[ちが]うので、議論[ぎろん]がかみ合[あ]わない。", "sentence_source": "generated"}, {"text": "彼は問題を、一段高い次元から眺めることができる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]を、一段[いちだん]高[たか]い次元[じげん]から眺[なが]めることができる。", "sentence_source": "generated"}, {"text": "先生は、私たちとは違う次元から物事を見ている。", "target_word": "次元", "complexity_tier": "T3", "furigana": "先生[せんせい]は、私[わたし]たちとは違[ちが]う次元[じげん]から物事[ものごと]を見[み]ている。", "sentence_source": "generated"}, {"text": "同じ次元で話さないと、意見の違いは埋まらない。", "target_word": "次元", "complexity_tier": "T3", "furigana": "同[おな]じ次元[じげん]で話[はな]さないと、意見[いけん]の違[ちが]いは埋[う]まらない。", "sentence_source": "generated"}, {"text": "彼の意見は、私の考えとは次元が異なっている。", "target_word": "次元", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は、私[わたし]の考[かんが]えとは次元[じげん]が異[こと]なっている。", "sentence_source": "generated"}, {"text": "見る次元を増やすと、一つの出来事にもいろいろな側面があると分かる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "見[み]る次元[じげん]を増[ふ]やすと、一[ひと]つの出来事[できごと]にもいろいろな側面[そくめん]があると分[わ]かる。", "sentence_source": "generated"}, {"text": "環境の問題を、経済という次元から見直した。", "target_word": "次元", "complexity_tier": "T3", "furigana": "環境[かんきょう]の問題[もんだい]を、経済[けいざい]という次元[じげん]から見直[みなお]した。", "sentence_source": "generated"}, {"text": "感情の次元と事実の次元を分けて話し合うべきだ。", "target_word": "次元", "complexity_tier": "T3", "furigana": "感情[かんじょう]の次元[じげん]と事実[じじつ]の次元[じげん]を分[わ]けて話[はな]し合[あ]うべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "次元", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物事を考えたり見たりするときの方向や角度、立場の違いを表す抽象名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "考え方の角度や見方を表し、別の角度から考えるという文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は考え方の角度ではないので、「別の料理から考える」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は見方を表さないので、考える角度として合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は考える角度ではないので、答えが見えてくる流れに関係しない。"}], "explanations": {"次元": "考え方の角度や見方を表し、別の角度から考えるという文に合う。", "料理": "料理は考え方の角度ではないので、「別の料理から考える」は成り立たない。", "天気": "天気は見方を表さないので、考える角度として合わない。", "手紙": "手紙は考える角度ではないので、答えが見えてくる流れに関係しない。"}, "sentence_index": 0, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この授業は、次元が長い。", "explanation": "ここは〈時間〉の意味。次元は見方や角度を表すので、授業の長さを言う使い方には合わない。"}, {"text": "契約書の次元が黒くにじんだ。", "explanation": "ここは〈印字〉の意味。次元は見方や角度で、インクのにじみには使わないので合わない。"}, {"text": "作業の次元を一つずつ確認する。", "explanation": "ここは〈手順〉の意味。次元は物事の見方や角度で、順序立てた作業の流れを指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "立場や見方の違いを表し、意見が異なるという文に合う。"}, {"text": "味", "is_correct": false, "explanation": "味は意見の見方の違いにならず、「味が異なる」は成り立たない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は意見の違いを表さないので、「音楽が異なる」は文が成り立たない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は意見の見方ではないので、考えとの違いを表す文に合わない。"}], "explanations": {"次元": "立場や見方の違いを表し、意見が異なるという文に合う。", "味": "味は意見の見方の違いにならず、「味が異なる」は成り立たない。", "音楽": "音楽は意見の違いを表さないので、「音楽が異なる」は文が成り立たない。", "値段": "値段は意見の見方ではないので、考えとの違いを表す文に合わない。"}, "sentence_index": 6, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯の次元が下がった。", "explanation": "ここは〈温度〉の意味。次元は見方や角度を表すので、お湯の温度の変化には合わないので誤り。"}, {"text": "在庫の次元を朝に食べた。", "explanation": "ここは〈食品〉の意味。次元は見方や角度で、食べ物の数は表さないので合わない。"}, {"text": "荷物の次元が増えた。", "explanation": "ここは〈重さ〉の意味。次元は見方を表し、荷物の重さの増加には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "別の次元に考えれば、答えが見えてくるはずだ。", "corrected_sentence": "別の次元から考えれば、答えが見えてくるはずだ。", "error_description": "「考える」の起点を示すのは「から」。「に」は対象・方向を示すので、「次元に考える」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36002, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次元が違い相手とは、話がかみ合わない。", "corrected_sentence": "次元が違う相手とは、話がかみ合わない。", "error_description": "「違う」は「相手」を修飾する連体形が必要。「違い」は連用形で名詞を修飾できないので、「違い相手」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「次元で」で、表す手段や基準を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「次元が表せる」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、名詞を受けず「表せる」に続かないので文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「次元へ表せる」は文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「次元で」で、表す手段や基準を示す。", "が": "主語を示すが、「次元が表せる」は成り立たない。", "の": "連体修飾の「の」で、名詞を受けず「表せる」に続かないので文が成り立たない。", "へ": "方向を示すが、「次元へ表せる」は文脈に合わない。"}, "error_tags": {"が": "主語（「表せる」の主語にならない）", "へ": "方向（「表せる」の対象ではない）", "の": "連体修飾（名詞を受けず「表せる」に続かない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「次元を」で、「加えて」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「加えて」の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「加える」の文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「次元から加える」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「次元を」で、「加えて」の目的語を示す。", "の": "連体修飾の「の」で、「加えて」の目的語にならない。", "より": "比較を示すが、「加える」の文脈に合わない。", "から": "起点を示すが、「次元から加える」は文脈に合わない。"}, "error_tags": {"の": "連体修飾（「加える」の目的語にならない）", "より": "比較（「加える」と合わない）", "から": "起点（「加える」の対象ではない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある対象を評価・分析する際の、特定の視点や切り口。また、空間や時間など、物事を測るための枠組み。", "primary_collocate": null, "pronunciation": "じげん", "ipa": "dʑiɡeɴ", "syllable_count": 3, "sentences": [{"text": "この調査では、商品を価格と品質の二つの次元で評価した。", "target_word": "次元", "complexity_tier": "T3", "furigana": "この調査[ちょうさ]では、商品[しょうひん]を価格[かかく]と品質[ひんしつ]の二[ふた]つの次元[じげん]で評価[ひょうか]した。", "sentence_source": "generated"}, {"text": "空間は、縦・横・高さという三つの次元で表せる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "空間[くうかん]は、縦[たて]・横[よこ]・高[たか]さという三[みっ]つの次元[じげん]で表[あらわ]せる。", "sentence_source": "generated"}, {"text": "時間を一つの次元として加えると、物の動きを正しく記述できる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "時間[じかん]を一[ひと]つの次元[じげん]として加[くわ]えると、物[もの]の動[うご]きを正[ただ]しく記述[きじゅつ]できる。", "sentence_source": "generated"}, {"text": "分析の次元が違うと、同じデータでも結果は変わる。", "target_word": "次元", "complexity_tier": "T3", "furigana": "分析[ぶんせき]の次元[じげん]が違[ちが]うと、同[おな]じデータでも結果[けっか]は変[か]わる。", "sentence_source": "generated"}, {"text": "学生の能力は、一つの次元だけでは測れない。", "target_word": "次元", "complexity_tier": "T3", "furigana": "学生[がくせい]の能力[のうりょく]は、一[ひと]つの次元[じげん]だけでは測[はか]れない。", "sentence_source": "generated"}, {"text": "地図は、縦と横の二つの次元で場所を示している。", "target_word": "次元", "complexity_tier": "T3", "furigana": "地図[ちず]は、縦[たて]と横[よこ]の二[ふた]つの次元[じげん]で場所[ばしょ]を示[しめ]している。", "sentence_source": "generated"}, {"text": "研究者は、性格を五つの次元に分けて調べた。", "target_word": "次元", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、性格[せいかく]を五[いつ]つの次元[じげん]に分[わ]けて調[しら]べた。", "sentence_source": "generated"}, {"text": "新しい次元を加えて分析し直したところ、傾向がはっきり見えた。", "target_word": "次元", "complexity_tier": "T3", "furigana": "新[あたら]しい次元[じげん]を加[くわ]えて分析[ぶんせき]し直[なお]したところ、傾向[けいこう]がはっきり見[み]えた。", "sentence_source": "generated"}, {"text": "この表では、年齢と収入という二つの次元で客を分類している。", "target_word": "次元", "complexity_tier": "T3", "furigana": "この表[ひょう]では、年齢[ねんれい]と収入[しゅうにゅう]という二[ふた]つの次元[じげん]で客[きゃく]を分類[ぶんるい]している。", "sentence_source": "generated"}, {"text": "線には長さという一つの次元しかないが、面には広がりもある。", "target_word": "次元", "complexity_tier": "T3", "furigana": "線[せん]には長[なが]さという一[ひと]つの次元[じげん]しかないが、面[めん]には広[ひろ]がりもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "次元", "label": "基本形"}], "register": "標準", "sense_fingerprint": "評価や分析の切り口、また空間や時間など物事を測る枠組みを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 表せる (Zipf 2.44)']::text[], 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "評価の切り口を表し、「二つの次元で評価した」という文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は評価の切り口ではないので、「二つの料理で評価した」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は評価の基準ではないので、商品の評価の文に合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は評価の切り口ではないので、「二つの音楽で評価した」は成り立たない。"}], "explanations": {"次元": "評価の切り口を表し、「二つの次元で評価した」という文に合う。", "料理": "料理は評価の切り口ではないので、「二つの料理で評価した」は成り立たない。", "手紙": "手紙は評価の基準ではないので、商品の評価の文に合わない。", "音楽": "音楽は評価の切り口ではないので、「二つの音楽で評価した」は成り立たない。"}, "sentence_index": 0, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の次元は晴れるらしい。", "explanation": "ここは〈天気〉の意味。次元は評価や分析の切り口を表すので、空模様の予想には合わない。"}, {"text": "作業の次元を一つずつ食べる。", "explanation": "ここは〈食品〉の意味。次元は評価や分析の切り口で、食べ物の一つ一つは指さないので合わない。"}, {"text": "チェックリストの次元が一つ折れた。", "explanation": "ここは〈紙〉の意味。次元は分析の切り口で、紙が折れる状態は表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次元", "is_correct": true, "explanation": "性格を分ける切り口を表し、「五つの次元に分けて調べた」という文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は性格の分類の切り口ではないので、分けて調べる文に合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は性格を分ける基準にならず、「五つの味に分けた」は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花は性格の切り口ではないので、「五つの花に分けた」は成り立たない。"}], "explanations": {"次元": "性格を分ける切り口を表し、「五つの次元に分けて調べた」という文に合う。", "天気": "天気は性格の分類の切り口ではないので、分けて調べる文に合わない。", "味": "味は性格を分ける基準にならず、「五つの味に分けた」は成り立たない。", "花": "花は性格の切り口ではないので、「五つの花に分けた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "次元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物差しの次元を一つずつ読んだ。", "explanation": "ここは〈目盛〉の意味。次元は物事を測る枠組みで、物差しの一つ一つの印は指さないので合わない。"}, {"text": "実験の次元が二つ割れた。", "explanation": "ここは〈器物〉の意味。次元は評価や分析の切り口で、物が割れることは表さないので合わない。"}, {"text": "教科書の次元を三つに焼いた。", "explanation": "ここは〈調理〉の意味。次元は分析の切り口で、焼いて仕上げる対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "価格という次元に商品を比べた。", "corrected_sentence": "価格という次元で商品を比べた。", "error_description": "基準を表す「で」が正しい。「に」は方向・対象を示すので、「次元に商品を比べた」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36003, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面積という次元を、部屋の広さを比べられる。", "corrected_sentence": "面積という次元で、部屋の広さを比べられる。", "error_description": "「次元」に続く助詞は「で」が正しい。「を」を付けると次元が目的語になり、「比べる」の基準を示す形と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
