INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36004, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても細かいところまで、正しく、間違いがないこと。", "primary_collocate": null, "pronunciation": "せいみつ", "ipa": "seimitsɯ", "syllable_count": 4, "sentences": [{"text": "この時計は精密な機械で、一日に一秒もずれない。", "target_word": "精密", "complexity_tier": "T3", "furigana": "この時計[とけい]は精密[せいみつ]な機械[きかい]で、一日[いちにち]に一秒[いちびょう]もずれない。", "sentence_source": "generated"}, {"text": "医者は精密な検査をして、病気の原因を見つけた。", "target_word": "精密", "complexity_tier": "T3", "furigana": "医者[いしゃ]は精密[せいみつ]な検査[けんさ]をして、病気[びょうき]の原因[げんいん]を見[み]つけた。", "sentence_source": "generated"}, {"text": "地図を精密に描くには、長い時間が必要だ。", "target_word": "精密", "complexity_tier": "T3", "furigana": "地図[ちず]を精密[せいみつ]に描[えが]くには、長[なが]い時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "精密な部品が一つでもこわれると、機械は動かない。", "target_word": "精密", "complexity_tier": "T3", "furigana": "精密[せいみつ]な部品[ぶひん]が一[ひと]つでもこわれると、機械[きかい]は動[うご]かない。", "sentence_source": "generated"}, {"text": "彼の仕事はいつも精密で、まちがいがほとんどない。", "target_word": "精密", "complexity_tier": "T3", "furigana": "彼[かれ]の仕事[しごと]はいつも精密[せいみつ]で、まちがいがほとんどない。", "sentence_source": "generated"}, {"text": "実験では、精密な数字を出すことが大切だ。", "target_word": "精密", "complexity_tier": "T3", "furigana": "実験[じっけん]では、精密[せいみつ]な数字[すうじ]を出[だ]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "この望遠鏡は精密に作られていて、遠くの星もはっきり見える。", "target_word": "精密", "complexity_tier": "T3", "furigana": "この望遠鏡[ぼうえんきょう]は精密[せいみつ]に作[つく]られていて、遠[とお]くの星[ほし]もはっきり見[み]える。", "sentence_source": "generated"}, {"text": "この機械の部品は、精密に検査されてから出荷される。", "target_word": "精密", "complexity_tier": "T3", "furigana": "この機械[きかい]の部品[ぶひん]は、精密[せいみつ]に検査[けんさ]されてから出荷[しゅっか]される。", "sentence_source": "generated"}, {"text": "工場では、精密な検査機で一つ一つの製品を確かめている。", "target_word": "精密", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、精密[せいみつ]な検査機[けんさき]で一[ひと]つ一[ひと]つの製品[せいひん]を確[たし]かめている。", "sentence_source": "generated"}, {"text": "古い地図は精密ではないが、昔の人の知恵が感じられる。", "target_word": "精密", "complexity_tier": "T3", "furigana": "古[ふる]い地図[ちず]は精密[せいみつ]ではないが、昔[むかし]の人[ひと]の知恵[ちえ]が感[かん]じられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "精密", "label": "語幹"}, {"form": "精密な", "label": "連体形"}, {"form": "精密に", "label": "連用形"}, {"form": "精密だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "細部まで正確でまちがいがない（精密な・精密に）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36004, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精密", "is_correct": true, "explanation": "「精密な機械」は正確さを表し、「一日に一秒もずれない」と結びつくので正解。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な機械」は性格を表す語で、「一秒もずれない」という正確さの話と合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかな機械」は様子を表す語で、正確さの説明にならない。"}, {"text": "派手", "is_correct": false, "explanation": "「派手な機械」は見た目を表す語で、「一秒もずれない」とは合わない。"}], "explanations": {"精密": "「精密な機械」は正確さを表し、「一日に一秒もずれない」と結びつくので正解。", "陽気": "「陽気な機械」は性格を表す語で、「一秒もずれない」という正確さの話と合わない。", "穏やか": "「穏やかな機械」は様子を表す語で、正確さの説明にならない。", "派手": "「派手な機械」は見た目を表す語で、「一秒もずれない」とは合わない。"}, "sentence_index": 0, "correct_answer": "精密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は精密な気持ちをそっと伝えた。", "explanation": "ここは〈繊細〉（細やかで敏感）の意味。気持ちの細やかさは〈繊細〉で表し、〈精密〉の「正確で間違いがない」とは合わない。"}, {"text": "先生は授業中、精密に生徒を叱った。", "explanation": "ここは〈厳しく〉（きびしく）の意味。叱り方の激しさは〈厳しく〉で表し、〈精密に〉では正確さの意味になってしまい合わない。"}, {"text": "精密な店員さんが迎えてくれた。", "explanation": "ここは〈愛想〉（感じのよさ）の意味。人の感じのよさは〈精密〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36004, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精密", "is_correct": true, "explanation": "「精密に作られていて」は正確に作られたことを表し、「遠くの星も見える」と合うので正解。"}, {"text": "賑やか", "is_correct": false, "explanation": "「賑やかに作られていて」は意味をなさず、望遠鏡の性能と合わない。"}, {"text": "大胆", "is_correct": false, "explanation": "「大胆に作られていて」は作り方の様子を表すが、遠くの星が見えることの説明にならない。"}, {"text": "元気", "is_correct": false, "explanation": "「元気に作られていて」は意味をなさない。"}], "explanations": {"精密": "「精密に作られていて」は正確に作られたことを表し、「遠くの星も見える」と合うので正解。", "賑やか": "「賑やかに作られていて」は意味をなさず、望遠鏡の性能と合わない。", "大胆": "「大胆に作られていて」は作り方の様子を表すが、遠くの星が見えることの説明にならない。", "元気": "「元気に作られていて」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "精密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は精密に笑い、みんなを明るくした。", "explanation": "ここは〈豪快〉（大きく勢いのある様子）の意味。笑い方の勢いは〈豪快〉で表し、〈精密〉では合わない。"}, {"text": "彼は精密な声で、みんなを大きく笑わせた。", "explanation": "ここは〈陽気〉（明るく楽しい）の意味。声の明るさは〈陽気〉で表し、〈精密〉では正確さの話になり合わない。"}, {"text": "彼女はいつも精密な笑顔で、子どもたちに話しかける。", "explanation": "ここは〈愛想〉（人当たりのよさ）の意味。笑顔の人当たりは〈愛想〉で表し、〈精密〉の「正確で間違いがない」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36004, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この体温計は精密の機械で、数分で正確な値を表示する。", "corrected_sentence": "この体温計は精密な機械で、数分で正確な値を表示する。", "error_description": "「精密」は名詞を修飾する形が必要で、「精密な」が正しい。「精密の」は誤った形（の→な）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "精密な", "is_correct": true, "explanation": "名詞「検査」を修飾する連体形で、ここでは正しい形。"}, {"text": "精密だ", "is_correct": false, "explanation": "終止形は「精密だ検査」と名詞を修飾できないので、この位置には入らない。"}, {"text": "精密で", "is_correct": false, "explanation": "中止形は名詞を直接修飾できないので、「精密で検査」は成り立たない。"}, {"text": "精密さ", "is_correct": false, "explanation": "名詞化した「精密さ」は、「検査」を直接修飾する形にはならない。"}], "correct_form": "精密な", "base_form": "精密だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"精密な": "名詞「検査」を修飾する連体形で、ここでは正しい形。", "精密だ": "終止形は「精密だ検査」と名詞を修飾できないので、この位置には入らない。", "精密で": "中止形は名詞を直接修飾できないので、「精密で検査」は成り立たない。", "精密さ": "名詞化した「精密さ」は、「検査」を直接修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36004, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この顕微鏡は精密な作られていて、小さな細胞もはっきり見える。", "corrected_sentence": "この顕微鏡は精密に作られていて、小さな細胞もはっきり見える。", "error_description": "「作られる」を修飾する形が必要で、連用形「精密に」が正しい。「精密な」は誤り（な→に）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "精密に", "is_correct": true, "explanation": "動詞「検査される」を修飾する連用形で、ここでは正しい形。"}, {"text": "精密な", "is_correct": false, "explanation": "連体形は「精密な検査されて」となり、動詞を修飾できないので成り立たない。"}, {"text": "精密だった", "is_correct": false, "explanation": "過去形では「精密だった、検査されて」と動詞を修飾できず、文が成り立たない。"}, {"text": "精密", "is_correct": false, "explanation": "語幹だけでは動詞を修飾できず、「精密、検査されて」と文の形が崩れる。"}], "correct_form": "精密に", "base_form": "精密だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"精密に": "動詞「検査される」を修飾する連用形で、ここでは正しい形。", "精密な": "連体形は「精密な検査されて」となり、動詞を修飾できないので成り立たない。", "精密だった": "過去形では「精密だった、検査されて」と動詞を修飾できず、文が成り立たない。", "精密": "語幹だけでは動詞を修飾できず、「精密、検査されて」と文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「成果が出た」の主語を示す「が」。努力の結果が出たことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「成果を出た」は目的語を取る形になるが、「出た」は自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「成果に出た」は位置を示す形で、「出た」の主語を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「成果へ出た」は方向を示すが、結果が出たという主語の関係を表せない。"}], "correct_answer": "が", "explanations": {"が": "「成果が出た」の主語を示す「が」。努力の結果が出たことを表す。", "を": "「成果を出た」は目的語を取る形になるが、「出た」は自動詞なので合わない。", "に": "「成果に出た」は位置を示す形で、「出た」の主語を表せない。", "へ": "「成果へ出た」は方向を示すが、結果が出たという主語の関係を表せない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「成果を見せる」の目的語を示す「を」。見せる対象が成果になる。"}, {"text": "が", "is_correct": false, "explanation": "「成果が見せる」では成果が見せる主体になり、文の意味（自分が見せる）と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「成果から見せる」は起点を示すが、見せる対象としては不自然。"}, {"text": "より", "is_correct": false, "explanation": "「成果より見せる」は比較を示すが、見せる対象を表せず意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「成果を見せる」の目的語を示す「を」。見せる対象が成果になる。", "が": "「成果が見せる」では成果が見せる主体になり、文の意味（自分が見せる）と合わない。", "から": "「成果から見せる」は起点を示すが、見せる対象としては不自然。", "より": "「成果より見せる」は比較を示すが、見せる対象を表せず意味が通らない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをがんばってやって、その結果、すごくいいものができたこと。", "primary_collocate": null, "pronunciation": "せいか", "ipa": "seːka", "syllable_count": 3, "sentences": [{"text": "毎日練習した成果が出て、試合に勝てた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]した成果[せいか]が出[で]て、試合[しあい]に勝[か]てた。", "sentence_source": "generated"}, {"text": "夏休みの自由研究で、いい成果が出た。", "target_word": "成果", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの自由研究[じゆうけんきゅう]で、いい成果[せいか]が出[で]た。", "sentence_source": "generated"}, {"text": "みんなでがんばった成果を、先生がほめてくれた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "みんなでがんばった成果[せいか]を、先生[せんせい]がほめてくれた。", "sentence_source": "generated"}, {"text": "勉強の成果がテストの点に表れた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "勉強[べんきょう]の成果[せいか]がテストの点[てん]に表[あらわ]れた。", "sentence_source": "generated"}, {"text": "長い間努力したのに、成果がなかなか出ない。", "target_word": "成果", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]努力[どりょく]したのに、成果[せいか]がなかなか出[で]ない。", "sentence_source": "generated"}, {"text": "この絵は、一年間の練習の成果だ。", "target_word": "成果", "complexity_tier": "T3", "furigana": "この絵[え]は、一年間[いちねんかん]の練習[れんしゅう]の成果[せいか]だ。", "sentence_source": "generated"}, {"text": "毎朝走った成果で、足が速くなった。", "target_word": "成果", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]走[はし]った成果[せいか]で、足[あし]が速[はや]くなった。", "sentence_source": "generated"}, {"text": "成果を見せるために、発表会で歌った。", "target_word": "成果", "complexity_tier": "T3", "furigana": "成果[せいか]を見[み]せるために、発表会[はっぴょうかい]で歌[うた]った。", "sentence_source": "generated"}, {"text": "兄は努力の成果で、希望の学校に入れた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "兄[あに]は努力[どりょく]の成果[せいか]で、希望[きぼう]の学校[がっこう]に入[はい]れた。", "sentence_source": "generated"}, {"text": "畑の世話をした成果として、おいしい野菜ができた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "畑[はたけ]の世話[せわ]をした成果[せいか]として、おいしい野菜[やさい]ができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成果", "label": "基本形"}], "register": "neutral (plain form, everyday)", "sense_fingerprint": "がんばった末に出たよい結果(子どもにもわかる日常的な意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "ここは〈努力して得た良い結果〉の意味。練習の成果として試合に勝てた、という文に合う。"}, {"text": "練習", "is_correct": false, "explanation": "練習は行為そのもの。「練習が出て」では結果が出たという意味にならず合わない。"}, {"text": "試合", "is_correct": false, "explanation": "試合は勝負の場を指す。「試合が出て」とは言えず、努力の結果という文脈に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は呼び名。「練習した名前が出て」では意味が通らない。"}], "explanations": {"成果": "ここは〈努力して得た良い結果〉の意味。練習の成果として試合に勝てた、という文に合う。", "練習": "練習は行為そのもの。「練習が出て」では結果が出たという意味にならず合わない。", "試合": "試合は勝負の場を指す。「試合が出て」とは言えず、努力の結果という文脈に合わない。", "名前": "名前は呼び名。「練習した名前が出て」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の成果で、町の電車が止まった。", "explanation": "ここは〈結果〉の意味。成果は努力して得た良いものを指すので、台風の被害には使えない。"}, {"text": "中間テストの成果は、五段階で「三」だった。", "explanation": "ここは〈成績〉の意味。成果は努力で得たものを指し、五段階の評価の数字には使えない。"}, {"text": "庭でとれた成果を、みんなで食べた。", "explanation": "ここは〈果物・実〉の意味。成果は努力の結果を指すので、食べられる実のことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "ここは〈努力の結果〉の意味。毎朝走った努力の結果として足が速くなった、に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様。走った天気で足が速くなるとは言えず合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時間の点。「走った時刻」では原因と結果の関係が成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分。「走った季節で足が速くなった」は意味が通らない。"}], "explanations": {"成果": "ここは〈努力の結果〉の意味。毎朝走った努力の結果として足が速くなった、に合う。", "天気": "天気は空模様。走った天気で足が速くなるとは言えず合わない。", "時刻": "時刻は時間の点。「走った時刻」では原因と結果の関係が成り立たない。", "季節": "季節は一年の区分。「走った季節で足が速くなった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作文に先生の高い成果がついた。", "explanation": "ここは〈評価〉の意味。成果は努力で得た結果を指すので、先生がつける評価には使えない。"}, {"text": "サッカーの試合で、成果は三点だった。", "explanation": "ここは〈得点〉の意味。成果は努力で得たよい結果を指すので、試合の点数には使えない。"}, {"text": "くじの成果で、旅行券が当たった。", "explanation": "ここは〈景品〉の意味。成果は努力して得た結果を指すので、くじで当たる賞品には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝練習した成果を出て、大会で勝てた。", "corrected_sentence": "毎朝練習した成果が出て、大会で勝てた。", "error_description": "「成果が出る」の主語は「が」。「を」にすると「出る」と合わず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36008, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "努力の成果を、おいしい野菜ができた。", "corrected_sentence": "努力の成果で、おいしい野菜ができた。", "error_description": "「できる」は「が」で主語を示す自動詞なので、「成果を」では文が成り立たない。手段や原因を示す「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「成果が表れる」の主語を示す「が」。制度の成果が現れたことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「成果を表れている」は目的語を取るが、「表れる」は自動詞なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「成果へ表れている」は方向を示すが、主語になれず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「成果と表れている」は並列を示すが、主語を表せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「成果が表れる」の主語を示す「が」。制度の成果が現れたことを表す。", "を": "「成果を表れている」は目的語を取るが、「表れる」は自動詞なので合わない。", "へ": "「成果へ表れている」は方向を示すが、主語になれず文が成り立たない。", "と": "「成果と表れている」は並列を示すが、主語を表せず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「成果として」の「と」。成果を、ある立場や性質として示す。"}, {"text": "を", "is_correct": false, "explanation": "「成果を」の後に目的語を取る動詞がなく、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「成果の」は続く名詞を修飾する形で、文の中で役割を果たせず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「成果が、」は主語を示すが、後ろの文と結びつかず成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「成果として」の「と」。成果を、ある立場や性質として示す。", "を": "「成果を」の後に目的語を取る動詞がなく、文が成り立たない。", "の": "「成果の」は続く名詞を修飾する形で、文の中で役割を果たせず不自然。", "が": "「成果が、」は主語を示すが、後ろの文と結びつかず成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "努力や活動によって得られた良い結果や実績。", "primary_collocate": null, "pronunciation": "せいか", "ipa": "seːka", "syllable_count": 3, "sentences": [{"text": "研究チームは三年間の調査で大きな成果を上げた。", "target_word": "成果", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは三年間[さんねんかん]の調査[ちょうさ]で大[おお]きな成果[せいか]を上[あ]げた。", "sentence_source": "generated"}, {"text": "新しい制度の成果が、数字ではっきり表れている。", "target_word": "成果", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]の成果[せいか]が、数字[すうじ]ではっきり表[あらわ]れている。", "sentence_source": "generated"}, {"text": "努力にもかかわらず、期待した成果は得られなかった。", "target_word": "成果", "complexity_tier": "T3", "furigana": "努力[どりょく]にもかかわらず、期待[きたい]した成果[せいか]は得[え]られなかった。", "sentence_source": "generated"}, {"text": "会議では、今年度の成果と課題が報告された。", "target_word": "成果", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、今年度[こんねんど]の成果[せいか]と課題[かだい]が報告[ほうこく]された。", "sentence_source": "generated"}, {"text": "長年の研究の成果が学会で高く評価された。", "target_word": "成果", "complexity_tier": "T3", "furigana": "長年[ながねん]の研究[けんきゅう]の成果[せいか]が学会[がっかい]で高[たか]く評価[ひょうか]された。", "sentence_source": "generated"}, {"text": "彼女は営業部で目に見える成果を残した。", "target_word": "成果", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は営業部[えいぎょうぶ]で目[め]に見[み]える成果[せいか]を残[のこ]した。", "sentence_source": "generated"}, {"text": "この事業の成果を測るために、調査を行う。", "target_word": "成果", "complexity_tier": "T3", "furigana": "この事業[じぎょう]の成果[せいか]を測[はか]るために、調査[ちょうさ]を行[おこな]う。", "sentence_source": "generated"}, {"text": "地道な活動の成果として、川の水質が改善した。", "target_word": "成果", "complexity_tier": "T3", "furigana": "地道[じみち]な活動[かつどう]の成果[せいか]として、川[かわ]の水質[すいしつ]が改善[かいぜん]した。", "sentence_source": "generated"}, {"text": "成果が出るまでには、数年の時間が必要である。", "target_word": "成果", "complexity_tier": "T3", "furigana": "成果[せいか]が出[で]るまでには、数年[すうねん]の時間[じかん]が必要[ひつよう]である。", "sentence_source": "generated"}, {"text": "社員は成果に応じて、賞与を受け取る。", "target_word": "成果", "complexity_tier": "T3", "furigana": "社員[しゃいん]は成果[せいか]に応[おう]じて、賞与[しょうよ]を受[う]け取[と]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成果", "label": "基本形"}], "register": "formal (written, plain form, research and business)", "sense_fingerprint": "努力や活動で得た良い結果・実績(研究・仕事・事業など改まった場面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "ここは〈努力で得た良い結果〉の意味。三年間の調査で良い結果を上げた、に合う。「成果を上げる」は決まった言い方。"}, {"text": "調査", "is_correct": false, "explanation": "調査は調べる行為。「大きな調査を上げた」とは言わないので合わない。"}, {"text": "研究", "is_correct": false, "explanation": "研究は活動そのもの。「大きな研究を上げた」は意味が通らない。"}, {"text": "議論", "is_correct": false, "explanation": "議論は話し合い。「大きな議論を上げた」とは言わないので合わない。"}], "explanations": {"成果": "ここは〈努力で得た良い結果〉の意味。三年間の調査で良い結果を上げた、に合う。「成果を上げる」は決まった言い方。", "調査": "調査は調べる行為。「大きな調査を上げた」とは言わないので合わない。", "研究": "研究は活動そのもの。「大きな研究を上げた」は意味が通らない。", "議論": "議論は話し合い。「大きな議論を上げた」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の原因と成果が公表された。", "explanation": "ここは〈結果〉の意味。成果は努力や活動で得た良い結果を指すので、事故の結末には使えない。"}, {"text": "研究所は新しい成果を三人雇った。", "explanation": "ここは〈人員・社員〉の意味。成果は努力や活動で得た結果を指すので、人を雇う文には使えない。"}, {"text": "その工場は、毎日多くの成果を全国に出荷している。", "explanation": "ここは〈製品〉の意味。成果は努力の結果を指すので、工場で作って出荷する製品には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "ここは〈努力の結果〉の意味。事業の結果を測る、という文に合う。"}, {"text": "方針", "is_correct": false, "explanation": "方針は進め方の指針。測るものではないので合わない。"}, {"text": "日程", "is_correct": false, "explanation": "日程は予定の並び。「日程を測る」とは言わないので合わない。"}, {"text": "人員", "is_correct": false, "explanation": "人員は人の数。事業の出来栄えを測る対象にはならない。"}], "explanations": {"成果": "ここは〈努力の結果〉の意味。事業の結果を測る、という文に合う。", "方針": "方針は進め方の指針。測るものではないので合わない。", "日程": "日程は予定の並び。「日程を測る」とは言わないので合わない。", "人員": "人員は人の数。事業の出来栄えを測る対象にはならない。"}, "sentence_index": 6, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は成果が明るく、誰とでも話せる。", "explanation": "ここは〈性格〉の意味。成果は努力や活動で得た結果を指すので、人の性格には使えない。"}, {"text": "社員は社内の成果に従って行動した。", "explanation": "ここは〈規則〉の意味。規則には従うが、成果には従えないので合わない。"}, {"text": "研究所は今年度の成果を立てた。", "explanation": "ここは〈目標〉の意味。目標は立てるものだが、成果は出すもので、立てるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事業の成果を、数字で示された。", "corrected_sentence": "この事業の成果が、数字で示された。", "error_description": "「示す」を受け身にすると、目的語の「成果」が主語になり「が」を取る。「を」のままでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36009, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地道な活動の成果を、川の水質が改善した。", "corrected_sentence": "地道な活動の成果で、川の水質が改善した。", "error_description": "「成果で」で手段や原因を示す。「成果を」は後の「改善した」と結びつかず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「初期の携帯電話」の「の」。初期を携帯電話の時期として結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「初期を携帯電話は」は名詞に「を」が続き、文の骨組みが合わず成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「初期が携帯電話は」は主語が二つになり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「初期へ携帯電話は」は方向を示すが、名詞同士の関係を表せない。"}], "correct_answer": "の", "explanations": {"の": "「初期の携帯電話」の「の」。初期を携帯電話の時期として結ぶ。", "を": "「初期を携帯電話は」は名詞に「を」が続き、文の骨組みが合わず成り立たない。", "が": "「初期が携帯電話は」は主語が二つになり、文として成り立たない。", "へ": "「初期へ携帯電話は」は方向を示すが、名詞同士の関係を表せない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末期", "is_correct": true, "explanation": "ここは〈終わりのころ〉の意味。初期（いちばん最初の時期）と対になる語として辞書に載る。"}, {"text": "中期", "is_correct": false, "explanation": "中期は途中の時期で、初期の対義語ではない。"}, {"text": "中盤", "is_correct": false, "explanation": "中盤は試合や物語の途中の段階で、初期と対にはならない。"}, {"text": "完成", "is_correct": false, "explanation": "完成は出来上がった状態で、時期の対義語ではない。"}], "correct_answer": "末期", "explanations": {"末期": "ここは〈終わりのころ〉の意味。初期（いちばん最初の時期）と対になる語として辞書に載る。", "中期": "中期は途中の時期で、初期の対義語ではない。", "中盤": "中盤は試合や物語の途中の段階で、初期と対にはならない。", "完成": "完成は出来上がった状態で、時期の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「初期の校舎」の「の」。初期を校舎の時期として結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「初期を校舎は」は目的語を示すが、続く動詞がなく文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「初期で校舎は」は場所や手段を示すが、時期を表す形としては不自然。"}, {"text": "が", "is_correct": false, "explanation": "「初期が校舎は」は主語が二つ並び、文の骨組みが崩れて不自然。"}], "correct_answer": "の", "explanations": {"の": "「初期の校舎」の「の」。初期を校舎の時期として結ぶ。", "を": "「初期を校舎は」は目的語を示すが、続く動詞がなく文が成り立たない。", "で": "「初期で校舎は」は場所や手段を示すが、時期を表す形としては不自然。", "が": "「初期が校舎は」は主語が二つ並び、文の骨組みが崩れて不自然。"}, "error_tags": {"を": "目的語", "で": "場所", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末期", "is_correct": true, "explanation": "ここは〈終わりのころ〉の意味。映画の最初の時期と対になる語として辞書に載る。"}, {"text": "絶頂", "is_correct": false, "explanation": "絶頂は最も高まった状態で、初期の対義語ではない。"}, {"text": "最盛期", "is_correct": false, "explanation": "最盛期は勢いが最も強い時期で、初期と対にはならない。"}, {"text": "成熟", "is_correct": false, "explanation": "成熟は十分に発達した状態で、時期の対義語ではない。"}], "correct_answer": "末期", "explanations": {"末期": "ここは〈終わりのころ〉の意味。映画の最初の時期と対になる語として辞書に載る。", "絶頂": "絶頂は最も高まった状態で、初期の対義語ではない。", "最盛期": "最盛期は勢いが最も強い時期で、初期と対にはならない。", "成熟": "成熟は十分に発達した状態で、時期の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いちばんはじめのころのこと。", "primary_collocate": null, "pronunciation": "しょき", "ipa": "ɕoki", "syllable_count": 2, "sentences": [{"text": "病気は初期のうちに見つけると、治りやすい。", "target_word": "初期", "complexity_tier": "T3", "furigana": "病気[びょうき]は初期[しょき]のうちに見[み]つけると、治[なお]りやすい。", "sentence_source": "generated"}, {"text": "初期の携帯電話は、とても大きくて重かった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "初期[しょき]の携帯電話[けいたいでんわ]は、とても大[おお]きくて重[おも]かった。", "sentence_source": "generated"}, {"text": "江戸時代の初期に、この町ができた。", "target_word": "初期", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]の初期[しょき]に、この町[まち]ができた。", "sentence_source": "generated"}, {"text": "計画の初期には、まだ参加者が十人しかいなかった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "計画[けいかく]の初期[しょき]には、まだ参加者[さんかしゃ]が十人[じゅうにん]しかいなかった。", "sentence_source": "generated"}, {"text": "彼の初期の作品は暗いが、後の作品は明るい。", "target_word": "初期", "complexity_tier": "T3", "furigana": "彼[かれ]の初期[しょき]の作品[さくひん]は暗[くら]いが、後[あと]の作品[さくひん]は明[あか]るい。", "sentence_source": "generated"}, {"text": "活動の初期は失敗が多かったが、今は上手になった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "活動[かつどう]の初期[しょき]は失敗[しっぱい]が多[おお]かったが、今[いま]は上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "町の初期の写真が、図書館に残っている。", "target_word": "初期", "complexity_tier": "T3", "furigana": "町[まち]の初期[しょき]の写真[しゃしん]が、図書館[としょかん]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "この学校の初期の校舎は、木でできていた。", "target_word": "初期", "complexity_tier": "T3", "furigana": "この学校[がっこう]の初期[しょき]の校舎[こうしゃ]は、木[き]でできていた。", "sentence_source": "generated"}, {"text": "会社は設立の初期、小さな部屋で仕事をしていた。", "target_word": "初期", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は設立[せつりつ]の初期[しょき]、小[ちい]さな部屋[へや]で仕事[しごと]をしていた。", "sentence_source": "generated"}, {"text": "映画の初期は白黒で、音も入っていなかった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "映画[えいが]の初期[しょき]は白黒[しろくろ]で、音[おと]も入[はい]っていなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初期", "label": "基本形"}], "register": "neutral (plain form)", "sense_fingerprint": "ある期間・時代・過程の、いちばん最初の時期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "ここは〈いちばん最初の時期〉の意味。病気がまだ軽いうちに見つける、という文に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院は場所。「病院のうちに見つけると」とは言わないので合わない。"}, {"text": "薬", "is_correct": false, "explanation": "薬は治療に使う物。病気を見つける時期を表せないので合わない。"}, {"text": "手術", "is_correct": false, "explanation": "手術は体に施す処置。見つける時期を表す語にはならないので合わない。"}], "explanations": {"初期": "ここは〈いちばん最初の時期〉の意味。病気がまだ軽いうちに見つける、という文に合う。", "病院": "病院は場所。「病院のうちに見つけると」とは言わないので合わない。", "薬": "薬は治療に使う物。病気を見つける時期を表せないので合わない。", "手術": "手術は体に施す処置。見つける時期を表す語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は初期の英語を三回受験して、合格した。", "explanation": "ここは〈試験〉の意味。初期は時期を表す言葉なので、英語の試験の名前には使えない。"}, {"text": "彼はいつまでも初期を忘れないと誓った。", "explanation": "ここは〈初心〉の意味。初期は時期を表すので、最初の気持ちは指さないので合わない。"}, {"text": "初期の風が心地よい。", "explanation": "ここは〈初夏〉の意味。初期は物事の始まりの時期で、季節の名前の代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "ここは〈いちばん最初の時期〉の意味。町の古い時代の写真として合う。"}, {"text": "悲鳴", "is_correct": false, "explanation": "悲鳴は叫び声で、写真の時期を表す語にはならない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、写真の時期を表せないので合わない。"}, {"text": "発音", "is_correct": false, "explanation": "発音は言葉の音の出し方で、写真には当てはまらない。"}], "explanations": {"初期": "ここは〈いちばん最初の時期〉の意味。町の古い時代の写真として合う。", "悲鳴": "悲鳴は叫び声で、写真の時期を表す語にはならない。", "値段": "値段は価格で、写真の時期を表せないので合わない。", "発音": "発音は言葉の音の出し方で、写真には当てはまらない。"}, "sentence_index": 6, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は初期が降った。", "explanation": "ここは〈初雪〉の意味。初期は物事の始まりの時期で、雪が降ることには使わない。"}, {"text": "この舞台を見て、初期が泣いた。", "explanation": "ここは〈観客〉の意味。初期は時期を表すので、泣く人を指すことはできない。"}, {"text": "昨日、初期の金魚を一匹買った。", "explanation": "ここは〈金魚（生き物）〉の意味。初期は時期を表すので、ペットの生き物を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの病気は初期が見つけると、治りやすい。", "corrected_sentence": "子どもの病気は初期に見つけると、治りやすい。", "error_description": "時期を表すのは「に」。「が」では主語になり、「見つける」の時期を示せず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の初期を、写真が図書館に残っている。", "corrected_sentence": "町の初期に、写真が図書館に残っている。", "error_description": "「残っている」は自動詞で「を」の目的語を取らないので、「町の初期を」は文が成り立たない。時期を示す「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好きだ」の対象は「が」で示すので、メロディーに続けるのは「が」。"}, {"text": "を", "is_correct": false, "explanation": "「好きだ」は目的語に「を」をとらないので、「を」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「好きだ」の対象を「に」で示す用法はなく、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「好きだ」の対象としては意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「好きだ」の対象は「が」で示すので、メロディーに続けるのは「が」。", "を": "「好きだ」は目的語に「を」をとらないので、「を」は不自然。", "に": "「好きだ」の対象を「に」で示す用法はなく、文が通らない。", "で": "「で」は手段や場所を示すので、「好きだ」の対象としては意味が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
